    const mcore=lerp(10,92,ramp(coreNo,.1,.95))*appear;
    const mb2=brainSide(L.mx,L.sy+L.sg-18,L.ms,{lesion:appear>0?{at:[150,108],core:mcore,penumbra:Math.max(penR,mcore),saved:0,mca:true}:null});
