    s+=`<line x1="${f1(seg[0])}" x2="${f1(seg[1])}" y1="${ys[0]+h+1}" y2="${ys[1]-15}" style="stroke:var(--ink);stroke-width:1.4;stroke-dasharray:5 3"/>`;
