    const sigTxt=h<=7.25?'Within the range where benefit stayed significant, which held through 7 hours 18 minutes <sup class="c" data-ref="Saver2016" title="Source 895"><a href="/stroke/sources/#src-Saver2016">895</a></sup>.':'Past 7 hours 18 minutes, where significance no longer held <sup class="c" data-ref="Saver2016" title="Source 895"><a href="/stroke/sources/#src-Saver2016">895</a></sup>.';
    let nt=`<div class="kicker">HERMES timing · onset to puncture</div><h4>${h} hours</h4>`;
