  tiB.addEventListener('click',e=>{const b=e.target.closest('[data-g]');if(!b)return;tiI=+b.dataset.g;$$('[data-g]',tiB).forEach((q,k)=>q.setAttribute('aria-pressed',k===tiI));drawTi()});
