inits.prevent=()=>{
  /* ---------- the adder ---------- */
  const svg=$('#pvSvg'),rg=$('#pvT'),sel=new Set(PV_F.map(f=>f.id));
  function draw(t){const N=vb(svg,'720 392','400 392'),W=N?400:720,x0=N?118:166,sw=N?272:536,X=v=>x0+sw*v/210,rh=24,y0=48;
    const on=PV_F.filter(f=>sel.has(f.id)),n=on.length,reach=t/.8;let cum=0,prod=1,s='';
    const yEnd=y0+rh*10;
    /* the impossible zone and axis */
    s+=`<rect x="${f1(X(100))}" y="${y0-6}" width="${f1(X(210)-X(100))}" height="${yEnd-y0+90}" style="fill:var(--bad-soft)"/>`;
    s+=`<text x="${f1(X(210))}" y="16" class="t-sm t-end" style="fill:var(--bad);font-weight:700">above 100%: impossible</text>`;
    [0,50,100,150,200].forEach(v=>{const x=X(v);s+=`<line x1="${f1(x)}" x2="${f1(x)}" y1="${y0-6}" y2="${yEnd+84}" ${v===100?'style="stroke:var(--bad);stroke-width:1.4;stroke-dasharray:5 4"':'class="grid"'}/><text x="${f1(x)}" y="36" class="t-xs t-mid">${v}%</text>`});
    s+=`<text x="8" y="36" class="t-xs">PAR, all stroke</text>`;
    const segs=[];
    PV_F.forEach((f,i)=>{const y=y0+i*rh,isOn=sel.has(f.id);
      s+=`<text x="8" y="${y+15}" class="t-sm" style="fill:${isOn?'var(--ink)':'var(--muted)'};opacity:${isOn?1:.6}${isOn?'':';text-decoration:line-through'}">${f.l}</text>`;
      if(!isOn)return;
      const k=on.indexOf(f),q=ease(clamp(reach*n-k)),w=f.par*q;
      if(q>0){const a=X(cum),b=X(cum+w),farRight=cum+f.par>150;
        s+=`<rect x="${f1(a)}" y="${y+4}" width="${f1(Math.max(.5,b-a))}" height="15" rx="2" style="fill:var(--prev);opacity:${k%2?.62:.95}"/>`;
        s+=`<text x="${f1(farRight?a-4:b+4)}" y="${y+15}" class="t-sm${farRight?' t-end':''}" style="fill:var(--ink);opacity:${f1(clamp(q*2))};paint-order:stroke;stroke:var(--panel);stroke-width:3px">${f.par.toFixed(1)}%</text>`;
        if(k>0)s+=`<line x1="${f1(a)}" x2="${f1(a)}" y1="${y-rh+19}" y2="${y+4}" style="stroke:var(--prev);stroke-width:1;stroke-dasharray:2 2"/>`;
        segs.push([cum,w,k]);cum+=w;prod*=1-w/100}});
    /* stacked sum */
    const ys=yEnd+14,yc=yEnd+54,fin=clamp(ramp(t,.8,.84));
    s+=`<text x="8" y="${ys+22}" class="t-lbl">Added up</text><text x="${x0}" y="${ys+4}" class="t-sm" style="fill:var(--ink);paint-order:stroke;stroke:var(--panel);stroke-width:3px">simple sum ${cum.toFixed(1)}%${cum>100?': no real meaning':''}</text>`;
    segs.forEach(([a,w,k])=>{s+=`<rect x="${f1(X(a))}" y="${ys+9}" width="${f1(Math.max(.5,X(a+w)-X(a)))}" height="15" style="fill:var(--prev);opacity:${k%2?.62:.95};stroke:var(--panel);stroke-width:.8"/>`});
    /* combined */
    const est=(1-prod)*100,all=n===10&&fin>0;
    s+=`<text x="8" y="${yc+22}" class="t-lbl">Combined</text><text x="${N?8:x0}" y="${yc+4}" class="t-sm" style="fill:var(--ink);paint-order:stroke;stroke:var(--panel);stroke-width:3px">teaching estimate ${est.toFixed(1)}%${all?'; published for all ten 90.7%':''}</text>`;
    s+=`<rect x="${f1(X(0))}" y="${yc+9}" width="${f1(X(est)-X(0))}" height="15" rx="2" style="fill:var(--salvage)"/>`;
    if(all)s+=`<line x1="${f1(X(90.7))}" x2="${f1(X(90.7))}" y1="${yc+6}" y2="${yc+27}" style="stroke:var(--ink);stroke-width:2.4"/>`;
    if(!n)s+=`<text x="${f1(W/2)}" y="${y0+120}" class="t-lbl t-mid">Switch on at least one factor above.</text>`;
    svg.innerHTML=s;
    const p=phaseOf(PV_STEPS,t);setSt(p);$('#pvNote').innerHTML=noteHTML(PV_STEPS[p])}
  const stop=playWire(rg,$('#pvPlay'),draw,16000,'Replay','prevent');
  const setSt=stepWire($('#pvSteps'),PV_STEPS,rg,draw,stop);
  const paint=()=>$$('[data-pvf]').forEach(b=>b.setAttribute('aria-pressed',sel.has(b.dataset.pvf)));
  $('#pvToggles').innerHTML=PV_F.map(f=>`<button class="btn" data-pvf="${f.id}" aria-pressed="true">${f.l}</button>`).join('');
  $('#pvToggles').addEventListener('click',e=>{const b=e.target.closest('[data-pvf]');if(!b)return;stop();sel.has(b.dataset.pvf)?sel.delete(b.dataset.pvf):sel.add(b.dataset.pvf);paint();if(+rg.value<.82)rg.value=.81;draw(+rg.value)});
  $('#pvAll').addEventListener('click',()=>{stop();PV_F.forEach(f=>sel.add(f.id));paint();draw(+rg.value)});
  draw(+rg.value);

  /* ---------- trials explorer ---------- */
  const fs=$('#pvFor'),frg=$('#pvForT');let fk='bp',fi=0;
  function drawFor(t){const N=vb(fs,'720 348','400 560'),D=PV_TR[fk],W=N?400:720;
    const F=pvForest(N?18:18,D.rows,{N,W,p:t/.9,sel:fi,rh:26});
    let s=`<text x="${N?10:238}" y="11" class="t-xs">ratio, log scale. Diamond = estimate, line = 95% CI</text>`+F.svg;
    fs.innerHTML=s;
    const r=D.rows[fi];$('#pvForNote').innerHTML=`<div class="kicker">${D.name} · ${r.k}</div><h4>${r.t}</h4><p>${r.d}</p>`}
  const fstop=playWire(frg,$('#pvForPlay'),drawFor,8000,'Replay','prevent');
  pvRows(fs,'data-fr',i=>{fstop();fi=i;drawFor(+frg.value)});
  $$('[data-pvt]').forEach(b=>b.addEventListener('click',()=>{fstop();fk=b.dataset.pvt;fi=0;$$('[data-pvt]').forEach(c=>c.setAttribute('aria-pressed',c===b));frg.value=0;$('#pvForPlay').click()}));
  drawFor(+frg.value);

  /* ---------- one cigarette ---------- */
  const sm=$('#pvSmk'),srg=$('#pvSmkT');let sk='m';
  function drawSmk(t){const N=vb(sm,'720 300','400 470'),D=PV_SMK[sk],L=N?{x:44,y:24,w:330,h:220,bx:16,by:320,bw:368}:{x:52,y:24,w:360,h:220,bx:452,by:70,bw:250};
    const f=monoFn([ [0,1],[1,D.one],[20,D.tw] ]),up=20*t,C=curve(L.x,L.y,L.w,L.h,f,{x0:0,x1:20,y0:1,y1:2.3,upto:up,col:'var(--prev)',dot:true});
    let s=C.svg;
    [1,1.5,2].forEach(v=>{s+=`<text x="${L.x-6}" y="${f1(C.Y(v)+3)}" class="t-xs t-end">${v.toFixed(1)}</text><line x1="${L.x}" x2="${L.x+L.w}" y1="${f1(C.Y(v))}" y2="${f1(C.Y(v))}" class="grid"/>`});
    [0,1,10,20].forEach(v=>{s+=`<text x="${f1(C.X(v))}" y="${L.y+L.h+14}" class="t-xs t-mid">${v}</text>`});
    s+=`<text x="${L.x+L.w}" y="${L.y+L.h+28}" class="t-xs t-end">cigarettes a day</text><text x="${L.x}" y="${L.y-8}" class="t-xs">relative risk of stroke</text>`;
    if(up>=1)s+=`<text x="${f1(C.X(1)+12)}" y="${f1(C.Y(D.one)+18)}" class="t-sm" style="fill:var(--ink);font-weight:700;paint-order:stroke;stroke:var(--field);stroke-width:3px">1 a day: RR ${D.one.toFixed(2)}</text>`;
    if(up>=19.8)s+=`<text x="${f1(C.X(20)-10)}" y="${f1(C.Y(D.tw)-10)}" class="t-sm t-end" style="fill:var(--ink);font-weight:700;paint-order:stroke;stroke:var(--field);stroke-width:3px">20 a day: RR ${D.tw.toFixed(2)}</text>`;
    const q=ease(ramp(t,.08,.5));
    s+=`<text x="${L.bx}" y="${L.by-26}" class="t-lbl">${D.n}: one a day carries</text><text x="${L.bx}" y="${L.by+2}" class="t-big" style="font-size:26px">${Math.round(D.sh*q)}%</text><text x="${L.bx+56}" y="${L.by+1}" class="t-sm">of the excess risk of 20 a day</text>`;
    s+=`<rect x="${L.bx}" y="${L.by+12}" width="${L.bw}" height="16" rx="4" style="fill:var(--panel-2)"/><rect x="${L.bx}" y="${L.by+12}" width="${f1(L.bw*D.sh/100*q)}" height="16" rx="4" style="fill:var(--prev)"/>`;
    s+=`<text x="${L.bx}" y="${L.by+46}" class="t-xs">1 cigarette is 5% of 20 cigarettes,</text><text x="${L.bx}" y="${L.by+60}" class="t-xs">but far more than 5% of the excess risk.</text>`;
    sm.innerHTML=s}
  const sstop=playWire(srg,$('#pvSmkPlay'),drawSmk,7000,'Replay','prevent');
  $$('[data-pvs]').forEach(b=>b.addEventListener('click',()=>{sstop();sk=b.dataset.pvs;$$('[data-pvs]').forEach(c=>c.setAttribute('aria-pressed',c===b));drawSmk(+srg.value)}));
  drawSmk(+srg.value);

  /* ---------- salt substitute ---------- */
  const sa=$('#pvSalt');let saStop=null;
  function drawSalt(p){const N=vb(sa,'720 216','400 324'),x0=N?12:190,bw=N?300:430,rh=N?104:66,mx=50,X=v=>bw*v/mx;let s='';
    PV_SALT.forEach((r,i)=>{const y=(N?8:12)+i*rh,q=ease(clamp(p*1.3-i*.15));
      if(N)s+=`<text x="${x0}" y="${y+10}" class="t-lbl">${r.l}</text><text x="${x0}" y="${y+24}" class="t-xs">${r.r}</text>`;
      else s+=`<text x="${x0-12}" y="${y+18}" class="t-lbl t-end">${r.l}</text>`;
      const y1=N?y+32:y+2,y2=y1+22;
      s+=`<rect x="${x0}" y="${y1}" width="${f1(X(r.a)*q)}" height="18" rx="3" style="fill:var(--salvage)"/><rect x="${x0}" y="${y2}" width="${f1(X(r.b)*q)}" height="18" rx="3" style="fill:var(--device)"/>`;
      s+=`<text x="${f1(x0+X(r.a)*q+6)}" y="${y1+13}" class="t-xs" style="fill:var(--ink)">substitute ${r.a.toFixed(2)}</text><text x="${f1(x0+X(r.b)*q+6)}" y="${y2+13}" class="t-xs" style="fill:var(--ink)">regular salt ${r.b.toFixed(2)}</text>`;
      if(!N)s+=`<text x="${x0-12}" y="${y+32}" class="t-xs t-end">${r.r.replace(', not significantly higher','')}</text>`});
    sa.innerHTML=s}
  $('#pvSaltPlay').addEventListener('click',()=>{if(saStop)saStop();saStop=animate(1100,drawSalt,()=>{saStop=null})});
  drawSalt(1);
  const pr=redraws.prevent;redraws.prevent=()=>{pr&&pr();drawSalt(1)};
};
/* =============== 4.2 AF and antithrombotics =============== */
/* Widgets: AF to embolic stroke (main scrubber), CHA2DS2-VASc teaching calculator, warfarin icon array, DOAC forest
   (pvForest from module prevent), DOAC timing timeline, dual antiplatelet curve, appendage closure. */
const AF_STEPS=[
 {from:0,at:.07,k:'Step 1 · sinus rhythm',t:'A regular heartbeat',
  txt:'The strip shows a regular rhythm: each beat at the same interval, with a small wave from the atria before it. The atria squeeze in time and blood moves on through the heart. The drawing is schematic.',
  pt:'The top chambers of the heart squeeze in a steady rhythm.'},
 {from:.16,at:.27,k:'Step 2 · fibrillation',t:'The atria quiver',
  txt:'In atrial fibrillation (AF) the atria quiver and the beat becomes irregular. A state public health review describes AF as the causal mechanism of about 20% of acute ischaemic strokes <sup class="c" data-ref="Tai2023" title="Source 955"><a href="/stroke/sources/#src-Tai2023">955</a></sup>.',
  pt:'An irregular heartbeat called atrial fibrillation can form clots that travel to the brain <sup class="c" data-ref="Hart2007" title="Source 404"><a href="/stroke/sources/#src-Hart2007">404</a></sup>.',
  hook:'About 1 in 5 acute ischaemic strokes is attributed to AF in this review <sup class="c" data-ref="Tai2023" title="Source 955"><a href="/stroke/sources/#src-Tai2023">955</a></sup>.'},
 {from:.34,at:.46,k:'Step 3 · a clot forms',t:'A clot in the appendage',
  txt:'The drawing puts the clot in the left atrial appendage, the pouch that closure devices seal off <sup class="c" data-ref="Reddy2014,Whitlock2021" title="Source 829,1045"><a href="/stroke/sources/#src-Reddy2014">829,1045</a></sup>. Anticoagulants lower this risk a lot: adjusted-dose warfarin reduced stroke by 64% against control, and antiplatelets by 22% <sup class="c" data-ref="Hart2007" title="Source 404"><a href="/stroke/sources/#src-Hart2007">404</a></sup>.',
  hook:'Warfarin 64%, antiplatelets 22% stroke reduction in AF <sup class="c" data-ref="Hart2007" title="Source 404"><a href="/stroke/sources/#src-Hart2007">404</a></sup>.'},
 {from:.52,at:.62,k:'Step 4 · it breaks loose',t:'A piece leaves the heart',
  txt:'A fragment passes through the left ventricle and out through the aorta. The drawing shows the route only, not a measured event.',
  pt:'A piece of clot can break off and be carried along in the blood.'},
 {from:.68,at:.76,k:'Step 5 · the neck',t:'Up the neck arteries',
  txt:'From the aorta the fragment follows the arterial blood up the neck towards the brain. Module 1.2 shows the vessels, and module 1.4 sets cardioembolism among the other causes of ischaemic stroke.',
  pt:'The blood carries the clot up to the brain, where the arteries get narrower.'},
 {from:.83,at:.95,k:'Step 6 · the block',t:'A brain artery is blocked',
  txt:'The clot lodges in a middle cerebral artery, flow stops beyond it and tissue is injured. The centre is the core and the amber rim is the penumbra (module 1.3). A previous thromboembolism is one of the two 2-point items in the score below <sup class="c" data-ref="Olesen2011" title="Source 756"><a href="/stroke/sources/#src-Olesen2011">756</a></sup>.',
  pt:'Part of the brain loses its blood supply. If you think someone is having a stroke, call your local emergency number <sup class="c" data-ref="Harbison2003,Ekundayo2013" title="Source 274,398"><a href="/stroke/sources/#src-Harbison2003">274,398</a></sup>.'}];
const AF_CHAIN=['Regular rhythm','Atria quiver: AF','Clot in the appendage','Clot leaves the heart','Up the neck arteries','Brain artery blocked'];
/* score rows: [value, 1-year thromboembolism per 100 person-years] <sup class="c" data-ref="Olesen2011" title="Source 756"><a href="/stroke/sources/#src-Olesen2011">756</a></sup> */
const AF_RATE=[.78,2.01,3.71,5.92,9.27,15.26,19.74,21.50,22.38,23.64];
const AF_ITEMS=[{id:'chf',l:'Heart failure',p:1},{id:'htn',l:'Hypertension',p:1},{id:'dm',l:'Diabetes',p:1},{id:'pte',l:'Previous thromboembolism',p:2},{id:'vas',l:'Vascular disease',p:1}];
const AF_WAR={w:{k:36,n:'Warfarin',txt:'Adjusted-dose warfarin reduced stroke by 64% (49 to 74) vs control, in 6 trials and 2900 participants <sup class="c" data-ref="Hart2007" title="Source 404"><a href="/stroke/sources/#src-Hart2007">404</a></sup>.'},a:{k:78,n:'Antiplatelets',txt:'Antiplatelets reduced stroke by 22% (6 to 35) vs control. Warfarin beat antiplatelets by 39% (22 to 52) <sup class="c" data-ref="Hart2007" title="Source 404"><a href="/stroke/sources/#src-Hart2007">404</a></sup>.'}};
const AF_DOAC=[
 {l:'Stroke or systemic embolism',txt:'RR 0.81 (0.73 to 0.91)',v:.81,lo:.73,hi:.91},
 {l:'Haemorrhagic stroke',txt:'RR 0.49 (0.38 to 0.64)',v:.49,lo:.38,hi:.64},
 {l:'Intracranial haemorrhage',txt:'RR 0.48 (0.39 to 0.59)',v:.48,lo:.39,hi:.59},
 {l:'All-cause mortality',txt:'RR 0.90 (0.85 to 0.95)',v:.90,lo:.85,hi:.95},
 {l:'Gastrointestinal bleeding',txt:'RR 1.25 (1.01 to 1.55)',v:1.25,lo:1.01,hi:1.55}];
const AF_TIME=[
 {l:'ELAN, minor',e:[0,2],d:[3,4],r:''},
 {l:'ELAN, moderate',e:[0,2],d:[6,7],r:'all ELAN: 2.9% vs 4.1%, 30 days'},
 {l:'ELAN, major',e:[6,7],d:[12,14],r:''},
 {l:'TIMING',e:[0,4],d:[5,10],r:'6.89% vs 8.68%, 90 days'},
 {l:'OPTIMAS',e:[0,4],d:[7,14],r:'3.3% in each group, 90 days'},
 {l:'CATALYST, pooled',e:[0,4],d:[5,14],open:1,r:'2.1% vs 3.0%, 30 days'}];
const AF_DUR=[ ['CHANCE',21],['POINT',90],['THALES',30],['CHANCE-2',21] ];
const AF_LAA={
 pro:{n:'PROTECT AF',cmp:'warfarin',bars:[ ['Primary event, per 100 patient-years',2.3,3.8] ],
  txt:'707 people, device vs warfarin. Rate ratio 0.60; cardiovascular mortality HR 0.40 (0.21 to 0.75) <sup class="c" data-ref="Reddy2014" title="Source 829"><a href="/stroke/sources/#src-Reddy2014">829</a></sup>. Pooled with PREVAIL at 5 years, the composite (HR 0.820) and all stroke or embolism (HR 0.961) were not significant. Ischaemic stroke or embolism was numerically higher with closure (HR 1.71, p=0.080). Haemorrhagic stroke (HR 0.20) and post-procedure bleeding (HR 0.48) favoured closure <sup class="c" data-ref="Reddy2017" title="Source 830"><a href="/stroke/sources/#src-Reddy2017">830</a></sup>.'},
 laa:{n:'LAAOS III',cmp:'no closure',bars:[ ['Stroke or embolism, %',4.8,7.0] ],
  txt:'Closure added during cardiac surgery, with most people staying on anticoagulation. HR 0.67 (0.53 to 0.85) <sup class="c" data-ref="Whitlock2021" title="Source 1045"><a href="/stroke/sources/#src-Whitlock2021">1045</a></sup>. This tests closure on top of anticoagulants, not instead of them.'},
 opt:{n:'OPTION',cmp:'anticoagulant',bars:[ ['Non-procedural bleeding, %',8.5,18.1],['Death, stroke or embolism, %',5.3,5.8] ],
  txt:'1600 people after catheter ablation, 36 months. Superior on bleeding and noninferior on death, stroke or embolism <sup class="c" data-ref="Wazni2025" title="Source 1036"><a href="/stroke/sources/#src-Wazni2025">1036</a></sup>.'},
 cha:{n:'CHAMPION-AF',cmp:'NOAC',bars:[ ['Non-procedural bleeding, %',10.9,19.0],['CV death, stroke or embolism, %',5.7,4.8] ],
  txt:'3000 people suitable for anticoagulation. At 3 years the efficacy difference was 0.9 points (-0.8 to 2.6), noninferior with a 4.8-point margin. Bleeding HR 0.55 <sup class="c" data-ref="Doshi2026" title="Source 252"><a href="/stroke/sources/#src-Doshi2026">252</a></sup>.'},
 clo:{n:'CLOSURE-AF',cmp:'best medical care',bars:[ ['Primary composite, per 100 patient-years',16.8,13.3],['Serious adverse events, %',82.5,77.4] ],
  txt:'912 people in Germany, mean age 77.9, CHA2DS2-VASc 5.2, HAS-BLED 3.0. Closure was not noninferior (P=0.44) <sup class="c" data-ref="Landmesser2026" title="Source 536"><a href="/stroke/sources/#src-Landmesser2026">536</a></sup>.'}};
inits.af=()=>{
  /* ---------- AF to stroke ---------- */
  const svg=$('#afSvg'),rg=$('#afT');
  const R=Array.from({length:8},(_,i)=>i*49.5),I=[0,38,108,154,182,244,288,362];
  function ecg(x,y,w,h,af,sh){const id='afEcgClip';let d='';const bt=R.map((r,i)=>lerp(r,I[i],af));
    for(let px=0;px<=w;px+=1.5){const u=((px+sh)%396+396)%396;let dm=1e9;bt.forEach(b=>{[b,b+396,b-396].forEach(c=>{if(Math.abs(u-c)<Math.abs(dm))dm=u-c})});
      const a=Math.abs(dm);let v=a<4?(1-a/4)*h*.42:0;if(dm>4&&dm<8)v-=h*.08*(1-af);if(dm<-11&&dm>-21)v+=(1-af)*h*.1*Math.sin((dm+21)/10*Math.PI);
      if(af>0)v+=af*(Math.sin(px*.9+sh*.2)*1.6+Math.sin(px*.37)*1.2);d+=(px?'L':'M')+f1(x+px)+' '+f1(y+h*.62-v)}
    return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" style="fill:var(--field);stroke:var(--line)"/><path d="${d}" style="fill:none;stroke:var(--ink);stroke-width:1.5;stroke-linejoin:round"/>`}
  function draw(t){const N=vb(svg,'720 468','400 672'),bx=N?60:70,by=6,bs=.95,hs=.8,hx=bx+104.5-83.2,hy=280;
    const afv=ease(ramp(t,.16,.26)),th=ease(ramp(t,.34,.46)),em=ramp(t,.52,.67),neck=ramp(t,.68,.82),les=ease(ramp(t,.84,.97)),block=t>=.82,ph=t*5;
    const ex=[hx+104*hs,hy],m0=[bx+110*bs,by+206*bs],mE=[bx+101*bs,by+158*bs];
    let s='';
    s+=brainSide(bx,by,bs,{vessels:block?{occl:'m1',flow:1,ph}:{flow:1,ph},lesion:les>0?{core:34*les,penumbra:66*les,saved:0,mca:true}:null}).svg;
    /* the neck artery */
    s+=`<path d="M${f1(ex[0])} ${f1(ex[1]+4)}C${f1(ex[0]+8)} ${f1(ex[1]-26)} ${f1(m0[0]-8)} ${f1(m0[1]+26)} ${f1(m0[0])} ${f1(m0[1])}" style="fill:none;stroke:var(--artery-line);stroke-width:8"/><path d="M${f1(ex[0])} ${f1(ex[1]+4)}C${f1(ex[0]+8)} ${f1(ex[1]-26)} ${f1(m0[0]-8)} ${f1(m0[1]+26)} ${f1(m0[0])} ${f1(m0[1])}" style="fill:none;stroke:var(--artery);stroke-width:6"/>`;
    s+=kitLabel(ex[0]+12,(ex[1]+m0[1])/2+3,'neck artery');
    s+=heartAF(hx,hy,hs,{af:afv,ph:t*.6,thrombus:th*(em>=1?.65:1),embolus:em>0&&em<1?em:0,labels:true}).svg;
    if(neck>0&&!block){const P=[[ex[0],ex[1]],[ex[0]+3,ex[1]-20],[m0[0]-3,m0[1]+20],m0,[bx+108*bs,by+180*bs],mE],C=crPts(P,false,8),i=Math.min(C.length-1,Math.floor(neck*(C.length-1))),q=C[i];s+=clot(q[0],q[1],11,{seed:3})}
    /* rhythm strip, chain */
    const ex0=N?16:420,ew=N?368:286,ey=N?486:34;
    s+=`<text x="${ex0}" y="${ey-8}" class="t-sm" style="fill:var(--ink)">rhythm strip, schematic: ${afv>.5?'irregular':'regular'}</text>`+ecg(ex0,ey,ew,58,afv,t*2400);
    const cx=N?16:420,cy=N?572:128,crh=N?17:36,p=phaseOf(AF_STEPS,t);
    AF_CHAIN.forEach((l,i)=>{const y=cy+i*crh,on=i===p,past=i<p;
      if(i)s+=`<line x1="${cx+7}" x2="${cx+7}" y1="${y-crh+7}" y2="${y-7}" style="stroke:var(--line);stroke-width:2"/>`;
      s+=`<circle cx="${cx+7}" cy="${y}" r="${N?6:7}" style="fill:${on?'var(--bad)':past?'var(--muted)':'var(--panel)'};stroke:var(--muted);stroke-width:1.4"/><text x="${cx+22}" y="${y+4}" class="${on?'t-lbl':'t-sm'}">${l}</text>`});
    if(!N)s+=`<text x="420" y="372" class="t-big" style="font-size:24px">about 20%</text><text x="420" y="390" class="t-sm">of acute ischaemic strokes, as described</text><text x="420" y="405" class="t-sm">in a state public health review</text>`;
    svg.innerHTML=s;setSt(p);$('#afNote').innerHTML=noteHTML(AF_STEPS[p])}
  const stop=playWire(rg,$('#afPlay'),draw,18000,'Replay','af');
  const setSt=stepWire($('#afSteps'),AF_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---------- the calculator ---------- */
  const cs=$('#afCalc'),st={chf:false,htn:true,dm:false,pte:false,vas:false,age:'65',sex:'m',va:false};let shown=2,cStop=null;
  const score=()=>{let v=0;AF_ITEMS.forEach(i=>{if(st[i.id])v+=i.p});if(st.age==='65')v+=1;if(st.age==='75')v+=2;return {va:v,vasc:v+(st.sex==='f'?1:0)}};
  function drawCalc(p){const N=vb(cs,'720 270','400 270'),S=score(),x0=N?34:50,w=N?356:650,bw=w/10,y0=32,h=178,mx=25,Y=v=>y0+h-h*v/mx,cur=lerp(shown,S.vasc,p);let s='';
    s+=`<text x="${N?4:x0-6}" y="16" class="t-xs">thromboembolism per 100 person-years at 1 year${N?'':', by CHA2DS2-VASc, not on a vitamin K antagonist'}</text>`;
    [0,10,20].forEach(v=>{s+=`<line x1="${x0}" x2="${x0+w}" y1="${f1(Y(v))}" y2="${f1(Y(v))}" class="grid"/><text x="${x0-6}" y="${f1(Y(v)+3)}" class="t-xs t-end">${v}</text>`});
    AF_RATE.forEach((r,i)=>{const on=!st.va&&Math.abs(i-cur)<.5,x=x0+i*bw;
      s+=`<rect x="${f1(x+3)}" y="${f1(Y(r))}" width="${f1(bw-6)}" height="${f1(y0+h-Y(r))}" rx="3" style="fill:${on?'var(--prev)':'var(--panel-2)'};stroke:${on?'var(--ink)':'var(--line)'};stroke-width:${on?1.6:1}"/>`;
      s+=`<text x="${f1(x+bw/2)}" y="${f1(Y(r)-5)}" class="t-xs t-mid" style="fill:var(--ink)${on?';font-weight:700':''}">${N?r.toFixed(1):r.toFixed(2)}</text><text x="${f1(x+bw/2)}" y="${y0+h+15}" class="t-sm t-mid" style="fill:var(--ink)${on?';font-weight:700':''}">${i}</text>`});
    s+=`<text x="${x0+w}" y="${y0+h+32}" class="t-xs t-end">CHA2DS2-VASc score. Danish hospital cohort: rates run high.</text>`;
    if(st.va)s+=`<text x="${x0+4}" y="${y0+22}" class="t-lbl">CHA2DS2-VA has no rate column here: no bar is lit.</text>`;
    cs.innerHTML=s}
  function outCalc(){const S=score(),r=AF_RATE[S.vasc];
    $('#afCalcOut').innerHTML=st.va
     ?`<div class="kicker">ESC 2024 approach</div><h4>CHA2DS2-VA: ${S.va} of 8</h4><p>The same items without the sex point, so the maximum falls to 8 (derived from the item list) <sup class="c" data-ref="Olesen2011,ClueEspuny2025" title="Source 193,756"><a href="/stroke/sources/#src-Olesen2011">193,756</a></sup>. The 2024 ESC/EACTS guideline indicates CHA2DS2-VA as a replacement when no locally validated tool exists. That comes from a paper describing the guideline, because the guideline itself could not be read here <sup class="c" data-ref="ClueEspuny2025,VanGelder2024" title="Source 193,1000"><a href="/stroke/sources/#src-ClueEspuny2025">193,1000</a></sup>. Rates by CHA2DS2-VA and ESC treatment thresholds could not be confirmed here, so none is shown.</p>`
     :`<div class="kicker">How the scale scores these inputs</div><h4>CHA2DS2-VASc: ${S.vasc} of 9</h4><p>In the Danish cohort, a score of ${S.vasc} went with <b>${r.toFixed(2)}</b> thromboembolic events per 100 person-years at 1 year <sup class="c" data-ref="Olesen2011" title="Source 756"><a href="/stroke/sources/#src-Olesen2011">756</a></sup>. With the sex point removed, this person scores CHA2DS2-VA ${S.va}.</p><div class="callout"><p><b>A broader outcome than stroke.</b> This count includes peripheral embolism, ischaemic stroke and pulmonary embolism, in people admitted to hospital. So it runs higher than stroke rates alone <sup class="c" data-ref="Olesen2011" title="Source 756"><a href="/stroke/sources/#src-Olesen2011">756</a></sup>.</p></div>`}
  function setCalc(){const S=score();$$('[data-afc]').forEach(b=>b.setAttribute('aria-pressed',!!st[b.dataset.afc]));$$('[data-afa]').forEach(b=>b.setAttribute('aria-pressed',st.age===b.dataset.afa));$$('[data-afs]').forEach(b=>b.setAttribute('aria-pressed',st.sex===b.dataset.afs));$$('[data-afm]').forEach(b=>b.setAttribute('aria-pressed',(b.dataset.afm==='va')===st.va));
    outCalc();if(cStop)cStop();const from=shown;cStop=animate(350,p=>{shown=from;drawCalc(p)},()=>{shown=S.vasc;cStop=null;drawCalc(0)})}
  $('#afItems').innerHTML=AF_ITEMS.map(i=>`<button class="btn" data-afc="${i.id}" aria-pressed="false">${i.l} +${i.p}</button>`).join('');
  $('#afCalcBox').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.afc)st[d.afc]=!st[d.afc];else if(d.afa)st.age=d.afa;else if(d.afs)st.sex=d.afs;else if(d.afm)st.va=d.afm==='va';else return;setCalc()});
  shown=score().vasc;setCalc();drawCalc(0);

  /* ---------- warfarin ---------- */
  const ws=$('#afWar');let wk='w',wStop=null;
  function drawWar(p){const N=vb(ws,'720 244','400 470'),D=AF_WAR[wk],A=N?[100,34]:[60,40],B=N?[100,264]:[420,40],z=14;
    const k=Math.round(lerp(100,D.k,ease(p)));
    let s=`<text x="${A[0]}" y="${A[1]-12}" class="t-sm" style="fill:var(--ink)">without treatment: 100 strokes</text><text x="${B[0]}" y="${B[1]-12}" class="t-sm" style="fill:var(--ink)">${D.n}: ${k} strokes</text>`;
    s+=icons(A[0],A[1],{n:100,cols:10,k:100,size:z,gap:4,col:'var(--core)',shape:'dot'}).svg+icons(B[0],B[1],{n:100,cols:10,k,size:z,gap:4,col:'var(--core)',shape:'dot'}).svg;
    ws.innerHTML=s}
  function setWar(k){wk=k;$$('[data-afw]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.afw===k));$('#afWarNote').innerHTML=AF_WAR[k].txt;if(wStop)wStop();wStop=animate(1000,drawWar,()=>{wStop=null})}
  $$('[data-afw]').forEach(b=>b.addEventListener('click',()=>setWar(b.dataset.afw)));
  $('#afWarNote').innerHTML=AF_WAR.w.txt;drawWar(1);

  /* ---------- DOAC forest ---------- */
  const fs=$('#afFor');let fi=0;
  const AF_DN=['DOACs prevented more stroke and embolism than warfarin','Haemorrhagic stroke was about halved','Intracranial haemorrhage was about halved','Mortality was lower','Gastrointestinal bleeding was higher'];
  function drawFor(p){const N=vb(fs,'720 182','400 272'),F=pvForest(4,AF_DOAC,{N,W:N?400:720,p,sel:fi,rh:26,min:.35,max:1.75,ticks:[.5,1,1.5],lo:'lower with a DOAC',hi:'higher with a DOAC'});fs.innerHTML=F.svg;$('#afForNote').innerHTML=`${AF_DN[fi]}: ${AF_DOAC[fi].txt}, DOACs vs warfarin, 71 683 participants <sup class="c" data-ref="Ruff2014" title="Source 867"><a href="/stroke/sources/#src-Ruff2014">867</a></sup>.`}
  pvRows(fs,'data-fr',i=>{fi=i;drawFor(1)});drawFor(1);

  /* ---------- timing ---------- */
  const ts=$('#afTime'),trg=$('#afTimeT');
  function drawTime(t){const N=vb(ts,'720 290','400 396'),x0=N?12:136,w=N?376:340,X=d=>x0+w*d/14,y0=N?48:44,rh=N?52:36,day=t*14;let s='';
    s+=`<rect x="${N?12:136}" y="8" width="18" height="10" rx="2" style="fill:var(--tpa)"/><text x="${N?34:158}" y="17" class="t-xs" style="fill:var(--ink)">earlier start</text><rect x="${N?120:250}" y="8" width="18" height="10" rx="2" style="fill:var(--panel);stroke:var(--device);stroke-width:1.5;stroke-dasharray:3 2"/><text x="${N?142:272}" y="17" class="t-xs" style="fill:var(--ink)">later start</text>`;
    [0,2,4,6,8,10,12,14].forEach(d=>{const x=X(d);s+=`<line x1="${f1(x)}" x2="${f1(x)}" y1="${y0-6}" y2="${y0+rh*6}" class="grid"/><text x="${f1(x)}" y="${y0+rh*6+14}" class="t-xs t-mid">${d}</text>`});
    s+=`<text x="${x0+w}" y="${y0+rh*6+28}" class="t-xs t-end">days after the stroke</text>`;
    if(!N)s+=`<text x="492" y="${y0-14}" class="t-xs">composite, earlier vs later</text>`;
    const cx=X(day);s+=`<line x1="${f1(cx)}" x2="${f1(cx)}" y1="${y0-10}" y2="${y0+rh*6}" style="stroke:var(--ink);stroke-width:1.6"/>`;
    AF_TIME.forEach((r,i)=>{const y=y0+i*rh,by=N?y+18:y+2,bh=N?10:9,bar=(a,solid,yy)=>{const e=Math.min(day,a[1]);if(e<=a[0])return `<rect x="${f1(X(a[0]))}" y="${yy}" width="${f1(X(a[1])-X(a[0]))}" height="${bh}" rx="2" style="fill:none;stroke:var(--line);stroke-width:1"/>`;
        return `<rect x="${f1(X(a[0]))}" y="${yy}" width="${f1(X(a[1])-X(a[0]))}" height="${bh}" rx="2" style="fill:none;stroke:var(--line);stroke-width:1"/><rect x="${f1(X(a[0]))}" y="${yy}" width="${f1(X(e)-X(a[0]))}" height="${bh}" rx="2" style="${solid?'fill:var(--tpa)':'fill:var(--panel);stroke:var(--device);stroke-width:1.5;stroke-dasharray:3 2'}"/>`};
      s+=`<text x="${N?12:8}" y="${N?y+11:y+14}" class="t-sm" style="fill:var(--ink);paint-order:stroke;stroke:var(--panel);stroke-width:3px">${r.l}</text>`;
      if(r.r)s+=`<text x="${N?388:492}" y="${N?y+11:y+14}" class="t-sm${N?' t-end':''}" style="fill:var(--ink);paint-order:stroke;stroke:var(--panel);stroke-width:3px">${r.r}</text>`;
      s+=bar(r.e,true,by)+bar(r.d,false,by+bh+2);
      if(r.open&&day>=13.5)s+=`<text x="${f1(X(14)+3)}" y="${by+bh+11}" class="t-xs">${N?'':'or later'}</text>`});
    ts.innerHTML=s}
  playWire(trg,$('#afTimePlay'),drawTime,9000,'Replay','af');drawTime(+trg.value);

  /* ---------- dual antiplatelet curve ---------- */
  const ds=$('#afDapt'),drg=$('#afDaptT');
  const fC=monoFn([ [0,0],[21,7.8],[90,9.1] ]),fD=monoFn([ [0,0],[21,5.2],[90,6.5] ]);
  function drawDapt(t){const N=vb(ds,'720 356','400 490'),L=N?{x:66,y:22,w:318,h:190,by:252,rx:16,ry:366}:{x:74,y:22,w:420,h:200,by:264,rx:520,ry:44},up=t*90;
    const C=curve(L.x,L.y,L.w,L.h,fC,{x0:0,x1:90,y0:0,y1:10,upto:up,col:'var(--device)'});
    let s=C.svg;const xw=C.X(21);
    s+=`<rect x="${L.x}" y="${L.y}" width="${f1(xw-L.x)}" height="${L.h}" style="fill:var(--tpa);opacity:.14"/><text x="${f1(L.x+6)}" y="${L.y+14}" class="t-xs" style="fill:var(--ink)">first 21 days</text>`;
    let d='';const n=120;for(let i=0;i<=n;i++){const v=up*i/n;d+=(i?'L':'M')+f1(C.X(v))+' '+f1(C.Y(fD(v)))}
    if(up>0)s+=`<path d="${d}" style="fill:none;stroke:var(--tpa);stroke-width:2.8;stroke-linejoin:round"/><circle cx="${f1(C.X(up))}" cy="${f1(C.Y(fD(up)))}" r="5" style="fill:var(--tpa);stroke:var(--panel);stroke-width:2"/><circle cx="${f1(C.X(up))}" cy="${f1(C.Y(fC(up)))}" r="5" style="fill:var(--device);stroke:var(--panel);stroke-width:2"/>`;
    [0,5,10].forEach(v=>{s+=`<text x="${L.x-6}" y="${f1(C.Y(v)+3)}" class="t-xs t-end">${v}%</text>`});
    s+=`<text x="${L.x}" y="${L.y-8}" class="t-xs">cumulative stroke or major ischaemic event (pooled CHANCE and POINT)</text>`.replace('cumulative stroke or major ischaemic event (pooled CHANCE and POINT)',N?'events, pooled CHANCE and POINT':'cumulative events, pooled CHANCE and POINT');
    if(up>=40){s+=`<text x="${f1(C.X(90)-4)}" y="${f1(C.Y(9.1)-8)}" class="t-sm t-end" style="fill:var(--ink)">aspirin alone</text><text x="${f1(C.X(90)-4)}" y="${f1(C.Y(6.5)+16)}" class="t-sm t-end" style="fill:var(--ink)">dual therapy</text>`}
    /* how long each trial gave dual therapy */
    s+=`<text x="${L.x}" y="${L.by-6}" class="t-xs">days of dual therapy in each trial, same day scale</text>`;
    AF_DUR.forEach(([l,dd],i)=>{const y=L.by+i*19;s+=`<text x="${L.x-6}" y="${y+10}" class="t-xs t-end" style="fill:var(--ink)">${l}</text><rect x="${L.x}" y="${y+1}" width="${f1(C.X(dd)-L.x)}" height="11" rx="3" style="fill:var(--tpa);opacity:.7"/><text x="${f1(C.X(dd)+5)}" y="${y+10}" class="t-xs" style="fill:var(--ink)">${dd}</text>`});
    const axY=L.y+L.h+12;[21,90].forEach(v=>{s+=`<text x="${f1(C.X(v))}" y="${axY}" class="t-xs t-mid">day ${v}</text>`});
    const col=(x,y,h,a,b,g)=>`<text x="${x}" y="${y}" class="t-lbl">${h}</text><text x="${x}" y="${y+18}" class="t-sm">aspirin alone ${a}%</text><text x="${x}" y="${y+33}" class="t-sm">dual therapy ${b}%</text><text x="${x}" y="${y+50}" class="t-sm" style="fill:var(--ink);font-weight:700">gap ${g} points</text>`;
    if(up>=21)s+=col(L.rx,L.ry,'At day 21','7.8','5.2','2.6');
    if(up>=89.5)s+=N?col(208,L.ry,'At day 90','9.1','6.5','2.6'):col(L.rx,L.ry+84,'At day 90','9.1','6.5','2.6');
    if(!N&&up>=89.5)s+=`<text x="${L.rx}" y="${L.ry+160}" class="t-sm" style="fill:var(--ink)">The gap opens early, then</text><text x="${L.rx}" y="${L.ry+175}" class="t-sm" style="fill:var(--ink)">stops growing.</text>`;
    ds.innerHTML=s}
  playWire(drg,$('#afDaptPlay'),drawDapt,9000,'Replay','af');drawDapt(+drg.value);

  /* ---------- closure ---------- */
  const ls=$('#afLaa'),lrg=$('#afLaaT');let lk='cha';
  function drawLaa(t){const N=vb(ls,'720 290','400 430'),hs=1.15,hx=N?70:16,hy=8,D=AF_LAA[lk],T=(a,b)=>[hx+a*hs,hy+b*hs];
    const go=ease(ramp(t,.1,.6)),open=ease(ramp(t,.55,.85));
    let s=heartAF(hx,hy,hs,{af:.5,ph:t*.4,thrombus:.75,labels:true}).svg;
    const a=T(118,72),b=T(162,63),p=[lerp(a[0],b[0],go),lerp(a[1],b[1],go)],r=lerp(2,11,open)*hs;
    s+=`<path d="M${f1(a[0]-46)} ${f1(a[1]+22)}L${f1(p[0])} ${f1(p[1])}" style="fill:none;stroke:var(--device);stroke-width:2.2;opacity:${f1(1-ramp(t,.85,1))}"/>`;
    s+=`<g transform="rotate(-24 ${f1(p[0])} ${f1(p[1])})"><path d="M${f1(p[0]-3)} ${f1(p[1]-r)}Q${f1(p[0]+r*1.1)} ${f1(p[1])} ${f1(p[0]-3)} ${f1(p[1]+r)}Z" style="fill:var(--device);stroke:var(--ink);stroke-width:1"/></g>`;
    if(open>.9)s+=kitLabel(p[0]-4,p[1]+r+16,'device',{a:'m'});
    const bx=N?16:300,bw=N?230:290,by0=N?290:46;
    s+=`<text x="${bx}" y="${by0-20}" class="t-lbl">${D.n}: device vs ${D.cmp}</text>`;
    const q=ease(ramp(t,.3,.9));
    D.bars.forEach((r0,i)=>{const y=by0+i*72,mx=Math.max(r0[1],r0[2])*1.05;
      s+=`<text x="${bx}" y="${y}" class="t-sm" style="fill:var(--ink)">${r0[0]}</text><rect x="${bx}" y="${y+6}" width="${f1(bw*r0[1]/mx*q)}" height="16" rx="3" style="fill:var(--tpa)"/><text x="${f1(bx+bw*r0[1]/mx*q+5)}" y="${y+18}" class="t-sm" style="fill:var(--ink)">device ${r0[1].toFixed(1)}</text><rect x="${bx}" y="${y+26}" width="${f1(bw*r0[2]/mx*q)}" height="16" rx="3" style="fill:var(--device)"/><text x="${f1(bx+bw*r0[2]/mx*q+5)}" y="${y+38}" class="t-sm" style="fill:var(--ink)">${D.cmp} ${r0[2].toFixed(1)}</text>`});
    ls.innerHTML=s;$('#afLaaNote').innerHTML=`<div class="kicker">${D.n}</div><p>${D.txt}</p>`}
  const lstop=playWire(lrg,$('#afLaaPlay'),drawLaa,6000,'Replay','af');
  $('#afLaaBtns').innerHTML=Object.keys(AF_LAA).map(k=>`<button class="btn" data-afl="${k}" aria-pressed="${k===lk}">${AF_LAA[k].n}</button>`).join('');
  $('#afLaaBtns').addEventListener('click',e=>{const b=e.target.closest('[data-afl]');if(!b)return;lstop();lk=b.dataset.afl;$$('[data-afl]').forEach(c=>c.setAttribute('aria-pressed',c===b));drawLaa(+lrg.value)});
  drawLaa(+lrg.value);
  const pr=redraws.af;redraws.af=()=>{pr&&pr();drawCalc(0);drawWar(1);drawFor(1)};
};
/* =============== 4.3 Carotid disease and PFO =============== */
/* Widgets: plaque growth with NASCET and ECST measures (main scrubber), a measuring tool, NNT icon arrays,
   asymptomatic trial bars, RoPE points with stratum panels, PASCAL forest (pvForest from module prevent). */
const CRT_STEPS=[
 {from:0,at:.05,k:'Step 1 · the bifurcation',t:'A healthy bifurcation',
  txt:'The common carotid artery (CCA) divides in the neck into the internal carotid (ICA), which widens into a bulb and supplies the brain, and the external carotid (ECA). Trials of surgery asked which narrowings of the ICA are worth treating <sup class="c" data-ref="Barnett1991,ECST1998" title="Source 85,269"><a href="/stroke/sources/#src-Barnett1991">85,269</a></sup>.',
  pt:'Two big arteries in your neck carry blood to the brain. Each one splits in two, and this split is where a narrowing is measured.'},
 {from:.1,at:.22,k:'Step 2 · plaque',t:'Plaque narrows the bulb',
  txt:'As plaque builds on the far wall of the bulb, the channel for blood gets smaller. In NASCET, people with 70 to 99% stenosis who had medical treatment alone had a 26% risk of ipsilateral stroke at 2 years <sup class="c" data-ref="Barnett1991" title="Source 85"><a href="/stroke/sources/#src-Barnett1991">85</a></sup>.',
  pt:'Fatty build-up narrows the artery. How narrow it is, and whether it has caused symptoms, shapes what the trials found.'},
 {from:.34,at:.52,k:'Step 3 · NASCET',t:'Measuring the NASCET way',
  txt:'NASCET compares the narrowest lumen (N) with the normal ICA well beyond the bulb (D): stenosis = (1 - N/D) x 100. The percentage shown is computed from the drawing itself, so it shows the geometry and is not a clinical measurement.',
  hook:'NASCET: narrowest lumen against normal distal ICA. Below 50% there was no benefit (14.9% vs 18.7%, P=0.16) <sup class="c" data-ref="Barnett1998" title="Source 86"><a href="/stroke/sources/#src-Barnett1998">86</a></sup>.'},
 {from:.72,at:.8,k:'Step 4 · ECST',t:'The same lesion, another number',
  txt:'ECST estimated the original width of the bulb (E) as its reference. The same narrowing then gives a bigger percentage. On its own measure, surgery was worthwhile above about 80%: 3-year major stroke or death 26.5% control vs 14.9% surgery. Its surgical risk was 7.0% <sup class="c" data-ref="ECST1998" title="Source 269"><a href="/stroke/sources/#src-ECST1998">269</a></sup>. Re-measuring ECST angiograms the NASCET way gave highly consistent results <sup class="c" data-ref="Rothwell2003" title="Source 859"><a href="/stroke/sources/#src-Rothwell2003">859</a></sup>.',
  hook:'NASCET and ECST measure differently, so always ask which method a percentage uses <sup class="c" data-ref="Rothwell2003" title="Source 859"><a href="/stroke/sources/#src-Rothwell2003">859</a></sup>.'},
 {from:.86,at:.95,k:'Step 5 · pooled benefit',t:'Benefit by band',
  txt:'Pooled across 6092 people with symptomatic stenosis, the 5-year absolute reduction in ipsilateral ischaemic stroke was -2.2% below 30% (harm), 3.2% at 30 to 49%, 4.6% at 50 to 69% and 16.0% at 70% or more without near-occlusion. For near-occlusion it was 5.6% at 2 years and -1.7% at 5 years <sup class="c" data-ref="Rothwell2003" title="Source 859"><a href="/stroke/sources/#src-Rothwell2003">859</a></sup>.',
  pt:'If a neck artery is badly narrowed and has caused symptoms, surgery helped most. With a mild narrowing it did not help, and below 30% it did harm.',
  hook:'Symptomatic carotid: 70% or more gives 16% absolute 5-year gain, 50 to 69% gives 4.6%, below 30% is harmed <sup class="c" data-ref="Rothwell2003" title="Source 859"><a href="/stroke/sources/#src-Rothwell2003">859</a></sup>.'}];
const CRT_BANDS=[{l:'below 30%',v:-2.2,a:0,b:30},{l:'30 to 49%',v:3.2,a:30,b:50},{l:'50 to 69%',v:4.6,a:50,b:70},{l:'70% or more',v:16,a:70,b:101},{l:'near-occlusion',v:-1.7,a:-1,b:-1}];
const CRT_NNT={time:{n:'Time since last event',a:['Within 2 weeks',5],b:['After more than 12 weeks',125]},sex:{n:'Sex',a:['Men',9],b:['Women',36]},age:{n:'Age',a:['75 or over',5],b:['Under 65',18]}};
const CRT_ASY=[
 {l:'ACAS, 5 years',s:'60% or more',bars:[ ['surgery',5.1],['medical',11.0] ]},
 {l:'ACST-1, 5 years, net',s:'includes 3.1% perioperative',bars:[ ['surgery',6.4],['deferral',11.8] ]},
 {l:'ACST-1, 10 years, net',s:'gain 4.6% (1.2 to 7.9)',bars:[ ['surgery',13.4],['deferral',17.9] ]},
 {l:'SPACE-2, stopped early',s:'513 of 3640 planned',bars:[ ['surgery',2.5],['stenting',4.4],['medical',3.1] ]},
 {l:'CREST-2 stenting, 4 years',s:'P=0.02',bars:[ ['stenting',2.8],['medical',6.0] ]},
 {l:'CREST-2 surgery, 4 years',s:'P=0.24',bars:[ ['surgery',3.7],['medical',5.3] ]}];
const CRT_ROPE=[{id:'nh',l:'No hypertension'},{id:'nd',l:'No diabetes'},{id:'ns',l:'No prior stroke or TIA'},{id:'nm',l:'Non-smoker'},{id:'co',l:'Cortical infarct on imaging'}];
const CRT_AGE=[ ['18 to 29',5],['30 to 39',4],['40 to 49',3],['50 to 59',2],['60 to 69',1],['70 or over',0] ];
const CRT_STR=[{l:'0-3',f:0,r:20},{l:'4',f:38,r:12},{l:'5',f:34,r:7},{l:'6',f:62,r:8},{l:'7',f:72,r:6},{l:'8',f:84,r:6},{l:'9-10',f:88,r:2}];
const CRT_PAS=[
 {l:'Unlikely',txt:'HR 1.14 (0.53 to 2.46)',v:1.14,lo:.53,hi:2.46,arr:'-0.7%',af:'4.41%',sh:'14.6%',st5:'0.4% more strokes',af5:'4.6% more',why:'Neither high RoPE nor a high-risk feature.'},
 {l:'Possible',txt:'HR 0.38 (0.22 to 0.65)',v:.38,lo:.22,hi:.65,arr:'2.1%',af:'1.53%',sh:'48.4%',st5:'3.4% fewer strokes',af5:'1.1% more',why:'One of the two is present.'},
 {l:'Probable',txt:'HR 0.10 (0.03 to 0.35)',v:.10,lo:.03,hi:.35,arr:'2.1%',af:'0.65%',sh:'37.0%',st5:'2.5% fewer strokes',af5:'1.3% more',why:'Both are present.'}];
inits.carotid=()=>{
  /* ---------- plaque and the measures ---------- */
  const svg=$('#caSvg'),rg=$('#caT');
  function draw(t){const N=vb(svg,'720 424','400 606'),st=.9*ease(ramp(t,.1,.7)),na=t>=.34,ec=t>=.72,G=carotidBif(N?100:34,N?6:22,N?1.15:1.5,{stenosis:st,flow:1,ph:t*8,nascet:na,ecst:ec,labels:true});
    let s=G.svg;const pc=Math.max(0,(1-G.n/G.d)*100),pe=Math.max(0,(1-G.n/G.e)*100),x=N?12:330;
    let y=N?316:30;
    if(!na){s+=`<text x="${x}" y="${y}" class="t-lbl">Plaque: ${st>.02?'narrowing the bulb':'none yet'}</text><text x="${x}" y="${y+18}" class="t-sm">Scrub on to measure it.</text>`}
    else{s+=`<text x="${x}" y="${y}" class="t-sm" style="fill:var(--ink)">N narrowest lumen: ${G.n.toFixed(1)} px on this drawing</text><text x="${x}" y="${y+16}" class="t-sm" style="fill:var(--ink)">D normal distal ICA: ${G.d.toFixed(1)} px</text>`;
      if(ec)s+=`<text x="${x}" y="${y+32}" class="t-sm" style="fill:var(--ink)">E estimated bulb width: ${G.e.toFixed(1)} px</text>`;
      s+=`<text x="${x}" y="${y+60}" class="t-big" style="font-size:22px">NASCET ${Math.round(pc)}%</text>`;
      if(ec)s+=`<text x="${x+(N?190:190)}" y="${y+60}" class="t-big" style="font-size:22px">ECST ${Math.round(pe)}%</text>`}
    /* band chart */
    const cy=N?402:138,z=N?136:462,k=N?11:13,rh=N?33:36,cur=CRT_BANDS.findIndex(b=>pc>=b.a&&pc<b.b);
    s+=`<text x="${x}" y="${cy-4}" class="t-sm">5-year absolute reduction with surgery, % points</text>`;
    const Xv=v=>z+k*v;
    s+=`<line x1="${z}" x2="${z}" y1="${cy+4}" y2="${cy+6+rh*5}" style="stroke:var(--ink);stroke-width:1.2"/>`;
    CRT_BANDS.forEach((b,i)=>{const yy=cy+6+i*rh,on=na&&i===cur,a=Math.min(z,Xv(b.v)),w=Math.abs(k*b.v),reveal=t>=.86?1:.45;
      s+=`<rect x="${x-4}" y="${yy}" width="${N?380:386}" height="${rh-3}" rx="5" style="fill:${on?'var(--prev-soft)':'none'}"/><text x="${x}" y="${yy+rh/2+2}" class="${on?'t-lbl':'t-sm'}" style="${on?'':'fill:var(--ink)'}">${b.l}</text>`;
      s+=`<rect x="${f1(a)}" y="${yy+6}" width="${f1(w)}" height="${rh-15}" rx="2" style="fill:${b.v<0?'var(--core)':'var(--prev)'};opacity:${reveal}"/><text x="${f1(b.v<0?z+6:Xv(b.v)+5)}" y="${yy+rh/2+2}" class="t-sm" style="fill:var(--ink)">${b.v>0?'':'-'}${Math.abs(b.v).toFixed(1)}</text>`});
    svg.innerHTML=s;const p=phaseOf(CRT_STEPS,t);setSt(p);$('#caNote').innerHTML=noteHTML(CRT_STEPS[p])}
  const stop=playWire(rg,$('#caPlay'),draw,16000,'Replay','carotid');
  const setSt=stepWire($('#caSteps'),CRT_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---------- the measuring tool ---------- */
  const ms=$('#caMeas'),iN=$('#caN'),iD=$('#caD'),iE=$('#caE');
  function drawMeas(){const NN=vb(ms,'720 176','400 268'),n=+iN.value,d=+iD.value,e=+iE.value,x=NN?12:20,sc=NN?30:42,rh=44;
    const nas=Math.max(0,(1-n/d)*100),ecs=Math.max(0,(1-n/e)*100);
    const R=[ ['N, narrowest lumen',n,'var(--core)'],['D, normal distal ICA',d,'var(--device)'],['E, estimated bulb',e,'var(--device)']];let s='';
    R.forEach((r,i)=>{const y=8+i*(NN?46:rh);s+=`<text x="${x}" y="${y+10}" class="t-sm" style="fill:var(--ink)">${r[0]}: ${r[1].toFixed(1)}</text><rect x="${x}" y="${y+15}" width="${f1(r[1]*sc)}" height="16" rx="3" style="fill:${r[2]}"/>`});
    const rx=NN?12:540,ry=NN?174:44;
    s+=`<text x="${rx}" y="${ry}" class="t-big" style="font-size:22px">NASCET ${Math.round(nas)}%</text><text x="${rx}" y="${ry+34}" class="t-big" style="font-size:22px">ECST ${Math.round(ecs)}%</text>`;
    s+=`<text x="${rx}" y="${ry+56}" class="t-xs">${n>d?'N wider than D: reads as 0%':'(1 - N/D) and (1 - N/E), x 100'}</text>`;
    ms.innerHTML=s;
    const b=CRT_BANDS.find(k=>nas>=k.a&&nas<k.b)||CRT_BANDS[0];
    $('#caMeasOut').innerHTML=`<b>NASCET band: ${b.l}.</b> In the pooled symptomatic trials, this band had a 5-year absolute reduction of ${b.v.toFixed(1)} percentage points in ipsilateral ischaemic stroke with surgery <sup class="c" data-ref="Rothwell2003" title="Source 859"><a href="/stroke/sources/#src-Rothwell2003">859</a></sup>. Population figure, not a result for anyone. Near-occlusion cannot be detected from this sum and was analysed apart.`}
  [iN,iD,iE].forEach(i=>i.addEventListener('input',drawMeas));drawMeas();

  /* ---------- NNT ---------- */
  const nt=$('#caNnt');let nk='time',nStop=null;
  function drawNnt(p){const N=vb(nt,'720 112','400 176'),D=CRT_NNT[nk],z=11,A=N?[20,24]:[16,24],B=N?[20,86]:[372,24];
    const blk=(P,r)=>{const n=r[1],k=Math.ceil(n*ease(p)),I=icons(P[0],P[1]+6,{n:k,cols:25,k:1,size:z,gap:2,col:'var(--bad)',base:'var(--device)'});
      return `<text x="${P[0]}" y="${P[1]-8}" class="t-sm" style="fill:var(--ink)">${r[0]}: NNT ${n}</text>${I.svg}`};
    nt.innerHTML=blk(A,D.a)+blk(B,D.b)}
  function setNnt(k){nk=k;$$('[data-can]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.can===k));if(nStop)nStop();nStop=animate(1100,drawNnt,()=>{nStop=null})}
  $$('[data-can]').forEach(b=>b.addEventListener('click',()=>setNnt(b.dataset.can)));
  drawNnt(1);

  /* ---------- asymptomatic ---------- */
  const az=$('#caAsy'),arg=$('#caAsyT');
  function drawAsy(t){const N=vb(az,'720 296','400 398'),x0=N?12:214,sc=N?15:22;let y=N?8:22,s='';
    if(!N){[0,5,10,15].forEach(v=>{s+=`<line x1="${x0+v*sc}" x2="${x0+v*sc}" y1="14" y2="288" class="grid"/><text x="${x0+v*sc}" y="10" class="t-xs t-mid">${v}%</text>`})}
    CRT_ASY.forEach((r,i)=>{const q=ease(clamp(t*CRT_ASY.length*.95-i));
      s+=`<text x="${N?12:8}" y="${y+10}" class="t-sm" style="fill:var(--ink);font-weight:600">${r.l}</text>`;
      s+=`<text x="${N?388:8}" y="${N?y+10:y+24}" class="t-xs${N?' t-end':''}">${r.s}</text>`;
      let by=N?y+15:y;r.bars.forEach(b=>{const med=b[0]==='medical'||b[0]==='deferral',w=b[1]*sc*q;
        s+=`<rect x="${x0}" y="${by}" width="${f1(w)}" height="11" rx="2" style="${med?'fill:var(--device)':'fill:var(--prev)'}"/>`;
        if(q>.1)s+=`<text x="${f1(x0+w+5)}" y="${by+9.5}" class="t-xs" style="fill:var(--ink);opacity:${f1(q)}">${b[0]} ${b[1].toFixed(1)}%</text>`;by+=14});
      y=by+(N?9:9)});
    az.innerHTML=s}
  playWire(arg,$('#caAsyPlay'),drawAsy,8000,'Replay','carotid');drawAsy(+arg.value);

  /* ---------- RoPE ---------- */
  const ro=$('#caRope'),st={nh:true,nd:true,ns:true,nm:true,co:true,age:3,fe:false};let shown=0,rStop=null,view=null;
  const rope=()=>CRT_ROPE.reduce((a,i)=>a+(st[i.id]?1:0),0)+CRT_AGE[st.age][1];
  const strat=s=>s<=3?0:s>=9?6:s-3;
  function drawRope(p){const N=vb(ro,'720 280','400 280'),x0=N?12:80,w=N?376:600,bw=w/7,cur=lerp(shown,strat(rope()),ease(p)),pa=[{y:24,h:88,k:'f',t:'PFO-attributable fraction',mx:100},{y:154,h:88,k:'r',t:'2-year stroke or TIA recurrence',mx:25}];let s='';
    s+=`<rect x="${f1(x0+cur*bw+1)}" y="6" width="${f1(bw-2)}" height="256" rx="6" style="fill:var(--prev-soft)"/>`;
    pa.forEach(P=>{s+=`<text x="${x0+4}" y="${P.y-4+(P.k==='r'?0:0)}" class="t-sm" style="fill:var(--ink)">${P.t}</text>`;
      CRT_STR.forEach((c,i)=>{const v=c[P.k],h=P.h*v/P.mx,x=x0+i*bw;
        s+=`<rect x="${f1(x+bw*.2)}" y="${f1(P.y+P.h-h)}" width="${f1(bw*.6)}" height="${f1(h)}" rx="2" style="fill:${P.k==='f'?'var(--prev)':'var(--device)'}"/><text x="${f1(x+bw/2)}" y="${f1(P.y+P.h-h-3+(h<16?0:0))}" class="t-xs t-mid" style="fill:var(--ink);paint-order:stroke;stroke:var(--panel);stroke-width:2.5px">${v}%</text>`});
      s+=`<line x1="${x0}" x2="${x0+w}" y1="${P.y+P.h}" y2="${P.y+P.h}" class="axis"/>`});
    CRT_STR.forEach((c,i)=>{s+=`<text x="${f1(x0+i*bw+bw/2)}" y="258" class="t-sm t-mid" style="fill:var(--ink)">${c.l}</text>`});
    s+=`<text x="${x0+w}" y="276" class="t-xs t-end">RoPE score stratum</text>`;
    ro.innerHTML=s}
  /* ---------- PASCAL ---------- */
  const pz=$('#caPas');
  const cls=()=>{const a=rope()>=7,b=st.fe;return a&&b?2:a||b?1:0};
  function drawPas(){const N=vb(pz,'720 124','400 200'),c=view==null?cls():view,F=pvForest(4,CRT_PAS,{N,W:N?400:720,sel:c,rh:26,min:.025,max:3,ticks:[.05,.1,.25,.5,1,2],lo:'fewer strokes with closure',hi:'more',ax0:110,axW:430});pz.innerHTML=F.svg;
    const P=CRT_PAS[c];$('#caPasOut').innerHTML=`<div class="kicker">PASCAL · ${view==null?'from your inputs':'row chosen'}</div><h4>${P.l}</h4><p>${P.why} RoPE here is ${rope()}, ${rope()>=7?'in the high range (7 or more)':'below 7'}; high-risk feature ${st.fe?'present':'absent'}.</p><p>Closure vs medical therapy, pooled trials: stroke ${P.txt}, 2-year absolute reduction ${P.arr}, added AF beyond day 45 ${P.af} <sup class="c" data-ref="Kent2021" title="Source 492"><a href="/stroke/sources/#src-Kent2021">492</a></sup>. At 5 years, in ${P.sh} of people: ${P.st5}, late AF ${P.af5} <sup class="c" data-ref="Saver2026" title="Source 898"><a href="/stroke/sources/#src-Saver2026">898</a></sup>.</p>`;
    $$('#caPasTbl tbody tr').forEach((r,i)=>r.classList.toggle('hl',i===c))}
  function setRope(){const S=rope();$$('[data-car]').forEach(b=>b.setAttribute('aria-pressed',!!st[b.dataset.car]));$$('[data-caa]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.caa===st.age));$('#caFe').setAttribute('aria-pressed',st.fe);
    const c=CRT_STR[strat(S)];$('#caRopeOut').innerHTML=`<div class="kicker">How the scale scores these inputs</div><h4>RoPE ${S} of 10</h4><p>In the stratum ${c.l}, the PFO-attributable fraction was ${c.f}% and 2-year recurrence ${c.r}% <sup class="c" data-ref="Nouh2016" title="Source 745"><a href="/stroke/sources/#src-Nouh2016">745</a></sup>. A higher score makes it more likely that the PFO was the cause, and also goes with a lower chance of another stroke.</p>`;
    view=null;drawPas();if(rStop)rStop();const from=shown;rStop=animate(450,p=>{shown=from;drawRope(p)},()=>{shown=strat(S);rStop=null;drawRope(1)})}
  $('#caRopeItems').innerHTML=CRT_ROPE.map(i=>`<button class="btn" data-car="${i.id}" aria-pressed="true">${i.l} +1</button>`).join('');
  $('#caRopeAge').insertAdjacentHTML('beforeend',CRT_AGE.map((a,i)=>`<button class="btn" data-caa="${i}" aria-pressed="false">${a[0]} +${a[1]}</button>`).join(''));
  $('#caRopeBox').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.car)st[d.car]=!st[d.car];else if(d.caa)st.age=+d.caa;else if(b.id==='caFe')st.fe=!st.fe;else return;setRope()});
  pvRows(pz,'data-fr',i=>{view=i;drawPas()});
  shown=strat(rope());setRope();
  const pr=redraws.carotid;redraws.carotid=()=>{pr&&pr();drawMeas();drawNnt(1);drawRope(1);drawPas()};
};
/* =============== 5.1 Rehabilitation & recovery =============== */
/* Widgets: recovery curve scrubber with a plasticity drawing on one timeline; proportional recovery explorer with a
   simulated mathematical-coupling demo; deficit tabs with small charts; CPASS timing player; fluoxetine player.
   Every number comes from research pass H. Lines between published points are schematic and labelled so. */
const RHB_DOMS={
 adl:{b:'Daily activities',src:'<sup class="c" data-ref="Jorgensen1995" title="Source 471"><a href="/stroke/sources/#src-Jorgensen1995">471</a></sup>',groups:[
  {id:'all',b:'All strokes',pts:[ [6,80],[12.5,95] ]},
  {id:'mild',b:'Mild',pts:[ [3,80] ],best:8.5},
  {id:'mod',b:'Moderate',pts:[ [7,80] ],best:13},
  {id:'sev',b:'Severe',pts:[ [11.5,80] ],best:17},
  {id:'vsev',b:'Very severe',pts:[ [11.5,80] ],best:20}]},
 arm:{b:'Arm',src:'<sup class="c" data-ref="Nakayama1994" title="Source 701"><a href="/stroke/sources/#src-Nakayama1994">701</a></sup>',groups:[
  {id:'all',b:'All strokes',pts:[ [3,80],[9,95] ]},
  {id:'mild',b:'Mild weakness',pts:[ [3,80],[6,95] ]},
  {id:'sev',b:'Severe weakness',pts:[ [6,80],[11,95] ]}]},
 walk:{b:'Walking',src:'<sup class="c" data-ref="Jorgensen1995Walking" title="Source 473"><a href="/stroke/sources/#src-Jorgensen1995Walking">473</a></sup>',groups:[
  {id:'all',b:'All strokes',pts:[ [11,95] ]}]},
 lang:{b:'Language',src:'<sup class="c" data-ref="Pedersen1995" title="Source 779"><a href="/stroke/sources/#src-Pedersen1995">779</a></sup>',groups:[
  {id:'mild',b:'Mild aphasia',pts:[ [2,95] ]},
  {id:'mod',b:'Moderate aphasia',pts:[ [6,95] ]},
  {id:'sev',b:'Severe aphasia',pts:[ [10,95] ]}]}};
const RHB_STEPS=[
 {from:0,at:.03,k:'First days',t:'A sudden loss',
  txt:'The Copenhagen Stroke Study followed 1197 consecutive people with acute stroke from a catchment of 239,886, examined weekly. Initial severity was very severe in 19%, severe in 14%, moderate in 26%, mild in 41% <sup class="c" data-ref="Jorgensen1995,Jorgensen1995Part1" title="Source 471,472"><a href="/stroke/sources/#src-Jorgensen1995">471,472</a></sup>. Neuroplasticity is the nervous system\'s ability to reorganise structure, function and connections. Its common themes are experience dependence, time sensitivity, motivation and attention <span class="ev est">Established</span> <sup class="c" data-ref="Cramer2011" title="Source 207"><a href="/stroke/sources/#src-Cramer2011">207</a></sup>.',
  pt:'After a stroke, your brain can rewire itself. Practice helps it do this <sup class="c" data-ref="Cramer2011,Murphy2009" title="Source 207,695"><a href="/stroke/sources/#src-Cramer2011">207,695</a></sup>.'},
 {from:.13,at:.217,k:'Week 6',t:'80% at their best',
  txt:'In all strokes together, 80% reached their best in daily activities within 6 weeks (95% CI 5.3 to 6.7). Neurological recovery ran ahead by 2 weeks on average <sup class="c" data-ref="Jorgensen1995" title="Source 471"><a href="/stroke/sources/#src-Jorgensen1995">471</a></sup>. In animal models, a time-limited window of plasticity opens, with activity-dependent rewiring and strengthening of synapses <span class="ev est">Established in animals</span> <sup class="c" data-ref="Murphy2009" title="Source 695"><a href="/stroke/sources/#src-Murphy2009">695</a></sup>.',
  hook:'80% reach best ADL function by 6 weeks and 95% by 12.5 weeks <sup class="c" data-ref="Jorgensen1995" title="Source 471"><a href="/stroke/sources/#src-Jorgensen1995">471</a></sup>.'},
 {from:.32,at:.448,k:'Week 12.5',t:'95% at their best',
  txt:'Functional recovery was complete within 12.5 weeks (95% CI 11.6 to 13.4) in 95%. Time alone explained 16% to 42% of the improvement in the first 6 to 10 weeks in another study: 42% of Barthel change, 22% of walking categories, 19% of the Action Research Arm Test <sup class="c" data-ref="Jorgensen1995,Kwakkel2006" title="Source 471,527"><a href="/stroke/sources/#src-Jorgensen1995">471,527</a></sup>.',
  pt:'"Reached their best" is about each person\'s own best. It does not mean everyone is back to where they were.'},
 {from:.52,at:.61,k:'Up to week 20',t:'Bigger strokes take longer',
  txt:'Best function was reached within 8.5 weeks after a mild stroke, 13 after moderate, 17 after severe and 20 after very severe. The authors warned their tables should not be used to select who gets rehabilitation, because "even the most severe cases regularly experience meaningful improvement" <sup class="c" data-ref="Jorgensen1995,Jorgensen1995Part1" title="Source 471,472"><a href="/stroke/sources/#src-Jorgensen1995">471,472</a></sup>.',
  pt:'Try the Severe and Very severe buttons above. The line reaches its top later, and there is still a climb.'},
 {from:.7,at:.8,k:'About 5 months',t:'The old stopping point',
  txt:'The same authors wrote that recovery "should not be expected after the first 5 months" <sup class="c" data-ref="Jorgensen1995" title="Source 471"><a href="/stroke/sources/#src-Jorgensen1995">471</a></sup>. Later data challenge this. Decline is real too: in Sweden, dependency rose from 16.2% at 3 months to 28.3% at 12 months <sup class="c" data-ref="Ullberg2015" title="Source 992"><a href="/stroke/sources/#src-Ullberg2015">992</a></sup>.'},
 {from:.87,at:.95,k:'Months and years later',t:'Still room to gain',
  txt:'Queen Square: 90 hours over 3 weeks in 224 people, median 18 months after stroke. Median Fugl-Meyer Upper Limb 26 to 37 and ARAT 18 to 27 from admission to 6 months, with no control group described in the abstract <sup class="c" data-ref="Ward2019" title="Source 1028"><a href="/stroke/sources/#src-Ward2019">1028</a></sup>. VNS-REHAB and FCET2EC, both randomised, also found gains long after stroke <sup class="c" data-ref="Dawson2021,Breitenstein2017" title="Source 128,218"><a href="/stroke/sources/#src-Dawson2021">128,218</a></sup>. Language recovery continued, less, beyond 6 months <sup class="c" data-ref="RELEASE2021" title="Source 836"><a href="/stroke/sources/#src-RELEASE2021">836</a></sup>.',
  pt:'Getting better can continue with the right practice, even long after the stroke <sup class="c" data-ref="Ward2019" title="Source 1028"><a href="/stroke/sources/#src-Ward2019">1028</a></sup>.'}];
const RHB_PR_NOTES={
 rule:{k:'The rule',t:'About 70% of what was lost',
  txt:'In 41 people with ischaemic stroke, clinical variables explained 47% of variance in arm recovery. With a set of severe, poorly recovering outliers removed, this rose to 89%, and recovery approximated 0.70 x initial impairment <sup class="c" data-ref="Prabhakaran2008" title="Source 810"><a href="/stroke/sources/#src-Prabhakaran2008">810</a></sup>. A replication gave predicted change = 0.7 x (66 - initial score) + 0.4. In 211 people, about 70% (n=146) showed recovery of about 78%, and 65 did worse than predicted <sup class="c" data-ref="Winters2015" title="Source 1055"><a href="/stroke/sources/#src-Winters2015">1055</a></sup>.',
  hook:'Proportional recovery: about 0.7 of initial impairment, except a subgroup with severe impairment <sup class="c" data-ref="Prabhakaran2008,Winters2015" title="Source 810,1055"><a href="/stroke/sources/#src-Prabhakaran2008">810,1055</a></sup>.'},
 crit:{k:'The critique',t:'Could it be arithmetic?',
  txt:'Hope and colleagues argued that headline correlations are "likely inflated". Recovery is final score minus start score, so the start score is built into it. Correlations between baseline and recovery become extreme when outcomes vary less than baselines, regardless of the true relationship <sup class="c" data-ref="Hope2019" title="Source 437"><a href="/stroke/sources/#src-Hope2019">437</a></sup>. The dots here are simulated: final scores are drawn at random, with no link to the start score. Move the lower slider and watch the left-hand strength.',
  hook:'Statistical coupling may inflate the proportional recovery correlation <sup class="c" data-ref="Hope2019" title="Source 437"><a href="/stroke/sources/#src-Hope2019">437</a></sup>.'},
 rej:{k:'The rejoinder',t:'True for groups, not for one person',
  txt:'Kundert and colleagues replied that existing data are "largely consistent" with the rule as a population-level model for arm motor recovery, and that reports of its demise "are exaggerated" because they focus on individual prediction. About 30% with severe paresis do not follow it <sup class="c" data-ref="Kundert2019" title="Source 522"><a href="/stroke/sources/#src-Kundert2019">522</a></sup>.',
  pt:'This rule describes groups. It cannot tell one person how far they will get.'}};
const RHB_CP_STEPS=[
 {from:0,at:.14,k:'In animals',t:'A window in rats',
  txt:'Rats given 5 weeks of enriched rehabilitation starting at 5 days improved markedly, at 14 days somewhat less, and at 30 days no better than social housing. Dendritic growth in undamaged motor cortex tracked this <sup class="c" data-ref="Biernaskie2004" title="Source 104"><a href="/stroke/sources/#src-Biernaskie2004">104</a></sup>.'},
 {from:.2,at:.625,k:'In people',t:'CPASS: 20 extra hours',
  txt:'20 extra hours of self-selected task-specific therapy. By 1 year, the Action Research Arm Test difference versus controls was +5.25 ± 2.59 (P=0.043) when begun at 30 days or less, +6.87 ± 2.63 (P=0.009) at 2 to 3 months, and +2.41 ± 2.25 (P=0.29) at 6 months or later <sup class="c" data-ref="Dromerick2021" title="Source 256"><a href="/stroke/sources/#src-Dromerick2021">256</a></sup>.',
  hook:'CPASS: extra therapy worked best at 2 to 3 months <sup class="c" data-ref="Dromerick2021" title="Source 256"><a href="/stroke/sources/#src-Dromerick2021">256</a></sup>.'},
 {from:.63,at:.67,k:'Reading it well',t:'Phase II, not the last word',
  txt:'<span class="ev early">Early evidence</span> CPASS is a phase II trial <sup class="c" data-ref="Dromerick2021" title="Source 256"><a href="/stroke/sources/#src-Dromerick2021">256</a></sup>. It suggests timing matters. It does not show that therapy stops helping later on, and the 2026 guideline still states that uncertainty remains on timing and dosing <sup class="c" data-ref="Richards2026" title="Source 843"><a href="/stroke/sources/#src-Richards2026">843</a></sup>.',
  pt:'If you are past 6 months, this does not mean the door has closed. Read on.'},
 {from:.7,at:.92,k:'A counterpoint',t:'Queen Square',
  txt:'90 hours over 3 weeks in 224 people, median 18 months after stroke. Median scores, admission to 6 months: Fugl-Meyer Upper Limb 26 to 37, ARAT 18 to 27, CAHAI 40 to 52, ArmA-A 8 to 3, ArmA-B 38 to 19 (lower ArmA is better). Gains continued during follow-up. No control group is described in the abstract <sup class="c" data-ref="Ward2019" title="Source 1028"><a href="/stroke/sources/#src-Ward2019">1028</a></sup>.'}];
const RHB_FL_STEPS=[
 {from:0,at:.16,k:'2011 · FLAME',t:'A hopeful small trial',
  txt:'118 people with moderate to severe motor deficit. Fugl-Meyer improvement at day 90 was 34.0 points with fluoxetine 20 mg versus 24.3 with placebo (p=0.003) <sup class="c" data-ref="Chollet2011" title="Source 186"><a href="/stroke/sources/#src-Chollet2011">186</a></sup>.',
  pt:'Fluoxetine is an antidepressant. It was once hoped to help movement recover.'},
 {from:.24,at:.5,k:'2019 to 2020',t:'Three large trials',
  txt:'FOCUS (n=3127), AFFINITY (n=1280) and EFFECTS (n=1500) all looked at the modified Rankin Scale. Common odds ratios 0.951, 0.94 and 0.94, and every confidence interval crosses 1 <sup class="c" data-ref="Dennis2019,Hankey2020,Lundstrom2020" title="Source 238,392,602"><a href="/stroke/sources/#src-Dennis2019">238,392,602</a></sup>.'},
 {from:.52,at:.74,k:'Benefit and harm',t:'Less depression, more fractures',
  txt:'New depression fell, in FOCUS 13.43% versus 17.21% and in EFFECTS 7% versus 11%. Fractures rose in all three. AFFINITY also found more falls and seizures, and EFFECTS more hyponatraemia <sup class="c" data-ref="Dennis2019,Hankey2020,Lundstrom2020" title="Source 238,392,602"><a href="/stroke/sources/#src-Dennis2019">238,392,602</a></sup>.',
  pt:'Big trials found it did not help movement recover, and it raised the chance of broken bones <sup class="c" data-ref="Dennis2019" title="Source 238"><a href="/stroke/sources/#src-Dennis2019">238</a></sup>.'},
 {from:.8,at:.92,k:'The lesson',t:'Why three trials agree',
  txt:'<span class="ev est">Established</span> FOCUS, AFFINITY and EFFECTS were designed collaboratively with the same basic protocol, so their agreement is strong evidence <sup class="c" data-ref="Mead2020,Dennis2019,Hankey2020,Lundstrom2020" title="Source 238,392,602,651"><a href="/stroke/sources/#src-Mead2020">238,392,602,651</a></sup>. Cochrane 2021 (76 studies, 13,029 participants): in low risk of bias studies, no difference in disability (SMD -0.0, -0.05 to 0.05) or independence (RR 0.98, 0.93 to 1.03), less depression (RR 0.75, 0.65 to 0.86), more fractures (RR 2.35, 1.62 to 3.41) and seizures (RR 1.40, 1.00 to 1.98). "When all studies, irrespective of risk of bias, were included", SSRIs reduced disability scores but not the proportion independent <sup class="c" data-ref="Legg2021" title="Source 565"><a href="/stroke/sources/#src-Legg2021">565</a></sup>. The 2026 guideline cites a meta-analysis of the three trials (n=5907): no effect on mRS, with very low absolute risks of the harms <sup class="c" data-ref="Richards2026" title="Source 843"><a href="/stroke/sources/#src-Richards2026">843</a></sup>.',
  hook:'Fluoxetine: no functional benefit, less depression, more fractures <sup class="c" data-ref="Dennis2019,Hankey2020,Lundstrom2020,Legg2021" title="Source 238,392,565,602"><a href="/stroke/sources/#src-Dennis2019">238,392,565,602</a></sup>.'}];
/* charts for the tabs, values all from research: h = heading; v = one bar; lo/hi = a range; segs = stacked (mrs index i) */
const RHB_CHARTS={
 arm:[{h:'Full arm function reached, Copenhagen'},{l:'Mild weakness',v:79,txt:'79%'},{l:'Severe weakness',v:18,txt:'18%'},
  {h:'RATULS: ARAT success at 3 months'},{l:'Robot training',v:44,txt:'44%'},{l:'Enhanced therapy',v:50,txt:'50%'},{l:'Usual care',v:42,txt:'42%'}],
 walk:[{h:'Walking, Copenhagen (804 people)'},
  {l:'At onset: cannot walk, with help, independent',segs:[{v:51,i:5},{v:12,i:3},{v:37,i:1}]},
  {l:'End of rehabilitation: died, cannot walk, with help, independent',ln:'End of rehab: died, cannot walk, with help, independent',segs:[{v:21,i:6},{v:18,i:5},{v:11,i:3},{v:50,i:1}]}],
 aph:[{h:'Aphasia, Copenhagen (881 people)'},{l:'At admission',v:38,txt:'38%'},{l:'At discharge',v:18,txt:'18%'},
  {h:'Median frequency, mixed stroke (review)'},{l:'Acute',v:30,txt:'30%'},{l:'Rehabilitation',v:34,txt:'34%'}],
 swl:[{h:'Dysphagia depends on how you look for it'},{l:'Cursory screening',lo:37,hi:45,txt:'37% to 45%'},{l:'Clinical testing',lo:51,hi:55,txt:'51% to 55%'},{l:'Instrumental testing',lo:64,hi:78,txt:'64% to 78%'},
  {h:'At 6 months, among survivors (128 people at start)'},{l:'Back on their prestroke diet',v:87,txt:'87%'}],
 spa:[{h:'Spasticity prevalence, range across studies'},{l:'1 to 4 weeks',lo:4,hi:27,txt:'4% to 27%'},{l:'1 to 3 months',lo:19,hi:26.7,txt:'19% to 26.7%'},{l:'Beyond 3 months',lo:17,hi:42.6,txt:'17% to 42.6%'},{l:'Disabling spasticity',lo:2,hi:13,txt:'2% to 13%'}],
 vis:[{h:'Spatial neglect (6324 people, 41 articles)'},{l:'After right brain damage',v:38,txt:'38%'},{l:'After left brain damage',v:18,txt:'18%'},
  {h:'Visual field loss at follow-up'},{l:'Full recovery, improvement, no recovery',segs:[{v:7.5,i:1},{v:39,i:3},{v:52,i:4}]}],
 avert:[{h:'AVERT: favourable outcome at 3 months'},{l:'Very early, higher dose',v:46,txt:'46%'},{l:'Usual care',v:50,txt:'50%'},
  {h:'AVERT: mobilised within 24 hours'},{l:'Very early, higher dose',v:92,txt:'92%'},{l:'Usual care',v:59,txt:'59%'}]};
/* shared with 5.2: draws heading, bar, range and stacked rows into an svg, each row's label on its own line */
function rhbBars(svg,rows,o={}){
  const col=o.col||'var(--rec)',N=NARROW()||o.W===400,W=N?400:720,x0=4,bw=W-x0-92,X=v=>x0+bw*v/100;let y=2,s='';
  rows.forEach(r=>{
    if(r.h){y+=y>2?14:0;s+=`<text x="${x0}" y="${f1(y+12)}" class="t-lbl">${r.h}</text>`;y+=22;return}
    const lab=N&&r.ln?r.ln:r.l;
    s+=`<text x="${x0}" y="${f1(y+11)}" class="t-sm">${lab}</text>`;
    const by=y+16,bh=14;
    s+=`<rect x="${x0}" y="${by}" width="${f1(r.segs?W-x0*2:bw)}" height="${bh}" rx="3" style="fill:var(--panel-2)"/>`;
    if(r.segs){const tot=r.segs.reduce((a,g)=>a+g.v,0),full=W-x0*2;let cx=x0;
      r.segs.forEach(g=>{const w=full*g.v/tot;s+=`<rect x="${f1(cx)}" y="${by}" width="${f1(Math.max(0,w-1))}" height="${bh}" style="fill:var(--mrs${g.i})"/><text x="${f1(cx+w/2)}" y="${by+11}" class="t-sm t-mid" style="fill:var(--mrs-on${g.i})">${g.v}%</text>`;cx+=w})}
    else if(r.lo!=null){s+=`<rect x="${f1(X(r.lo))}" y="${by}" width="${f1(X(r.hi)-X(r.lo))}" height="${bh}" rx="3" style="fill:${col}"/><text x="${f1(X(r.hi)+6)}" y="${by+11}" class="t-sm" style="fill:var(--ink)">${r.txt}</text>`}
    else{s+=`<rect x="${x0}" y="${by}" width="${f1(X(r.v)-x0)}" height="${bh}" rx="3" style="fill:${col}"/><text x="${f1(X(r.v)+6)}" y="${by+11}" class="t-sm" style="fill:var(--ink)">${r.txt}</text>`}
    y+=38});
  svg.setAttribute('viewBox',`0 0 ${W} ${f1(y+2)}`);svg.innerHTML=s}
/* a label with a halo, for use over plotted lines */
function rhbLab(x,y,t,o={}){return `<text x="${f1(x)}" y="${f1(y)}" class="${o.c||'t-sm'}${o.a?' '+o.a:''}" style="fill:var(--ink);paint-order:stroke;stroke:var(--panel);stroke-width:3px;stroke-linejoin:round;${o.st||''}">${t}</text>`}
/* plasticity panel: a small brain for context, then neurons around a lesion. Lost links go faint, new routes grow round it. */
const RHB_NEU=[ [.1,.2],[.36,.1],[.66,.1],[.9,.22],[.1,.8],[.36,.92],[.66,.92],[.9,.78] ];
const RHB_LOST=[ [1,6],[2,5],[0,7] ];
const RHB_ROUTES=[ {a:1,b:5,c:[.06,.5],w0:1.5,w1:8},{a:2,b:6,c:[.94,.5],w0:2.5,w1:10},{a:0,b:3,c:[.5,.2],w0:5,w1:14},{a:4,b:7,c:[.5,.8],w0:7,w1:19} ];
function rhbPlastic(L,wk,lat,t){
  const {px,py,pw,ph}=L,nb={x:px+12,y:py+94,w:pw-24,h:ph-138};
  const P=q=>[nb.x+nb.w*q[0],nb.y+nb.h*q[1]];
  let s=`<rect x="${px}" y="${py}" width="${pw}" height="${ph}" rx="10" style="fill:var(--field);stroke:var(--line)"/>`;
  const les=ramp(t,0,.02),lc=P([.5,.5]),lr=Math.min(nb.w,nb.h)*.19*les;
  const br=brainSide(px+8,py+8,.28,{lesion:{core:30*les,penumbra:0,mca:true},id:'rhbbr'});
  s+=br.svg;
  s+=`<text x="${px+102}" y="${py+30}" class="t-lbl">Beside the injury</text><text x="${px+102}" y="${py+47}" class="t-sm">zoomed in, schematic</text>`;
  /* links lost when the lesion formed */
  RHB_LOST.forEach(([a,b])=>{const A=P(RHB_NEU[a]),B=P(RHB_NEU[b]);
    s+=`<line x1="${f1(A[0])}" y1="${f1(A[1])}" x2="${f1(B[0])}" y2="${f1(B[1])}" style="stroke:var(--muted);stroke-width:1.3;stroke-dasharray:${les>=1?'3 4':'none'};opacity:${f1(lerp(.9,.35,ramp(wk,0,10)))}"/>`});
  if(les>0){s+=`<path d="${blob(lc[0],lc[1],lr,5,{n:18,rough:.14})}" style="fill:var(--core);fill-opacity:.22;stroke:var(--core);stroke-width:1.6"/>`;
    if(les>=1){s+=neuron(lc[0]-14,lc[1]-10,8,{state:'dead',axon:0,seed:3})+neuron(lc[0]+14,lc[1]-4,8,{state:'dead',axon:0,seed:8})}}
  /* new routes */
  const qp=(R,u)=>{const A=P(RHB_NEU[R.a]),B=P(RHB_NEU[R.b]),C=P(R.c),m=1-u;return [m*m*A[0]+2*m*u*C[0]+u*u*B[0],m*m*A[1]+2*m*u*C[1]+u*u*B[1]]};
  RHB_ROUTES.forEach((R,i)=>{const g=ramp(wk,R.w0,R.w1);if(g<=0)return;
    const A=P(RHB_NEU[R.a]),B=P(RHB_NEU[R.b]),C=P(R.c),sw=1.8+lat*1.8;
    s+=`<path d="M${f1(A[0])} ${f1(A[1])}Q${f1(C[0])} ${f1(C[1])} ${f1(B[0])} ${f1(B[1])}" pathLength="1" style="fill:none;stroke:var(--rec);stroke-width:${f1(sw)};stroke-linecap:round;stroke-dasharray:${g.toFixed(3)} 1.2"/>`;
    if(g<1){const q=qp(R,g);s+=`<circle cx="${f1(q[0])}" cy="${f1(q[1])}" r="3.4" style="fill:var(--rec);stroke:var(--panel);stroke-width:1"/>`}
    else{const q=qp(R,(t*26+i*.27)%1);s+=`<circle cx="${f1(q[0])}" cy="${f1(q[1])}" r="3.2" style="fill:var(--gold);stroke:var(--panel);stroke-width:1"/>`;
      s+=`<circle cx="${f1(B[0])}" cy="${f1(B[1])}" r="${f1(11)}" style="fill:none;stroke:var(--rec);stroke-width:1;opacity:.5"/>`}});
  RHB_NEU.forEach((q,i)=>{const p=P(q),near=i===1||i===2||i===5||i===6;
    s+=neuron(p[0],p[1],7.5,{state:near&&wk<2&&les>0?'stressed':'alive',axon:0,seed:i+2})});
  if(les>=1)s+=rhbLab(lc[0],lc[1]+22,'lesion',{a:'t-mid',c:'t-xs'});
  /* legend, with line samples so it does not rely on colour */
  const ly=py+ph-16,lx=px+14;
  s+=`<line x1="${lx}" x2="${lx+24}" y1="${ly-3}" y2="${ly-3}" style="stroke:var(--muted);stroke-width:1.3;stroke-dasharray:3 4"/><text x="${lx+30}" y="${ly}" class="t-sm">lost link</text>`;
  s+=`<line x1="${lx+106}" x2="${lx+130}" y1="${ly-3}" y2="${ly-3}" style="stroke:var(--rec);stroke-width:2.4"/><text x="${lx+136}" y="${ly}" class="t-sm">new route</text>`;
  return s}
inits.rehab=()=>{
  /* ---- recovery curve ---- */
  const svg=$('#rhbSvg'),rg=$('#rhbT');let dom='adl',grp='all';
  const domEl=$('#rhbDom'),grpEl=$('#rhbGrp');
  function pickerHTML(){domEl.innerHTML='<span class="stage-cap">Kind</span>'+Object.keys(RHB_DOMS).map(k=>`<button class="btn" data-d="${k}" aria-pressed="${k===dom}">${RHB_DOMS[k].b}</button>`).join('');
    grpEl.innerHTML='<span class="stage-cap">Group</span>'+RHB_DOMS[dom].groups.map(g=>`<button class="btn" data-g="${g.id}" aria-pressed="${g.id===grp}">${g.b}</button>`).join('')}
  const seriesPts=g=>{const P=[ [0,0],...g.pts ];if(g.best)P.push([g.best,98]);return P};
  function draw(t){
    const N=vb(svg,'720 400','400 770');
    const L=N?{cx:44,cy:40,cw:340,ch:240,px:6,py:322,pw:388,ph:440}:{cx:46,cy:34,cw:352,ch:306,px:424,py:8,pw:290,ph:384};
    const lim=.86,wk=t<=lim?t/lim*24:24,lat=ramp(t,lim,1),X=w=>L.cx+L.cw*.84*w/24,Y=v=>L.cy+L.ch-L.ch*v/100;
    const D=RHB_DOMS[dom],G=D.groups.find(g=>g.id===grp)||D.groups[0];
    let s=`<text x="${L.cx-34}" y="${L.cy-16}" class="t-lbl">Share of people at their best so far</text>`;
    const zx=X(24),zr=L.cx+L.cw;
    s+=`<rect x="${f1(zx)}" y="${L.cy}" width="${f1(zr-zx)}" height="${L.ch}" style="fill:var(--rec-soft)"/>`;
    [0,20,40,60,80,100].forEach(v=>{s+=`<line x1="${L.cx}" x2="${zr}" y1="${f1(Y(v))}" y2="${f1(Y(v))}" class="grid"/><text x="${L.cx-6}" y="${f1(Y(v)+3)}" class="t-xs t-end">${v}%</text>`});
    [0,4,8,12,16,20,24].forEach(w=>{s+=`<text x="${f1(X(w))}" y="${L.cy+L.ch+14}" class="t-xs t-mid">${w}</text>`});
    s+=`<text x="${f1((zx+zr)/2)}" y="${L.cy+L.ch+14}" class="t-xs t-mid">later</text><text x="${f1(X(12))}" y="${L.cy+L.ch+30}" class="t-sm t-mid">weeks after stroke</text>`;
    s+=`<line x1="${L.cx}" x2="${zr}" y1="${L.cy+L.ch}" y2="${L.cy+L.ch}" class="axis"/><line x1="${L.cx}" x2="${L.cx}" y1="${L.cy}" y2="${L.cy+L.ch}" class="axis"/>`;
    const pathOf=(g,up)=>{const P=seriesPts(g),f=monoFn(P),end=Math.min(up,P[P.length-1][0]);let d='';for(let i=0;i<=50;i++){const w=end*i/50;d+=(i?'L':'M')+f1(X(w))+' '+f1(Y(clamp(f(w),0,100)))}return d};
    D.groups.forEach(g=>{if(g.id!==G.id)s+=`<path d="${pathOf(g,99)}" style="fill:none;stroke:var(--muted);stroke-width:1;opacity:.45"/>`});
    if(wk>0)s+=`<path d="${pathOf(G,wk)}" style="fill:none;stroke:var(--rec);stroke-width:2.6;stroke-dasharray:6 4;stroke-linecap:round"/>`;
    G.pts.forEach(p=>{const on=wk>=p[0];s+=`<circle cx="${f1(X(p[0]))}" cy="${f1(Y(p[1]))}" r="5.5" style="fill:${on?'var(--rec)':'var(--panel)'};stroke:var(--rec);stroke-width:2"/>`;
      if(on)s+=rhbLab(X(p[0])+9,Y(p[1])+16,`${p[1]}% by ${p[0]} wk`)});
    if(G.best){const on=wk>=G.best;s+=`<path d="M${f1(X(G.best))} ${L.cy}v12" style="stroke:var(--rec);stroke-width:2.4"/>`;
      if(on)s+=rhbLab(X(G.best)+6,L.cy+13,`best by ${G.best} wk`)}
    const cx=t<=lim?X(wk):lerp(zx,zr-3,lat);
    s+=`<line x1="${f1(cx)}" x2="${f1(cx)}" y1="${L.cy}" y2="${L.cy+L.ch}" style="stroke:var(--ink);stroke-width:1.2"/>`;
    const wl=t<=lim?`week ${wk<9.95?(Math.round(wk*2)/2):Math.round(wk)}`:'months, years later';
    s+=rhbLab(cx>L.cx+L.cw*.55?cx-5:cx+5,L.cy+L.ch-8,wl,{a:cx>L.cx+L.cw*.55?'t-end':''});
    if(lat>0)s+=`<g style="opacity:${f1(ramp(lat,.1,.6))}">${rhbLab(zx-8,Y(44),'gains reported with',{a:'t-end'})}${rhbLab(zx-8,Y(44)+15,'intensive practice',{a:'t-end'})}</g>`;
    s+=rhbPlastic(L,wk,lat,t);
    svg.innerHTML=s;
    const pub=G.pts.map(p=>`${p[1]}% by ${p[0]} weeks`).join(', ')+(G.best?`; best by ${G.best} weeks`:'');
    $('#rhbRead').innerHTML=`<span>${D.b}: <b>${G.b}</b></span><span>Published: <b>${pub}</b> ${D.src}</span>`;
    const p=phaseOf(RHB_STEPS,t);setSt(p);$('#rhbNote').innerHTML=noteHTML(RHB_STEPS[p]);
  }
  const stop=playWire(rg,$('#rhbPlay'),draw,22000,'Replay','rehab');
  const setSt=stepWire($('#rhbSteps'),RHB_STEPS,rg,draw,stop);
  domEl.addEventListener('click',e=>{const b=e.target.closest('[data-d]');if(!b)return;dom=b.dataset.d;grp=RHB_DOMS[dom].groups[0].id;pickerHTML();draw(+rg.value)});
  grpEl.addEventListener('click',e=>{const b=e.target.closest('[data-g]');if(!b)return;grp=b.dataset.g;pickerHTML();draw(+rg.value)});
  pickerHTML();draw(+rg.value);

  /* ---- proportional recovery ---- */
  const prS=$('#rhbPrSvg'),prX=$('#rhbPrX'),prV=$('#rhbPrV'),prSp=$('#rhbPrS');let prView='rule';
  prV.innerHTML=[['rule','The rule'],['crit','The critique'],['rej','The rejoinder']].map(([k,b])=>`<button class="btn" data-v="${k}" aria-pressed="${k===prView}">${b}</button>`).join('');
  const prR=rng(11),prD=[];for(let i=0;i<60;i++)prD.push({b:4+42*prR(),e:prR(),off:prR(),sev:prR()});
  const rhbCorr=(A,B)=>{const n=A.length,ma=A.reduce((x,y)=>x+y,0)/n,mb=B.reduce((x,y)=>x+y,0)/n;let c=0,xa=0,xb=0;for(let i=0;i<n;i++){c+=(A[i]-ma)*(B[i]-mb);xa+=(A[i]-ma)**2;xb+=(B[i]-mb)**2}return c/Math.sqrt(xa*xb)};
  const prF=x=>.7*(66-x)+.4;
  function prScatter(B,xs,ys,y0,y1,title,yl,rv){const X=v=>B.x+B.w*v/66,Y=v=>B.y+B.h-B.h*(v-y0)/(y1-y0);
    let g=`<text x="${B.x}" y="${B.y-8}" class="t-sm" style="fill:var(--ink)">${title}: <tspan style="font-weight:700">r = ${rv.toFixed(2).replace('-','−')}</tspan></text>`;
    g+=`<rect x="${B.x}" y="${B.y}" width="${B.w}" height="${B.h}" style="fill:var(--field)"/><line x1="${B.x}" x2="${B.x+B.w}" y1="${B.y+B.h}" y2="${B.y+B.h}" class="axis"/><line x1="${B.x}" x2="${B.x}" y1="${B.y}" y2="${B.y+B.h}" class="axis"/>`;
    xs.forEach((v,i)=>{g+=`<circle cx="${f1(X(v))}" cy="${f1(Y(clamp(ys[i],y0,y1)))}" r="2.8" style="fill:var(--rec);opacity:.75"/>`});
    g+=`<text x="${B.x+B.w}" y="${B.y+B.h+13}" class="t-xs t-end">start score</text>`;return g}
  function drawPr(){
    const N=vb(prS,'720 360','400 760'),x0=+prX.value,s0=+prSp.value;
    const A=N?{x:44,y:30,w:340,h:256}:{x:44,y:30,w:310,h:276},R=N?{x:14,y:360,w:372}:{x:392,y:22,w:316};
    const X=v=>A.x+A.w*v/66,Y=v=>A.y+A.h-A.h*v/66;
    let s=`<text x="${A.x-30}" y="${A.y-14}" class="t-lbl">Change in arm score, by start score</text>`;
    s+=`<rect x="${A.x}" y="${A.y}" width="${A.w}" height="${A.h}" style="fill:var(--field)"/>`;
    [0,22,44,66].forEach(v=>{s+=`<line x1="${A.x}" x2="${A.x+A.w}" y1="${f1(Y(v))}" y2="${f1(Y(v))}" class="grid"/><text x="${A.x-6}" y="${f1(Y(v)+3)}" class="t-xs t-end">${v}</text><text x="${f1(X(v))}" y="${A.y+A.h+14}" class="t-xs t-mid">${v}</text>`});
    s+=`<line x1="${A.x}" x2="${A.x+A.w}" y1="${A.y+A.h}" y2="${A.y+A.h}" class="axis"/><line x1="${A.x}" x2="${A.x}" y1="${A.y}" y2="${A.y+A.h}" class="axis"/><text x="${f1(A.x+A.w/2)}" y="${A.y+A.h+30}" class="t-sm t-mid">start score on the Fugl-Meyer arm scale</text>`;
    s+=`<line x1="${f1(X(0))}" y1="${f1(Y(66))}" x2="${f1(X(66))}" y2="${f1(Y(0))}" style="stroke:var(--muted);stroke-width:1.3;stroke-dasharray:3 4"/>`;
    s+=`<line x1="${f1(X(0))}" y1="${f1(Y(prF(0)))}" x2="${f1(X(66))}" y2="${f1(Y(prF(66)))}" style="stroke:var(--rec);stroke-width:2.6"/>`;
    if(prView==='rej'){prD.forEach(d=>{const sx=d.b*(66/46),dv=d.sev<.3&&sx<22?d.off*5:prF(sx)+(d.off-.5)*12;s+=`<circle cx="${f1(X(sx))}" cy="${f1(Y(clamp(dv,0,66)))}" r="2.8" style="fill:var(--brand);opacity:.6"/>`});
      s+=rhbLab(X(44),Y(44),'dots: simulated',{c:'t-sm'})}
    s+=rhbLab(X(14),Y(60),'solid: the rule, 0.7 x (66 - start) + 0.4',{c:'t-xs'})+rhbLab(X(18),Y(54),'dotted: the most the scale allows',{c:'t-xs'});
    const pc=prF(x0),py=Math.min(66,x0+pc);
    s+=`<line x1="${f1(X(x0))}" x2="${f1(X(x0))}" y1="${A.y}" y2="${A.y+A.h}" style="stroke:var(--ink);stroke-width:1.1"/><circle cx="${f1(X(x0))}" cy="${f1(Y(pc))}" r="6" style="fill:var(--rec);stroke:var(--panel);stroke-width:2"/>`;
    if(prView==='crit'){
      const bs=prD.map(d=>d.b),os=prD.map(d=>62-s0*d.e),ch=os.map((o,i)=>o-bs[i]);
      s+=prScatter({x:R.x+20,y:R.y+22,w:R.w-34,h:N?130:118},bs,ch,-20,66,'Start vs recovery','recovery',rhbCorr(bs,ch));
      s+=prScatter({x:R.x+20,y:R.y+(N?202:186),w:R.w-34,h:N?130:118},bs,os,0,66,'Start vs final score','final score',rhbCorr(bs,os));
      s+=`<text x="${R.x+20}" y="${R.y+(N?372:326)}" class="t-sm" style="fill:var(--ink)">Simulated dots, not patient data.</text>`;
    }else if(prView==='rule'){
      const tw=R.w-20,TX=v=>R.x+10+tw*v/66,ty=R.y+44,ax=TX(x0),bx=TX(py);
      s+=`<text x="${R.x+10}" y="${R.y+14}" class="t-lbl">What the formula gives</text>`;
      s+=`<rect x="${R.x+10}" y="${ty}" width="${tw}" height="14" rx="7" style="fill:var(--panel-2)"/><rect x="${f1(ax)}" y="${ty}" width="${f1(Math.max(0,bx-ax))}" height="14" style="fill:var(--rec)"/>`;
      s+=`<text x="${R.x+10}" y="${ty+30}" class="t-xs">0</text><text x="${R.x+10+tw}" y="${ty+30}" class="t-xs t-end">66</text>`;
      const startA=x0>33,startEnd=x0>52;
      s+=`<text x="${f1(ax)}" y="${ty-6}" class="t-sm ${startEnd?'t-end':startA?'t-mid':''}" style="fill:var(--ink)">start ${x0}</text>`;
      s+=`<text x="${f1(R.x+10+tw/2)}" y="${ty+30}" class="t-sm t-mid" style="fill:var(--ink)">predicted score ${py.toFixed(1)}</text>`;
      const by=R.y+(N?118:112);
      s+=`<text x="${R.x+10}" y="${by-10}" class="t-lbl">Who fitted, in 211 people</text>`;
      const w1=tw*146/211;
      s+=`<rect x="${R.x+10}" y="${by}" width="${f1(w1-1)}" height="24" style="fill:var(--mrs1)"/><rect x="${f1(R.x+10+w1)}" y="${by}" width="${f1(tw-w1)}" height="24" style="fill:var(--mrs4)"/>`;
      s+=`<text x="${f1(R.x+10+w1/2)}" y="${by+16}" class="t-sm t-mid" style="fill:var(--mrs-on1)">146: about 78%</text><text x="${f1(R.x+10+w1+(tw-w1)/2)}" y="${by+16}" class="t-sm t-mid" style="fill:var(--mrs-on4)">65: worse</text>`;
      ['Not fitting went with:','no finger extension, facial palsy,','more severe leg paresis,','more severe Bamford stroke type.'].forEach((l,i)=>{s+=`<text x="${R.x+10}" y="${by+50+i*16}" class="${i?'t-sm':'t-lbl'}">${l}</text>`});
    }else{
      const tw=R.w-20;
      s+=`<text x="${R.x+10}" y="${R.y+14}" class="t-lbl">One line, many people</text>`;
      ['The rule may describe a group well.','One person can sit well off the line.'].forEach((l,i)=>{s+=`<text x="${R.x+10}" y="${R.y+34+i*16}" class="t-sm">${l}</text>`});
      const by=R.y+92;
      s+=`<text x="${R.x+10}" y="${by-8}" class="t-sm" style="fill:var(--ink)">Severe paresis: do not follow it, about 30%</text>`;
      s+=`<rect x="${R.x+10}" y="${by}" width="${tw}" height="16" rx="3" style="fill:var(--panel-2)"/><rect x="${R.x+10}" y="${by}" width="${f1(tw*.3)}" height="16" rx="3" style="fill:var(--brand)"/>`;
      s+=`<text x="${R.x+10}" y="${by+44}" class="t-sm" style="fill:var(--ink)">PREP2: arm prediction correct, 75%</text>`;
      s+=`<rect x="${R.x+10}" y="${by+52}" width="${tw}" height="16" rx="3" style="fill:var(--panel-2)"/><rect x="${R.x+10}" y="${by+52}" width="${f1(tw*.75)}" height="16" rx="3" style="fill:var(--brand)"/>`;
      ['Even a tool built to predict, using brain','signals, was wrong for a quarter of people.'].forEach((l,i)=>{s+=`<text x="${R.x+10}" y="${by+92+i*16}" class="t-sm">${l}</text>`});
    }
    prS.innerHTML=s;
    $('#rhbPrRead').innerHTML=`<span>Start <b>${x0}</b></span><span>Formula's change <b>${pc.toFixed(1)}</b></span><span>Score it implies <b>${py.toFixed(1)}</b> of 66</span>`;
    $('#rhbPrCap').innerHTML=prView==='crit'?'<b>Simulated.</b> Each dot is generated here, not a person. Baseline scores spread widely, final scores cluster near the top, and that alone makes start and recovery look tightly linked.':'<b>Formula from Winters 2015</b> <sup class="c" data-ref="Winters2015" title="Source 1055"><a href="/stroke/sources/#src-Winters2015">1055</a></sup>, applied to non-severe impairment only. Not a tool for individual prognosis.';
    $('#rhbPrSW').hidden=prView!=='crit';
    $('#rhbPrNote').innerHTML=noteHTML(RHB_PR_NOTES[prView]);
  }
  prV.addEventListener('click',e=>{const b=e.target.closest('[data-v]');if(!b)return;prView=b.dataset.v;$$('[data-v]',prV).forEach(k=>k.setAttribute('aria-pressed',k===b));drawPr()});
  prX.addEventListener('input',drawPr);prSp.addEventListener('input',drawPr);drawPr();

  /* ---- deficit tabs and their charts ---- */
  const tabs=$('#rhbTabs');let tab='arm';
  const drawTab=()=>{const el=$('#rhbC-'+tab);if(el)rhbBars(el,RHB_CHARTS[tab])};
  tabs.addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;tab=b.dataset.tab;
    $$('[data-tab]',tabs).forEach(k=>k.setAttribute('aria-pressed',k===b));
    $$('.rhbpanel',$('#m-rehab')).forEach(p=>p.hidden=p.id!=='rhbP-'+tab);drawTab()});
  const drawAvert=()=>rhbBars($('#rhbC-avert'),RHB_CHARTS.avert,{W:400});
  drawTab();drawAvert();

  /* ---- CPASS timing ---- */
  const cp=$('#rhbCpSvg'),cpT=$('#rhbCpT');
  const CP_BARS=[{l:'30 days or less',v:5.25,e:2.59,p:'P=0.043'},{l:'2 to 3 months',v:6.87,e:2.63,p:'P=0.009'},{l:'6 months or later',v:2.41,e:2.25,p:'P=0.29'}];
  const CP_SL=[{n:'Fugl-Meyer UL',a:26,b:37},{n:'ARAT',a:18,b:27},{n:'CAHAI',a:40,b:52}];
  const CP_RAT=[['Day 5','improved markedly',''],['Day 14','somewhat less',''],['Day 30','no better than','social housing']];
  function drawCp(t){
    const N=vb(cp,'720 380','400 800');
    const L=N?{rx:8,ry:30,rw:124,rg:6,bx:42,by:150,bw:350,bh:270,wx:10,wy:490,ww:380,wh:290}:{rx:14,ry:30,rw:140,rg:8,bx:46,by:136,bw:416,bh:200,wx:486,wy:22,ww:226,wh:338};
    let s=`<text x="${L.rx}" y="${L.ry-10}" class="t-lbl">Rats: enriched rehabilitation, by start day</text>`;
    CP_RAT.forEach((r,i)=>{const x=L.rx+i*(L.rw+L.rg),op=ramp(t,i*.04,.06+i*.04);
      s+=`<g style="opacity:${f1(op)}"><rect x="${x}" y="${L.ry}" width="${L.rw}" height="62" rx="8" style="fill:var(--rec-soft);stroke:var(--line)"/><text x="${x+9}" y="${L.ry+19}" class="t-lbl">${r[0]}</text><text x="${x+9}" y="${L.ry+36}" class="t-sm" style="fill:var(--ink)">${r[1]}</text><text x="${x+9}" y="${L.ry+50}" class="t-sm" style="fill:var(--ink)">${r[2]}</text></g>`});
    const Y=v=>L.by+L.bh-L.bh*v/12,hg=ramp(t,.22,.4);
    s+=`<text x="${L.bx-38}" y="${L.by-14}" class="t-lbl" style="opacity:${f1(ramp(t,.18,.24))}">People, CPASS: arm score gain at 1 year</text>`;
    s+=`<g style="opacity:${f1(ramp(t,.18,.24))}">`;
    [0,4,8,12].forEach(v=>{s+=`<line x1="${L.bx}" x2="${L.bx+L.bw}" y1="${f1(Y(v))}" y2="${f1(Y(v))}" class="grid"/><text x="${L.bx-6}" y="${f1(Y(v)+3)}" class="t-xs t-end">${v}</text>`});
    s+=`<line x1="${L.bx}" x2="${L.bx+L.bw}" y1="${L.by+L.bh}" y2="${L.by+L.bh}" class="axis"/></g>`;
    /* the schematic idea of a window */
    if(hg>0){const f=monoFn([ [0,1],[.3,8],[.5,9],[.85,3],[1,1.6] ]);let d=`M${L.bx} ${f1(Y(0))}`;for(let i=0;i<=40;i++){const u=i/40;d+=`L${f1(L.bx+L.bw*u)} ${f1(Y(f(u)))}`}d+=`L${L.bx+L.bw} ${f1(Y(0))}Z`;
      s+=`<path d="${d}" style="fill:var(--rec);opacity:${f1(.14*hg)}"/>`}
    const cw=L.bw/3;
    CP_BARS.forEach((b,i)=>{const g=ease(ramp(t,.26+i*.12,.38+i*.12)),cx=L.bx+cw*(i+.5),w=N?54:64;
      s+=`<text x="${f1(cx)}" y="${L.by+L.bh+16}" class="t-sm t-mid" style="fill:var(--ink);opacity:${f1(ramp(t,.18,.24))}">${b.l}</text>`;
      if(g<=0)return;
      s+=`<rect x="${f1(cx-w/2)}" y="${f1(Y(b.v*g))}" width="${w}" height="${f1(Y(0)-Y(b.v*g))}" rx="3" style="fill:${i===2?'var(--muted)':'var(--rec)'}"/>`;
      if(g>=1){const yu=Y(b.v+b.e),yd=Y(Math.max(0,b.v-b.e));s+=`<path d="M${f1(cx)} ${f1(yu)}V${f1(yd)}M${f1(cx-6)} ${f1(yu)}h12M${f1(cx-6)} ${f1(yd)}h12" style="fill:none;stroke:var(--ink);stroke-width:1.5"/>`;
        s+=`<text x="${f1(cx)}" y="${f1(yu-20)}" class="t-big t-mid">+${b.v}</text><text x="${f1(cx)}" y="${f1(yu-6)}" class="t-xs t-mid" style="fill:var(--ink)">± ${b.e}, ${b.p}</text>`}});
    /* counterpoint: Queen Square medians */
    const w=ramp(t,.7,.84);
    if(w>0){const a=L.wx+16,bX=a+(N?170:90),y0=L.wy+66,h=L.wh-120,YS=v=>y0+h-h*v/60;
      s+=`<g style="opacity:${f1(ramp(t,.7,.74))}"><text x="${L.wx}" y="${L.wy+12}" class="t-lbl">Queen Square, chronic phase</text><text x="${L.wx}" y="${L.wy+30}" class="t-sm">224 people, median 18 months on</text><text x="${L.wx}" y="${L.wy+46}" class="t-sm">90 hours over 3 weeks</text>`;
      s+=`<line x1="${a}" x2="${a}" y1="${y0}" y2="${y0+h}" class="grid"/><line x1="${bX}" x2="${bX}" y1="${y0}" y2="${y0+h}" class="grid"/><text x="${a}" y="${y0+h+15}" class="t-xs t-mid">admission</text><text x="${bX}" y="${y0+h+15}" class="t-xs t-mid">6 months</text>`;
      CP_SL.forEach(q=>{const xe=lerp(a,bX,ease(w)),ye=lerp(YS(q.a),YS(q.b),ease(w));
        s+=`<line x1="${a}" y1="${f1(YS(q.a))}" x2="${f1(xe)}" y2="${f1(ye)}" style="stroke:var(--rec);stroke-width:2.2"/><circle cx="${a}" cy="${f1(YS(q.a))}" r="3.6" style="fill:var(--rec)"/><text x="${a+7}" y="${f1(YS(q.a)+14)}" class="t-xs" style="fill:var(--ink)">${q.a}</text>`;
        if(w>=1)s+=`<circle cx="${bX}" cy="${f1(YS(q.b))}" r="3.6" style="fill:var(--rec)"/><text x="${bX+8}" y="${f1(YS(q.b)+4)}" class="t-sm" style="fill:var(--ink)">${q.b} ${q.n}</text>`});
      s+=`<text x="${L.wx}" y="${y0+h+38}" class="t-sm" style="fill:var(--ink)">Medians. No control group</text><text x="${L.wx}" y="${y0+h+52}" class="t-sm" style="fill:var(--ink)">described in the abstract.</text></g>`}
    cp.innerHTML=s;
    const p=phaseOf(RHB_CP_STEPS,t);setCp(p);$('#rhbCpNote').innerHTML=noteHTML(RHB_CP_STEPS[p]);
  }
  const stopCp=playWire(cpT,$('#rhbCpPlay'),drawCp,16000,'Replay','rehab');
  const setCp=stepWire($('#rhbCpSteps'),RHB_CP_STEPS,cpT,drawCp,stopCp);
  drawCp(+cpT.value);

  /* ---- fluoxetine ---- */
  const fl=$('#rhbFlSvg'),flT=$('#rhbFlT');
  const FL_FOR=[{n:'FOCUS',m:.951,a:.839,b:1.079,t:'0.951 (0.839 to 1.079)'},{n:'AFFINITY',m:.94,a:.76,b:1.15,t:'0.94 (0.76 to 1.15)'},{n:'EFFECTS',m:.94,a:.78,b:1.13,t:'0.94 (0.78 to 1.13)'}];
  const FL_DEP=[{n:'FOCUS',f:13.43,p:17.21},{n:'EFFECTS',f:7,p:11}];
  const FL_FRX=[{n:'FOCUS',f:2.88,p:1.47},{n:'AFFINITY',f:3,p:1},{n:'EFFECTS',f:4,p:2}];
  function flDumb(B,rows,mx,title,op){const nw=66,X=v=>B.x+nw+(B.w-nw-26)*v/mx;
    let g=`<g style="opacity:${f1(op)}"><text x="${B.x}" y="${B.y+12}" class="t-lbl">${title}</text>`;
    rows.forEach((r,i)=>{const y=B.y+42+i*34,lo=Math.min(r.f,r.p),hi=Math.max(r.f,r.p);
      g+=`<text x="${B.x}" y="${y+4}" class="t-sm" style="fill:var(--ink)">${r.n}</text><line x1="${f1(X(0))}" x2="${f1(X(mx))}" y1="${y}" y2="${y}" class="grid"/><line x1="${f1(X(lo))}" x2="${f1(X(hi))}" y1="${y}" y2="${y}" style="stroke:var(--muted);stroke-width:2"/>`;
      g+=`<circle cx="${f1(X(r.p))}" cy="${y}" r="5.5" style="fill:var(--panel);stroke:var(--ink);stroke-width:2"/><circle cx="${f1(X(r.f))}" cy="${y}" r="5.5" style="fill:var(--rec);stroke:var(--panel);stroke-width:1"/>`;
      g+=`<text x="${f1(X(lo)-9)}" y="${y-8}" class="t-xs t-end" style="fill:var(--ink)">${(lo===r.f?'F ':'P ')+lo}</text><text x="${f1(X(hi)+9)}" y="${y-8}" class="t-xs" style="fill:var(--ink)">${(hi===r.f?'F ':'P ')+hi}</text>`});
    return g+'</g>'}
  function drawFl(t){
    const N=vb(fl,'720 440','400 880');
    const L=N?{ax:14,ay:30,aw:372,bx:14,by:188,bw:372,cx:14,cy:400,cw:372,dx:14,dy:540,dw:372,ly:742}:{ax:14,ay:30,aw:262,bx:300,by:30,bw:410,cx:14,cy:232,cw:336,dx:376,dy:232,dw:336,ly:414};
    const pa=ramp(t,0,.1);let s=`<g style="opacity:${f1(pa)}"><text x="${L.ax}" y="${L.ay-8}" class="t-lbl">FLAME, 2011: Fugl-Meyer gain, day 90</text>`;
    const fw=(L.aw-92);
    [['Fluoxetine',34.0,'var(--rec)'],['Placebo',24.3,'var(--muted)']].forEach(([n,v,c],i)=>{const y=L.ay+16+i*50,g=ease(pa);
      s+=`<text x="${L.ax}" y="${y}" class="t-sm" style="fill:var(--ink)">${n}</text><rect x="${L.ax}" y="${y+6}" width="${f1(fw*v/40*g)}" height="18" rx="3" style="fill:${c}"/><text x="${f1(L.ax+fw*v/40*g+6)}" y="${y+20}" class="t-big">${v.toFixed(1)}</text>`});
    s+=`<text x="${L.ax}" y="${L.ay+120}" class="t-sm">118 people. p=0.003</text></g>`;
    /* forest plot */
    const pb=ramp(t,.2,.26),nw=N?74:80,vw=N?120:124,fx=L.bx+nw,fwd=L.bw-nw-vw-8,XO=v=>fx+fwd*(Math.log(v)-Math.log(.6))/(Math.log(1.4)-Math.log(.6));
    s+=`<g style="opacity:${f1(pb)}"><text x="${L.bx}" y="${L.by-8}" class="t-lbl">Then: mRS common odds ratio (95% CI)</text>`;
    const fy=L.by+6,fh=132;
    s+=`<line x1="${f1(XO(1))}" x2="${f1(XO(1))}" y1="${fy}" y2="${fy+fh}" style="stroke:var(--ink);stroke-width:1.3;stroke-dasharray:4 3"/><text x="${f1(XO(1))}" y="${fy+fh+14}" class="t-xs t-mid" style="fill:var(--ink)">1 = no difference</text>`;
    [.6,1.4].forEach(v=>{s+=`<text x="${f1(XO(v))}" y="${fy+fh+14}" class="t-xs t-mid">${v}</text>`});
    s+=`<line x1="${fx}" x2="${fx+fwd}" y1="${fy+fh}" y2="${fy+fh}" class="axis"/></g>`;
    FL_FOR.forEach((r,i)=>{const g=ease(ramp(t,.26+i*.07,.33+i*.07)),y=fy+24+i*40;if(g<=0)return;
      s+=`<g style="opacity:${f1(g)}"><text x="${L.bx}" y="${y+4}" class="t-sm" style="fill:var(--ink)">${r.n}</text><line x1="${f1(XO(r.a))}" x2="${f1(XO(r.b))}" y1="${y}" y2="${y}" style="stroke:var(--rec);stroke-width:2.4"/><rect x="${f1(XO(r.m)-5)}" y="${y-5}" width="10" height="10" style="fill:var(--rec)"/><text x="${L.bx+L.bw}" y="${y+4}" class="t-xs t-end" style="fill:var(--ink)">${r.t}</text></g>`});
    /* harms */
    s+=flDumb({x:L.cx,y:L.cy,w:L.cw},FL_DEP,20,'New depression (%)',ramp(t,.52,.6));
    s+=flDumb({x:L.dx,y:L.dy,w:L.dw},FL_FRX,6,'Fractures (%)',ramp(t,.6,.68));
    const pc=ramp(t,.52,.6);
    s+=`<text x="${L.cx}" y="${L.ly-(N?-18:0)}" class="t-sm" style="fill:var(--ink);opacity:${f1(pc)}">F, filled: fluoxetine. P, hollow: placebo.</text>`;
    const pd=ramp(t,.8,.86);
    s+=`<text x="${N?L.cx:L.cx+300}" y="${N?L.ly+48:L.ly}" class="t-lbl" style="opacity:${f1(pd)}">Same basic protocol. Three trials. One answer.</text>`;
    fl.innerHTML=s;
    const p=phaseOf(RHB_FL_STEPS,t);setFl(p);$('#rhbFlNote').innerHTML=noteHTML(RHB_FL_STEPS[p]);
  }
  const stopFl=playWire(flT,$('#rhbFlPlay'),drawFl,16000,'Replay','rehab');
  const setFl=stepWire($('#rhbFlSteps'),RHB_FL_STEPS,flT,drawFl,stopFl);
  drawFl(+flT.value);

  const prev=redraws.rehab;redraws.rehab=()=>{prev&&prev();drawPr();drawTab();drawAvert()};
};
/* =============== 5.2 Life after stroke =============== */
/* Widgets: the invisible-effects explorer (six effects on one timeline, each with an array of 100 people and a chart of
   published prevalence by time window), life-domain tabs with charts and the DVLA rule explorer, and population curves
   for survival and recurrence. Every number comes from research pass H. rhbBars is shared from 5.1. */
const AFT_FX=[
 {id:'dep',k:'Effect 1 of 6',t:'Depression',head:31,big:'About 31 in 100',sub:'pooled, at any time',
  segs:[{a:.1,b:180,v:31,dash:'band',lab:'pooled, any time: 31%',x:'r',y:-6},
   {a:.1,b:120,v:29,dash:'6 4',lab:'second review: 29%, stable to 10 yr',x:'l',y:14},
   {a:12,b:60,v:25,lab:'1 to 5 yr: 25%',x:'l',y:15},
   {a:60,b:60,v:23,lab:'5 yr: 23%',x:'pr',y:16},
   {a:180,b:180,v:39.1,lab:'15 yr: 39.1%, selected group',x:'pe',y:-9}],
  txt:'Pooled frequency 31% (95% CI 28% to 35%), 61 studies and 25,488 people, unchanged from 33% in the 2005 review <sup class="c" data-ref="Hackett2014" title="Source 381"><a href="/stroke/sources/#src-Hackett2014">381</a></sup>. Two reviews disagree on the course: Hackett reports lower frequency with time, Ayerbe reports stable prevalence <sup class="c" data-ref="Hackett2014,Ayerbe2013" title="Source 67,381"><a href="/stroke/sources/#src-Hackett2014">67,381</a></sup>. Predictors include pre-stroke depression and more severe deficit, and depression worsens functional outcome, a reciprocal relationship <sup class="c" data-ref="Kutlubaev2014" title="Source 525"><a href="/stroke/sources/#src-Kutlubaev2014">525</a></sup>. Inflammation, genetic variation, white matter disease and altered neuroplasticity are proposed mechanisms <span class="ev hyp">Hypothesis</span> <sup class="c" data-ref="Robinson2016" title="Source 848"><a href="/stroke/sources/#src-Robinson2016">848</a></sup>.',
  pt:'Low mood is common and it can be treated. It is part of the stroke, not a weakness <sup class="c" data-ref="Hackett2014,Richards2026" title="Source 381,843"><a href="/stroke/sources/#src-Hackett2014">381,843</a></sup>.',
  hook:'Post-stroke depression is about 31% <sup class="c" data-ref="Hackett2014" title="Source 381"><a href="/stroke/sources/#src-Hackett2014">381</a></sup>.'},
 {id:'anx',k:'Effect 2 of 6',t:'Anxiety',head:29,big:'About 29 in 100',sub:'in the first year',
  segs:[{a:.1,b:.46,v:36.7,lab:'0 to 2 weeks: 36.7%',x:'l',y:-7},
   {a:.1,b:12,v:29.3,dash:'6 4',lab:'first year, pooled: 29.3%',x:'lc',y:-6},
   {a:.46,b:3,v:24.1,lab:'2 weeks to 3 months: 24.1%',x:'l',y:15},
   {a:3,b:12,v:23.8,lab:'3 to 12 months: 23.8%',x:'l',y:30},
   {a:180,b:180,v:34.9,lab:'15 yr: 34.9%, selected group',x:'pe',y:-9}],
  txt:'Pooled anxiety prevalence in the first year 29.3% (24.8% to 33.8%), with high heterogeneity. It is highest in the first 2 weeks <sup class="c" data-ref="Rafsten2018" title="Source 824"><a href="/stroke/sources/#src-Rafsten2018">824</a></sup>. At 15 years in South London, anxiety was 34.9% among survivors, a small, selected group <sup class="c" data-ref="Crichton2016" title="Source 210"><a href="/stroke/sources/#src-Crichton2016">210</a></sup>. Regular benzodiazepines are potentially harmful in anxiety (COR 3: Harm, LOE B-NR) <sup class="c" data-ref="Richards2026" title="Source 843"><a href="/stroke/sources/#src-Richards2026">843</a></sup>.',
  pt:'Worry is common after a stroke, and it is often highest at the very start <sup class="c" data-ref="Rafsten2018" title="Source 824"><a href="/stroke/sources/#src-Rafsten2018">824</a></sup>.',
  hook:'Anxiety is about 29% <sup class="c" data-ref="Rafsten2018" title="Source 824"><a href="/stroke/sources/#src-Rafsten2018">824</a></sup>.'},
 {id:'pts',k:'Effect 3 of 6',t:'Post-traumatic stress',head:23,big:'About 23 in 100',sub:'within a year',
  segs:[{a:.1,b:12,v:23,lab:'within 1 year: 23%',x:'l',y:-7},
   {a:12,b:180,v:11,dash:'6 4',lab:'after 1 year: 11%',x:'l',y:-7}],
  txt:'PTSD after stroke or TIA, 9 studies, N=1138: 23% (16% to 33%) within 1 year, 11% (8% to 14%) after 1 year <sup class="c" data-ref="Edmondson2013" title="Source 270"><a href="/stroke/sources/#src-Edmondson2013">270</a></sup>. The dashed line shows "after 1 year" as an open-ended window, not a measurement at each point.',
  pt:'A stroke can be frightening. Post-traumatic stress after it is a recognised effect, and it is less common after the first year <sup class="c" data-ref="Edmondson2013" title="Source 270"><a href="/stroke/sources/#src-Edmondson2013">270</a></sup>.'},
 {id:'fat',k:'Effect 4 of 6',t:'Fatigue',head:48,big:'About 48 in 100',sub:'score of 4 or more',tag:['No single time curve here.','Time of assessment explains part of the spread.'],
  segs:[{a:.1,b:180,v:48,dash:'band',lab:'pooled: 48%',x:'r',y:-6},
   {a:.1,b:180,v:40,dash:'6 4',lab:'guideline: more than 40%',x:'r',y:15}],
  txt:'Pooled prevalence using a Fatigue Severity Scale cut-off of 4 or more: 48% (95% CI 42% to 53%), 35 studies, N=6851. Time of assessment, stroke type and geography explain variation, so no single time curve is drawn <sup class="c" data-ref="Alghamdi2021" title="Source 20"><a href="/stroke/sources/#src-Alghamdi2021">20</a></sup>. The 2026 guideline gives "&gt;40%" and defines fatigue as not relieved by rest <sup class="c" data-ref="Richards2026" title="Source 843"><a href="/stroke/sources/#src-Richards2026">843</a></sup>. Cochrane found insufficient evidence on any treatment or prevention <sup class="c" data-ref="Wu2015" title="Source 1064"><a href="/stroke/sources/#src-Wu2015">1064</a></sup>.',
  pt:'Feeling very tired is common after a stroke, and rest does not always fix it. It is worth telling your team <sup class="c" data-ref="Alghamdi2021,Richards2026" title="Source 20,843"><a href="/stroke/sources/#src-Alghamdi2021">20,843</a></sup>.',
  hook:'Fatigue is about 48% <sup class="c" data-ref="Alghamdi2021" title="Source 20"><a href="/stroke/sources/#src-Alghamdi2021">20</a></sup>.'},
 {id:'cog',k:'Effect 5 of 6',t:'Cognition & dementia',head:44,big:'About 44 in 100',sub:'impaired overall, 2 to 6 months',
  segs:[{a:2,b:6,v:44,lab:'2 to 6 months, overall: 44%',x:'l',y:-7},
   {a:2,b:6,v:32.5,band:[30,35],lab:'single domains: 30% to 35%',x:'r6',y:4},
   {a:.1,b:.1,v:10,lab:'dementia: 10% before, 10% soon after a first stroke',ln:'dementia: 10% before, 10% soon after',x:'pr',y:17},
   {a:180,b:180,v:30,lab:'15 yr: 30.0%, selected group',x:'pe',y:18}],
  txt:'STROKOG (3146 people, 13 studies, 8 countries): 44% impaired in global cognition and 30% to 35% in individual domains at 2 to 6 months <sup class="c" data-ref="Lo2019" title="Source 593"><a href="/stroke/sources/#src-Lo2019">593</a></sup>. 10% had dementia before a first stroke, 10% developed it soon after, and more than a third had it after recurrent stroke. The range runs from 7.4% to 41.3% depending on the kind of study <sup class="c" data-ref="Pendlebury2009" title="Source 780"><a href="/stroke/sources/#src-Pendlebury2009">780</a></sup>. REGARDS found an acute drop in global cognition, then faster decline <sup class="c" data-ref="Levine2015" title="Source 566"><a href="/stroke/sources/#src-Levine2015">566</a></sup>. Lack of a harmonised definition is the main challenge <sup class="c" data-ref="Rost2022" title="Source 857"><a href="/stroke/sources/#src-Rost2022">857</a></sup>.',
  pt:'Trouble with thinking is common after a stroke. The 2026 guideline lists cognitive training and exercise. Dementia is more common after a second stroke, so prevention matters <sup class="c" data-ref="Richards2026,Pendlebury2009" title="Source 780,843"><a href="/stroke/sources/#src-Richards2026">780,843</a></sup>.',
  hook:'10% dementia soon after first stroke, more than a third after recurrent stroke <sup class="c" data-ref="Pendlebury2009" title="Source 780"><a href="/stroke/sources/#src-Pendlebury2009">780</a></sup>.'},
 {id:'pai',k:'Effect 6 of 6',t:'Pain',head:29,big:'About 29 in 100',sub:'shoulder pain in follow-up',
  segs:[{a:.1,b:180,v:29,dash:'band',lab:'shoulder pain, any time in follow-up: 29%',x:'r',y:-6},
   {a:4,b:12,v:21,lab:'shoulder, 4 and 12 months: 21%',x:'l',y:15},
   {a:.1,b:.1,v:10,lab:'shoulder, baseline: 10%',x:'pr',y:16},
   {a:.1,b:180,v:11,dash:'6 4',lab:'central post-stroke pain, pooled: 11%',x:'r',y:-6}],
  txt:'Hemiplegic shoulder pain, population-based: 10% at baseline, 21% at 4 and 12 months, 29% overall, with peak onset and severity at 4 months <sup class="c" data-ref="AdeyWakeling2015" title="Source 10"><a href="/stroke/sources/#src-AdeyWakeling2015">10</a></sup>. Central post-stroke pain pooled 11% (7% to 18%), exceeding 50% with medullary or thalamic stroke <sup class="c" data-ref="Liampas2020" title="Source 572"><a href="/stroke/sources/#src-Liampas2020">572</a></sup>. It is pain with sensory abnormalities in the body parts matching the injured brain territory <sup class="c" data-ref="Klit2009" title="Source 510"><a href="/stroke/sources/#src-Klit2009">510</a></sup>. Pain is linked to depression, cognitive dysfunction and poor quality of life, and it is underdiagnosed <sup class="c" data-ref="Harrison2015" title="Source 403"><a href="/stroke/sources/#src-Harrison2015">403</a></sup>.',
  pt:'Pain after a stroke has several causes, and it can begin weeks or months later. It is often missed, so it is worth mentioning <sup class="c" data-ref="Harrison2015,Liampas2020" title="Source 403,572"><a href="/stroke/sources/#src-Harrison2015">403,572</a></sup>.',
  hook:'Central pain is about 11% <sup class="c" data-ref="Liampas2020" title="Source 572"><a href="/stroke/sources/#src-Liampas2020">572</a></sup>, hemiplegic shoulder pain about 29% <sup class="c" data-ref="AdeyWakeling2015" title="Source 10"><a href="/stroke/sources/#src-AdeyWakeling2015">10</a></sup>.'}];
const AFT_STEPS=AFT_FX.map((f,i)=>({from:i/6,at:i/6+.125,k:f.k,t:f.t,txt:f.txt,pt:f.pt,hook:f.hook}));
const AFT_TICKS=[ [.46,'2 wk'],[3,'3 mo'],[12,'1 yr'],[60,'5 yr'],[120,'10 yr'],[180,'15 yr'] ];
const AFT_BARS={
 work:[{h:'Back at work, median across studies of young stroke'},{l:'0 to 6 months',v:41,txt:'41%'},{l:'1 year',v:53,txt:'53%'},{l:'1.5 years',v:56,txt:'56%'},{l:'2 to 4 years',v:66,txt:'66%'}],
 young:[{h:'FUTURE: poor outcome (mRS over 2), mean 9.1 years on'},{l:'After TIA',v:16.8,txt:'16.8%'},{l:'After ischaemic stroke',v:36.5,txt:'36.5%'},{l:'After intracerebral haemorrhage',v:49.3,txt:'49.3%'}],
 need:[{h:'UK survey, 1251 people, 1 to 5 years after stroke'},{l:'No unmet needs',v:51,txt:'51%'},{h:'Also reported (the base may differ from the bar above)'},{l:'Unmet need for stroke information',v:54,txt:'54%'},{l:'Lost work activities',v:52,txt:'52%'},{l:'Higher expenses',v:31,txt:'31%'},{l:'Lost income',v:18,txt:'18%'}]};
const AFT_DRIVE={
 '1s':{m:1,h:'Group 1 after a stroke: 1 month',t:'Must not drive. May resume after 1 month with satisfactory clinical recovery. Need not notify the DVLA unless residual neurological deficit remains at 1 month, such as visual field defects, cognitive defects or impaired limb function <sup class="c" data-ref="DVLA-Neuro" title="Source 263"><a href="/stroke/sources/#src-DVLA-Neuro">263</a></sup>.'},
 '1t':{m:1,h:'Group 1 after a TIA: 1 month',t:'1 month off driving after each episode <sup class="c" data-ref="DVLA-Neuro" title="Source 263"><a href="/stroke/sources/#src-DVLA-Neuro">263</a></sup>.'},
 '2s':{m:12,h:'Group 2 after a stroke: 1 year',t:'Must notify the DVLA. The licence is refused or revoked for 1 year. Relicensing is considered with no debarring residual impairment and no other significant risk factors <sup class="c" data-ref="DVLA-Neuro" title="Source 263"><a href="/stroke/sources/#src-DVLA-Neuro">263</a></sup>.'},
 '2t':{m:12,h:'Group 2 after a TIA: 1 year',t:'Must notify the DVLA. The licence is refused or revoked for 1 year. Relicensing is considered with no debarring residual impairment and no other significant risk factors <sup class="c" data-ref="DVLA-Neuro" title="Source 263"><a href="/stroke/sources/#src-DVLA-Neuro">263</a></sup>.'}};
const AFT_SV_STEPS=[
 {from:0,at:.16,k:'First months',t:'3 months',
  txt:'Australia and New Zealand, 313,162 people, 2008 to 2017: 79.4% alive at 3 months. Pooled recurrence 3.1% at 30 days; 7.8% at 3 months in the Australian and New Zealand cohort <sup class="c" data-ref="Peng2022,Mohan2011" title="Source 682,781"><a href="/stroke/sources/#src-Peng2022">682,781</a></sup>.'},
 {from:.2,at:.32,k:'One year',t:'1 year',
  txt:'73.0% alive at 1 year. Recurrence 11.1% pooled and 11.0% in Australia and New Zealand, close agreement between very different sources <sup class="c" data-ref="Peng2022,Mohan2011" title="Source 682,781"><a href="/stroke/sources/#src-Peng2022">682,781</a></sup>.'},
 {from:.42,at:.71,k:'Five years',t:'5 years',
  txt:'52.8% alive at 5 years. Recurrence 26.4% pooled, 19.8% in Australia and New Zealand <sup class="c" data-ref="Peng2022,Mohan2011" title="Source 682,781"><a href="/stroke/sources/#src-Peng2022">682,781</a></sup>. These are averages over everyone in the register.',
  pt:'A second stroke is a real risk for years, so preventing one is lifelong work <sup class="c" data-ref="Mohan2011,Maaijwee2014" title="Source 613,682"><a href="/stroke/sources/#src-Mohan2011">613,682</a></sup>.',
  hook:'Five-year recurrence 26.4% <sup class="c" data-ref="Mohan2011" title="Source 682"><a href="/stroke/sources/#src-Mohan2011">682</a></sup>; 5-year survival 52.8% <sup class="c" data-ref="Peng2022" title="Source 781"><a href="/stroke/sources/#src-Peng2022">781</a></sup>.'},
 {from:.85,at:1,k:'Ten years',t:'10 years, and the trend',
  txt:'36.4% alive at 10 years, and recurrence 39.2% pooled, 26.8% in Australia and New Zealand. Life expectancy loss was 5.5 years on average (32.7% of predicted) and 7.4 years with haemorrhagic stroke <sup class="c" data-ref="Peng2022,Mohan2011" title="Source 682,781"><a href="/stroke/sources/#src-Peng2022">682,781</a></sup>. In Perth\'s 1989 cohort, 10-year recurrence was 43% <sup class="c" data-ref="Hardie2004" title="Source 401"><a href="/stroke/sources/#src-Hardie2004">401</a></sup>. The better news is the trend: across studies, five-year recurrence risk fell from 32% to 16.2% <sup class="c" data-ref="Mohan2011" title="Source 682"><a href="/stroke/sources/#src-Mohan2011">682</a></sup>.',
  pt:'These are not your odds. They are averages over huge groups. And the five-year risk of a second stroke fell across studies <sup class="c" data-ref="Mohan2011" title="Source 682"><a href="/stroke/sources/#src-Mohan2011">682</a></sup>.'}];
const AFT_SURV=[ [.25,79.4],[1,73.0],[5,52.8],[10,36.4] ];
const AFT_REC_P=[ [1/12,3.1],[1,11.1],[5,26.4],[10,39.2] ];
const AFT_REC_A=[ [.25,7.8],[1,11.0],[5,19.8],[10,26.8] ];
function aftTX(m){return Math.log10(1+m*2)/Math.log10(361)}
inits.after=()=>{
  /* ---- invisible effects ---- */
  const svg=$('#aftSvg'),rg=$('#aftT');
  function draw(t){
    const N=vb(svg,'720 410','400 740');
    const L=N?{ix:14,iy:82,cols:20,sz:15,gap:3,cx:40,cy:232,cw:344,ch:430}:{ix:18,iy:92,cols:10,sz:17,gap:3,cx:258,cy:42,cw:448,ch:320};
    const idx=Math.min(5,Math.floor(t*6)),u=clamp((t-idx/6)*6),F=AFT_FX[idx];
    const X=m=>L.cx+L.cw*aftTX(m),Y=v=>L.cy+L.ch-L.ch*v/60;
    let s=`<text x="${L.ix}" y="24" class="t-big">${F.t}</text><text x="${L.ix}" y="${N?46:48}" class="t-lbl">${F.big}</text><text x="${L.ix}" y="${N?62:66}" class="t-sm">${F.sub}</text>`;
    const IC=icons(L.ix,L.iy,{n:100,cols:L.cols,k:Math.round(F.head*ease(ramp(u,.04,.4))),size:L.sz,gap:L.gap,col:'var(--rec)',base:'var(--line)',shape:'person'});
    s+=IC.svg;
    /* the chart frame */
    s+=`<text x="${L.cx-30}" y="${L.cy-14}" class="t-lbl">Share affected, by time since stroke</text>`;
    s+=`<rect x="${L.cx}" y="${L.cy}" width="${L.cw}" height="${L.ch}" style="fill:var(--field)"/>`;
    [0,20,40,60].forEach(v=>{s+=`<line x1="${L.cx}" x2="${L.cx+L.cw}" y1="${f1(Y(v))}" y2="${f1(Y(v))}" class="grid"/><text x="${L.cx-6}" y="${f1(Y(v)+3)}" class="t-xs t-end">${v}%</text>`});
    AFT_TICKS.forEach(([m,l])=>{if(N&&m===120)return;s+=`<line x1="${f1(X(m))}" x2="${f1(X(m))}" y1="${L.cy}" y2="${L.cy+L.ch}" class="grid"/><text x="${f1(X(m))}" y="${L.cy+L.ch+14}" class="t-xs t-mid">${l}</text>`});
    s+=`<line x1="${L.cx}" x2="${L.cx+L.cw}" y1="${L.cy+L.ch}" y2="${L.cy+L.ch}" class="axis"/><line x1="${L.cx}" x2="${L.cx}" y1="${L.cy}" y2="${L.cy+L.ch}" class="axis"/>`;
    F.segs.forEach((g,j)=>{const p=ease(ramp(u,.1+j*.08,.2+j*.08));if(p<=0)return;
      const xa=g.a<=.1?L.cx:X(g.a),xb=X(g.b),xe=lerp(xa,xb,p),y=Y(g.v);let lab=N&&g.ln?g.ln:g.lab;
      if(g.band){s+=`<rect x="${f1(xa)}" y="${f1(Y(g.band[1]))}" width="${f1(xe-xa)}" height="${f1(Y(g.band[0])-Y(g.band[1]))}" rx="2" style="fill:var(--rec);opacity:.55"/>`}
      else if(g.a===g.b){s+=`<circle cx="${f1(xa)}" cy="${f1(y)}" r="${f1(5.5*p)}" style="fill:var(--rec);stroke:var(--panel);stroke-width:1.5"/>`}
      else if(g.dash==='band'){s+=`<line x1="${f1(xa)}" x2="${f1(xe)}" y1="${f1(y)}" y2="${f1(y)}" style="stroke:var(--brand);stroke-width:2"/>`}
      else s+=`<line x1="${f1(xa)}" x2="${f1(xe)}" y1="${f1(y)}" y2="${f1(y)}" style="stroke:var(--rec);stroke-width:${g.dash?2:4};stroke-linecap:round${g.dash?';stroke-dasharray:'+g.dash:''}"/>`;
      /* its label, placed by the data entry so that nothing collides */
      let lx=xa+6,an='',ly=y+g.y;
      if(g.x==='l')lx=xa+2;
      if(g.x==='l0')lx=L.cx+6;
      if(g.x==='lc')lx=X(.46)+6;
      if(g.x==='r'){lx=L.cx+L.cw-4;an='t-end'}
      if(g.x==='r6'){lx=xb+8;}
      if(g.x==='pr'){lx=xa+7}
      if(g.x==='pe'){lx=xa-2;an='t-end'}
      s+=aftLab(lx,ly,lab,an,ramp(u,.18+j*.08,.26+j*.08))});
    if(F.tag&&u>.45)F.tag.forEach((l,i)=>{s+=aftLab(L.cx+L.cw/2,Y(22)+i*16,l,'t-mid',ramp(u,.45,.55))});
    svg.innerHTML=s;
    const p=phaseOf(AFT_STEPS,t);setSt(p);$('#aftNote').innerHTML=noteHTML(AFT_STEPS[p]);
  }
  const stop=playWire(rg,$('#aftPlay'),draw,36000,'Replay','after');
  const setSt=stepWire($('#aftSteps'),AFT_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---- life tabs ---- */
  const tabs=$('#aftTabs');let tab='work',drL='1',drE='s';
  const drawDrive=()=>{const el=$('#aftC-drive'),N=NARROW(),W=N?400:720,x0=N?14:24,w=W-x0*2,D=AFT_DRIVE[drL+drE],X=m=>x0+w*m/12,y=46;
    el.setAttribute('viewBox',`0 0 ${W} 130`);
    let s=`<text x="${x0}" y="20" class="t-lbl">Time off driving, UK DVLA rules as published</text>`;
    s+=`<rect x="${x0}" y="${y}" width="${w}" height="26" rx="4" style="fill:var(--panel-2)"/><rect x="${x0}" y="${y}" width="${f1(X(D.m)-x0)}" height="26" rx="4" style="fill:var(--warn)"/>`;
    [0,3,6,9,12].forEach(m=>{s+=`<line x1="${f1(X(m))}" x2="${f1(X(m))}" y1="${y+26}" y2="${y+32}" class="axis"/><text x="${f1(X(m))}" y="${y+45}" class="t-xs ${m===0?'':m===12?'t-end':'t-mid'}">${m===0?'event':m+' mo'}</text>`});
    s+=D.m<12?`<text x="${f1(X(D.m)+8)}" y="${y+18}" class="t-sm" style="fill:var(--ink)">1 month off driving</text>`:`<text x="${f1(x0+w/2)}" y="${y+18}" class="t-sm t-mid" style="fill:var(--panel)">1 year: licence refused or revoked</text>`;
    s+=`<text x="${x0}" y="${y+70}" class="t-sm">Rules differ by country.</text>`;
    el.innerHTML=s;$('#aftDrH').textContent=D.h;$('#aftDrT').innerHTML=D.t};
  const drawTab=()=>{if(AFT_BARS[tab])rhbBars($('#aftC-'+tab),AFT_BARS[tab]);if(tab==='drive')drawDrive()};
  tabs.addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;tab=b.dataset.tab;
    $$('[data-tab]',tabs).forEach(k=>k.setAttribute('aria-pressed',k===b));
    $$('.aftpanel',$('#m-after')).forEach(p=>p.hidden=p.id!=='aftP-'+tab);drawTab()});
  $('#aftDrL').addEventListener('click',e=>{const b=e.target.closest('[data-l]');if(!b)return;drL=b.dataset.l;$$('[data-l]',$('#aftDrL')).forEach(k=>k.setAttribute('aria-pressed',k===b));drawDrive()});
  $('#aftDrE').addEventListener('click',e=>{const b=e.target.closest('[data-e]');if(!b)return;drE=b.dataset.e;$$('[data-e]',$('#aftDrE')).forEach(k=>k.setAttribute('aria-pressed',k===b));drawDrive()});
  drawTab();drawDrive();

  /* ---- survival and recurrence ---- */
  const sv=$('#aftSvSvg'),svT=$('#aftSvT');
  function aftPanel(B,title,sers,yr,ymax,step){
    const YX=v=>B.x+B.w*Math.sqrt(v)/Math.sqrt(10),Y=v=>B.y+B.h-B.h*v/ymax;
    let g=`<text x="${B.x-28}" y="${B.y-12}" class="t-lbl">${title}</text><rect x="${B.x}" y="${B.y}" width="${B.w}" height="${B.h}" style="fill:var(--field)"/>`;
    for(let v=0;v<=ymax;v+=step)g+=`<line x1="${B.x}" x2="${B.x+B.w}" y1="${f1(Y(v))}" y2="${f1(Y(v))}" class="grid"/><text x="${B.x-6}" y="${f1(Y(v)+3)}" class="t-xs t-end">${v}%</text>`;
    [ [.25,'3 mo'],[1,'1 yr'],[5,'5 yr'],[10,'10 yr'] ].forEach(([v,l])=>{g+=`<text x="${f1(YX(v))}" y="${B.y+B.h+14}" class="t-xs ${v===10?'t-end':'t-mid'}">${l}</text>`});
    g+=`<line x1="${B.x}" x2="${B.x+B.w}" y1="${B.y+B.h}" y2="${B.y+B.h}" class="axis"/><line x1="${B.x}" x2="${B.x}" y1="${B.y}" y2="${B.y+B.h}" class="axis"/>`;
    sers.forEach(S=>{const f=monoFn(S.pts),a=S.pts[0][0],e=Math.min(yr,10);
      if(e>a){let d='';for(let i=0;i<=50;i++){const v=a+(e-a)*Math.pow(i/50,2);d+=(i?'L':'M')+f1(YX(v))+' '+f1(Y(f(v)))}g+=`<path d="${d}" style="fill:none;stroke:${S.col};stroke-width:2.2;stroke-dasharray:${S.dash}"/>`}
      S.pts.forEach((p,i)=>{if(yr<p[0])return;g+=S.shape==='sq'?`<rect x="${f1(YX(p[0])-4.5)}" y="${f1(Y(p[1])-4.5)}" width="9" height="9" style="fill:${S.col};stroke:var(--panel);stroke-width:1"/>`:`<circle cx="${f1(YX(p[0]))}" cy="${f1(Y(p[1]))}" r="5" style="fill:${S.col};stroke:var(--panel);stroke-width:1.2"/>`;
        const P=S.lab[i];g+=rhbLab(YX(p[0])+P[0],Y(p[1])+P[1],`${p[1].toFixed(1)}%`,{a:P[2]||''})});
      if(S.name)g+=rhbLab(B.x+B.w-6,Y(S.ny),S.name,{a:'t-end'})});
    return g}
  function drawSv(t){
    const N=vb(sv,'720 370','400 720');
    const A=N?{x:42,y:40,w:340,h:250}:{x:42,y:36,w:290,h:286},B=N?{x:42,y:400,w:340,h:270}:{x:402,y:36,w:296,h:286};
    const yr=Math.pow(clamp(t),2)*10,cx=[A,B];
    let s=aftPanel(A,'Alive, Australia and New Zealand',[{pts:AFT_SURV,col:'var(--rec)',dash:'6 4',lab:[ [8,-6],[8,-6],[8,-6],[-8,16,'t-end'] ]}],yr,100,25);
    s+=aftPanel(B,'Had a further stroke (cumulative)',[
      {pts:AFT_REC_P,col:'var(--brand)',dash:'6 4',lab:[ [0,-9,'t-mid'],[-6,-9,'t-end'],[-6,-9,'t-end'],[-6,-9,'t-end'] ],name:'circles: pooled review',ny:8},
      {pts:AFT_REC_A,col:'var(--rec)',dash:'2 4',shape:'sq',lab:[ [0,-9,'t-mid'],[6,17],[6,17],[-6,-9,'t-end'] ],name:'squares: Australia and NZ',ny:3.5}],yr,50,10);
    const sw=()=>Math.sqrt(yr)/Math.sqrt(10);
    cx.forEach(P=>{const x=P.x+P.w*sw();s+=`<line x1="${f1(x)}" x2="${f1(x)}" y1="${P.y}" y2="${P.y+P.h}" style="stroke:var(--ink);stroke-width:1"/>`});
    const yl=`${yr<.95?Math.round(yr*12)+' months':yr.toFixed(yr<9.95?1:0)+' years'} after stroke`;cx.forEach(P=>{s+=`<text x="${f1(P.x+P.w/2)}" y="${P.y+P.h+30}" class="t-sm t-mid">${yl}</text>`});
    sv.innerHTML=s;
    const p=phaseOf(AFT_SV_STEPS,t);setSv(p);$('#aftSvNote').innerHTML=noteHTML(AFT_SV_STEPS[p]);
  }
  const stopSv=playWire(svT,$('#aftSvPlay'),drawSv,16000,'Replay','after');
  const setSv=stepWire($('#aftSvSteps'),AFT_SV_STEPS,svT,drawSv,stopSv);
  drawSv(+svT.value);

  const prev=redraws.after;redraws.after=()=>{prev&&prev();drawTab();drawDrive()};
};
function aftLab(x,y,t,a,op){return `<text x="${f1(x)}" y="${f1(y)}" class="t-sm${a?' '+a:''}" style="fill:var(--ink);opacity:${f1(op)};paint-order:stroke;stroke:var(--panel);stroke-width:3px;stroke-linejoin:round">${t}</text>`}
/* =============== 5.3 Nursing care =============== */
/* Six widgets: the first 72 h as nine 8-hour blocks (lanes, with toggles); swallow-first flow; post-thrombolysis
   observation schedules from OPTIMISTmain with a running count; warning signs on a face; a bedside body map with bars;
   an invented aphasia dialogue and a teaching checklist. Eight-hour blocks and even tick spacing are teaching devices. */
const NRS_STEPS=[
 {from:0,at:.055,k:'Hours 0 to 8',t:'0 to 8 h: swallow first',
  txt:`Swallow screen or assessment within 4 h of admission and before oral food, drink or medications <sup class="c" data-ref="Fasugba2023" title="Source 292"><a href="/stroke/sources/#src-Fasugba2023">292</a></sup>. Formal venous glucose on admission, and temperature and glucose charting start <sup class="c" data-ref="Fasugba2023" title="Source 292"><a href="/stroke/sources/#src-Fasugba2023">292</a></sup>. After thrombolysis: observations every 15 min for 2 h, then every 30 min for 6 h <sup class="c" data-ref="Anderson2025F" title="Source 43"><a href="/stroke/sources/#src-Anderson2025F">43</a></sup>. Watch lips and tongue: orolingual angio-oedema began a median of 65 min after alteplase started <sup class="c" data-ref="Hurford2015" title="Source 451"><a href="/stroke/sources/#src-Hurford2015">451</a></sup>.`,
  pt:`You may not be allowed to eat, drink or take tablets until a nurse has checked your swallow <sup class="c" data-ref="Martino2005,Fasugba2023" title="Source 292,637"><a href="/stroke/sources/#src-Martino2005">292,637</a></sup>.`},
 {from:1/9,at:.166,k:'Hours 8 to 16',t:'8 to 16 h: thresholds',
  txt:`Temperature and glucose at least four times a day. Protocol triggers as listed: 37.5°C or more, "treat with paracetamol or other anti-pyretic"; above 10 mmol/L, "treat with insulin" <sup class="c" data-ref="Fasugba2023" title="Source 292"><a href="/stroke/sources/#src-Fasugba2023">292</a></sup>. Post-thrombolysis observations move to hourly at 8 h <sup class="c" data-ref="Anderson2025F" title="Source 43"><a href="/stroke/sources/#src-Anderson2025F">43</a></sup>. Record GCS as its three components <sup class="c" data-ref="Teasdale2014" title="Source 967"><a href="/stroke/sources/#src-Teasdale2014">967</a></sup>. Head position: HeadPoST found no outcome difference between flat and 30 degrees or more <sup class="c" data-ref="Anderson2017" title="Source 40"><a href="/stroke/sources/#src-Anderson2017">40</a></sup>.`},
 {from:2/9,at:.277,k:'Hours 16 to 24',t:'16 to 24 h: first-day close',
  txt:`The post-thrombolysis schedule runs until 24 h <sup class="c" data-ref="Anderson2025F" title="Source 43"><a href="/stroke/sources/#src-Anderson2025F">43</a></sup>. Progressing stroke occurred in 18.4% in the first week of one stroke unit, so a change from the last check matters <sup class="c" data-ref="Indredavik2008" title="Source 457"><a href="/stroke/sources/#src-Indredavik2008">457</a></sup>. Can this person walk to the toilet without help? That was the CLOTS 3 test for immobility <sup class="c" data-ref="Dennis2013" title="Source 236"><a href="/stroke/sources/#src-Dennis2013">236</a></sup>.`},
 {from:3/9,at:.388,k:'Hours 24 to 32',t:'24 to 32 h: out of bed',
  txt:`Exploratory network analysis suggested first mobilisation at around 24 h had the lowest odds of death or poor outcome <sup class="c" data-ref="Langhorne2018" title="Source 543"><a href="/stroke/sources/#src-Langhorne2018">543</a></sup>. The AVERT dose signal favours shorter, more frequent out-of-bed sessions, and nurses recorded session data alongside physiotherapists in the trial <sup class="c" data-ref="Bernhardt2016" title="Source 99"><a href="/stroke/sources/#src-Bernhardt2016">99</a></sup>. Moving brings falls risk: 25% fell during admission in one cohort, 5% with serious injury <sup class="c" data-ref="Langhorne2000" title="Source 540"><a href="/stroke/sources/#src-Langhorne2000">540</a></sup>.`,
  pt:`Getting up matters, but more is not always better in the first day. Short and frequent sessions looked better than long ones <sup class="c" data-ref="Bernhardt2016" title="Source 99"><a href="/stroke/sources/#src-Bernhardt2016">99</a></sup>.`},
 {from:4/9,at:.5,k:'Hours 32 to 40',t:'32 to 40 h: watch for swelling',
  txt:`After large infarcts nurses watch for new impaired consciousness and pupil changes; in cerebellar infarction, falling consciousness <sup class="c" data-ref="Wijdicks2014" title="Source 1047"><a href="/stroke/sources/#src-Wijdicks2014">1047</a></sup>. The pooled craniectomy trials operated within 48 h, so early recognition has a deadline <sup class="c" data-ref="Vahedi2007" title="Source 994"><a href="/stroke/sources/#src-Vahedi2007">994</a></sup>. Keep temperature and glucose going <sup class="c" data-ref="Fasugba2023" title="Source 292"><a href="/stroke/sources/#src-Fasugba2023">292</a></sup>.`},
 {from:5/9,at:.611,k:'Hours 40 to 48',t:'40 to 48 h: glucose review',
  txt:`The glucose element runs for the first 48 h, continuing for 72 h if unstable <sup class="c" data-ref="Fasugba2023" title="Source 292"><a href="/stroke/sources/#src-Fasugba2023">292</a></sup>. Most first-week complications occurred in the first 4 days, and stroke severity was the most important risk factor <sup class="c" data-ref="Indredavik2008" title="Source 457"><a href="/stroke/sources/#src-Indredavik2008">457</a></sup>.`},
 {from:6/9,at:.722,k:'Hours 48 to 56',t:'48 to 56 h: catheter, bowel, skin',
  txt:`Catheters were placed for output monitoring, retention or continence issues, with no policy or standard tool and poor documentation <sup class="c" data-ref="Cowey2012" title="Source 205"><a href="/stroke/sources/#src-Cowey2012">205</a></sup>. Catheterisation was associated with urinary infection (OR 3.03, 1.41 to 6.52) <sup class="c" data-ref="Stott2009" title="Source 945"><a href="/stroke/sources/#src-Stott2009">945</a></sup>. New constipation affected 46.3% of 600 people <span class="ev early">Early evidence</span> <sup class="c" data-ref="Lv2026" title="Source 604"><a href="/stroke/sources/#src-Lv2026">604</a></sup>. Check under devices: leg skin breaks were 3% vs 1% with pneumatic compression <sup class="c" data-ref="Dennis2013" title="Source 236"><a href="/stroke/sources/#src-Dennis2013">236</a></sup>.`},
 {from:7/9,at:.833,k:'Hours 56 to 64',t:'56 to 64 h: mood, mind, words',
  txt:`Delirium occurred in 11.8% in the first week of one cohort <sup class="c" data-ref="Oldenbeuving2011" title="Source 754"><a href="/stroke/sources/#src-Oldenbeuving2011">754</a></sup>. Standard self-report mood tools may not suit people with aphasia, and two tools use visual prompts <sup class="c" data-ref="Burton2015" title="Source 148"><a href="/stroke/sources/#src-Burton2015">148</a></sup>. Communication problems raise preventable adverse events (OR 3.00, 1.43 to 6.27) <sup class="c" data-ref="Bartlett2008" title="Source 88"><a href="/stroke/sources/#src-Bartlett2008">88</a></sup>. Start teaching with the person and family: active information did better than passive on mood <sup class="c" data-ref="Forster2012" title="Source 331"><a href="/stroke/sources/#src-Forster2012">331</a></sup>.`},
 {from:8/9,at:.944,k:'Hours 64 to 72',t:'64 to 72 h: hand on the plan',
  txt:`The temperature element covers the first 72 h <sup class="c" data-ref="Fasugba2023" title="Source 292"><a href="/stroke/sources/#src-Fasugba2023">292</a></sup>. Nurses ensure stroke education through transitions home <sup class="c" data-ref="Ashcraft2021" title="Source 55"><a href="/stroke/sources/#src-Ashcraft2021">55</a></sup>. Early supported discharge cut stay by about seven days and death or dependency (OR 0.80, 0.67 to 0.97), mainly with a co-ordinated team and mild to moderate disability <sup class="c" data-ref="Fearon2012" title="Source 299"><a href="/stroke/sources/#src-Fearon2012">299</a></sup>. Shoulder pain peaks later, at 4 months, so it belongs in the plan <sup class="c" data-ref="AdeyWakeling2015" title="Source 10"><a href="/stroke/sources/#src-AdeyWakeling2015">10</a></sup>.`,
  hook:`Standard post-lysis observations: every 15 min for 2 h, every 30 min for 6 h, then hourly until 24 h <sup class="c" data-ref="Anderson2025F" title="Source 43"><a href="/stroke/sources/#src-Anderson2025F">43</a></sup>.`}];
const nrsStd=()=>{const a=[];for(let h=.25;h<=2;h+=.25)a.push(h);for(let h=2.5;h<=8;h+=.5)a.push(h);for(let h=9;h<=24;h++)a.push(h);return a};
const nrsLow=()=>{const a=[];for(let h=.25;h<=2;h+=.25)a.push(h);for(let h=4;h<=10;h+=2)a.push(h);for(let h=14;h<=24;h+=4)a.push(h);return a};

/* ---- swallow-first flow ---- */
const NRS_FL_STEPS=[
 {from:0,at:.06,k:'Step 1',t:'Admission',txt:`The clock starts at admission. The FeSS wording asks for a screen or assessment within 4 h <sup class="c" data-ref="Fasugba2023" title="Source 292"><a href="/stroke/sources/#src-Fasugba2023">292</a></sup>. In Ontario, 19.2% of those eligible had no documented screen, and people with mild stroke were less likely to be screened (adjusted OR 0.51, 0.41 to 0.64) <sup class="c" data-ref="Joundi2017" title="Source 474"><a href="/stroke/sources/#src-Joundi2017">474</a></sup>.`,
  hook:`Mild stroke is the group most often missed <sup class="c" data-ref="Joundi2017" title="Source 474"><a href="/stroke/sources/#src-Joundi2017">474</a></sup>.`},
 {from:.2,at:.26,k:'Step 2',t:'Nothing by mouth yet',txt:`The screen comes "prior to being given oral food, drink, or medications" <sup class="c" data-ref="Fasugba2023" title="Source 292"><a href="/stroke/sources/#src-Fasugba2023">292</a></sup>. That includes tablets. If aspirin is due, the Cochrane review states it may be given orally, by nasogastric tube or per rectum in people who cannot swallow <sup class="c" data-ref="Minhas2022,Sandercock2014" title="Source 678,879"><a href="/stroke/sources/#src-Minhas2022">678,879</a></sup>.`,
  pt:`Food or drink going down the wrong way can cause a chest infection <sup class="c" data-ref="Martino2005" title="Source 637"><a href="/stroke/sources/#src-Martino2005">637</a></sup>.`},
 {from:.4,at:.48,k:'Step 3',t:'The screen',txt:`In the Cochrane review 21 of 37 screens were carried out by nurses. No single tool had high and precisely estimated sensitivity and specificity; water-only tools ranged 46% to 100% sensitivity and 43% to 100% specificity <sup class="c" data-ref="Boaden2021" title="Source 111"><a href="/stroke/sources/#src-Boaden2021">111</a></sup>.`},
 {from:.6,at:.72,k:'Step 4',t:'Result and next step',txt:`Those who fail are referred to a speech pathologist <sup class="c" data-ref="Fasugba2023" title="Source 292"><a href="/stroke/sources/#src-Fasugba2023">292</a></sup>. Failing was associated with pneumonia (adjusted OR 4.71), severe disability (5.19), long-term care (2.79) and 1-year death (HR 2.42), including in mild stroke <sup class="c" data-ref="Joundi2017" title="Source 474"><a href="/stroke/sources/#src-Joundi2017">474</a></sup>. A pass does not remove all risk: no screening tool is precise <sup class="c" data-ref="Boaden2021" title="Source 111"><a href="/stroke/sources/#src-Boaden2021">111</a></sup>.`},
 {from:.85,at:.95,k:'Step 5',t:'Chart it',txt:`Record the time of screen and the result, before any oral intake or medicines. Delay carries pneumonia risk: absolute incidence rose by 1% per day of delay to specialist assessment <sup class="c" data-ref="Bray2017,Fasugba2023" title="Source 125,292"><a href="/stroke/sources/#src-Bray2017">125,292</a></sup>.`}];
const NRS_NODES={
 a:{t:'Admission',l:['Stroke suspected.','The 4 h clock starts.']},
 b:{t:'Nothing by mouth',l:['No food, no drink,','no tablets yet.']},
 c:{t:'Swallow screen',l:['Within 4 h, and before','anything by mouth.']},
 d:{t:'Passed',l:['Oral food, drink and','tablets can follow.']},
 e:{t:'Failed',l:['Referral to a','speech pathologist.']},
 f:{t:'Medicines still due?',l:['Aspirin: tube or','rectal route exists.']},
 g:{t:'Chart it',l:['Time of screen, result, anything by mouth.']}};

/* ---- warning signs ---- */
const NRS_SIGNS={
 hemi:{t:'Swollen hemispheric infarct',k:'Large infarct',signs:['New or further impaired consciousness','Cerebral ptosis','Changes in pupil size'],
  txt:`These are the AHA statement's warning signs in swollen hemispheric infarction <sup class="c" data-ref="Wijdicks2014" title="Source 1047"><a href="/stroke/sources/#src-Wijdicks2014">1047</a></sup>. Its pooled surgical trials operated within 48 h <sup class="c" data-ref="Vahedi2007" title="Source 994"><a href="/stroke/sources/#src-Vahedi2007">994</a></sup>.`},
 cereb:{t:'Swollen cerebellar infarct',k:'Back of the brain',signs:['Falling consciousness','Possible early loss of corneal reflexes','Miosis (small pupils)'],
  txt:`Falling consciousness from brainstem compression, possibly with early loss of corneal reflexes and miosis <sup class="c" data-ref="Wijdicks2014" title="Source 1047"><a href="/stroke/sources/#src-Wijdicks2014">1047</a></sup>.`},
 lysis:{t:'Angio-oedema after thrombolysis',k:'During and after the drip',signs:['Lip or tongue swelling','5 to 189 min after alteplase started','Prior ACE inhibitor: OR 2.3'],
  txt:`Orolingual angio-oedema occurred in 7.9% of 530 people. 12% of those cases were severe (1% of all treated) and needed urgent advanced airway management <sup class="c" data-ref="Hurford2015" title="Source 451"><a href="/stroke/sources/#src-Hurford2015">451</a></sup>. The label says to stop the infusion and treat if anaphylactoid reaction or angioedema develops <sup class="c" data-ref="FDA-Activase" title="Source 293"><a href="/stroke/sources/#src-FDA-Activase">293</a></sup>.`,
  pt:`After the clot-busting drip, nurses check you often through the first day. Tell them at once if your lips or tongue feel swollen <sup class="c" data-ref="Anderson2025F,FDA-Activase" title="Source 43,293"><a href="/stroke/sources/#src-Anderson2025F">43,293</a></sup>.`}};

/* ---- bedside body map ---- */
const NRS_BODY=[
 {id:'head',n:'1',b:'Head position',at:[-.035,-.44],
  bars:{h:'HeadPoST, lying flat vs head up',max:100,r:[{l:'Kept to lying flat for 24 h',v:87,s:'87%'},{l:'Kept to head up for 24 h',v:95,s:'95%'},{l:'Died, lying flat',v:7.3,s:'7.3%'},{l:'Died, head up',v:7.4,s:'7.4%'}]},
  txt:`Lying flat for 24 h did not improve outcome over sitting up with the head at 30 degrees or more, and fewer people kept to it. Serious adverse events including pneumonia did not differ <sup class="c" data-ref="Anderson2017" title="Source 40"><a href="/stroke/sources/#src-Anderson2017">40</a></sup>.`,
  pt:`Lying flat does not help more than sitting up with your head raised <sup class="c" data-ref="Anderson2017" title="Source 40"><a href="/stroke/sources/#src-Anderson2017">40</a></sup>.`},
 {id:'mouth',n:'2',b:'Mouth care',at:[.04,-.395],
  bars:{h:'Pneumonia in the one trial reporting it',max:10,r:[{l:'Oral care programme',v:5.05,s:'5 of 99'},{l:'Comparison',v:.95,s:'1 of 105'}]},
  txt:`Oral care is widely taught as pneumonia prevention, but the trial evidence specifically in stroke is thin. Cochrane 2020 found less denture plaque and better knowledge, and no difference in pneumonia in the one trial reporting it (OR 4.17, 0.82 to 21.11; low quality) <sup class="c" data-ref="Campbell2020" title="Source 158"><a href="/stroke/sources/#src-Campbell2020">158</a></sup>. A European review finds only weak evidence <sup class="c" data-ref="Lyons2018" title="Source 609"><a href="/stroke/sources/#src-Lyons2018">609</a></sup>. ESO/ESSD lists oral health care among dysphagia treatment options <sup class="c" data-ref="Dziewas2021" title="Source 264"><a href="/stroke/sources/#src-Dziewas2021">264</a></sup>. Status: unresolved.`},
 {id:'shoulder',n:'3',b:'Shoulder',at:[.125,-.285],
  bars:{h:'Shoulder pain, population study',max:30,r:[{l:'Baseline',v:10,s:'10%'},{l:'4 months',v:21,s:'21%'},{l:'12 months',v:21,s:'21%'},{l:'At some point in 12 months',v:29,s:'29%'}]},
  txt:`Peak onset and severity were at 4 months, after most rehabilitation ends. Passive range-of-motion testing elicited more pain than self-report and predicted later pain (crude RR 3.22, 1.01 to 10.27) <sup class="c" data-ref="AdeyWakeling2015" title="Source 10"><a href="/stroke/sources/#src-AdeyWakeling2015">10</a></sup>. Cochrane found insufficient evidence on slings and wheelchair attachments; strapping delayed onset by 14 days without reducing severity <sup class="c" data-ref="Ada2005" title="Source 3"><a href="/stroke/sources/#src-Ada2005">3</a></sup>.`,
  pt:`Shoulder pain often starts some months after a stroke, so keep mentioning it after you go home <sup class="c" data-ref="AdeyWakeling2015" title="Source 10"><a href="/stroke/sources/#src-AdeyWakeling2015">10</a></sup>.`},
 {id:'bladder',n:'4',b:'Bladder',at:[0,-.03],
  bars:{h:'Urinary incontinence over time',max:50,r:[{l:'At first',v:40,s:'40%'},{l:'3 months',v:19,s:'19%'},{l:'1 year',v:15,s:'15%'},{l:'2 years',v:10,s:'10%'}]},
  txt:`Urinary infection affected 15.8% of 412 people, at a median of 14 days, and was associated with catheterisation (OR 3.03) <sup class="c" data-ref="Stott2009" title="Source 945"><a href="/stroke/sources/#src-Stott2009">945</a></sup>. A programme in three Japanese hospitals cut inappropriate catheter use from 50.1% to 22.5% and symptomatic infection from 9.5% to 4.9%, without more retention <sup class="c" data-ref="IkedaSakai2022" title="Source 456"><a href="/stroke/sources/#src-IkedaSakai2022">456</a></sup>. Cochrane found insufficient evidence to guide continence care in rehabilitation <sup class="c" data-ref="Thomas2019" title="Source 978"><a href="/stroke/sources/#src-Thomas2019">978</a></sup>. Bars from <sup class="c" data-ref="Patel2001" title="Source 776"><a href="/stroke/sources/#src-Patel2001">776</a></sup>.`,
  pt:`Trouble passing urine or holding it is common and often gets better over time. A catheter can raise the chance of infection, so it should be there only if needed <sup class="c" data-ref="Patel2001,Stott2009" title="Source 776,945"><a href="/stroke/sources/#src-Patel2001">776,945</a></sup>.`},
 {id:'bowel',n:'5',b:'Bowel',at:[-.1,.03],
  bars:{h:'New-onset faecal incontinence',max:50,r:[{l:'7 to 10 days',v:30,s:'30%'},{l:'3 months',v:11,s:'11%'},{l:'1 year',v:11,s:'11%'},{l:'3 years',v:15,s:'15%'}]},
  txt:`At 3 months it was tied to anticholinergic drugs (OR 3.1) and needing help with the toilet (OR 3.5), both potentially changeable <sup class="c" data-ref="Harari2003" title="Source 397"><a href="/stroke/sources/#src-Harari2003">397</a></sup>. In 600 people, 46.3% had constipation, with risk factors including bedpan use, depression, poor sleep and NIHSS <span class="ev early">Early evidence</span> <sup class="c" data-ref="Lv2026" title="Source 604"><a href="/stroke/sources/#src-Lv2026">604</a></sup>.`},
 {id:'skin',n:'6',b:'Skin',at:[.09,.1],
  bars:{h:'Pressure sores: three different groups',max:30,r:[{l:'Inpatients, 2000 cohort',v:21,s:'21%'},{l:'First week, one stroke unit',v:2.5,s:'2.5% or fewer'},{l:'Year after severely disabling stroke',v:22,s:'22%'}]},
  txt:`These are not one rate: the people and time frames differ <sup class="c" data-ref="Langhorne2000,Indredavik2008,Sackley2008" title="Source 457,540,876"><a href="/stroke/sources/#src-Langhorne2000">457,540,876</a></sup>. Devices harm skin too: leg skin breaks 3% vs 1% with pneumatic compression <sup class="c" data-ref="Dennis2013" title="Source 236"><a href="/stroke/sources/#src-Dennis2013">236</a></sup> and 5% vs 1% with stockings <sup class="c" data-ref="Dennis2009" title="Source 234"><a href="/stroke/sources/#src-Dennis2009">234</a></sup>. Nutrition supplements were associated with fewer pressure sores (OR 0.56, 0.32 to 0.96) <sup class="c" data-ref="Geeganage2012" title="Source 347"><a href="/stroke/sources/#src-Geeganage2012">347</a></sup>.`},
 {id:'legs',n:'7',b:'Legs and clots',at:[-.08,.26],
  bars:{h:'Proximal DVT in the CLOTS trials',max:15,r:[{l:'CLOTS 3: pneumatic compression',v:8.5,s:'8.5%'},{l:'CLOTS 3: none',v:12.1,s:'12.1%'},{l:'CLOTS 1: thigh stockings',v:10,s:'10.0%'},{l:'CLOTS 1: none',v:10.5,s:'10.5%'}]},
  txt:`Immobile in CLOTS 3 meant unable to walk to the toilet without another person's help <sup class="c" data-ref="Dennis2013" title="Source 236"><a href="/stroke/sources/#src-Dennis2013">236</a></sup>. Stockings did not help against none, and caused more skin problems <sup class="c" data-ref="Dennis2009" title="Source 234"><a href="/stroke/sources/#src-Dennis2009">234</a></sup>.`,
  pt:`Machines that gently squeeze your legs can lower the risk of clots in people who cannot walk alone <sup class="c" data-ref="Dennis2013" title="Source 236"><a href="/stroke/sources/#src-Dennis2013">236</a></sup>.`},
 {id:'falls',n:'8',b:'Falls',at:[.08,.42],
  bars:{h:'People who fell, in four settings',max:100,r:[{l:'In hospital, one cohort',v:25,s:'25%'},{l:'Community, Auckland',v:37,s:'37%'},{l:'Within 6 months of discharge',v:73,s:'73%'},{l:'12 months, severely disabling',v:73,s:'73%'}]},
  txt:`Falls occur at all stages: acute, rehabilitative and chronic <sup class="c" data-ref="Batchelor2012" title="Source 89"><a href="/stroke/sources/#src-Batchelor2012">89</a></sup>. Bars from <sup class="c" data-ref="Langhorne2000,Kerse2008,Forster1995,Sackley2008" title="Source 330,494,540,876"><a href="/stroke/sources/#src-Langhorne2000">330,494,540,876</a></sup>. A fall in hospital combined with poor balance predicted recurrent falls in a small study of 55 people <sup class="c" data-ref="Mackintosh2006" title="Source 619"><a href="/stroke/sources/#src-Mackintosh2006">619</a></sup>. Exercise may reduce the rate of falls (rate ratio 0.72, 0.54 to 0.94; low quality) but not the number of fallers <sup class="c" data-ref="Denissen2019" title="Source 231"><a href="/stroke/sources/#src-Denissen2019">231</a></sup>.`,
  pt:`Many people fall after a stroke, even at home. A fall in hospital is a warning sign to plan for <sup class="c" data-ref="Forster1995,Kerse2008" title="Source 330,494"><a href="/stroke/sources/#src-Forster1995">330,494</a></sup>.`}];

/* ---- aphasia ---- */
const NRS_DIAL={
 off:[{w:'Nurse',s:`Do you want the blue one or the white one, and did your daughter bring your glasses, or are they still at home?`},{w:'Person',s:`(Tries to answer. Words will not come.)`},{w:'Nurse',s:`Never mind. I will ask your daughter.`}],
 on:[{w:'Nurse',s:`I know you know what you want to say. Take your time. Is it about your glasses?`},{w:'Person',s:`(Nods.)`},{w:'Nurse',s:`Here is a pen. Show me: at home, or in the bag? (Holds up two written words.)`},{w:'Person',s:`(Points to "home".)`},{w:'Nurse',s:`At home. Have I got that right? I will ask your daughter to bring them.`}]};
/* ---- teaching checklist ---- */
const NRS_TEACH=[
 `FAST: Face, Arm, Speech, Time. Call emergency services for sudden symptoms. FAST catches most strokes but not all: it missed 30.6% of haemorrhages <sup class="c" data-ref="Kleindorfer2007" title="Source 508"><a href="/stroke/sources/#src-Kleindorfer2007">508</a></sup>.`,
 `Which stroke type and cause, and what the risk factors are. Information improves patient knowledge (SMD 0.29) and carer knowledge (SMD 0.74) <sup class="c" data-ref="Forster2012" title="Source 331"><a href="/stroke/sources/#src-Forster2012">331</a></sup>.`,
 `Medicines: what each is for. Knowledge alone does not guarantee control: educational interventions showed no clear difference in adherence or recurrent events <sup class="c" data-ref="Bridgwood2018" title="Source 129"><a href="/stroke/sources/#src-Bridgwood2018">129</a></sup>.`,
 `Blood pressure at home. COMPASS raised home monitoring from 64% to 72% (aOR 1.43) <sup class="c" data-ref="Duncan2020" title="Source 260"><a href="/stroke/sources/#src-Duncan2020">260</a></sup>.`,
 `Swallow plan: what is safe to eat, drink and swallow, and who assessed it <sup class="c" data-ref="Fasugba2023" title="Source 292"><a href="/stroke/sources/#src-Fasugba2023">292</a></sup>.`,
 `Falls: what happened in hospital, and the plan at home. 73% of older people with residual disability fell within 6 months of discharge <sup class="c" data-ref="Forster1995" title="Source 330"><a href="/stroke/sources/#src-Forster1995">330</a></sup>.`,
 `Bladder and bowel: common, and often improves <sup class="c" data-ref="Patel2001,Harari2003" title="Source 397,776"><a href="/stroke/sources/#src-Patel2001">397,776</a></sup>.`,
 `Mood: about 3 in 10 people feel low after a stroke. Tell someone <sup class="c" data-ref="Hackett2014,Towfighi2017" title="Source 381,980"><a href="/stroke/sources/#src-Hackett2014">381,980</a></sup>.`,
 `Shoulder pain may start later. Keep mentioning it <sup class="c" data-ref="AdeyWakeling2015" title="Source 10"><a href="/stroke/sources/#src-AdeyWakeling2015">10</a></sup>.`,
 `Communication: how this person shows yes and no, and what helps <sup class="c" data-ref="Kagan2001" title="Source 480"><a href="/stroke/sources/#src-Kagan2001">480</a></sup>.`,
 `Carers: burden is real, and evidence on support is limited <sup class="c" data-ref="Bakas2022" title="Source 74"><a href="/stroke/sources/#src-Bakas2022">74</a></sup>. Follow-up: who to call, and when <sup class="c" data-ref="Duncan2020" title="Source 260"><a href="/stroke/sources/#src-Duncan2020">260</a></sup>.`];

inits.nursing=()=>{
  /* ---- 1. 72-hour scrubber ---- */
  (function(){const svg=$('#nrsSvg'),rg=$('#nrsT');const tg={lys:true,imm:true,fail:false};
    function draw(t){const N=vb(svg,'720 470','400 556'),h=t*72,px=N?14:164,pw=N?372:542,X=v=>px+pw*v/72,top=N?60:62,lh=N?58:46,bh=N?22:24;let s='',lab='';
      /* blocks */
      for(let i=0;i<9;i++){const a=X(i*8),on=h>=i*8&&h<(i+1)*8||(i===8&&h>=72);
        s+=`<rect x="${f1(a+1)}" y="14" width="${f1(pw/9-2)}" height="24" rx="5" style="fill:${on?'var(--brand)':'var(--panel-2)'}"/><text x="${f1(a+pw/18)}" y="30" class="t-sm t-mid" style="fill:${on?'var(--on-brand)':'var(--ink)'};font-weight:700">${i+1}</text>`}
      if(!N)s+=`<text x="14" y="30" class="t-lbl">8-hour block</text>`;
      [0,24,48,72].forEach(v=>{s+=`<text x="${f1(clamp(X(v),px+7,px+pw-10))}" y="52" class="t-xs t-mid">${v} h</text><line x1="${f1(X(v))}" x2="${f1(X(v))}" y1="${top-4}" y2="${top+lh*8-4}" class="grid"/>`});
      const tick=(x,y,seen,o={})=>`<line x1="${f1(x)}" x2="${f1(x)}" y1="${y}" y2="${y+bh}" style="stroke:var(--brand);stroke-width:${o.w||2};opacity:${seen?1:.35}${o.dash?';stroke-dasharray:2 3':''}"/>`;
      const band=(a,b,y,fill,txt,o={})=>{let g=`<rect x="${f1(X(a))}" y="${y}" width="${f1(X(b)-X(a))}" height="${bh}" rx="4" style="fill:${fill}${o.dash?';stroke:var(--muted);stroke-dasharray:4 3':''}"/>`;if(txt)lab+=`<text x="${f1(X(a)+6+(o.off||0))}" y="${y+bh/2+4}" class="t-sm" style="fill:var(--ink);paint-order:stroke;stroke:var(--panel);stroke-width:3px">${txt}</text>`;return g};
      const lanes=['Swallow','Temperature',N?'Glucose (dashed after 48 h: if unstable)':'Glucose','Post-lysis checks','GCS, NIHSS','Legs','Out of bed','Bladder, skin, falls'];
      lanes.forEach((L,i)=>{const y=top+i*lh,by=N?y+18:y+6;
        s+=N?`<text x="14" y="${y+12}" class="t-lbl">${L}</text>`:(i===2?`<text x="14" y="${by+9}" class="t-lbl">${L}</text><text x="14" y="${by+24}" class="t-sm">dashed: if unstable</text>`:`<text x="14" y="${by+bh/2+4}" class="t-lbl">${L}</text>`);
        if(i===0){s+=band(0,3,by,'var(--accent)','');
          if(tg.fail)s+=band(3,72,by,'var(--warn-soft)',N?'failed: speech pathologist referral':'failed the screen: referral to a speech pathologist',{dash:1,off:N?6:10});
          else s+=band(3,72,by,'var(--rec-soft)',N?'passed at 3 h: oral intake can follow':'passed at 3 h in this example: oral food, drink and tablets can follow',{off:N?6:10});
          s+=`<line x1="${f1(X(4))}" x2="${f1(X(4))}" y1="${by-3}" y2="${by+bh+3}" style="stroke:var(--accent);stroke-width:1.5;stroke-dasharray:3 2"/>`}
        if(i===1){for(let v=0;v<=72;v+=6)s+=tick(clamp(X(v),px+1,px+pw-1),by,v<=h)}
        if(i===2){for(let v=0;v<=72;v+=6)s+=tick(clamp(X(v),px+1,px+pw-1),by,v<=h,{dash:v>48})}
        if(i===3){if(tg.lys){nrsStd().forEach(v=>{s+=tick(X(v),by,v<=h,{w:1.1})});lab+=`<text x="${f1(X(25))}" y="${by+bh/2+4}" class="t-sm" style="fill:var(--ink);paint-order:stroke;stroke:var(--panel);stroke-width:3px">${N?'15 min, 30 min, hourly':'every 15 min, 30 min, then hourly, to 24 h'}</text>`}
          else s+=band(0,72,by,'var(--panel-2)','no thrombolysis: this schedule does not apply')}
        if(i===4)s+=band(0,72,by,'var(--panel-2)',N?'serial checks; no schedule in sources':'serial checks; no general schedule in the sources read',{dash:1});
        if(i===5){if(tg.imm)s+=band(0,72,by,'var(--brand-soft)',N?'cannot walk alone: CLOTS 3 group':'cannot walk to the toilet alone: the CLOTS 3 group');else s+=band(0,72,by,'var(--panel-2)','walks alone: outside the CLOTS 3 entry test')}
        if(i===6){s+=`<circle cx="${f1(X(24))}" cy="${by+bh/2}" r="5" style="fill:var(--rec)"/>`;for(let v=28;v<=70;v+=4.8)s+=`<rect x="${f1(X(v))}" y="${by+5}" width="5" height="${bh-10}" rx="2" style="fill:var(--rec);opacity:${v<=h?1:.35}"/>`;
          lab+=`<text x="${f1(X(1))}" y="${by+bh/2+4}" class="t-sm" style="fill:var(--ink);paint-order:stroke;stroke:var(--panel);stroke-width:3px">${N?'around 24 h':'first time: around 24 h'}</text>`}
        if(i===7)s+=band(0,72,by,'var(--panel-2)',N?'each block: catheter, skin, falls, mood':'each block: catheter need, skin, falls risk, mood and communication tools',{dash:1})});
      const b=top+lh*8-4,cx=X(h);s+=`<line x1="${f1(cx)}" x2="${f1(cx)}" y1="40" y2="${b}" style="stroke:var(--accent);stroke-width:2"/>`;
      const pw2=60,plx=clamp(cx-pw2/2,N?2:px-pw2/2,(N?398:718)-pw2);s+=`<rect x="${f1(plx)}" y="${b}" width="${pw2}" height="20" rx="10" style="fill:var(--accent)"/><text x="${f1(plx+pw2/2)}" y="${b+14}" class="t-sm t-mid" style="fill:var(--bg);font-weight:700">${Math.round(h)} h</text>`+lab;
      svg.innerHTML=s;const p=phaseOf(NRS_STEPS,t);setSt(p);$('#nrsNote').innerHTML=noteHTML(NRS_STEPS[p])}
    const stop=playWire(rg,$('#nrsPlay'),draw,24000,'Replay','nursing');
    const setSt=stepWire($('#nrsSteps'),NRS_STEPS,rg,draw,stop);
    $$('[data-nrstg]').forEach(b=>b.addEventListener('click',()=>{const k=b.dataset.nrstg;tg[k]=!tg[k];b.setAttribute('aria-pressed',tg[k]);draw(+rg.value)}));
    draw(+rg.value)})();

  /* ---- 2. swallow-first flow ---- */
  (function(){const svg=$('#nrsFlSvg'),rg=$('#nrsFlT'),bs=$$('[data-nrsfl]');let res='pass';
    function draw(t){const N=vb(svg,'720 340','400 640');const G=N?{a:[110,8,180,76],b:[110,104,180,76],c:[110,200,180,76],d:[8,312,180,76],e:[212,312,180,76],f:[212,420,180,76],g:[8,540,384,76]}:{a:[12,24,150,86],b:[176,24,150,86],c:[340,24,150,86],d:[552,8,156,86],e:[552,122,156,86],f:[552,236,156,86],g:[176,236,314,86]};
      const p=phaseOf(NRS_FL_STEPS,t),lit={a:p>=0,b:p>=1,c:p>=2,d:p>=3&&res==='pass',e:p>=3&&res==='fail',f:p>=3&&res==='fail',g:p>=4};
      const C=k=>[G[k][0]+G[k][2]/2,G[k][1]+G[k][3]/2];
      const line=(pts,on)=>`<path d="${ptsD(pts)}" marker-end="url(#nrsAr)" style="fill:none;stroke:${on?'var(--brand)':'var(--line)'};stroke-width:${on?2:1.5}"/>`;
      let s=`<defs>${marker('nrsAr','var(--muted)')}</defs>`;
      const [ax,ay,aw,ah]=G.a,[bx,by,bw,bh]=G.b,[cx,cy,cw,ch]=G.c,[dx,dy,dw,dh]=G.d,[ex,ey,ew,eh]=G.e,[fx,fy,fw,fh]=G.f,[gx,gy,gw,gh]=G.g;
      if(N){s+=line([ [C('a')[0],ay+ah],[C('b')[0],by-2] ],p>=1)+line([ [C('b')[0],by+bh],[C('c')[0],cy-2] ],p>=2);
        s+=line([ [C('c')[0]-40,cy+ch],[C('c')[0]-40,cy+ch+18],[C('d')[0],cy+ch+18],[C('d')[0],dy-2] ],lit.d)+line([ [C('c')[0]+40,cy+ch],[C('c')[0]+40,cy+ch+18],[C('e')[0],cy+ch+18],[C('e')[0],ey-2] ],lit.e);
        s+=line([ [C('e')[0],ey+eh],[C('e')[0],fy-2] ],lit.f)+line([ [C('d')[0],dy+dh],[C('d')[0],gy-2] ],lit.g&&res==='pass')+line([ [C('f')[0],fy+fh],[C('f')[0],gy-2] ],lit.g&&res==='fail');
        s+=`<text x="${f1(C('d')[0]+6)}" y="${cy+ch+33}" class="t-sm" style="fill:var(--ink)">pass</text><text x="${f1(C('e')[0]+6)}" y="${cy+ch+33}" class="t-sm" style="fill:var(--ink)">fail</text>`}
      else{s+=line([ [ax+aw,C('a')[1]],[bx-2,C('b')[1]] ],p>=1)+line([ [bx+bw,C('b')[1]],[cx-2,C('c')[1]] ],p>=2);
        s+=line([ [cx+cw,C('c')[1]-14],[522,C('c')[1]-14],[522,C('d')[1]],[dx-2,C('d')[1]] ],lit.d)+line([ [cx+cw,C('c')[1]+14],[522,C('c')[1]+14],[522,C('e')[1]],[ex-2,C('e')[1]] ],lit.e);
        s+=line([ [C('e')[0],ey+eh],[C('f')[0],fy-2] ],lit.f)+line([ [fx,C('f')[1]],[gx+gw+2,C('g')[1]] ],lit.g&&res==='fail')+line([ [C('c')[0],cy+ch],[C('c')[0],gy-2] ],lit.g&&res==='pass');
        s+=`<text x="494" y="${f1(C('c')[1]-19)}" class="t-sm" style="fill:var(--ink)">pass</text><text x="494" y="${f1(C('c')[1]+28)}" class="t-sm" style="fill:var(--ink)">fail</text>`}
      Object.keys(G).forEach(k=>{const [x,y,w,h]=G[k],N0=NRS_NODES[k],on=lit[k];
        s+=`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="10" style="fill:${on?'var(--brand-soft)':'var(--panel)'};stroke:${on?'var(--brand)':'var(--line)'};stroke-width:${on?2:1}"/>`;
        s+=`<text x="${x+10}" y="${y+24}" class="t-lbl">${N0.t}</text>`;N0.l.forEach((l,i)=>{s+=`<text x="${x+10}" y="${y+44+i*17}" class="t-sm" style="fill:var(--ink)">${l}</text>`})});
      /* travelling token */
      const route=[C('a'),C('b'),C('c'),C(res==='pass'?'d':'e')],q=clamp(t/.72)*(route.length-1),i=Math.min(route.length-2,Math.floor(q)),u=ease(q-i),tx=lerp(route[i][0],route[i+1][0],u),ty=lerp(route[i][1],route[i+1][1],u);
      const tp=t>.72&&res==='fail'?[C('e')[0],lerp(C('e')[1],C('f')[1],ramp(t,.74,.84))]:[tx,ty];
      s+=`<circle cx="${f1(tp[0]+ (N?78:64))}" cy="${f1(tp[1]-28)}" r="7" style="fill:var(--accent);stroke:var(--panel);stroke-width:2"/>`;
      svg.innerHTML=s;setSt(p);$('#nrsFlNote').innerHTML=noteHTML(NRS_FL_STEPS[p])}
    const stop=playWire(rg,$('#nrsFlPlay'),draw,14000,'Replay','nursing');
    const setSt=stepWire($('#nrsFlSteps'),NRS_FL_STEPS,rg,draw,stop);
    bs.forEach(b=>b.addEventListener('click',()=>{res=b.dataset.nrsfl;bs.forEach(o=>o.setAttribute('aria-pressed',o===b));draw(+rg.value)}));
    draw(+rg.value)})();

  /* ---- 3. monitoring after thrombolysis ---- */
  (function(){const svg=$('#nrsMoSvg'),rg=$('#nrsMoT'),bs=$$('[data-nrsmo]');let mx=24;const A=nrsStd(),B=nrsLow();
    function draw(t){const N=vb(svg,'720 270','400 350'),h=t*mx,px=N?14:152,pw=N?372:554,X=v=>px+pw*v/mx,lh=N?104:72,top=N?30:34,bh=30;let s='';
      const step=mx===24?4:1;for(let v=0;v<=mx+1e-9;v+=step){s+=`<line x1="${f1(X(v))}" x2="${f1(X(v))}" y1="${top}" y2="${top+lh*3-12}" class="grid"/><text x="${f1(clamp(X(v),px+8,px+pw-10))}" y="${top-8}" class="t-sm t-mid">${v} h</text>`}
      s+='<!--c-->';const rows=[{l:'Standard',ar:A,c:'var(--brand)',bars:[ [0,2,'15 min'],[2,8,'30 min'],[8,24,'hourly'] ]},{l:'Low-intensity',ar:B,c:'var(--rx)',bars:[ [0,2,'15 min'],[2,10,'2-hourly'],[10,24,'4-hourly'] ]}];
      rows.forEach((R,i)=>{const y=top+i*lh,by=N?y+24:y+4,n=R.ar.filter(v=>v<=h+1e-6).length;
        if(N){s+=`<text x="14" y="${y+16}" class="t-lbl">${R.l}</text><text x="386" y="${y+16}" class="t-sm t-end" style="fill:var(--ink)">${n} checks so far</text>`}
        else{s+=`<text x="14" y="${by+13}" class="t-lbl">${R.l}</text><text x="14" y="${by+29}" class="t-sm" style="fill:var(--ink)">${n} so far</text>`}
        R.bars.forEach(b=>{const a=X(b[0]),e=X(Math.min(b[1],mx));if(a>=px+pw)return;const tw=b[2].length*6+10;
          s+=`<rect x="${f1(a+1)}" y="${by+bh+3}" width="${f1(Math.max(0,e-a-2))}" height="16" rx="3" style="fill:var(--panel-2)"/>`;if(e-a>=tw)s+=`<text x="${f1((a+e)/2)}" y="${by+bh+15}" class="t-xs t-mid" style="fill:var(--ink)">${b[2]}</text>`});
        R.ar.forEach(v=>{if(v>mx)return;const on=v<=h+1e-6,x=X(v);s+=`<line x1="${f1(x)}" x2="${f1(x)}" y1="${by}" y2="${by+bh}" style="stroke:${R.c};stroke-width:${mx===24?1.6:3};opacity:${on?1:.28}"/>`})});
      const y=top+2*lh,by=N?y+24:y+4,a=X(5/60),e=X(189/60),m=X(65/60);
      if(N)s+=`<text x="14" y="${y+16}" class="t-lbl">Tongue and lip swelling: onset</text>`;else{s+=`<text x="14" y="${by+13}" class="t-lbl">Tongue, lip</text><text x="14" y="${by+29}" class="t-lbl">swelling onset</text>`}
      s+=`<rect x="${f1(a)}" y="${by+4}" width="${f1(e-a)}" height="20" rx="5" style="fill:var(--warn-soft);stroke:var(--warn)"/><line x1="${f1(m)}" x2="${f1(m)}" y1="${by}" y2="${by+28}" style="stroke:var(--ink);stroke-width:2"/>`;
      s+=mx===24&&!N?`<text x="${f1(e+8)}" y="${by+18}" class="t-sm" style="fill:var(--ink);paint-order:stroke;stroke:var(--panel);stroke-width:3px">5 to 189 min from the start of alteplase, median 65 (UK series)</text>`:`<text x="${f1(N&&mx===24?e+8:px)}" y="${by+(N&&mx===24?18:44)}" class="t-sm" style="fill:var(--ink);paint-order:stroke;stroke:var(--panel);stroke-width:3px">${N&&mx===24?'5 to 189 min, median 65':'5 to 189 min from the start of alteplase, median 65'}</text>`;
      const cx=X(h);s=s.replace('<!--c-->',`<line x1="${f1(cx)}" x2="${f1(cx)}" y1="${top}" y2="${top+lh*3-12}" style="stroke:var(--accent);stroke-width:2"/>`);
      svg.innerHTML=s;
      const low=B.filter(v=>v<=h+1e-6).length,ends=h>=24-1e-6;
      $('#nrsMoRead').innerHTML=`<span>Time <b>${h<10?h.toFixed(1):Math.round(h)} h</b></span><span>Standard <b>${A.filter(v=>v<=h+1e-6).length}</b></span><span>Low-intensity <b>${ends?'about 15 to 16':low}</b></span><span>Totals derived from the published intervals, not stated in the paper</span>`}
    playWire(rg,$('#nrsMoPlay'),draw,14000,'Replay','nursing');
    bs.forEach(b=>b.addEventListener('click',()=>{mx=+b.dataset.nrsmo;bs.forEach(o=>o.setAttribute('aria-pressed',o===b));draw(+rg.value)}));
    draw(+rg.value)})();

  /* ---- 4. warning signs on a face ---- */
  (function(){const svg=$('#nrsFaSvg'),rg=$('#nrsFaT'),bs=$$('[data-nrsfa]');let mode='hemi';
    function eye(cx,cy,pr,lid){let g=`<ellipse cx="${cx}" cy="${cy}" rx="24" ry="14" style="fill:var(--panel);stroke:var(--brain-line);stroke-width:1.4"/><circle cx="${cx}" cy="${cy}" r="11" style="fill:var(--glia)"/><circle cx="${f1(cx)}" cy="${cy}" r="${f1(pr)}" style="fill:var(--ink)"/>`;
      g+=`<path d="M${cx-25} ${cy-1}Q${cx} ${f1(cy-17)} ${cx+25} ${cy-1}L${cx+25} ${f1(cy-1)}Q${cx} ${f1(cy-17+lid*30)} ${cx-25} ${cy-1}Z" style="fill:var(--skin);stroke:var(--brain-line);stroke-width:1.2"/>`;return g}
    function draw(t){const N=vb(svg,'720 330','400 530'),S=NRS_SIGNS[mode],u=ease(t);const cx=N?200:166,cy=N?126:140,lx=N?14:340,lw=N?372:366,ly=N?322:40;let s='';
      s+=`<ellipse cx="${cx}" cy="${cy}" rx="94" ry="114" style="fill:var(--skin);stroke:var(--brain-line);stroke-width:2"/>`;
      const hemi=mode==='hemi',cer=mode==='cereb',lys=mode==='lysis';
      const lid=hemi?u*.72:cer?u*.3:0,pL=hemi?lerp(4.5,8.6,u):cer?lerp(4.5,1.8,u):4.5,pR=hemi?4.5:cer?lerp(4.5,1.8,u):4.5;
      s+=eye(cx-38,cy-26,pR,lid)+eye(cx+38,cy-26,pL,lid);
      s+=`<path d="M${cx} ${cy-14}V${cy+18}l-8 5" style="fill:none;stroke:var(--brain-line);stroke-width:1.6;stroke-linecap:round"/>`;
      const sw=lys?u:0,mh=5+sw*17,mw=32+sw*10;
      s+=`<path d="M${cx-mw} ${cy+56}Q${cx} ${f1(cy+56-mh)} ${cx+mw} ${cy+56}Q${cx} ${f1(cy+56+mh+3)} ${cx-mw} ${cy+56}Z" style="fill:var(--heart);stroke:var(--brain-line);stroke-width:1.3"/>`;
      if(lys&&sw>.3)s+=`<ellipse cx="${cx}" cy="${f1(cy+58)}" rx="${f1(10+sw*14)}" ry="${f1(sw*7)}" style="fill:var(--core);opacity:.55"/>`;
      /* alertness track */
      const tx=N?60:66,ty=N?276:290,tw=N?280:200,al=hemi?u*.8:cer?u*.85:.04;
      s+=`<rect x="${tx}" y="${ty}" width="${tw}" height="8" rx="4" style="fill:var(--panel-2)"/><circle cx="${f1(tx+tw*al)}" cy="${ty+4}" r="7" style="fill:var(--accent)"/><text x="${tx}" y="${ty-6}" class="t-sm">alert</text><text x="${tx+tw}" y="${ty-6}" class="t-sm t-end">hard to rouse</text>`;
      s+=`<text x="${lx}" y="${ly-14+ (N?0:0)}" class="t-big">${S.t}</text>`;
      S.signs.forEach((tx2,i)=>{const on=clamp(u*3.2-i*.8),yy=ly+6+i*56;
        s+=`<rect x="${lx}" y="${yy}" width="${lw}" height="46" rx="10" style="fill:${on>.5?'var(--warn-soft)':'var(--panel-2)'}"/><text x="${lx+14}" y="${yy+28}" class="t-lbl">${tx2}</text>`});
      s+=`<text x="${lx}" y="${ly+186}" class="t-sm">${lys?'Schematic face.':'Schematic face. Which pupil changes is not a claim.'}</text>`;
      svg.innerHTML=s}
    function note(){const S=NRS_SIGNS[mode];$('#nrsFaNote').innerHTML=noteHTML({k:S.k,t:S.t,txt:S.txt,pt:S.pt})}
    bs.forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.nrsfa;bs.forEach(o=>o.setAttribute('aria-pressed',o===b));note();draw(+rg.value)}));
    playWire(rg,$('#nrsFaPlay'),draw,8000,'Replay','nursing');note();draw(+rg.value)})();

  /* ---- 5. bedside body map ---- */
  (function(){const svg=$('#nrsBoSvg'),row=$('#nrsBoBtns');let sel='bladder';
    row.innerHTML=NRS_BODY.map(b=>`<button class="btn" data-nrsb="${b.id}" aria-pressed="${b.id===sel}">${b.n} ${b.b}</button>`).join('');
    function draw(){const N=vb(svg,'720 400','400 690'),B=NRS_BODY.find(b=>b.id===sel),cx=N?200:160,cy=N?190:200,H=N?350:370;let s='';
      s+=bodyHemi(cx,cy,H,{left:.45,labels:false});
      s+=`<text x="${cx-90}" y="${N?26:24}" class="t-sm t-mid">person's right</text><text x="${cx+90}" y="${N?26:24}" class="t-sm t-mid">person's left</text>`;
      NRS_BODY.forEach(b=>{const x=cx+b.at[0]*H,y=cy+b.at[1]*H,on=b.id===sel;
        s+=`<g class="clk" tabindex="0" role="button" aria-pressed="${on}" aria-label="${b.b}" data-nrsb="${b.id}"><circle cx="${f1(x)}" cy="${f1(y)}" r="20" style="fill:transparent"/><circle cx="${f1(x)}" cy="${f1(y)}" r="13" style="fill:${on?'var(--accent)':'var(--panel)'};stroke:var(--accent);stroke-width:2"/><text x="${f1(x)}" y="${f1(y+4.5)}" class="t-lbl t-mid" style="fill:${on?'var(--bg)':'var(--ink)'}">${b.n}</text></g>`});
      const X=N?14:330,Y=N?392:30,W=N?372:376,D=B.bars;
      s+=`<text x="${X}" y="${Y+10}" class="t-big">${D.h}</text>`;
      D.r.forEach((r,i)=>{const y=Y+38+i*58,w=(W-6)*r.v/D.max;
        s+=`<text x="${X}" y="${y}" class="t-lbl">${r.l}</text><rect x="${X}" y="${y+7}" width="${W-6}" height="18" rx="4" style="fill:var(--panel-2)"/><rect x="${X}" y="${y+7}" width="${f1(w)}" height="18" rx="4" style="fill:var(--brand)"/>`;
        const lblIn=w>W*.5;s+=`<text x="${f1(lblIn?X+w-6:X+w+6)}" y="${y+21}" class="t-sm${lblIn?' t-end':''}" style="fill:${lblIn?'var(--on-brand)':'var(--ink)'};font-weight:700">${r.s}</text>`});
      s+=`<text x="${X}" y="${Y+38+D.r.length*58+2}" class="t-sm">Bar lengths use one scale per panel, up to ${D.max===10?'10%':D.max+'%'}.</text>`;
      svg.innerHTML=s;
      $('#nrsBoNote').innerHTML=noteHTML({k:'Bedside round',t:B.b,txt:B.txt,pt:B.pt});
      $$('[data-nrsb]',row).forEach(o=>o.setAttribute('aria-pressed',o.dataset.nrsb===sel))}
    const pick=e=>{const c=e.target.closest('[data-nrsb]');if(!c)return;sel=c.dataset.nrsb;draw();const again=svg.querySelector(`[data-nrsb="${sel}"]`);if(e.type==='keydown'&&again)again.focus()};
    row.addEventListener('click',pick);svg.addEventListener('click',pick);
    svg.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick(e)}});
    draw();const pr=redraws.nursing;redraws.nursing=()=>{pr&&pr();draw()}})();

  /* ---- 6. aphasia dialogue and checklist ---- */
  (function(){const box=$('#nrsDial'),bs=$$('[data-nrsdi]');
    function show(k){box.innerHTML=NRS_DIAL[k].map(l=>`<div class="nrs-bub ${l.w==='Nurse'?'a':'b'}"><b>${l.w}</b><span>${l.s}</span></div>`).join('')}
    bs.forEach(b=>b.addEventListener('click',()=>{bs.forEach(o=>o.setAttribute('aria-pressed',o===b));show(b.dataset.nrsdi)}));show('on');
    const list=$('#nrsTeach'),rd=$('#nrsTeachRead');let ok=store.get('nrsTeach',[]);if(!Array.isArray(ok))ok=[];
    list.innerHTML=NRS_TEACH.map((tx,i)=>`<li><label><input type="checkbox" data-nrst="${i}"${ok.includes(i)?' checked':''}><span>${tx}</span></label></li>`).join('');
    function rc(){rd.textContent=`${ok.length} of ${NRS_TEACH.length} covered`}
    list.addEventListener('change',e=>{const c=e.target.closest('[data-nrst]');if(!c)return;const i=+c.dataset.nrst;ok=ok.filter(v=>v!==i);if(c.checked)ok.push(i);store.set('nrsTeach',ok);rc()});rc()})();
};
/* =============== 5.4 Research frontier =============== */
/* Route map (filter + select), route explorer (phase lanes against years), factor XI vs X cascade, paired VNS,
   arm comparator. All numbers come from research pass I (and H for the VNS guideline line). Registry rows are shown as
   the registry lists them: r:'none' never means a result. */
const FX_TODAY=2026.85;
const FX_EV={est:'Established',early:'Early evidence',hyp:'Hypothesis'};
const FX_STAGES=[
 {id:'prev',t:'Prevention',col:'var(--prev)'},
 {id:'acute',t:'Acute treatment',col:'var(--rx)'},
 {id:'rec',t:'Recovery',col:'var(--rec)'},
 {id:'bleed',t:'Bleeding strokes',col:'var(--dx)'},
 {id:'sys',t:'Systems of care',col:'var(--brand)'}];
const FX_LANES=[
 {id:'idea',t:'Idea or mechanism'},
 {id:'small',t:'Smaller, early or uncontrolled'},
 {id:'large',t:'Large, pivotal or phase 3'},
 {id:'pool',t:'Post hoc, subgroup or pooled'},
 {id:'reg',t:'Regulator or guideline'},
 {id:'wait',t:'Registry: no results shown'}];
const FX_RES={
 fav:{t:'Favoured the treatment on the stated outcome',g:'+',col:'var(--good)'},
 neu:{t:'No clear difference',g:'=',col:'var(--muted)'},
 bad:{t:'Worse than the comparator',g:'-',col:'var(--bad)'},
 mix:{t:'Mixed, post hoc, pooled, uncontrolled or not a stroke result',g:'~',col:'var(--warn)'},
 none:{t:'Registry entry: no results shown, not a result',g:'?',col:'var(--muted)'}};
/* claim: n name, y year (or nd:true, no date in the record), l lane, r result kind, e evidence label, x text */
const FX_ROUTES=[
 {id:'fxi',st:'prev',sh:'Factor XI inhibitors',t:'Factor XI and XIa inhibitors',
  s:'A new target for blood thinners, tested after non-cardioembolic stroke and in AF.',
  pt:'A newer type of blood thinner, asundexian, lowered the chance of another clot-related stroke in one very large study, without more serious bleeding. It is one study, and a similar medicine is still being tested. The same medicine did worse than a standard blood thinner for people with AF, so a medicine that helps one group may not help another <sup class="c" data-ref="Sharma2026,NCT05702034,Piccini2025" title="Source 721,795,916"><a href="/stroke/sources/#src-Sharma2026">721,795,916</a></sup>.',
  hook:'Asundexian failed against apixaban in AF but reduced ischaemic stroke against placebo after non-cardioembolic stroke: mechanism of stroke and comparator matter <sup class="c" data-ref="Piccini2025,Sharma2026" title="Source 795,916"><a href="/stroke/sources/#src-Piccini2025">795,916</a></sup>.',
  c:[
  {n:'Stated hypothesis',y:2024,l:'idea',r:'mix',e:'hyp',x:'Can anticoagulant effect be separated from bleeding? The LIBREXIA-AF design paper states that milvexian "may offer similar anticoagulant efficacy with less bleeding risk" <sup class="c" data-ref="Jain2024" title="Source 461"><a href="/stroke/sources/#src-Jain2024">461</a></sup>.'},
  {n:'PACIFIC-Stroke',y:2022,l:'small',r:'neu',e:'early',x:'Phase 2b, 1808 people, asundexian 10, 20 or 50 mg vs placebo. Covert infarct or ischaemic stroke at 26 weeks in 19%, 22% and 20% vs 19%. Bleeding pooled HR 1.57 (90% CI 0.91-2.71) <sup class="c" data-ref="Shoamanesh2022" title="Source 922"><a href="/stroke/sources/#src-Shoamanesh2022">922</a></sup>.'},
  {n:'AXIOMATIC-SSP',y:2024,l:'small',r:'neu',e:'early',x:'Phase 2, 2366 people, milvexian on dual antiplatelet therapy. Composite at 90 days 16.8% with placebo vs 15.3-16.7% across doses, no dose-response <sup class="c" data-ref="Sharma2024" title="Source 915"><a href="/stroke/sources/#src-Sharma2024">915</a></sup>.'},
  {n:'OCEANIC-AF',y:2025,l:'large',r:'bad',e:'est',x:'14,810 people with AF, asundexian 50 mg vs apixaban, stopped early. Stroke or systemic embolism 1.3% vs 0.4% (HR 3.79, 95% CI 2.46-5.83). Major bleeding 0.2% vs 0.7% (HR 0.32, 95% CI 0.18-0.55) <sup class="c" data-ref="Piccini2025" title="Source 795"><a href="/stroke/sources/#src-Piccini2025">795</a></sup>.'},
  {n:'AZALEA-TIMI 71',y:2025,l:'large',r:'mix',e:'est',x:'Established for bleeding only. 1287 people with AF, abelacimab vs rivaroxaban. Bleeding 3.2 and 2.6 vs 8.4 events per 100 person-years. Stroke efficacy is not reported as a result in the abstract <sup class="c" data-ref="Ruff2025" title="Source 868"><a href="/stroke/sources/#src-Ruff2025">868</a></sup>.'},
  {n:'OCEANIC-STROKE',y:2026,l:'large',r:'fav',e:'est',x:'A single positive phase 3 trial. 12,327 people after non-cardioembolic stroke or high-risk TIA, asundexian 50 mg vs placebo. Ischaemic stroke 6.2% vs 8.4% (cause-specific HR 0.74, 95% CI 0.65-0.84). Major bleeding 1.9% vs 1.7% (HR 1.10, 95% CI 0.85-1.44) <sup class="c" data-ref="Sharma2026" title="Source 916"><a href="/stroke/sources/#src-Sharma2026">916</a></sup>.'},
  {n:'LIBREXIA-STROKE',y:2026.79,l:'wait',r:'none',e:'hyp',x:'Milvexian vs placebo after stroke or high-risk TIA. Active, not recruiting, 12,523 enrolled, primary completion listed 2026-10-15, no results posted <sup class="c" data-ref="NCT05702034" title="Source 721"><a href="/stroke/sources/#src-NCT05702034">721</a></sup>.'},
  {n:'LIBREXIA-AF',y:2026.93,l:'wait',r:'none',e:'hyp',x:'Milvexian vs apixaban. Active, not recruiting, 20,284 enrolled (the design paper planned 15,500), primary completion listed 2026-12-08, no results posted <sup class="c" data-ref="NCT05757869,Jain2024" title="Source 461,723"><a href="/stroke/sources/#src-NCT05757869">461,723</a></sup>.'},
  {n:'LILAC-TIMI 76',y:2027.99,l:'wait',r:'none',e:'hyp',x:'Abelacimab vs placebo in AF unsuitable for oral anticoagulation. Recruiting, 2500 estimated, primary completion listed 2027-12-30 <sup class="c" data-ref="NCT05712200" title="Source 722"><a href="/stroke/sources/#src-NCT05712200">722</a></sup>.'},
  {n:'LILAC (Novartis)',y:2030.99,l:'wait',r:'none',e:'hyp',x:'A second record under the same name. Not yet recruiting, completion listed 2030-12-30 <sup class="c" data-ref="NCT07739888" title="Source 727"><a href="/stroke/sources/#src-NCT07739888">727</a></sup>.'}]},
 {id:'col',st:'prev',sh:'Colchicine',t:'Colchicine and inflammation',
  s:'Can calming inflammation prevent another stroke? The trials and the pooled result point different ways.',
  c:[
  {n:'CONVINCE',y:2024,l:'large',r:'neu',e:'early',x:'Underpowered. 3144 people, open-label add-on. Primary end point 9.8% vs 11.7% (HR 0.84, 95% CI 0.68-1.05; p=0.12). CRP was lower. Ended before the planned 367 events because of budget constraints <sup class="c" data-ref="Kelly2024" title="Source 490"><a href="/stroke/sources/#src-Kelly2024">490</a></sup>.'},
  {n:'CHANCE-3',y:2024,l:'large',r:'neu',e:'est',x:'8343 people, minor-to-moderate stroke or TIA with hs-CRP at least 2 mg/L. Stroke within 90 days 6.3% vs 6.5% (HR 0.98, 95% CI 0.83-1.16) <sup class="c" data-ref="Li2024CHANCE3" title="Source 569"><a href="/stroke/sources/#src-Li2024CHANCE3">569</a></sup>.'},
  {n:'Meta-analysis',y:2024,l:'pool',r:'mix',e:'early',x:'Mixed population: 6 trials, 14,934 people with prior stroke or coronary disease. Ischaemic stroke 1.8% vs 2.5% (RR 0.73, 95% CI 0.58-0.90), with no difference in death <sup class="c" data-ref="Fiolet2024" title="Source 309"><a href="/stroke/sources/#src-Fiolet2024">309</a></sup>.'},
  {n:'CoVasc-ICH2',y:2028.58,l:'wait',r:'none',e:'hyp',x:'Colchicine after intracerebral haemorrhage. Not yet recruiting, 1125 planned, no result <sup class="c" data-ref="NCT06587737" title="Source 725"><a href="/stroke/sources/#src-NCT06587737">725</a></sup>.'}]},
 {id:'lpa',st:'prev',sh:'Lipoprotein(a)',t:'Lipoprotein(a) lowering',
  s:'Lower Lp(a) a lot, and ask whether cardiovascular events, including stroke, fall too.',
  c:[
  {n:'ALPACA',y:2025,l:'small',r:'mix',e:'early',x:'Lepodisiran 400 mg lowered Lp(a) by 93.9 percentage points over days 60-180 in 320 people. A biomarker result, not an outcome result <sup class="c" data-ref="Nissen2025" title="Source 738"><a href="/stroke/sources/#src-Nissen2025">738</a></sup>.'},
  {n:'Lp(a)HORIZON topline',y:2026.54,l:'large',r:'neu',e:'early',x:'Second-hand: a 2026 review reports September 2026 topline results with lower Lp(a) but no reduction in the primary composite. Full data are awaited, and the registry lists the trial as completed with no results posted. No numbers are available <sup class="c" data-ref="Cho2025,Sabouret2026,NCT04023552" title="Source 185,716,873"><a href="/stroke/sources/#src-Cho2025">185,716,873</a></sup>.'},
  {n:'OCEAN(a)-Outcomes',y:2028.25,l:'wait',r:'none',e:'hyp',x:'Olpasiran, 7297 people, primary completion 2028-03-31. No result <sup class="c" data-ref="NCT05581303" title="Source 719"><a href="/stroke/sources/#src-NCT05581303">719</a></sup>.'},
  {n:'ACCLAIM-Lp(a)',y:2029.2,l:'wait',r:'none',e:'hyp',x:'Lepodisiran, 17,300 people, primary completion 2029-03. No result <sup class="c" data-ref="NCT06292013" title="Source 724"><a href="/stroke/sources/#src-NCT06292013">724</a></sup>.'}]},
 {id:'glp',st:'prev',sh:'GLP-1 drugs',t:'GLP-1 receptor agonists',
  s:'Clear falls in composite outcomes. Whether stroke itself falls is disputed.',
  c:[
  {n:'7-trial synthesis',y:2019,l:'pool',r:'mix',e:'early',x:'Seven trials in type 2 diabetes, 56,004 people: fatal or non-fatal stroke HR 0.84 (95% CI 0.76-0.93) <sup class="c" data-ref="Kristensen2019" title="Source 520"><a href="/stroke/sources/#src-Kristensen2019">520</a></sup>.'},
  {n:'SELECT',y:2023,l:'large',r:'mix',e:'est',x:'Established for the composite. 17,604 people with cardiovascular disease and overweight or obesity, no diabetes: 6.5% vs 8.0% (HR 0.80, 95% CI 0.72-0.90). The abstract does not give stroke separately <sup class="c" data-ref="Lincoff2023SELECT" title="Source 579"><a href="/stroke/sources/#src-Lincoff2023SELECT">579</a></sup>.'},
  {n:'SOUL',y:2025,l:'large',r:'mix',e:'est',x:'Established for the composite. 9650 people, type 2 diabetes, oral semaglutide: 12.0% vs 13.8% (HR 0.86, 95% CI 0.77-0.96). The abstract does not give stroke separately <sup class="c" data-ref="McGuire2025" title="Source 645"><a href="/stroke/sources/#src-McGuire2025">645</a></sup>.'},
  {n:'21-trial synthesis',y:2025,l:'pool',r:'neu',e:'early',x:'Twenty-one trials across wider populations, 99,599 people: MACE IRR 0.87 and no difference in stroke <sup class="c" data-ref="Galli2025" title="Source 341"><a href="/stroke/sources/#src-Galli2025">341</a></sup>.'}]},
 {id:'pol',st:'prev',sh:'Polypills',t:'Polypills',
  s:'Several medicines in one tablet. Tested before any heart event and after a heart attack, not after stroke.',
  c:[
  {n:'TIPS-3',y:2021,l:'large',r:'fav',e:'est',x:'5713 people without cardiovascular disease at intermediate risk, 4.6 years. Polypill plus aspirin 4.1% vs double placebo 5.8% (HR 0.69, 95% CI 0.50-0.97) <sup class="c" data-ref="Yusuf2021" title="Source 1088"><a href="/stroke/sources/#src-Yusuf2021">1088</a></sup>.'},
  {n:'SECURE',y:2022,l:'large',r:'fav',e:'est',x:'2499 people within 6 months after myocardial infarction. Major cardiovascular events 9.5% vs 12.7% (HR 0.76, 95% CI 0.60-0.96), with better reported adherence <sup class="c" data-ref="Castellano2022SECURE" title="Source 168"><a href="/stroke/sources/#src-Castellano2022SECURE">168</a></sup>.'},
  {n:'After stroke?',y:2022,l:'idea',r:'mix',e:'hyp',x:'SECURE enrolled people after a heart attack, not after stroke. Extending it to people who have had a stroke is an inference <sup class="c" data-ref="Castellano2022SECURE" title="Source 168"><a href="/stroke/sources/#src-Castellano2022SECURE">168</a></sup>.'}]},
 {id:'afs',st:'prev',sh:'AF screening',t:'Finding atrial fibrillation early',
  s:'Finding more AF does not automatically mean fewer strokes.',
  hook:'Three times more AF found and twice as much anticoagulation did not significantly reduce stroke in LOOP <sup class="c" data-ref="Svendsen2021" title="Source 950"><a href="/stroke/sources/#src-Svendsen2021">950</a></sup>.',
  c:[
  {n:'LOOP',y:2021,l:'large',r:'neu',e:'est',x:'6004 people aged about 75 with stroke risk factors, implanted recorder vs usual care. AF found 31.8% vs 12.2%, anticoagulation 29.7% vs 13.1%, stroke or systemic embolism 4.5% vs 5.6% (HR 0.80, 95% CI 0.61-1.05; p=0.11) <sup class="c" data-ref="Svendsen2021" title="Source 950"><a href="/stroke/sources/#src-Svendsen2021">950</a></sup>.'},
  {n:'STROKESTOP',y:2021,l:'large',r:'fav',e:'est',x:'A small net benefit. 28,768 randomised in Sweden, 51.3% of those invited attended, 6.9 years. Primary events 31.9% vs 33.0% (HR 0.96, 95% CI 0.92-1.00; p=0.045) <sup class="c" data-ref="Svennberg2021" title="Source 951"><a href="/stroke/sources/#src-Svennberg2021">951</a></sup>.'}]},
 {id:'ner',st:'acute',sh:'Nerinetide',t:'Neuroprotection: nerinetide',
  s:'A peptide that interferes with PSD-95, given as a single 2.6 mg/kg dose up to 270 mg in the thrombectomy trials <sup class="c" data-ref="Hill2020,Hill2025" title="Source 427,428"><a href="/stroke/sources/#src-Hill2020">427,428</a></sup>. Three neutral primary results.',
  pt:'Scientists are trying to protect brain cells during a stroke. Many drugs looked good in animals but have not clearly helped people yet <sup class="c" data-ref="Hill2025,Christenson2025" title="Source 188,428"><a href="/stroke/sources/#src-Hill2025">188,428</a></sup>.',
  hook:'The nerinetide subgroup signal in ESCAPE-NA1 did not replicate in ESCAPE-NEXT: treat subgroups as hypotheses <sup class="c" data-ref="Hill2020,Hill2025" title="Source 427,428"><a href="/stroke/sources/#src-Hill2020">427,428</a></sup>.',
  c:[
  {n:'ESCAPE-NA1',y:2020,l:'large',r:'neu',e:'est',x:'1105 people, thrombectomy within 12 h. mRS 0-2 at 90 days 61.4% vs 59.2% (adjusted RR 1.04, 95% CI 0.96-1.14; p=0.35) <sup class="c" data-ref="Hill2020" title="Source 427"><a href="/stroke/sources/#src-Hill2020">427</a></sup>.'},
  {n:'NA1 alteplase subgroup',y:2020,l:'pool',r:'mix',e:'early',x:'Effect modification was reported, with the treatment effect inhibited in people receiving alteplase <sup class="c" data-ref="Hill2020" title="Source 427"><a href="/stroke/sources/#src-Hill2020">427</a></sup>.'},
  {n:'ESCAPE-NEXT',y:2025,l:'large',r:'neu',e:'est',x:'850 people not given a plasminogen activator, testing that idea. mRS 0-2 in 45% vs 46% (OR 0.97, 95% CI 0.72-1.30; p=0.82). The confirmation failed <sup class="c" data-ref="Hill2025" title="Source 428"><a href="/stroke/sources/#src-Hill2025">428</a></sup>.'},
  {n:'FRONTIER',y:2025,l:'small',r:'neu',e:'early',x:'Phase 2, paramedics, 532 treated, median 64 min from onset. Favourable outcome 57% vs 58% (adjusted OR 1.05, 95% CI 0.73-1.51). Only 63% had ischaemic stroke: 18% had intracranial haemorrhage, 9% TIA and 10% a mimic <sup class="c" data-ref="Christenson2025" title="Source 188"><a href="/stroke/sources/#src-Christenson2025">188</a></sup>.'},
  {n:'Early-window pool',y:2025,l:'pool',r:'mix',e:'early',x:'Post hoc, 690 of 2487 people within 3 h and selected for reperfusion. Responders 56% vs 48% (adjusted OR 1.48, 95% CI 1.07-2.06). The authors say the criteria should be tested in a future trial <sup class="c" data-ref="Tymianski2025" title="Source 991"><a href="/stroke/sources/#src-Tymianski2025">991</a></sup>.'},
  {n:'NEXT at 1 year',y:2026,l:'pool',r:'mix',e:'early',x:'Functional independence 48.0% vs 47.9% overall (adjusted OR 1.12, 95% CI 0.74-1.71). Early-window post hoc group (n=163) 52.6% vs 45.5% (adjusted OR 2.80, 95% CI 1.18-6.66) <sup class="c" data-ref="Adams2026" title="Source 7"><a href="/stroke/sources/#src-Adams2026">7</a></sup>.'}]},
 {id:'gli',st:'acute',sh:'Glibenclamide',t:'Glibenclamide (glyburide) for swelling',
  s:'An attempt to limit brain swelling after large hemispheric infarction.',
  c:[
  {n:'CHARM',y:2024,l:'large',r:'neu',e:'early',x:'Stopped early by the sponsor for strategic and operational reasons, and underpowered. 431 in the efficacy population. No favourable mRS shift (common OR 1.17, 95% CI 0.80-1.71; p=0.42). Death 32% vs 29%, serious hypoglycaemia 6% vs 2% <sup class="c" data-ref="Sheth2024,NCT02864953" title="Source 711,919"><a href="/stroke/sources/#src-Sheth2024">711,919</a></sup>.'},
  {n:'Core under 125 mL',y:2025,l:'pool',r:'mix',e:'hyp',x:'Post hoc, 147 people: adjusted common OR 2.11 (95% CI 1.10-4.01). The authors call it hypothesis-generating <sup class="c" data-ref="Kimberly2025" title="Source 504"><a href="/stroke/sources/#src-Kimberly2025">504</a></sup>.'},
  {n:'Cochrane 2025',y:2025,l:'pool',r:'neu',e:'early',x:'621 people: little to no difference in function (RR 1.08, 95% CI 0.89-1.32, low certainty) and more hypoglycaemia (RR 4.66, 95% CI 1.59-13.67, moderate certainty) <sup class="c" data-ref="Fan2025" title="Source 291"><a href="/stroke/sources/#src-Fan2025">291</a></sup>.'}]},
 {id:'mul',st:'acute',sh:'Multi-target agents',t:'Edaravone dexborneol and butylphthalide',
  s:'Multi-target agents tested mostly in China, with positive or borderline results not yet replicated elsewhere.',
  c:[
  {n:'TASTE',y:2021,l:'large',r:'fav',e:'early',x:'1165 people within 48 h, edaravone dexborneol vs edaravone alone. mRS 0-1 at 90 days 67.18% vs 58.97% (OR 1.42, 95% CI 1.12-1.81) <sup class="c" data-ref="Xu2021" title="Source 1070"><a href="/stroke/sources/#src-Xu2021">1070</a></sup>.'},
  {n:'BAST',y:2023,l:'large',r:'fav',e:'early',x:'Single-country, not yet replicated. 1216 people in 59 Chinese centres, butylphthalide within 6 h. Favourable outcome 56.7% vs 44.0% (OR 1.70, 95% CI 1.35-2.14) <sup class="c" data-ref="Wang2023" title="Source 1020"><a href="/stroke/sources/#src-Wang2023">1020</a></sup>.'},
  {n:'TASTE-2',y:2026,l:'large',r:'mix',e:'early',x:'Borderline. 1362 people, thrombectomy within 24 h. mRS 0-2 in 55.0% vs 49.6% (RR 1.11, 95% CI 1.00-1.23; P=0.05) <sup class="c" data-ref="Wang2026TASTE2" title="Source 1026"><a href="/stroke/sources/#src-Wang2026TASTE2">1026</a></sup>.'},
  {n:'TASTE-2 mismatch',y:2026,l:'pool',r:'mix',e:'hyp',x:'The effect seemed driven by people with clinical-imaging mismatch, 55.5% vs 42.9% (RR 1.29, 95% CI 1.10-1.52). The authors suggest a dedicated trial <sup class="c" data-ref="Wang2026TASTE2" title="Source 1026"><a href="/stroke/sources/#src-Wang2026TASTE2">1026</a></sup>.'}]},
 {id:'tir',st:'acute',sh:'Tirofiban',t:'Tirofiban around reperfusion',
  s:'The same antiplatelet drug did nothing in one setting and looked helpful in others.',
  c:[
  {n:'RESCUE BT',y:2022,l:'large',r:'neu',e:'est',x:'948 people, before thrombectomy. Median mRS 3 in both (adjusted common OR 1.08, 95% CI 0.86-1.36). Symptomatic ICH 9.7% vs 6.4% <sup class="c" data-ref="Qiu2022" title="Source 820"><a href="/stroke/sources/#src-Qiu2022">820</a></sup>.'},
  {n:'RESCUE BT2',y:2023,l:'large',r:'fav',e:'early',x:'1177 people without large or medium vessel occlusion, vs aspirin. mRS 0-1 in 29.1% vs 22.2% (adjusted RR 1.26, 95% CI 1.04-1.53). Secondary end points were generally not consistent <sup class="c" data-ref="Zi2023" title="Source 1097"><a href="/stroke/sources/#src-Zi2023">1097</a></sup>.'},
  {n:'ASSET-IT',y:2025,l:'large',r:'fav',e:'early',x:'Single-country phase 3, 832 people, within 60 min after thrombolysis. mRS 0-1 in 65.9% vs 54.9% (RR 1.20, 95% CI 1.07-1.34). Symptomatic ICH 1.7% vs none <sup class="c" data-ref="Tao2025" title="Source 962"><a href="/stroke/sources/#src-Tao2025">962</a></sup>.'}]},
 {id:'ste',st:'acute',sh:'Methylprednisolone',t:'Steroid with thrombectomy',
  s:'Intravenous methylprednisolone, 2 mg/kg/day for 3 days, in MARVEL.',
  hook:'MARVEL was intravenous methylprednisolone, with a neutral primary <sup class="c" data-ref="Yang2024MARVEL" title="Source 1080"><a href="/stroke/sources/#src-Yang2024MARVEL">1080</a></sup>.',
  c:[
  {n:'MARVEL',y:2024,l:'large',r:'neu',e:'est',x:'1680 people. No significant shift in disability (generalised OR 1.10, 95% CI 0.96-1.25; P=.17) <sup class="c" data-ref="Yang2024MARVEL" title="Source 1080"><a href="/stroke/sources/#src-Yang2024MARVEL">1080</a></sup>.'},
  {n:'MARVEL safety',y:2024,l:'pool',r:'mix',e:'early',x:'Secondary safety outcomes favoured the drug: death 23.2% vs 28.5%, symptomatic ICH 8.6% vs 11.7% <sup class="c" data-ref="Yang2024MARVEL" title="Source 1080"><a href="/stroke/sources/#src-Yang2024MARVEL">1080</a></sup>.'}]},
 {id:'ial',st:'acute',sh:'Intra-arterial lysis',t:'Intra-arterial lysis after thrombectomy',
  s:'Clot-busting drug given into the artery after a successful thrombectomy. Results are mixed.',
  c:[
  {n:'CHOICE',y:2022,l:'small',r:'fav',e:'early',x:'113 treated, alteplase. mRS 0-1 in 59.0% vs 40.4% (adjusted difference 18.4%, 95% CI 0.3-36.4) <sup class="c" data-ref="Renu2022" title="Source 839"><a href="/stroke/sources/#src-Renu2022">839</a></sup>.'},
  {n:'POST-TNK',y:2025,l:'large',r:'neu',e:'early',x:'540 people. 49.1% vs 44.1% (adjusted RR 1.15, 95% CI 0.97-1.36; not significant) <sup class="c" data-ref="Huang2025" title="Source 447"><a href="/stroke/sources/#src-Huang2025">447</a></sup>.'},
  {n:'POST-UK',y:2025,l:'large',r:'neu',e:'early',x:'535 people, urokinase. 45.1% vs 40.2% (adjusted RR 1.13, 95% CI 0.94-1.36; not significant) <sup class="c" data-ref="Liu2025" title="Source 590"><a href="/stroke/sources/#src-Liu2025">590</a></sup>.'},
  {n:'ANGEL-TNK',y:2025,l:'small',r:'fav',e:'early',x:'256 people, 4.5-24 h. mRS 0-1 in 40.5% vs 26.4% (RR 1.44, 95% CI 1.06-1.95). None of 7 secondary efficacy end points supported this <sup class="c" data-ref="Miao2025" title="Source 674"><a href="/stroke/sources/#src-Miao2025">674</a></sup>.'}]},
 {id:'coo',st:'acute',sh:'Cooling',t:'Cooling the body',
  s:'A trial that shows how hard the idea is to deliver.',
  c:[
  {n:'EuroHYP-1',y:2019,l:'small',r:'neu',e:'early',x:'Cooling to 34.0-35.0 C within 6 h. Stopped at 98 of 1500 planned people. Only 31% reached the target. OR 1.01 (95% CI 0.48-2.13). The authors judged the regimen not feasible for most and the trial underpowered <sup class="c" data-ref="vanderWorp2019" title="Source 998"><a href="/stroke/sources/#src-vanderWorp2019">998</a></sup>.'}]},
 {id:'ric',st:'acute',sh:'Remote conditioning',t:'Remote ischaemic conditioning',
  s:'Repeated cuff inflation on a limb, for example 5 cycles of 5 min on and 5 min off at about 200 mm Hg <sup class="c" data-ref="Chen2022,Blauenfeldt2023" title="Source 109,180"><a href="/stroke/sources/#src-Chen2022">109,180</a></sup>. Unresolved.',
  c:[
  {n:'RICAMIS',y:2022,l:'large',r:'fav',e:'early',x:'1893 people in China, open label, within 48 h. mRS 0-1 in 67.4% vs 62.0% (risk difference 5.4%, 95% CI 1.0-9.9). The authors say this needs replication <sup class="c" data-ref="Chen2022" title="Source 180"><a href="/stroke/sources/#src-Chen2022">180</a></sup>.'},
  {n:'RESIST',y:2023,l:'large',r:'neu',e:'est',x:'1500 people in Denmark, started in the ambulance, sham controlled, 902 with confirmed stroke. No improvement (OR 0.95, 95% CI 0.75-1.20; P=.67). Arm pain or petechiae 7.2% vs 1.5% <sup class="c" data-ref="Blauenfeldt2023" title="Source 109"><a href="/stroke/sources/#src-Blauenfeldt2023">109</a></sup>.'},
  {n:'SERIC-IVT',y:2025,l:'small',r:'neu',e:'early',x:'547 analysed, after thrombolysis. Excellent outcome 62.7% vs 56.8% (RR 1.10, 95% CI 0.96-1.27; P=0.169) <sup class="c" data-ref="Guo2025" title="Source 376"><a href="/stroke/sources/#src-Guo2025">376</a></sup>.'},
  {n:'SERIC-EVT',y:2026,l:'small',r:'fav',e:'early',x:'488 analysed in China, after thrombectomy, sham at 60 mm Hg. mRS 0-2 in 61.1% vs 48.9% (RR 1.25, 95% CI 1.06-1.47) <sup class="c" data-ref="Guo2026" title="Source 377"><a href="/stroke/sources/#src-Guo2026">377</a></sup>.'},
  {n:'Meta-analysis',y:2026,l:'pool',r:'mix',e:'early',x:'35 studies, 6304 people: OR 1.28 (95% CI 1.05-1.57), with limited quality: mostly Chinese studies, small samples and heterogeneity. It found better favourable outcomes only without reperfusion, which conflicts with SERIC-EVT <sup class="c" data-ref="Lam2026,Guo2026" title="Source 377,534"><a href="/stroke/sources/#src-Lam2026">377,534</a></sup>.'}]},
 {id:'vns',st:'rec',sh:'Paired VNS',t:'Paired vagus nerve stimulation',
  s:'The one recovery device here with a blinded pivotal trial and a regulator decision. The average gain was modest.',
  pt:'A small implant that stimulates a nerve in the neck during arm therapy is approved in the US for some people with long-term arm weakness. The average gain in the trial was modest <sup class="c" data-ref="Dawson2021,FDA-Vivistim" title="Source 218,298"><a href="/stroke/sources/#src-Dawson2021">218,298</a></sup>.',
  hook:'Vivistim is FDA-approved for chronic ischaemic stroke with moderate to severe arm impairment <sup class="c" data-ref="FDA-Vivistim" title="Source 298"><a href="/stroke/sources/#src-FDA-Vivistim">298</a></sup>; the VNS-REHAB between-group difference was 2.6 FMA-UE points <sup class="c" data-ref="Dawson2021" title="Source 218"><a href="/stroke/sources/#src-Dawson2021">218</a></sup>.',
  c:[
  {n:'VNS-REHAB',y:2021,l:'large',r:'fav',e:'est',x:'108 people, randomised and blinded. FMA-UE rose 5.0 vs 2.4 points (difference 2.6, 95% CI 1.0-4.2; p=0.0014). Response at 90 days 47% vs 24% <sup class="c" data-ref="Dawson2021" title="Source 218"><a href="/stroke/sources/#src-Dawson2021">218</a></sup>.'},
  {n:'FDA approval',y:2021.65,l:'reg',r:'fav',e:'est',x:'Vivistim System, PMA P210007, 27 August 2021, for chronic ischaemic stroke with moderate to severe arm impairment <sup class="c" data-ref="FDA-Vivistim" title="Source 298"><a href="/stroke/sources/#src-FDA-Vivistim">298</a></sup>.'},
  {n:'Subgroups',y:2023,l:'pool',r:'mix',e:'early',x:'The VNS effect was similar across the subgroups examined <sup class="c" data-ref="Dawson2023" title="Source 219"><a href="/stroke/sources/#src-Dawson2023">219</a></sup>.'},
  {n:'1-year follow-up',y:2025,l:'small',r:'mix',e:'early',x:'74 people, 69% of those enrolled, pooled with no control comparison. FMA-UE up 5.23 points from baseline (95% CI 4.08-6.39) <sup class="c" data-ref="Kimberley2025" title="Source 503"><a href="/stroke/sources/#src-Kimberley2025">503</a></sup>.'},
  {n:'Real-world programme',y:2026,l:'small',r:'mix',e:'early',x:'Uncontrolled. Mean gain 10.8 points, 28 of 35 responders. Well above the randomised trial and should not be read as an effect size <sup class="c" data-ref="Saylor2026" title="Source 899"><a href="/stroke/sources/#src-Saylor2026">899</a></sup>.'},
  {n:'2026 AHA/ASA guideline',y:2026,l:'reg',r:'mix',e:'est',x:'Lists VNS paired with high-dose task training as class 2b, level B-R <sup class="c" data-ref="Richards2026" title="Source 843"><a href="/stroke/sources/#src-Richards2026">843</a></sup>.'},
  {n:'GRASP registry',y:2028.99,l:'wait',r:'none',e:'hyp',x:'Post-market registry, up to 3 years of follow-up. Recruiting, 1000 estimated, no result <sup class="c" data-ref="Doherty2026,NCT05301140" title="Source 245,718"><a href="/stroke/sources/#src-Doherty2026">245,718</a></sup>.'}]},
 {id:'bci',st:'rec',sh:'Brain-computer',t:'Brain-computer interfaces',
  s:'Brain signals drive the training. Better than conventional therapy in pooled data, but not clearly better than sham BCI.',
  c:[
  {n:'BCI with FES',y:2018,l:'small',r:'fav',e:'early',x:'BCI coupled to functional electrical stimulation gave more recovery than sham stimulation in chronic stroke, lasting 6-12 months. No numeric effect is quoted here <sup class="c" data-ref="Biasiucci2018" title="Source 103"><a href="/stroke/sources/#src-Biasiucci2018">103</a></sup>.'},
  {n:'Feasibility study',y:2020,l:'small',r:'mix',e:'early',x:'Uncontrolled. FMA-UE gain 4.68 points. People with motor imagery accuracy above 80% gained 3.16 points more <sup class="c" data-ref="SebastianRomagosa2020" title="Source 909"><a href="/stroke/sources/#src-SebastianRomagosa2020">909</a></sup>.'},
  {n:'Cochrane 2026',y:2026,l:'pool',r:'mix',e:'early',x:'Vs conventional therapy, may slightly improve arm function (MD 4.67, 95% CI 2.25-7.09; 10 studies, 611 people; low certainty). Vs sham BCI, may make little to no difference <sup class="c" data-ref="Qin2026" title="Source 819"><a href="/stroke/sources/#src-Qin2026">819</a></sup>.'}]},
 {id:'dbs',st:'rec',sh:'Cerebellar, spinal',t:'Cerebellar DBS and spinal cord stimulation',
  s:'Implants tested in very small groups. Hopeful and unproven.',
  pt:'Early results from brain and spinal cord implants are hopeful. They come from very small groups of people and need bigger studies <sup class="c" data-ref="Baker2023,deFreitas2026" title="Source 75,225"><a href="/stroke/sources/#src-Baker2023">75,225</a></sup>.',
  c:[
  {n:'Dentate DBS',y:2023,l:'small',r:'mix',e:'early',x:'Open-label phase 1, 12 people, 1-3 years after stroke, with rehabilitation. Median FMA-UE gain 7 points, 15 in those with some preserved distal function. No serious perioperative or stimulation-related events <sup class="c" data-ref="Baker2023" title="Source 75"><a href="/stroke/sources/#src-Baker2023">75</a></sup>.'},
  {n:'Cervical stimulation',y:2023,l:'small',r:'mix',e:'early',x:'First report in 2 people, grip force up 40% and 108% <sup class="c" data-ref="Powell2023" title="Source 808"><a href="/stroke/sources/#src-Powell2023">808</a></sup>.'},
  {n:'Spinal feasibility',y:2026,l:'small',r:'mix',e:'early',x:'7 people, 4 weeks of implantation. No serious adverse events. Average FMA gain 5.6 points with stimulation on and 6.6 at study end <sup class="c" data-ref="deFreitas2026" title="Source 225"><a href="/stroke/sources/#src-deFreitas2026">225</a></sup>.'}]},
 {id:'nim',st:'rec',sh:'rTMS and robots',t:'Brain stimulation, robots and practice',
  s:'Large sham or usual-care comparisons have often been neutral.',
  c:[
  {n:'GRASP (2009)',y:2009,l:'small',r:'fav',e:'early',x:'A self-directed arm programme, not the Vivistim registry of the same name. CAHAI mean difference 6.2 at 4 weeks (95% CI 3.4-9.0), held at 5 months <sup class="c" data-ref="Harris2009" title="Source 402"><a href="/stroke/sources/#src-Harris2009">402</a></sup>.'},
  {n:'NICHE',y:2018,l:'large',r:'neu',e:'est',x:'199 people, navigated 1 Hz rTMS. At least a 5-point FMA gain in 67% vs 65% with sham (P=0.76). Rehabilitation helped both groups <sup class="c" data-ref="Harvey2018" title="Source 409"><a href="/stroke/sources/#src-Harvey2018">409</a></sup>.'},
  {n:'RATULS',y:2019,l:'large',r:'neu',e:'est',x:'770 people. ARAT success 44% robot, 50% enhanced therapy, 42% usual care. Neither beat usual care <sup class="c" data-ref="Rodgers2019" title="Source 850"><a href="/stroke/sources/#src-Rodgers2019">850</a></sup>.'},
  {n:'E-FIT',y:2023,l:'small',r:'neu',e:'est',x:'60 people, with NICHE in Bayesian analysis. Active not superior to sham (posterior mean OR 1.94, 96% credible interval 0.61-4.80) <sup class="c" data-ref="Edwards2023" title="Source 272"><a href="/stroke/sources/#src-Edwards2023">272</a></sup>.'}]},
 {id:'cel',st:'rec',sh:'Cell therapy',t:'Stem and other cell therapy',
  s:'Safe so far, with no clear benefit in controlled studies.',
  pt:'Stem cell treatments have been safe in trials so far, but they have not clearly improved recovery in controlled studies <sup class="c" data-ref="Hess2017,Houkin2024,NCT02448641" title="Source 425,439,710"><a href="/stroke/sources/#src-Hess2017">425,439,710</a></sup>.',
  hook:'Open-label gains can vanish with sham control: SB623 open-label versus ACTIsSIMA <sup class="c" data-ref="Steinberg2019,NCT02448641" title="Source 710,939"><a href="/stroke/sources/#src-Steinberg2019">710,939</a></sup>.',
  c:[
  {n:'SB623 open label',y:2016,l:'small',r:'mix',e:'early',x:'Phase 1/2a, 18 people, cells implanted into the brain. FMA motor score up 11.40 at 12 months <sup class="c" data-ref="Steinberg2016" title="Source 938"><a href="/stroke/sources/#src-Steinberg2016">938</a></sup>.'},
  {n:'MASTERS',y:2017,l:'small',r:'neu',e:'early',x:'Phase 2, 126 in the ITT population. No difference in global recovery at day 90 (OR 1.08, 95% CI 0.55-2.09). Safe <sup class="c" data-ref="Hess2017" title="Source 425"><a href="/stroke/sources/#src-Hess2017">425</a></sup>.'},
  {n:'ACTIsSIMA',y:2018.93,l:'small',r:'neu',e:'early',x:'Sham-controlled phase 2, registry-posted results, no peer-reviewed report found. At least a 10-point gain in 7 of 55, 9 of 56 and 7 of 52 (sham), p=0.6743 <sup class="c" data-ref="NCT02448641" title="Source 710"><a href="/stroke/sources/#src-NCT02448641">710</a></sup>.'},
  {n:'SB623 at 2 years',y:2019,l:'small',r:'mix',e:'early',x:'Open label. Up 10.4 at 24 months, with no change in mRS <sup class="c" data-ref="Steinberg2019" title="Source 939"><a href="/stroke/sources/#src-Steinberg2019">939</a></sup>.'},
  {n:'TREASURE',y:2024,l:'small',r:'neu',e:'early',x:'Phase 2/3 in Japan, 206 people. Excellent outcome 11.5% vs 9.8% (adjusted risk difference 0.5%, 95% CI -7.3 to 8.3). Safe, no short-term benefit <sup class="c" data-ref="Houkin2024" title="Source 439"><a href="/stroke/sources/#src-Houkin2024">439</a></sup>.'},
  {n:'MASTERS-2',nd:1,l:'wait',r:'none',e:'hyp',x:'Phase 3. Terminated by sponsor\'s decision at 206 people, no results posted <sup class="c" data-ref="NCT03545607" title="Source 712"><a href="/stroke/sources/#src-NCT03545607">712</a></sup>.'}]},
 {id:'drg',st:'rec',sh:'Maraviroc, fluoxetine',t:'Recovery drugs: maraviroc and fluoxetine',
  s:'One idea still being tested, and one that shows how promising recovery drugs can fail.',
  hook:'Fluoxetine reduces depression but does not improve disability after stroke, and raises fracture risk <sup class="c" data-ref="Lundstrom2020,Legg2021" title="Source 565,602"><a href="/stroke/sources/#src-Lundstrom2020">565,602</a></sup>.',
  c:[
  {n:'CCR5 rationale',y:2019,l:'idea',r:'mix',e:'hyp',x:'CCR5 is expressed in cortical neurons after stroke, blocking it improved motor recovery in animals, and human carriers of CCR5-delta32 recovered better <sup class="c" data-ref="Joy2019" title="Source 477"><a href="/stroke/sources/#src-Joy2019">477</a></sup>.'},
  {n:'Preclinical review',y:2025,l:'idea',r:'mix',e:'hyp',x:'5 studies found smaller infarcts with CCR5 antagonists, with high risk of bias in every study <sup class="c" data-ref="Sharif2025" title="Source 914"><a href="/stroke/sources/#src-Sharif2025">914</a></sup>.'},
  {n:'Maraviroc pilot',y:2024,l:'small',r:'mix',e:'early',x:'Post-stroke depression, not placebo controlled. Mean MADRS fall 16.4 points on 300 mg daily, returning partly after stopping <sup class="c" data-ref="Tene2024" title="Source 969"><a href="/stroke/sources/#src-Tene2024">969</a></sup>.'},
  {n:'EFFECTS',y:2020,l:'large',r:'neu',e:'est',x:'1500 people, fluoxetine. No effect on mRS (common OR 0.94, 95% CI 0.78-1.13), fewer new depression diagnoses but more fractures and hyponatraemia <sup class="c" data-ref="Lundstrom2020" title="Source 602"><a href="/stroke/sources/#src-Lundstrom2020">602</a></sup>.'},
  {n:'Cochrane 2021',y:2021,l:'pool',r:'neu',e:'est',x:'Low risk of bias studies: little to no difference in disability (SMD 0.0, 95% CI -0.05 to 0.05; 5436 people), high-quality evidence <sup class="c" data-ref="Legg2021" title="Source 565"><a href="/stroke/sources/#src-Legg2021">565</a></sup>.'},
  {n:'CAMAROS',nd:1,l:'wait',r:'none',e:'hyp',x:'Maraviroc, phase 2, 120 estimated. Unknown status, last verified 2024-07, no results <sup class="c" data-ref="NCT04789616" title="Source 717"><a href="/stroke/sources/#src-NCT04789616">717</a></sup>.'},
  {n:'MASTER',y:2027.92,l:'wait',r:'none',e:'hyp',x:'Maraviroc 300 mg twice daily for 90 days, 80 people, recruiting, no result <sup class="c" data-ref="Broc2026,NCT07080567" title="Source 130,726"><a href="/stroke/sources/#src-Broc2026">130,726</a></sup>.'}]},
 {id:'hae',st:'bleed',sh:'ICH haemostasis',t:'Drugs to stop an intracerebral bleed growing',
  s:'Smaller bleeds have not reliably meant better recovery, and clotting drugs can cost thrombosis.',
  hook:'A drug that reduces a marker may still not improve function: FASTEST slowed haematoma growth without functional benefit <sup class="c" data-ref="Broderick2026" title="Source 133"><a href="/stroke/sources/#src-Broderick2026">133</a></sup>.',
  c:[
  {n:'TICH-2',y:2018,l:'large',r:'neu',e:'est',x:'2325 people, tranexamic acid. Day 90 function aOR 0.88 (95% CI 0.76-1.03; p=0.11). Deaths by day 7 were 9% vs 11% (aOR 0.73), with no difference at 90 days <sup class="c" data-ref="Sprigg2018" title="Source 934"><a href="/stroke/sources/#src-Sprigg2018">934</a></sup>.'},
  {n:'STOP-AUST',y:2020,l:'small',r:'neu',e:'early',x:'100 people, spot sign. ICH growth 44% vs 52% (OR 0.72, 95% CI 0.32-1.59) <sup class="c" data-ref="Meretoja2020" title="Source 669"><a href="/stroke/sources/#src-Meretoja2020">669</a></sup>.'},
  {n:'ANNEXA-I',y:2024,l:'large',r:'mix',e:'est',x:'530 people on factor Xa inhibitors. Haemostatic efficacy 67.0% vs 53.1%. Thrombotic events 10.3% vs 5.6%, ischaemic stroke 6.5% vs 1.5%, no appreciable difference in mRS or 30-day death <sup class="c" data-ref="Connolly2024" title="Source 198"><a href="/stroke/sources/#src-Connolly2024">198</a></sup>.'},
  {n:'FASTEST',y:2026,l:'large',r:'neu',e:'est',x:'626 people, recombinant factor VIIa within 2 h, stopped for futility. mRS common OR 1.09 (95% CI 0.79-1.51). Haematoma growth 3.7 mL smaller, life-threatening thromboembolic events RR 3.41 <sup class="c" data-ref="Broderick2026" title="Source 133"><a href="/stroke/sources/#src-Broderick2026">133</a></sup>.'},
  {n:'Tranexamic acid IPD',y:2026,l:'pool',r:'neu',e:'est',x:'5 trials, 2860 people. Worse outcome 53.2% vs 53.6% (aOR 0.93, 95% CI 0.81-1.07). Day 7 mortality aOR 0.70, expansion OR 0.81. Established for no 90-day functional benefit <sup class="c" data-ref="Menon2026" title="Source 663"><a href="/stroke/sources/#src-Menon2026">663</a></sup>.'}]},
 {id:'sur',st:'bleed',sh:'ICH surgery',t:'Surgery for intracerebral haemorrhage',
  s:'Which bleeds, and which operation, is the live question.',
  hook:'ENRICH\'s benefit appeared in lobar bleeds <sup class="c" data-ref="Pradilla2024" title="Source 813"><a href="/stroke/sources/#src-Pradilla2024">813</a></sup>.',
  c:[
  {n:'MISTIE III',y:2019,l:'large',r:'neu',e:'est',x:'506 people, minimally invasive surgery with thrombolysis. mRS 0-3 at 365 days 45% vs 41% (adjusted risk difference 4%, 95% CI -4 to 12; p=0.33) <sup class="c" data-ref="Hanley2019" title="Source 394"><a href="/stroke/sources/#src-Hanley2019">394</a></sup>.'},
  {n:'ENRICH',y:2024,l:'large',r:'fav',e:'est',x:'A single trial. 300 people, surgery within 24 h. Utility-weighted mRS 0.458 vs 0.374 (posterior probability of superiority 0.981). The effect appeared in lobar bleeds (0.127), not anterior basal ganglia bleeds (-0.013) <sup class="c" data-ref="Pradilla2024" title="Source 813"><a href="/stroke/sources/#src-Pradilla2024">813</a></sup>.'},
  {n:'SWITCH',y:2024,l:'small',r:'neu',e:'early',x:'201 people, deep ICH, decompressive craniectomy, stopped early. mRS 5-6 at 180 days 44% vs 58% (aRR 0.77, 95% CI 0.59-1.01). The authors call this weak evidence and note severe disability in survivors of both groups <sup class="c" data-ref="Beck2024" title="Source 90"><a href="/stroke/sources/#src-Beck2024">90</a></sup>.'}]},
 {id:'bun',st:'bleed',sh:'ICH care bundle',t:'A care bundle for ICH',
  s:'Doing several ordinary things together, early.',
  pt:'For a bleed in the brain, keeping several things under control at once in the first hours, such as blood pressure, improved recovery in one large study <sup class="c" data-ref="Ma2023" title="Source 611"><a href="/stroke/sources/#src-Ma2023">611</a></sup>.',
  c:[
  {n:'INTERACT3',y:2023,l:'large',r:'fav',e:'est',x:'7036 people, 121 hospitals. Lower odds of poor outcome (common OR 0.86, 95% CI 0.76-0.97), fewer serious adverse events (16.0% vs 20.1%) <sup class="c" data-ref="Ma2023" title="Source 611"><a href="/stroke/sources/#src-Ma2023">611</a></sup>.'}]},
 {id:'cla',st:'bleed',sh:'Clazosentan (SAH)',t:'Clazosentan in subarachnoid haemorrhage',
  s:'Less vasospasm on imaging has not meant better function.',
  c:[
  {n:'REACT',y:2025,l:'large',r:'neu',e:'est',x:'Phase 3, 409 randomised. Clinical deterioration from delayed cerebral ischaemia 15.8% vs 17.2% (p=0.734). Poor outcome numerically higher, 24.8% vs 20.1% (not significant). Rescue therapy 10.4% vs 18.1% <sup class="c" data-ref="Mayer2025" title="Source 643"><a href="/stroke/sources/#src-Mayer2025">643</a></sup>.'},
  {n:'Meta-analysis',y:2026,l:'pool',r:'mix',e:'est',x:'Less angiographic vasospasm and rescue therapy, no significant difference in function or death. More hypotension, anaemia, pleural effusion, pulmonary oedema and pneumonia. Established for the vasospasm-function gap <sup class="c" data-ref="Alsakti2026" title="Source 25"><a href="/stroke/sources/#src-Alsakti2026">25</a></sup>.'}]},
 {id:'mma',st:'bleed',sh:'MMA embolisation',t:'Middle meningeal artery embolisation',
  s:'For subdural haematoma, not ICH, but part of the same neurovascular frontier.',
  c:[
  {n:'EMBOLISE',y:2024,l:'large',r:'fav',e:'est',x:'400 people. Repeat surgery for recurrence or progression 4.1% vs 11.3% (RR 0.36) <sup class="c" data-ref="Davies2024" title="Source 215"><a href="/stroke/sources/#src-Davies2024">215</a></sup>.'},
  {n:'MAGIC-MT',y:2024,l:'large',r:'neu',e:'est',x:'722 people. Recurrence or progression 6.7% vs 9.9% (P=0.10, not significant), with fewer serious adverse events (6.7% vs 11.6%) <sup class="c" data-ref="Liu2024I" title="Source 589"><a href="/stroke/sources/#src-Liu2024I">589</a></sup>.'},
  {n:'STEM',y:2025,l:'large',r:'fav',e:'est',x:'310 people. Treatment failure 16% vs 36% (OR 0.36, 95% CI 0.20-0.66) <sup class="c" data-ref="Fiorella2025" title="Source 310"><a href="/stroke/sources/#src-Fiorella2025">310</a></sup>.'}]},
 {id:'ai',st:'sys',sh:'AI imaging',t:'AI reading of stroke imaging',
  s:'The two AI papers measure different things: one improved workflow times, the other found modest accuracy. Neither shows better function <sup class="c" data-ref="MartinezGutierrez2023,Mair2023" title="Source 623,636"><a href="/stroke/sources/#src-MartinezGutierrez2023">623,636</a></sup>.',
  c:[
  {n:'Review',y:2020,l:'idea',r:'mix',e:'hyp',x:'AI could reduce variation between readers and help non-expert centres, but any system should let experts catch errors <sup class="c" data-ref="Bivard2020" title="Source 107"><a href="/stroke/sources/#src-Bivard2020">107</a></sup>.'},
  {n:'LVO software',y:2023,l:'small',r:'mix',e:'early',x:'Stepped-wedge cluster trial, 243 people. Door-to-groin time fell by 11.2 min (95% CI 4.2-18.22), with no clear difference in functional independence (OR 1.3, 95% CI 0.42-4.0) <sup class="c" data-ref="MartinezGutierrez2023" title="Source 636"><a href="/stroke/sources/#src-MartinezGutierrez2023">636</a></sup>.'},
  {n:'CTA tool test',y:2023,l:'small',r:'mix',e:'early',x:'668 people, one tool against experts. Software processed 82% of scans, with sensitivity, specificity and accuracy each 72%. Users need to remain competent to read CT angiography <sup class="c" data-ref="Mair2023" title="Source 623"><a href="/stroke/sources/#src-Mair2023">623</a></sup>.'}]},
 {id:'msu',st:'sys',sh:'Mobile stroke units',t:'Mobile stroke units',
  s:'An ambulance with a CT scanner brings treatment to the person.',
  pt:'An ambulance with a CT scanner can start clot-busting treatment sooner, and people treated this way tended to recover better <sup class="c" data-ref="Grotta2021,Turc2022" title="Source 373,988"><a href="/stroke/sources/#src-Grotta2021">373,988</a></sup>.',
  c:[
  {n:'BEST-MSU',y:2021,l:'large',r:'fav',e:'est',x:'1047 eligible for t-PA. Onset to t-PA 72 vs 108 min, mRS 0-1 at 90 days 55.0% vs 44.4% (adjusted OR on utility-weighted mRS 2.43, 95% CI 1.75-3.36) <sup class="c" data-ref="Grotta2021" title="Source 373"><a href="/stroke/sources/#src-Grotta2021">373</a></sup>.'},
  {n:'B_PROUD',y:2021,l:'small',r:'fav',e:'early',x:'Berlin, non-randomised, 1543 people. Lower mRS with dispatch (common OR for worse outcome 0.71, 95% CI 0.58-0.86) <sup class="c" data-ref="Ebinger2021" title="Source 268"><a href="/stroke/sources/#src-Ebinger2021">268</a></sup>.'},
  {n:'Meta-analysis',y:2022,l:'pool',r:'fav',e:'est',x:'Excellent outcome adjusted OR 1.64 (95% CI 1.27-2.13), thrombolysis 31 min sooner, no increase in mortality or symptomatic ICH <sup class="c" data-ref="Turc2022" title="Source 988"><a href="/stroke/sources/#src-Turc2022">988</a></sup>.'}]},
 {id:'bpa',st:'sys',sh:'Ambulance BP',t:'Lowering blood pressure in the ambulance',
  s:'Lowering pressure before imaging, when the type of stroke is not yet known.',
  hook:'Prehospital blood pressure lowering helped haemorrhagic stroke and harmed cerebral ischaemia in INTERACT4, which shows why stroke type matters before lowering pressure <sup class="c" data-ref="Li2024" title="Source 568"><a href="/stroke/sources/#src-Li2024">568</a></sup>.',
  c:[
  {n:'INTERACT4',y:2024,l:'large',r:'neu',e:'est',x:'2404 people. No overall benefit (common OR 1.00, 95% CI 0.87-1.15) <sup class="c" data-ref="Li2024" title="Source 568"><a href="/stroke/sources/#src-Li2024">568</a></sup>.'},
  {n:'INTERACT4 by type',y:2024,l:'pool',r:'mix',e:'early',x:'Subgroups: benefit in haemorrhagic stroke (0.75, 95% CI 0.60-0.92), harm in cerebral ischaemia (1.30, 95% CI 1.06-1.60) <sup class="c" data-ref="Li2024" title="Source 568"><a href="/stroke/sources/#src-Li2024">568</a></sup>.'}]}
];
const FX_MAPTXT={none:'No route matches these filters. Clear a filter to see more.',count:(a,b)=>`Showing ${a} of ${b} routes`};
const FX_READ={year:'Year shown',today:'Today: November 2026',past:'Everything drawn up to this line is a published record or a registry listing.',future:'After today, markers are registry dates, not results.'};

/* cascade steps */
const FXC_STEPS=[
 {from:0,at:.08,k:'Outline · no drug',t:'A chain that ends in fibrin',
  txt:'The drawing is a simplified teaching outline: a contact route through XII, XI and IX, and an injury route from tissue factor with VII, both reaching X, then thrombin, then fibrin. It is here to place the two drug targets. It is not a trial finding. <sup class="c" data-ref="Gailani2015" title="Source 339"><a href="/stroke/sources/#src-Gailani2015">339</a></sup>',
  pt:'Blood clots through a chain of steps. Each step switches on the next. Drugs can block the chain at different points.',
  tag:'TEACHING OUTLINE',tc:'brand',w:['Both routes reach X. X makes thrombin, thrombin makes fibrin.'],n:['Both routes reach X. X makes thrombin,','and thrombin makes fibrin.'],
  a:'Thrombin output can feed clot growth.',b:'The same output helps seal a tear.'},
 {from:.16,at:.26,k:'Block at X',t:'Blocking at factor X',
  txt:'The comparators in the factor XI trials, apixaban and rivaroxaban, act at factor X. Both routes pass through X, so in this outline both lose output. In OCEANIC-AF, major bleeding with apixaban was 0.7% <sup class="c" data-ref="Piccini2025" title="Source 795"><a href="/stroke/sources/#src-Piccini2025">795</a></sup>. ANNEXA-I enrolled 530 people with ICH while on factor Xa inhibitors <sup class="c" data-ref="Connolly2024" title="Source 198"><a href="/stroke/sources/#src-Connolly2024">198</a></sup>.',
  tag:'TEACHING OUTLINE',tc:'brand',w:['Block at X: both routes lose output. Examples: apixaban, rivaroxaban.'],n:['Block at X: both routes lose output.','Examples: apixaban, rivaroxaban.'],
  a:'Less thrombin: less clot growth.',b:'Less thrombin: weaker sealing, more bleeding.'},
 {from:.36,at:.46,k:'Block at XI · the idea',t:'Blocking at factor XI',
  txt:'<span class="ev hyp">Hypothesis</span> The idea under test is that anticoagulant effect can be separated from bleeding. The LIBREXIA-AF design paper states that milvexian "may offer similar anticoagulant efficacy with less bleeding risk" <sup class="c" data-ref="Jain2024" title="Source 461"><a href="/stroke/sources/#src-Jain2024">461</a></sup>. In the drawing, the injury route stays open at X. Asundexian and milvexian target factor XIa, and abelacimab binds factor XI <sup class="c" data-ref="Sharma2026,Sharma2024,Ruff2025" title="Source 868,915,916"><a href="/stroke/sources/#src-Sharma2026">868,915,916</a></sup>. Abelacimab lowered free factor XI by a median 99% at 150 mg and 97% at 90 mg <sup class="c" data-ref="Ruff2025" title="Source 868"><a href="/stroke/sources/#src-Ruff2025">868</a></sup>.',
  pt:'The hope is a blood thinner that stops harmful clots but leaves more of the body\'s ability to stop a bleed. This is what the trials set out to test.',
  hook:'The stated rationale is a trial hypothesis, not a result <sup class="c" data-ref="Jain2024" title="Source 461"><a href="/stroke/sources/#src-Jain2024">461</a></sup>. Judge it by the trials that follow.',
  tag:'HYPOTHESIS',tc:'hyp',w:['Block at XI: the injury route stays open. Asundexian, milvexian, abelacimab.'],n:['Block at XI: the injury route stays open.','Asundexian, milvexian, abelacimab.'],
  a:'Hypothesis: clot growth still falls.',b:'Hypothesis: sealing mostly kept.'},
 {from:.56,at:.64,k:'Trial data · bleeding',t:'What trials found on bleeding',
  txt:'<span class="ev est">Established</span> OCEANIC-AF: major bleeding 0.2% with asundexian vs 0.7% with apixaban (HR 0.32, 95% CI 0.18-0.55) <sup class="c" data-ref="Piccini2025" title="Source 795"><a href="/stroke/sources/#src-Piccini2025">795</a></sup>. AZALEA-TIMI 71: 3.2 and 2.6 vs 8.4 events per 100 person-years with abelacimab vs rivaroxaban, stopped early for the bleeding reduction <sup class="c" data-ref="Ruff2025" title="Source 868"><a href="/stroke/sources/#src-Ruff2025">868</a></sup>. OCEANIC-STROKE: major bleeding 1.9% vs 1.7% with placebo (cause-specific HR 1.10, 95% CI 0.85-1.44). That comparison is against placebo, on top of antiplatelet therapy <sup class="c" data-ref="Sharma2026" title="Source 916"><a href="/stroke/sources/#src-Sharma2026">916</a></sup>.',
  tag:'TRIAL DATA',tc:'est',w:['Measured major bleeding, as published. Bars below are data.'],n:['Measured major bleeding, as published.','Bars below are data.']},
 {from:.72,at:.8,k:'Trial data · stroke',t:'And on stroke: the comparator matters',
  txt:'<span class="ev est">Established</span> Against apixaban in AF, asundexian was clearly worse at preventing stroke: 1.3% vs 0.4% (HR 3.79, 95% CI 2.46-5.83) <sup class="c" data-ref="Piccini2025" title="Source 795"><a href="/stroke/sources/#src-Piccini2025">795</a></sup>. Against placebo after non-cardioembolic stroke or high-risk TIA, it lowered ischaemic stroke: 6.2% vs 8.4% (cause-specific HR 0.74, 95% CI 0.65-0.84; P&lt;0.001), a difference of 2.2 percentage points. OCEANIC-STROKE is a single positive phase 3 trial <sup class="c" data-ref="Sharma2026" title="Source 916"><a href="/stroke/sources/#src-Sharma2026">916</a></sup>. Both phase 2 trials had missed their composite outcome <sup class="c" data-ref="Shoamanesh2022,Sharma2024" title="Source 915,922"><a href="/stroke/sources/#src-Shoamanesh2022">915,922</a></sup>.',
  pt:'In one very large study, asundexian lowered the chance of another clot-related stroke without more serious bleeding. For people with AF it did worse than a standard blood thinner. A medicine that helps one group may not help another <sup class="c" data-ref="Sharma2026,Piccini2025" title="Source 795,916"><a href="/stroke/sources/#src-Sharma2026">795,916</a></sup>.',
  hook:'Asundexian failed against apixaban in AF but reduced ischaemic stroke against placebo after non-cardioembolic stroke: mechanism of stroke and comparator matter <sup class="c" data-ref="Piccini2025,Sharma2026" title="Source 795,916"><a href="/stroke/sources/#src-Piccini2025">795,916</a></sup>.',
  tag:'TRIAL DATA',tc:'est',w:['Same drug and dose, two populations, two comparators. Do not compare across panels.'],n:['Same drug, two populations, two comparators.','Do not compare across panels.']},
 {from:.88,at:.95,k:'Registry · no results',t:'What has not reported',
  txt:'<span class="ev hyp">Hypothesis</span> until they report. LIBREXIA-STROKE and LIBREXIA-AF are active, not recruiting, with no results posted <sup class="c" data-ref="NCT05702034,NCT05757869" title="Source 721,723"><a href="/stroke/sources/#src-NCT05702034">721,723</a></sup>. LILAC-TIMI 76 is recruiting <sup class="c" data-ref="NCT05712200" title="Source 722"><a href="/stroke/sources/#src-NCT05712200">722</a></sup>, and a second record under the same name is not yet recruiting <sup class="c" data-ref="NCT07739888" title="Source 727"><a href="/stroke/sources/#src-NCT07739888">727</a></sup>. Regulatory and guideline status of factor XI drugs were not established when this research was done.',
  tag:'REGISTRY',tc:'hyp',w:['Registry entries only. No result is implied.'],n:['Registry entries only. No result is implied.']}
];
const FXC_REG=[
 {n:'LIBREXIA-STROKE',q:'Milvexian vs placebo after stroke or TIA',s:'Active, not recruiting · no results posted · listed 2026-10-15'},
 {n:'LIBREXIA-AF',q:'Milvexian vs apixaban in AF',s:'Active, not recruiting · no results posted · listed 2026-12-08'},
 {n:'LILAC-TIMI 76',q:'Abelacimab vs placebo in AF',s:'Recruiting · no results · listed 2027-12-30'},
 {n:'LILAC-TIMI 76 (second record)',q:'Abelacimab, Novartis',s:'Not yet recruiting · no results · listed 2030-12-30'}];
const FXC_BARS=[
 {t:'OCEANIC-STROKE',sub:'after non-cardioembolic stroke or TIA, vs placebo',
  g:[{m:'Major bleeding',a:['asundexian',1.9],b:['placebo',1.7]},{m:'Ischaemic stroke',a:['asundexian',6.2],b:['placebo',8.4]}]},
 {t:'OCEANIC-AF',sub:'atrial fibrillation, vs apixaban',
  g:[{m:'Major bleeding',a:['asundexian',.2],b:['apixaban',.7]},{m:'Stroke or systemic embolism',a:['asundexian',1.3],b:['apixaban',.4]}]}];

/* VNS steps */
const FXV_STEPS=[
 {from:0,at:.08,k:'The device',t:'A small implant and a lead',
  txt:'<span class="ev est">Established</span> The FDA approved the Vivistim System (PMA P210007) on 27 August 2021, to stimulate the vagus nerve during rehabilitation to reduce arm motor deficits and improve motor function in chronic ischaemic stroke with moderate to severe arm impairment <sup class="c" data-ref="FDA-Vivistim" title="Source 298"><a href="/stroke/sources/#src-FDA-Vivistim">298</a></sup>.',
  pt:'A small implant stimulates a nerve in the neck during arm therapy. It is approved in the US for some people with long-term arm weakness <sup class="c" data-ref="Dawson2021,FDA-Vivistim" title="Source 218,298"><a href="/stroke/sources/#src-Dawson2021">218,298</a></sup>.'},
 {from:.2,at:.3,k:'Therapy',t:'The arm practises a task',
  txt:'In VNS-REHAB, all 108 people had rehabilitation, and they were randomised to active or control stimulation, blinded <sup class="c" data-ref="Dawson2021" title="Source 218"><a href="/stroke/sources/#src-Dawson2021">218</a></sup>. All were at least 9 months after ischaemic stroke, with moderate to severe arm weakness, and all were implanted <sup class="c" data-ref="Dawson2021" title="Source 218"><a href="/stroke/sources/#src-Dawson2021">218</a></sup>. So everyone did the therapy. Only the stimulation differed.'},
 {from:.4,at:.5,k:'Pairing',t:'A burst with each movement',
  txt:'Paired means the nerve burst is delivered during the movement. Press Control stimulation to see the comparison arm. The 2026 AHA/ASA rehabilitation guideline lists VNS paired with high-dose task training as class 2b, level B-R <sup class="c" data-ref="Richards2026" title="Source 843"><a href="/stroke/sources/#src-Richards2026">843</a></sup>.',
  hook:'Vivistim is FDA-approved for chronic ischaemic stroke with moderate to severe arm impairment <sup class="c" data-ref="FDA-Vivistim" title="Source 298"><a href="/stroke/sources/#src-FDA-Vivistim">298</a></sup>.'},
 {from:.6,at:.72,k:'Repeats',t:'Why pairing might matter',
  txt:'<span class="ev hyp">Hypothesis</span> The drawing shows the idea that pairing a burst with practice strengthens the connections in use. Neuroplasticity is defined as the nervous system\'s ability to reorganise structure, function and connections, with experience dependence as a common theme <sup class="c" data-ref="Cramer2011" title="Source 207"><a href="/stroke/sources/#src-Cramer2011">207</a></sup>. The trials measured arm function, not synapses. The thickening line is an illustration.'},
 {from:.8,at:.92,k:'Trial data',t:'What VNS-REHAB measured',
  txt:'<span class="ev est">Established</span> FMA-UE rose 5.0 vs 2.4 points (difference 2.6, 95% CI 1.0-4.2; p=0.0014). A clinically meaningful response at 90 days occurred in 47% vs 24% (difference 24%, 95% CI 6-41) <sup class="c" data-ref="Dawson2021" title="Source 218"><a href="/stroke/sources/#src-Dawson2021">218</a></sup>. <span class="ev early">Early evidence</span> At 1 year, pooled in 74 people with no control comparison, the gain was 5.23 points from baseline (95% CI 4.08-6.39) <sup class="c" data-ref="Kimberley2025" title="Source 503"><a href="/stroke/sources/#src-Kimberley2025">503</a></sup>. An uncontrolled programme reported 10.8 points. That should not be read as an effect size <sup class="c" data-ref="Saylor2026" title="Source 899"><a href="/stroke/sources/#src-Saylor2026">899</a></sup>. Funded by MicroTransponder <sup class="c" data-ref="Dawson2021" title="Source 218"><a href="/stroke/sources/#src-Dawson2021">218</a></sup>.',
  pt:'People who had the real stimulation gained more arm movement on average, but the average gain in the trial was modest <sup class="c" data-ref="Dawson2021" title="Source 218"><a href="/stroke/sources/#src-Dawson2021">218</a></sup>.',
  hook:'The VNS-REHAB between-group difference was 2.6 FMA-UE points <sup class="c" data-ref="Dawson2021" title="Source 218"><a href="/stroke/sources/#src-Dawson2021">218</a></sup>.'}
];

/* arm comparator. p:true prints the count, as a share of its axis */
const FX_CMP=[
 {id:'ner',b:'Nerinetide',max:100,unit:'%',ax:'0 to 100%',arm:['nerinetide','placebo'],
  note:'<span class="ev est">Established</span> neutral in ESCAPE-NA1 and ESCAPE-NEXT. <span class="ev early">Early evidence</span> FRONTIER is phase 2, and the pooled gap comes from a post hoc group of 690 of 2487. A subgroup needs its own trial <sup class="c" data-ref="Hill2020,Hill2025,Christenson2025,Tymianski2025" title="Source 188,427,428,991"><a href="/stroke/sources/#src-Hill2020">188,427,428,991</a></sup>.',
  r:[{t:'ESCAPE-NA1, mRS 0-2',v:[61.4,59.2]},{t:'ESCAPE-NEXT, mRS 0-2',v:[45,46]},{t:'FRONTIER, favourable outcome',v:[57,58]},{t:'Post hoc pool, under 3 h, responders',v:[56,48]}]},
 {id:'ric',b:'Remote conditioning',max:100,unit:'%',ax:'0 to 100%',arm:['conditioning','control or sham'],
  note:'<span class="ev early">Early evidence</span> RICAMIS was open label and SERIC-EVT used sham. SERIC-IVT did not reach significance, and the sham-controlled RESIST found no improvement (OR 0.95, 95% CI 0.75-1.20), so it has no bar here <sup class="c" data-ref="Chen2022,Guo2026,Guo2025,Blauenfeldt2023" title="Source 109,180,376,377"><a href="/stroke/sources/#src-Chen2022">109,180,376,377</a></sup>.',
  r:[{t:'RICAMIS, mRS 0-1',v:[67.4,62.0]},{t:'SERIC-EVT, mRS 0-2',v:[61.1,48.9]},{t:'SERIC-IVT, excellent outcome',v:[62.7,56.8]}]},
 {id:'ial',b:'Intra-arterial lysis',max:100,unit:'%',ax:'0 to 100%',arm:['drug','control'],
  note:'<span class="ev early">Early evidence</span> CHOICE and ANGEL-TNK were positive with small samples, while POST-TNK and POST-UK were not significant <sup class="c" data-ref="Renu2022,Miao2025,Huang2025,Liu2025" title="Source 447,590,674,839"><a href="/stroke/sources/#src-Renu2022">447,590,674,839</a></sup>.',
  r:[{t:'CHOICE, mRS 0-1',v:[59.0,40.4]},{t:'POST-TNK, primary',v:[49.1,44.1]},{t:'POST-UK, primary',v:[45.1,40.2]},{t:'ANGEL-TNK, mRS 0-1',v:[40.5,26.4]}]},
 {id:'col',b:'Colchicine',max:20,unit:'%',ax:'0 to 20%. Lower is better',arm:['colchicine','control'],
  note:'<span class="ev early">Early evidence</span> CONVINCE missed significance (p=0.12) and CHANCE-3 was neutral. The pooled figure mixes prior stroke with coronary disease. CHANCE-3 measured 90 days, CONVINCE long-term follow-up <sup class="c" data-ref="Kelly2024,Li2024CHANCE3,Fiolet2024" title="Source 309,490,569"><a href="/stroke/sources/#src-Kelly2024">309,490,569</a></sup>.',
  r:[{t:'CONVINCE, primary end point',v:[9.8,11.7]},{t:'CHANCE-3, stroke at 90 days',v:[6.3,6.5]},{t:'Meta-analysis, ischaemic stroke',v:[1.8,2.5]}]},
 {id:'afs',b:'AF screening',max:40,unit:'%',ax:'0 to 40%',arm:['implanted recorder','usual care'],
  note:'<span class="ev est">Established</span> LOOP found three times more AF and gave twice as much anticoagulation, yet the fall in stroke or systemic embolism did not reach significance (HR 0.80, 95% CI 0.61-1.05; p=0.11) <sup class="c" data-ref="Svendsen2021" title="Source 950"><a href="/stroke/sources/#src-Svendsen2021">950</a></sup>.',
  r:[{t:'LOOP, AF found',v:[31.8,12.2]},{t:'LOOP, anticoagulation started',v:[29.7,13.1]},{t:'LOOP, stroke or systemic embolism',v:[4.5,5.6]}]},
 {id:'cel',b:'SB623 cells',max:30,unit:'',ax:'0 to 30% of the arm',arm:['cells','sham'],count:1,
  note:'<span class="ev early">Early evidence</span> Open-label SB623 reported FMA motor gains of 11.40 at 12 months and 10.4 at 24 months <sup class="c" data-ref="Steinberg2016,Steinberg2019" title="Source 938,939"><a href="/stroke/sources/#src-Steinberg2016">938,939</a></sup>. Against sham, ACTIsSIMA showed no difference, p=0.6743 for combined versus sham. The counts are from results posted on the registry, with no peer-reviewed report found <sup class="c" data-ref="NCT02448641" title="Source 710"><a href="/stroke/sources/#src-NCT02448641">710</a></sup>.',
  r:[{t:'ACTIsSIMA, 2.5 million cells vs sham: at least a 10-point gain',c:[ [7,55], [7,52] ]},{t:'ACTIsSIMA, 5.0 million cells vs sham: at least a 10-point gain',c:[ [9,56], [7,52] ]}]}
];

const fxTx=(x,y,s,c='t-xs',st='')=>`<text x="${f1(x)}" y="${f1(y)}" class="${c}"${st?` style="${st}"`:''}>${s}</text>`;
function fxGlyph(x,y,k,o=1,r=8){const R=FX_RES[k];
  if(k==='none')return `<g style="opacity:${f1(o)}"><circle cx="${f1(x)}" cy="${f1(y)}" r="${r}" style="fill:var(--panel);stroke:var(--muted);stroke-width:1.5;stroke-dasharray:3 2"/><text x="${f1(x)}" y="${f1(y+3.4)}" class="t-xs t-mid" style="fill:var(--ink);font-weight:700">?</text></g>`;
  const sh=k==='fav'?`<circle cx="${f1(x)}" cy="${f1(y)}" r="${r}" style="fill:${R.col}"/>`:
    k==='neu'?`<rect x="${f1(x-r+1)}" y="${f1(y-r+1)}" width="${2*r-2}" height="${2*r-2}" rx="2" style="fill:${R.col}"/>`:
    k==='bad'?`<path d="M${f1(x)} ${f1(y-r-1)}L${f1(x+r+1)} ${f1(y+r-1)}L${f1(x-r-1)} ${f1(y+r-1)}Z" style="fill:${R.col}"/>`:
    `<path d="M${f1(x)} ${f1(y-r-1)}L${f1(x+r+1)} ${f1(y)}L${f1(x)} ${f1(y+r+1)}L${f1(x-r-1)} ${f1(y)}Z" style="fill:${R.col}"/>`;
  return `<g style="opacity:${f1(o)}">${sh}<text x="${f1(x)}" y="${f1(y+3.4)}" class="t-xs t-mid" style="fill:var(--panel);font-weight:700">${R.g}</text></g>`}
function fxAlong(P,u){let L=0;const d=[];for(let i=1;i<P.length;i++){const l=Math.hypot(P[i][0]-P[i-1][0],P[i][1]-P[i-1][1]);d.push(l);L+=l}
  let a=clamp(u)*L;for(let i=0;i<d.length;i++){if(a<=d[i]||i===d.length-1){const v=d[i]?a/d[i]:0;return [lerp(P[i][0],P[i+1][0],v),lerp(P[i][1],P[i+1][1],v)]}a-=d[i]}return P[0]}
function fxDots(P,n,ph,col,o=1,r=3){let s='';if(o<=0.01||n<=0)return s;for(let i=0;i<n;i++){const u=(i/n+ph)%1,p=fxAlong(P,u);s+=`<circle cx="${f1(p[0])}" cy="${f1(p[1])}" r="${r}" style="fill:${col};opacity:${f1(o)}"/>`}return s}
function fxWrap(s,mx){const w=s.split(' '),o=[];let l='';w.forEach(k=>{if((l+' '+k).trim().length>mx){o.push(l.trim());l=k}else l+=' '+k});if(l.trim())o.push(l.trim());return o}

inits.frontier=()=>{
  /* ---------- state shared by map and explorer ---------- */
  const F={stage:'all',ev:'all',wait:false},byId=id=>FX_ROUTES.find(r=>r.id===id);
  let sel='fxi';
  const mapSvg=$('#fxMap'),svg=$('#fxSvg'),rg=$('#fxT'),note=$('#fxNote');
  const match=r=>(F.stage==='all'||r.st===F.stage)&&(F.ev==='all'||r.c.some(c=>c.e===F.ev))&&(!F.wait||r.c.some(c=>c.r==='none'));
  function counts(r){const n={est:0,early:0,hyp:0};r.c.forEach(c=>n[c.e]++);const a=[];
    if(n.est)a.push(n.est+' est');if(n.early)a.push(n.early+' early');if(n.hyp)a.push(n.hyp+' hyp');return a.join(', ')}
  function drawMap(refocus){
    const N=NARROW(),vis=FX_ROUTES.filter(match),sts=FX_STAGES.filter(s=>vis.some(r=>r.st===s.id));
    const PH=50,GAP=6;let g='',H=0;
    const pill=(r,x,y,w,col)=>{const on=r.id===sel,wc=r.c.filter(c=>c.r==='none').length;
      return `<g class="clk" tabindex="0" role="button" aria-pressed="${on}" aria-label="${r.t}" data-fxr="${r.id}"><rect class="fxpb" x="${f1(x)}" y="${f1(y)}" width="${f1(w)}" height="${PH}" rx="8" style="fill:${on?'var(--brand-soft)':'var(--panel)'};stroke:${on?'var(--brand)':'var(--line)'};stroke-width:${on?2.2:1}"/><rect x="${f1(x)}" y="${f1(y+6)}" width="4" height="${PH-12}" rx="2" style="fill:${col}"/>`+
        fxTx(x+11,y+15,r.sh,'fxpn')+fxTx(x+11,y+29,counts(r))+(wc?fxTx(x+11,y+42,wc+' with no results yet','t-xs','fill:var(--ink)'):'')+'</g>'};
    if(!sts.length){H=70;g=fxTx(N?200:360,38,FX_MAPTXT.none,'t-sm t-mid','fill:var(--ink)')}
    else if(N){let y=4;sts.forEach(s=>{const rs=vis.filter(r=>r.st===s.id);
        g+=fxTx(10,y+13,s.t,'t-lbl',`fill:${s.col}`);y+=22;
        rs.forEach((r,i)=>{g+=pill(r,10+(i%2)*194,y+Math.floor(i/2)*(PH+GAP),186,s.col)});
        y+=Math.ceil(rs.length/2)*(PH+GAP)+8});H=y}
    else{const k=sts.length,W=(704-(k-1)*10)/k,sub=Math.max(1,Math.floor((W+6)/136)),pw=(W-(sub-1)*6)/sub;
      sts.forEach((s,i)=>{const x0=8+i*(W+10),rs=vis.filter(r=>r.st===s.id);
        g+=fxTx(x0,18,s.t,'t-lbl',`fill:${s.col}`);
        rs.forEach((r,j)=>{g+=pill(r,x0+(j%sub)*(pw+6),28+Math.floor(j/sub)*(PH+GAP),pw,s.col)});
        H=Math.max(H,28+Math.ceil(rs.length/sub)*(PH+GAP)+4)})}
    vb(mapSvg,`720 ${Math.round(H)}`,`400 ${Math.round(H)}`);mapSvg.innerHTML=g;
    $('#fxCount').innerHTML=FX_MAPTXT.count(vis.length,FX_ROUTES.length);
    if(refocus){const el=mapSvg.querySelector(`[data-fxr="${refocus}"]`);if(el)el.focus()}
  }
  /* ---------- explorer ---------- */
  const range=r=>{const ys=r.c.filter(c=>!c.nd).map(c=>c.y);let a=Math.floor(Math.min(...ys))-1,b=Math.ceil(Math.max(...ys,FX_TODAY))+1;if(b-a<6){a=b-6}return [a,b]};
  function layout(r,N,X,xL,xR){
    const out=[];let y=0;
    FX_LANES.forEach(l=>{const cs=r.c.filter(c=>c.l===l.id).map(c=>({...c,yy:c.nd?FX_TODAY:c.y})).sort((p,q)=>p.yy-q.yy);if(!cs.length)return;
      const rows=[];cs.forEach(c=>{const mx=X(c.yy),lbl=c.n+(c.r==='none'?(c.nd?' · status only':' · no results'):''),w=lbl.length*6+6,right=mx+13+w<=xR,a=right?mx-11:mx-13-w,b=right?mx+13+w:mx+11;
        let k=0;while(rows[k]&&rows[k].some(iv=>a<iv[1]+4&&b>iv[0]-4))k++;(rows[k]=rows[k]||[]).push([a,b]);c.k=k;c.mx=mx;c.right=right;c.lbl=lbl});
      out.push({l,cs,rows:Math.max(1,rows.length)})});
    return out}
  function draw(t){
    const r=byId(sel),N=NARROW(),[y0,y1]=range(r),Y=lerp(y0+1,y1,t);
    const xL=N?16:170,xR=N?386:706,X=v=>xL+(xR-xL)*(v-y0)/(y1-y0),RH=24;
    const L=layout(r,N,X,xL,xR),top=N?50:38;
    let h=top;L.forEach(b=>{b.y=h;b.h=(N?20:6)+b.rows*RH+6;h+=b.h+4});
    const axY=h+4,H=axY+32;
    vb(svg,`720 ${Math.round(H)}`,`400 ${Math.round(H)}`);
    let g=fxTx(N?16:12,20,r.t.length>(N?44:90)?r.sh:r.t,'t-lbl');
    /* lanes */
    L.forEach(b=>{g+=`<rect x="${N?8:6}" y="${f1(b.y)}" width="${N?384:708}" height="${f1(b.h)}" rx="6" style="fill:${b.l.id==='wait'?'var(--panel-2)':'var(--field)'}"/>`;
      if(N)g+=fxTx(16,b.y+13,b.l.t,'t-xs','fill:var(--ink);font-weight:600');
      else fxWrap(b.l.t,24).forEach((ln,i)=>{g+=fxTx(12,b.y+16+i*12,ln,'t-xs','fill:var(--ink);font-weight:600')})});
    /* grid and axis */
    const span=y1-y0,step=span>16?4:span>9?2:1,yr0=Math.ceil(y0/step)*step;
    for(let v=yr0;v<=y1;v+=step){const x=X(v);g+=`<line x1="${f1(x)}" x2="${f1(x)}" y1="${top}" y2="${f1(axY)}" class="grid"/>`+fxTx(x,axY+14,v,'t-xs t-mid')}
    g+=`<line x1="${f1(xL)}" x2="${f1(xR)}" y1="${f1(axY)}" y2="${f1(axY)}" class="axis"/>`;
    /* today */
    const tx=X(FX_TODAY),px=X(Y),near=Math.abs(tx-px)<54;
    g+=`<line x1="${f1(tx)}" x2="${f1(tx)}" y1="${top-4}" y2="${f1(axY)}" style="stroke:var(--ink);stroke-width:1.2;stroke-dasharray:4 3"/>`;
    if(!near)g+=fxTx(tx,top-8,'today','t-xs t-mid','fill:var(--ink);font-weight:700');
    /* playhead under the markers, so labels stay readable */
    g+=`<line x1="${f1(px)}" x2="${f1(px)}" y1="${top-4}" y2="${f1(axY)}" style="stroke:var(--accent);stroke-width:2"/>`;
    /* markers */
    L.forEach(b=>{b.cs.forEach(c=>{const my=b.y+(N?20:6)+c.k*RH+RH/2,wait=c.r==='none',u=wait?1:ramp(Y,c.yy-.05,c.yy+Math.max(.25,span*.02));
      if(u<=0)return;
      g+=fxGlyph(c.mx,my,c.r,wait?.95:u);
      g+=fxTx(c.right?c.mx+13:c.mx-13,my+3.5,c.lbl,c.right?'t-xs':'t-xs t-end',`fill:var(--ink);paint-order:stroke;stroke:${b.l.id==='wait'?'var(--panel-2)':'var(--field)'};stroke-width:3;opacity:${f1(wait?1:u)}`)})});
    /* year label */
    const lx=clamp(px,xL+16,xR-16);g+=fxTx(lx,top-8,Math.floor(Y),'t-xs t-mid','fill:var(--accent);font-weight:700');
    svg.innerHTML=g;
    $('#fxRead').innerHTML=`<span>${FX_READ.year}: <b>${Math.floor(Y)}</b></span><span>${FX_READ.today}</span><span>${Y>FX_TODAY?FX_READ.future:FX_READ.past}</span>`;
    /* note: claims up to the year shown, then registry entries */
    const st=FX_STAGES.find(s=>s.id===r.st),shown=r.c.filter(c=>c.r==='none'||c.y<=Y).sort((p,q)=>(p.r==='none')-(q.r==='none')||(p.y||0)-(q.y||0)),later=r.c.length-shown.length;
    let n=`<div class="kicker">${st.t}</div><h4>${r.t}</h4><p>${r.s}</p><ul class="fxcl">`;
    shown.forEach(c=>{n+=`<li><b>${c.n}</b><span class="fxmeta"><span class="ev ${c.e}">${FX_EV[c.e]}</span>${c.r==='none'?'<span class="tag warn">No results shown</span>':''}</span><br>${c.x}</li>`});
    n+='</ul>';
    if(later)n+=`<p class="stage-cap">${later===1?'One more entry appears':later+' more entries appear'} later on the timeline.</p>`;
    if(r.pt)n+=`<div class="pt"><b>In plain words</b>${r.pt}</div>`;
    if(r.hook)n+=`<div class="hook"><b>Exam hook</b>${r.hook}</div>`;
    note.innerHTML=n;
  }
  /* opens on today; Play from there replays the route from its first year */
  const tNow=()=>{const [a,b]=range(byId(sel));return clamp((FX_TODAY-(a+1))/(b-a-1))};
  $('#fxPlay').addEventListener('click',()=>{if(Math.abs(+rg.value-tNow())<.002)rg.value=0});
  const stop=playWire(rg,$('#fxPlay'),draw,16000,'Replay','frontier');
  function pick(id,focus){sel=id;stop();rg.value=tNow();drawMap(focus?id:null);draw(+rg.value)}
  mapSvg.addEventListener('click',e=>{const g=e.target.closest('[data-fxr]');if(g)pick(g.dataset.fxr,true)});
  mapSvg.addEventListener('keydown',e=>{if(e.key!=='Enter'&&e.key!==' ')return;const g=e.target.closest('[data-fxr]');if(g){e.preventDefault();pick(g.dataset.fxr,true)}});
  function filt(sel_,attr,set){$$(sel_,$('#m-frontier')).forEach(b=>b.addEventListener('click',()=>{set(b.getAttribute(attr));
    $$(sel_,$('#m-frontier')).forEach(x=>x.setAttribute('aria-pressed',x===b));
    drawMap();const vis=FX_ROUTES.filter(match);if(vis.length&&!vis.some(r=>r.id===sel))pick(vis[0].id)}))}
  filt('[data-fxs]','data-fxs',v=>F.stage=v);filt('[data-fxe]','data-fxe',v=>F.ev=v);filt('[data-fxw]','data-fxw',v=>F.wait=v==='1');
  $('#fxLegend').innerHTML=Object.keys(FX_RES).map(k=>`<span><svg viewBox="0 0 20 20" aria-hidden="true">${fxGlyph(10,10,k,1,7)}</svg>${FX_RES[k].t}</span>`).join('');
  rg.value=tNow();drawMap();draw(+rg.value);

  /* ---------- factor XI vs factor X ---------- */
  const cs=$('#fxcSvg'),cr=$('#fxcT');
  function cDraw(t){
    const N=vb(cs,'720 448','400 696'),p=phaseOf(FXC_STEPS,t),P=FXC_STEPS[p];
    const xs=N?[30,88,146,204,280,360]:[60,170,280,396,516,646],nw=N?[44,44,44,44,64,52]:[64,64,64,64,84,76],cy=76,nh=30,nm=['XII','XI','IX','X','Thrombin','Fibrin'];
    const tf=N?{x:142,y:132,w:116}:{x:280,y:132,w:130};
    const bX=ramp(t,.16,.2)*(1-ramp(t,.32,.36)),bXI=ramp(t,.36,.4);
    const showA=p<=2,sA=showA?1-ramp(t,.52,.56):0;
    let g=`<defs>${marker('fxcA','var(--muted)',6)}</defs>`;
    /* arrows */
    const ar=(a,b,o=1)=>`<path d="${ptsD([ [a[0],a[1]], [b[0],b[1]] ])}" class="arrow" marker-end="url(#fxcA)" style="opacity:${f1(o)}"/>`;
    for(let i=0;i<5;i++)g+=ar([xs[i]+nw[i]/2+1,cy],[xs[i+1]-nw[i+1]/2-1,cy],(i<3&&i>0)?1-.7*bXI:1);
    /* amplifying loop, thrombin back to XI */
    const lp=`M${xs[4]} ${cy-nh/2}C${xs[4]} ${cy-62} ${xs[1]} ${cy-62} ${xs[1]} ${cy-nh/2-2}`;
    g+=`<path d="${lp}" class="arrow" marker-end="url(#fxcA)" style="stroke-dasharray:4 4;opacity:${f1(1-.75*bXI)}"/>`;
    g+=fxTx((xs[1]+xs[4])/2,cy-56,'amplifying loop','t-xs t-mid');
    /* injury route */
    const tr=tf.x+tf.w/2,inj=[ [tr,tf.y], [xs[3],tf.y], [xs[3],cy+nh/2+2] ];
    g+=`<path d="${ptsD(inj)}" class="arrow" marker-end="url(#fxcA)"/>`;
    g+=fxTx(xs[0]-nw[0]/2,cy-nh/2-7,N?'Contact':'Contact route','t-xs','fill:var(--ink);font-weight:600');
    g+=`<rect x="${f1(tf.x-tf.w/2)}" y="${f1(tf.y-14)}" width="${tf.w}" height="28" rx="7" style="fill:var(--panel);stroke:var(--brand);stroke-width:1.4"/>`+fxTx(tf.x,tf.y+3.5,'Tissue factor + VII','t-xs t-mid','fill:var(--ink);font-weight:600');
    g+=fxTx(tf.x-tf.w/2-6,tf.y+3.5,'Injury route','t-xs t-end','fill:var(--ink);font-weight:600');
    /* moving particles */
    const ph=t*9;
    const P1=[ [xs[0],cy], [xs[1],cy] ],P2=[ [xs[1],cy], [xs[2],cy], [xs[3],cy] ],P3=inj,P4=[ [xs[3],cy], [xs[4],cy], [xs[5],cy] ];
    g+=fxDots(P1,2,ph,'var(--brand)',.9);
    g+=fxDots(P2,4,ph,'var(--brand)',.9*(1-bXI));
    g+=fxDots(P3,3,ph,'var(--tpa)',.95);
    g+=fxDots(P4,bX>.5?2:bXI>.5?4:6,ph,'var(--artery)',.95);
    /* nodes */
    nm.forEach((n,i)=>{const hX=i===3&&bX>0,hXI=i===1&&bXI>0,on=hX||hXI;
      g+=`<rect x="${f1(xs[i]-nw[i]/2)}" y="${cy-nh/2}" width="${nw[i]}" height="${nh}" rx="8" style="fill:var(--panel);stroke:${on?'var(--accent)':'var(--brand)'};stroke-width:${on?3:1.4}"/>`+fxTx(xs[i],cy+4,n,i>3?'t-xs t-mid':'t-lbl t-mid',i>3?'fill:var(--ink);font-weight:700':'')});
    /* block bar on the arrow out of the blocked node */
    const blk=(i,o)=>{if(o<=0)return '';const mx=(xs[i]+nw[i]/2+xs[i+1]-nw[i+1]/2)/2;return `<g style="opacity:${f1(o)}"><line x1="${f1(mx)}" x2="${f1(mx)}" y1="${cy-14}" y2="${cy+14}" style="stroke:var(--accent);stroke-width:4;stroke-linecap:round"/></g>`};
    g+=blk(3,bX)+blk(1,bXI);
    /* strip */
    const sy=N?164:164,lines=N?P.n:P.w,tagc={brand:['var(--brand-soft)','var(--brand)'],hyp:['var(--rx-soft)','var(--rx)'],est:['var(--good-soft)','var(--good)']}[P.tc],tw=P.tag.length*6.2+14;
    g+=`<rect x="${N?8:14}" y="${sy}" width="${f1(tw)}" height="18" rx="4" style="fill:${tagc[0]}"/>`+fxTx((N?8:14)+7,sy+13,P.tag,'t-xs',`fill:${tagc[1]};font-weight:700`);
    lines.forEach((ln,i)=>{g+=N?fxTx(8,sy+34+i*14,ln,'t-sm','fill:var(--ink)'):fxTx(14+tw+10,sy+13+i*14,ln,'t-sm','fill:var(--ink)')});
    /* bottom scene */
    const by=N?222:200;
    if(showA&&sA>0){
      const tiles=N?[ [8,by,384,226], [8,by+234,384,226] ]:[ [14,by,340,234], [366,by,340,234] ],cl=[.72,.34,.34][p],rp=[.28,.8,.34][p],plug=[30,12,27][p];
      const T=(ti,ttl,txt,draw)=>{const [x,y,w,h]=ti;let s=`<g style="opacity:${f1(sA)}"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="10" style="fill:var(--field);stroke:var(--line)"/>`+fxTx(x+12,y+20,ttl,'t-lbl')+draw(x,y,w,h);
        fxWrap(txt,w>360?60:50).forEach((ln,i)=>{s+=fxTx(x+12,y+h-28+i*14,ln,'t-sm','fill:var(--ink)')});return s+'</g>'};
      g+=T(tiles[0],'A clot growing inside an artery',P.a,(x,y,w)=>{const A=artery(x+14,y+92,w-28,{h:40,clot:cl,flow:clamp(1.25-cl),ph:t*6,at:.62});return A.svg});
      g+=T(tiles[1],'A torn vessel being sealed',P.b,(x,y,w)=>{const A=artery(x+14,y+112,w-28,{h:34,rupture:rp,ruptureAt:.5,flow:1,ph:t*6});return A.svg+clot(x+w/2,y+112,plug,{seed:5})});
    }else if(p===3||p===4){
      const w=N?384:340,yBase=by,mx=10,scale=(w-120)/mx,fade=p===3?ramp(t,.56,.6):1;
      FXC_BARS.forEach((pn,i)=>{const x=N?8:14+i*(w+12),y=N?yBase+i*232:yBase;
        g+=`<g style="opacity:${f1(fade)}"><rect x="${x}" y="${y}" width="${w}" height="${N?224:234}" rx="10" style="fill:var(--field);stroke:var(--line)"/>`+fxTx(x+12,y+20,pn.t,'t-lbl')+fxTx(x+12,y+35,pn.sub);
        pn.g.forEach((m,j)=>{const vis=j===0?ramp(t,.58,.64):ramp(t,.72,.78),gy=y+50+j*(N?84:90);if(vis<=0)return;
          g+=`<g style="opacity:${f1(vis)}">`+fxTx(x+12,gy+8,m.m,'t-xs','fill:var(--ink);font-weight:700');
          [m.a,m.b].forEach((arm,k)=>{const ay=gy+14+k*30;
            g+=fxTx(x+12,ay+9,arm[0],'t-xs')+`<rect x="${x+12}" y="${ay+12}" width="${f1(Math.max(1.5,arm[1]*scale*vis))}" height="12" rx="3" style="fill:${k?'var(--muted)':'var(--tpa)'}"/>`+fxTx(x+18+arm[1]*scale*vis,ay+22,arm[1].toFixed(1)+'%','t-xs','fill:var(--ink);font-weight:700')});
          g+='</g>'});
        g+='</g>'});
    }else if(p===5){
      FXC_REG.forEach((R,i)=>{const h=N?100:52,y=by+i*(h+6),x=N?8:14,w=N?384:692;
        g+=`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="9" style="fill:var(--panel);stroke:var(--muted);stroke-width:1.2;stroke-dasharray:5 4"/>`+fxGlyph(x+18,y+(N?20:26),'none',1,8)+fxTx(x+36,y+(N?24:22),R.n,'t-lbl');
        if(N){fxWrap(R.q,58).forEach((ln,k)=>{g+=fxTx(x+12,y+44+k*13,ln,'t-xs','fill:var(--ink)')});fxWrap(R.s,58).forEach((ln,k)=>{g+=fxTx(x+12,y+62+k*13,ln)})}
        else{g+=fxTx(x+36,y+38,R.q,'t-xs','fill:var(--ink)')+fxTx(x+w-10,y+22,R.s,'t-xs t-end')}});
    }
    cs.innerHTML=g;setC(p);$('#fxcNote').innerHTML=noteHTML(P);
  }
  let setC=()=>{};
  const stopC=playWire(cr,$('#fxcPlay'),cDraw,20000,'Replay','frontier');
  setC=stepWire($('#fxcSteps'),FXC_STEPS,cr,cDraw,stopC);
  cDraw(+cr.value);

  /* ---------- paired VNS ---------- */
  const vs=$('#fxvSvg'),vr=$('#fxvT');let mode='paired';const REPS=7,T0=.2,T1=.8;
  function reach(t){if(t<T0||t>T1)return 0;const u=(t-T0)/(T1-T0)*REPS,fr=u-Math.floor(u);return Math.sin(Math.PI*clamp(fr/.62))*(fr<.62?1:0)}
  function vDraw(t){
    const N=vb(vs,'720 410','400 744'),p=phaseOf(FXV_STEPS,t),P=FXV_STEPS[p],paired=mode==='paired';
    const rc=reach(t),bursting=paired&&t>=.4&&t<=T1&&rc>.15&&rc<.98;
    let g=`<defs>${marker('fxvA','var(--muted)',6)}</defs>`;
    /* figure: same coordinates in both layouts */
    const bx=64,by=8,B=brainSide(bx,by,.62,{dim:.35,id:'fxv'});
    const bs=B.at.brainstem,neck=[bs[0]+2,bs[1]+18],sh=[bs[0]-6,bs[1]+64];
    const tx=sh[0]-30,ty=bs[1]+44;
    g+=`<path d="M${f1(neck[0]-13)} ${f1(bs[1])}L${f1(neck[0]-15)} ${f1(ty+2)}L${f1(tx)} ${f1(ty+6)}Q${f1(tx-14)} ${f1(ty+10)} ${f1(tx-12)} ${f1(ty+36)}L${f1(tx-4)} ${f1(ty+172)}L${f1(tx+116)} ${f1(ty+172)}L${f1(tx+112)} ${f1(ty+30)}Q${f1(tx+108)} ${f1(ty+8)} ${f1(tx+88)} ${f1(ty+6)}L${f1(neck[0]+15)} ${f1(ty+2)}L${f1(neck[0]+13)} ${f1(bs[1])}Z" style="fill:var(--skin);stroke:var(--brain-line);stroke-width:1.2"/>`;
    g+=B.svg;
    /* task target */
    const tgx=30,tgy=sh[1]+6;
    g+=`<rect x="${tgx-16}" y="${f1(tgy-12)}" width="24" height="24" rx="5" style="fill:var(--panel);stroke:var(--brand);stroke-width:1.5"/>`+fxTx(tgx-4,tgy+27,'task','t-xs t-mid','fill:var(--ink);font-weight:600');
    /* arm: rest hangs down, reach goes to the target */
    const a1=lerp(82,172,ease(rc))*Math.PI/180,a2=lerp(96,180,ease(rc))*Math.PI/180,L1=64,L2=58;
    const el=[sh[0]+Math.cos(a1)*L1,sh[1]+Math.sin(a1)*L1],ha=[el[0]+Math.cos(a2)*L2,el[1]+Math.sin(a2)*L2];
    g+=`<path d="M${f1(sh[0])} ${f1(sh[1])}L${f1(el[0])} ${f1(el[1])}L${f1(ha[0])} ${f1(ha[1])}" style="fill:none;stroke:var(--brain-line);stroke-width:16;stroke-linecap:round;stroke-linejoin:round"/><path d="M${f1(sh[0])} ${f1(sh[1])}L${f1(el[0])} ${f1(el[1])}L${f1(ha[0])} ${f1(ha[1])}" style="fill:none;stroke:var(--skin);stroke-width:13;stroke-linecap:round;stroke-linejoin:round"/>`;
    /* device and lead */
    const gen=[tx+78,ty+40],lead=[ [gen[0]+6,gen[1]], [neck[0]+8,neck[1]+16], [neck[0]+6,bs[1]+2] ];
    g+=`<path d="M${f1(lead[0][0])} ${f1(lead[0][1])}Q${f1(lead[1][0]+22)} ${f1(lead[1][1]+6)} ${f1(lead[1][0])} ${f1(lead[1][1])}L${f1(lead[2][0])} ${f1(lead[2][1])}" style="fill:none;stroke:var(--device);stroke-width:2.2"/>`;
    g+=`<rect x="${f1(gen[0]-9)}" y="${f1(gen[1]-8)}" width="28" height="18" rx="5" style="fill:var(--device);stroke:var(--ink);stroke-width:1"/>`;
    g+=kitLabel(gen[0]+26,gen[1]+4,'pulse generator')+kitLabel(neck[0]+24,neck[1]+8,'lead to vagus nerve');
    /* the signals */
    const motor=[lerp(B.at.frontal[0],B.at.parietal[0],.55),lerp(B.at.frontal[1],B.at.parietal[1],.35)];
    if(rc>.05){g+=`<path d="M${f1(motor[0])} ${f1(motor[1])}L${f1(bs[0])} ${f1(bs[1])}L${f1(sh[0])} ${f1(sh[1])}L${f1(el[0])} ${f1(el[1])}" style="fill:none;stroke:var(--brand);stroke-width:2.4;stroke-dasharray:5 4;opacity:${f1(rc)}"/>`}
    if(bursting){const u=(t*180)%1,path=[ gen, lead[1], [bs[0],bs[1]], motor ];g+=fxDots(path,4,u,'var(--accent)',1,3.6);g+=`<circle cx="${f1(motor[0])}" cy="${f1(motor[1])}" r="${f1(10+rc*5)}" style="fill:var(--accent);opacity:.25"/>`}
    g+=kitLabel(motor[0],B.at.frontal[1]-Math.max(10,0)-26,'arm movement areas',{a:'m'});
    /* right side */
    const R=N?{x:14,w:372,tY:352,sY:512,bY:352}:{x:352,w:356,tY:18,sY:192,bY:18};
    if(p<4){
      const X=v=>R.x+R.w*(v-T0)/(T1-T0),rowM=R.tY+46,rowB=R.tY+100;
      g+=`<rect x="${R.x-6}" y="${R.tY}" width="${R.w+12}" height="148" rx="10" style="fill:var(--field);stroke:var(--line)"/>`;
      g+=fxTx(R.x+2,R.tY+18,'Arm movement','t-xs','fill:var(--brand);font-weight:700')+fxTx(R.x+2,R.tY+72,paired?'Vagal burst, paired from step 3':'Control stimulation: settings not shown','t-xs','fill:var(--accent);font-weight:700');
      g+=`<line x1="${R.x}" x2="${R.x+R.w}" y1="${rowM}" y2="${rowM}" class="axis"/><line x1="${R.x}" x2="${R.x+R.w}" y1="${rowB}" y2="${rowB}" class="axis"/>`;
      for(let i=0;i<REPS;i++){const a=T0+(T1-T0)*i/REPS,b=a+(T1-T0)/REPS*.62;if(a>t)break;
        const e=Math.min(t,b),n=14;let d='';for(let k=0;k<=n;k++){const v=lerp(a,e,k/n);d+=(k?'L':'M')+f1(X(v))+' '+f1(rowM-reach(v)*20)}g+=`<path d="${d}" style="fill:none;stroke:var(--brand);stroke-width:2.2"/>`;
        if(paired&&a>=.4-1e-6){const bs0=a+(b-a)*.2,bs1=a+(b-a)*.8;if(t>=bs0)g+=`<rect x="${f1(X(bs0))}" y="${rowB-20}" width="${f1(X(Math.min(t,bs1))-X(bs0))}" height="20" rx="2" style="fill:var(--accent)"/>`}}
      if(t>=T0&&t<=T1)g+=`<line x1="${f1(X(t))}" x2="${f1(X(t))}" y1="${R.tY+24}" y2="${rowM+4}" style="stroke:var(--ink);stroke-width:1.4"/><line x1="${f1(X(t))}" x2="${f1(X(t))}" y1="${rowB-22}" y2="${rowB+4}" style="stroke:var(--ink);stroke-width:1.4"/>`;
      g+=fxTx(R.x+R.w,R.tY+122,t<T0?'Therapy has not started':'Repeat '+Math.min(REPS,Math.floor((clamp(t,T0,T1-.001)-T0)/(T1-T0)*REPS)+1)+' of '+REPS+' shown','t-xs t-end');
      g+=fxTx(R.x+2,R.tY+138,'Schematic: real sessions have far more repeats');
      /* connection */
      const u=ramp(t,.4,T1),wd=lerp(1.6,paired?9:4,u),sx=R.x+24,ex=R.x+R.w-24,cy2=R.sY+72;
      g+=`<rect x="${R.x-6}" y="${R.sY}" width="${R.w+12}" height="${N?196:198}" rx="10" style="fill:var(--field);stroke:var(--line)"/>`;
      g+=`<rect x="${R.x+2}" y="${R.sY+10}" width="82" height="17" rx="4" style="fill:var(--rx-soft)"/>`+fxTx(R.x+9,R.sY+22,'HYPOTHESIS','t-xs','fill:var(--rx);font-weight:700')+fxTx(R.x+92,R.sY+22,'connection in use','t-xs','fill:var(--ink);font-weight:600');
      g+=neuron(sx+14,cy2,14,{axon:0,seed:3})+neuron(ex-14,cy2,14,{axon:0,seed:7});
      g+=`<line x1="${f1(sx+30)}" x2="${f1(ex-30)}" y1="${cy2}" y2="${cy2}" style="stroke:var(--neuron);stroke-width:${f1(wd)};stroke-linecap:round"/>`;
      if(rc>.1)g+=fxDots([ [sx+30,cy2], [ex-30,cy2] ],3,t*30,'var(--brand)',rc,3);
      fxWrap(paired?'Idea: a burst during practice strengthens the connection in use. Not measured in the trial.':'Rehabilitation also helped: the control group gained too. Thickening here is an illustration.',N?64:62).forEach((ln,i)=>{g+=fxTx(R.x+2,R.sY+136+i*14,ln,'t-xs','fill:var(--ink)')});
      g+=fxTx(R.x+2,R.sY+182,'Line width is schematic.');
    }else{
      const vis=ramp(t,.8,.86),bw=R.w-90,rows=[{m:'FMA-UE gain, points',mx:10,a:['VNS',5.0,'5.0'],b:['control',2.4,'2.4'],foot:'Difference 2.6, 95% CI 1.0-4.2'},{m:'Response at 90 days',mx:100,a:['VNS',47,'47%'],b:['control',24,'24%'],foot:'Difference 24%, 95% CI 6-41'}];
      g+=`<rect x="${R.x-6}" y="${R.bY}" width="${R.w+12}" height="${N?380:372}" rx="10" style="fill:var(--field);stroke:var(--line)"/>`+`<rect x="${R.x+2}" y="${R.bY+10}" width="82" height="17" rx="4" style="fill:var(--good-soft)"/>`+fxTx(R.x+9,R.bY+22,'TRIAL DATA','t-xs','fill:var(--good);font-weight:700')+fxTx(R.x+92,R.bY+22,'VNS-REHAB, 108 people','t-xs','fill:var(--ink);font-weight:600');
      rows.forEach((q,i)=>{const y=R.bY+44+i*128;g+=fxTx(R.x+2,y,q.m,'t-lbl');
        [q.a,q.b].forEach((a,k)=>{const yy=y+12+k*36,ww=a[1]/q.mx*bw*vis;g+=fxTx(R.x+2,yy+8,a[0],'t-xs')+`<rect x="${R.x+2}" y="${yy+12}" width="${f1(Math.max(1,ww))}" height="14" rx="3" style="fill:${k?'var(--muted)':'var(--accent)'}"/>`+fxTx(R.x+8+ww,yy+24,a[2],'t-xs','fill:var(--ink);font-weight:700')});
        g+=fxTx(R.x+2,y+96,q.foot)});
      g+=fxTx(R.x+2,R.bY+316,'Pooled at 1 year, no control: 5.23 points','t-xs','fill:var(--ink)')+fxTx(R.x+2,R.bY+332,'Uncontrolled programme: 10.8 points.','t-xs','fill:var(--ink)')+fxTx(R.x+2,R.bY+348,'Not an effect size.','t-xs','fill:var(--ink)');
    }
    vs.innerHTML=g;setV(p);$('#fxvNote').innerHTML=noteHTML(P);
  }
  let setV=()=>{};
  const stopV=playWire(vr,$('#fxvPlay'),vDraw,22000,'Replay','frontier');
  setV=stepWire($('#fxvSteps'),FXV_STEPS,vr,vDraw,stopV);
  $$('[data-fxv]',$('#m-frontier')).forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.fxv;$$('[data-fxv]',$('#m-frontier')).forEach(x=>x.setAttribute('aria-pressed',x===b));vDraw(+vr.value)}));
  vDraw(+vr.value);

  /* ---------- arm comparator ---------- */
  const as=$('#fxaSvg');let cmp=FX_CMP[0];
  $('#fxaBtns').innerHTML=FX_CMP.map((c,i)=>`<button class="btn" data-fxa="${c.id}" aria-pressed="${i===0}">${c.b}</button>`).join('');
  function aDraw(){
    const N=NARROW(),C=cmp,lx=N?12:262,bw=N?300:370,lw=lx;let y=26,g='';
    const arm=(lbl,val,txt,k)=>{const ww=Math.max(1.5,val/C.max*bw);let s='';
      s+=fxTx(N?lx:lx-8,N?y+8:y+11,lbl,N?'t-xs':'t-xs t-end');const by=N?y+11:y;
      s+=`<rect x="${lx}" y="${by}" width="${f1(ww)}" height="14" rx="3" style="fill:${k?'var(--muted)':'var(--tpa)'}"/>`+fxTx(lx+ww+6,by+11,txt,'t-xs','fill:var(--ink);font-weight:700');
      y=by+(N?20:18);return s};
    g+=fxTx(N?12:lx,14,'Axis: '+C.ax);
    C.r.forEach(r=>{y+=6;
      if(N){fxWrap(r.t,58).forEach(ln=>{g+=fxTx(12,y+10,ln,'t-xs','fill:var(--ink);font-weight:700');y+=14});y+=2}
      else{fxWrap(r.t,27).forEach((ln,i)=>{g+=fxTx(4,y+11+i*13,ln,'t-xs','fill:var(--ink);font-weight:700')})}
      const base=y;if(!N){}
      if(r.c){r.c.forEach((c,k)=>{g+=N?arm(C.arm[k],c[0]/c[1]*100,c[0]+' of '+c[1],k):arm(C.arm[k],c[0]/c[1]*100,c[0]+' of '+c[1],k)})}
      else r.v.forEach((v,k)=>{g+=arm(C.arm[k],v,v.toFixed(1).replace(/\.0$/,'')+C.unit,k)});
      y=Math.max(y,base)+(N?8:12)});
    vb(as,`720 ${Math.round(y+4)}`,`400 ${Math.round(y+4)}`);as.innerHTML=g;$('#fxaNote').innerHTML=C.note;
  }
  $('#fxaBtns').addEventListener('click',e=>{const b=e.target.closest('[data-fxa]');if(!b)return;cmp=FX_CMP.find(c=>c.id===b.dataset.fxa);$$('[data-fxa]',$('#fxaBtns')).forEach(x=>x.setAttribute('aria-pressed',x===b));aDraw()});
  aDraw();

  const prev=redraws.frontier;redraws.frontier=()=>{prev&&prev();drawMap();aDraw()};
};
/* =============== 6.1 History & people =============== */
/* A scrubbable timeline on a stretched axis, one drawn scene per milestone, chips to jump, and a dumbbell chart of the thrombectomy
   trials. People and dates are as research pass A states them; the 2025-26 items come from passes E, H and I. */
const HS_EV=[
 {y:-500,yt:'Antiquity',c:'Greek physicians: apoplexia',sc:'word',w:'apoplexia',ws:'struck down with violence',who:'Hippocratic Corpus, Galen',l:['A word for a sudden collapse,','known at least 2500 years ago.'],
  t:'Antiquity · Struck down',txt:`"Apoplexia" means struck down with violence, a picture known to Greek physicians at least 2500 years ago. Its first recorded appearance is in the Hippocratic Corpus: "It is impossible to remove a strong attack of apoplexy, and not easy to remove a weak attack". Galen called it "a privation of sense and motion in all the nerves" <sup class="c" data-ref="Engelhardt2017" title="Source 280"><a href="/stroke/sources/#src-Engelhardt2017">280</a></sup>. Understanding rested on Galen and humoral pathology for centuries <sup class="c" data-ref="Yilmaz2025" title="Source 1083"><a href="/stroke/sources/#src-Yilmaz2025">1083</a></sup>.`,
  pt:`For centuries people called stroke "apoplexy", meaning struck down <sup class="c" data-ref="Engelhardt2017" title="Source 280"><a href="/stroke/sources/#src-Engelhardt2017">280</a></sup>.`,hook:`Apoplexy was an umbrella term, covering non-vascular and even non-cerebral events such as myocardial infarction and pulmonary embolism <sup class="c" data-ref="Engelhardt2017" title="Source 280"><a href="/stroke/sources/#src-Engelhardt2017">280</a></sup>.`},
 {y:1658,c:'Wepfer separates bleeding',sc:'wepfer',who:'Johann Jakob Wepfer',l:['Bleeding inside the skull is told','apart for the first time.'],
  t:'1658 · Wepfer finds the blood',txt:`Wepfer distinguished non-traumatic intracranial bleeding, including subarachnoid and cerebral haemorrhage, splitting the unitary concept for the first time <sup class="c" data-ref="Engelhardt2017" title="Source 280"><a href="/stroke/sources/#src-Engelhardt2017">280</a></sup>. He is credited with showing apoplexy results from brain haemorrhage or vessel occlusion, but a re-reading shows his thinking stayed rooted in Galenic theory and iatrochemistry <sup class="c" data-ref="Karenberg1998" title="Source 486"><a href="/stroke/sources/#src-Karenberg1998">486</a></sup>.`},
 {y:1664,c:'Willis: Cerebri anatome',sc:'willis',who:'Thomas Willis',l:['The arterial circle gets its','meaning, and its name.'],
  t:'1664 · The circle of Willis',txt:`Willis published <i>Cerebri anatome</i> in London. He explained the pathological and functional meaning of the circular arterial anastomosis named after him, and coined "neurologie". The source marks the 350th anniversary in 2014, which gives 1664 <sup class="c" data-ref="ArraezAybar2015" title="Source 51"><a href="/stroke/sources/#src-ArraezAybar2015">51</a></sup>.`},
 {y:1689,c:'Cole writes "stroke"',sc:'word',w:'stroke',ws:'for apoplexy, in English',who:'William Cole',l:['The English word enters','medical writing.'],
  t:'1689 · The word stroke',txt:`William Cole first used "stroke" for apoplexy in English medical writing in 1689 <sup class="c" data-ref="Engelhardt2017" title="Source 280"><a href="/stroke/sources/#src-Engelhardt2017">280</a></sup>.`},
 {y:1761,c:'Morgagni: three apoplexies',sc:'three',who:'Morgagni',l:['Apoplexy is sorted by what','is found after death.'],
  t:'1761 · Three kinds',txt:`Morgagni separated "sanguineous", "serous" and "neither" apoplexy <sup class="c" data-ref="Engelhardt2017" title="Source 280"><a href="/stroke/sources/#src-Engelhardt2017">280</a></sup>.`},
 {y:1814,c:'Rochoux, Rostan: bleed or softening',sc:'two',who:'Rochoux (1814), Rostan (1819)',l:['Haemorrhage and softening:','the division still in use.'],
  t:'1814 and 1819 · Bleed or softening',txt:`Rochoux (1814) and Rostan (1819) defined haemorrhagic apoplexy and brain softening, the basic haemorrhagic and ischaemic division still used <sup class="c" data-ref="Engelhardt2017" title="Source 280"><a href="/stroke/sources/#src-Engelhardt2017">280</a></sup>.`,hook:`The blocked-or-burst split is about two centuries old <sup class="c" data-ref="Engelhardt2017" title="Source 280"><a href="/stroke/sources/#src-Engelhardt2017">280</a></sup>.`},
 {y:1838,c:'Dechambre: "lacune"',sc:'lacune',who:'Dechambre',l:['A word for small holes,','long before Fisher.'],
  t:'1838 · Lacune',txt:`Dechambre introduced the word "lacune" in 1838, well before Fisher <sup class="c" data-ref="Engelhardt2017" title="Source 280"><a href="/stroke/sources/#src-Engelhardt2017">280</a></sup>.`},
 {y:1852,c:'Virchow: thrombosis, embolism',sc:'virchow',who:'Rudolf Virchow',l:['A clot forms in place, or','travels and lodges.'],
  t:'1852 · Thrombosis and embolism',txt:`Rudolf Virchow created the terms "thrombosis" and "embolism" and described embolic "apoplexia ischaemica" <sup class="c" data-ref="Engelhardt2017,Bagot2008" title="Source 70,280"><a href="/stroke/sources/#src-Engelhardt2017">70,280</a></sup>. Review of the historical literature casts doubt on a triad described by Virchow in its usual form; he was routinely credited with it only 100 years after his work <sup class="c" data-ref="Bagot2008" title="Source 70"><a href="/stroke/sources/#src-Bagot2008">70</a></sup>.`},
 {y:1872,c:'Cohnheim: "infarct"',sc:'infarct',who:'Cohnheim',l:['Dead tissue beyond an','obstructed end artery.'],
  t:'1872 · Infarct',txt:`Cohnheim introduced "infarct" after embolic obstruction of end arteries <sup class="c" data-ref="Engelhardt2017" title="Source 280"><a href="/stroke/sources/#src-Engelhardt2017">280</a></sup>.`},
 {y:1927,c:'Moniz: first angiogram',sc:'moniz',who:'Egas Moniz',yt:'1927',l:['28 June 1927: arteries are','seen in a living person.'],
  t:'1927 · The first angiogram',txt:`Egas Moniz showed the first cerebral angiogram on 28 June 1927, of a pituitary tumour in a young man, and presented it in Paris on 7 July 1927. His 1949 Nobel Prize was for prefrontal leucotomy, now unacceptable, not for angiography <sup class="c" data-ref="Artico2017" title="Source 53"><a href="/stroke/sources/#src-Artico2017">53</a></sup>. He described the first carotid occlusion in 1936 <sup class="c" data-ref="Oliveira2018" title="Source 758"><a href="/stroke/sources/#src-Oliveira2018">758</a></sup>.`,hook:`Moniz's Nobel was for leucotomy, not angiography <sup class="c" data-ref="Artico2017" title="Source 53"><a href="/stroke/sources/#src-Artico2017">53</a></sup>.`},
 {y:1938,c:'"Apoplexy" leaves the death lists',sc:'strike',who:'International death lists',l:['Apoplexy leaves the lists at the','5th revision; stroke joins in ICD-9.'],
  t:'1938 · Apoplexy retires',txt:`"Apoplexy" left the international death lists from the 5th revision (1938). "Stroke" appeared in ICD-9 <sup class="c" data-ref="Engelhardt2017" title="Source 280"><a href="/stroke/sources/#src-Engelhardt2017">280</a></sup>.`},
 {y:1951,c:'Fisher: carotid occlusion',sc:'carotid',who:'Miller Fisher',l:['Carotid occlusion is described','thoroughly in English.'],
  t:'1951 · The neck artery',txt:`Carotid occlusions were thoroughly described in English only with Miller Fisher's 1951 paper <sup class="c" data-ref="Oliveira2018,Fisher1951" title="Source 315,758"><a href="/stroke/sources/#src-Oliveira2018">315,758</a></sup>. No abstract is indexed for the paper; this comes from the historical review.`},
 {y:1965,c:'Fisher: lacunes',sc:'lacune',who:'Fisher',l:['Small deep infarcts, linked to','penetrating artery disease.'],
  t:'1965 · Lacunes explained',txt:`Fisher's 1965 paper described lacunes as small deep cerebral infarcts <sup class="c" data-ref="Fisher1965" title="Source 316"><a href="/stroke/sources/#src-Fisher1965">316</a></sup>. Through serial sections at necropsy he linked them to penetrating artery disease, naming lipohyalinosis and fibrinoid degeneration; a 1968 Fisher paper is the cited source for these terms <sup class="c" data-ref="Caplan2015" title="Source 163"><a href="/stroke/sources/#src-Caplan2015">163</a></sup>.`},
 {y:1971,c:'First CT of a live patient',sc:'ct',who:'Ambrose, Hounsfield',l:['1 October 1971, Atkinson Morley','Hospital. The brain can be seen.'],
  t:'1971 · The first CT',txt:`The first CT scan of a live patient was on 1 October 1971 at Atkinson Morley Hospital, under James Ambrose, in a woman with a suspected frontal tumour, later a cystic astrocytoma. Godfrey Hounsfield of EMI built the system, and Allan Cormack, with earlier reconstruction work, shared the Nobel Prize with him <sup class="c" data-ref="Schulz2021" title="Source 905"><a href="/stroke/sources/#src-Schulz2021">905</a></sup>. One review says CT entered clinical practice in 1975 <sup class="c" data-ref="Artico2017" title="Source 53"><a href="/stroke/sources/#src-Artico2017">53</a></sup>. Also from 1971: the WHO's stroke registers and first definition <sup class="c" data-ref="Hatano1976,Engelhardt2017" title="Source 280,410"><a href="/stroke/sources/#src-Hatano1976">280,410</a></sup>.`},
 {y:1975,c:'Penumbra experiments',sc:'penumbra',who:'Lindsay Symon, Jens Astrup',l:['Two flow thresholds in baboon','cortex, and a word for the gap.'],
  t:'1975 · The penumbra',txt:`The penumbra was discovered in four experiments in September 1975, in Lindsay Symon's London laboratory, where Symon first said the word <sup class="c" data-ref="Astrup2025" title="Source 60"><a href="/stroke/sources/#src-Astrup2025">60</a></sup>. Astrup 1977, baboon cortex: electrical failure below about 15 ml/100 g per minute (about 35% of control), and massive potassium release at a lower flow, median 6 <sup class="c" data-ref="Astrup1977" title="Source 58"><a href="/stroke/sources/#src-Astrup1977">58</a></sup>. The perfusion range between the two is the penumbra <sup class="c" data-ref="Heiss2011" title="Source 418"><a href="/stroke/sources/#src-Heiss2011">418</a></sup>.`,
  pt:`Some brain tissue stops working before it dies. If blood comes back in time, it can recover <sup class="c" data-ref="Heiss2011" title="Source 418"><a href="/stroke/sources/#src-Heiss2011">418</a></sup>.`},
 {y:1981,c:'"Ischemic penumbra" in print',sc:'penumbra2',who:'Astrup, Siesjö, Symon',l:['The term is set out: tissue','that may still be saved.'],
  t:'1981 · The term in print',txt:`The term was set out in Astrup, Siesjö and Symon, 1981 <sup class="c" data-ref="Astrup1981" title="Source 59"><a href="/stroke/sources/#src-Astrup1981">59</a></sup>. Flow restored above the functional threshold can reverse deficits without permanent damage, and the lower the flow, the shorter the time for useful reperfusion <sup class="c" data-ref="Heiss2011" title="Source 418"><a href="/stroke/sources/#src-Heiss2011">418</a></sup>.`},
 {y:1993,c:'Stroke units save lives',sc:'unit',who:'Langhorne and colleagues',l:['10 trials overturn the view that','units do not affect mortality.'],
  t:'1993 · Do stroke units save lives?',txt:`Langhorne 1993 (10 trials, 1586 patients): odds of death within 4 months 0.72 (0.56-0.92), a 28% reduction. This overturned the view that units did not affect mortality <sup class="c" data-ref="Langhorne1993" title="Source 539"><a href="/stroke/sources/#src-Langhorne1993">539</a></sup>. Cochrane 2020 (29 trials, 5902 people): death OR 0.76 (0.66-0.88) at a median of 1 year, not dependent on age, sex, severity or stroke type <sup class="c" data-ref="Langhorne2020" title="Source 544"><a href="/stroke/sources/#src-Langhorne2020">544</a></sup>.`},
 {y:1995,c:'NINDS: t-PA within 3 hours',sc:'lysis',who:'NINDS rt-PA Stroke Study Group',l:['624 patients, global OR 1.7.','Dissolving the clot can work.'],
  t:'1995 · NINDS',txt:`The development of thrombolysis is traced to the 1930s <sup class="c" data-ref="Yilmaz2025" title="Source 1083"><a href="/stroke/sources/#src-Yilmaz2025">1083</a></sup>, and early trials were held back by high rates of ICH <sup class="c" data-ref="NINDS1995" title="Source 737"><a href="/stroke/sources/#src-NINDS1995">737</a></sup>. NINDS 1995 (624 patients, t-PA within 3 hours): global OR for favourable outcome 1.7 (1.2-2.6). Symptomatic ICH 6.4% against 0.6%; mortality at 3 months 17% against 21% (P=0.30) <sup class="c" data-ref="NINDS1995" title="Source 737"><a href="/stroke/sources/#src-NINDS1995">737</a></sup>. ECASS the same year (1.1 mg/kg, within 6 hours) showed no difference in its primary end points by intention to treat <sup class="c" data-ref="Hacke1995" title="Source 378"><a href="/stroke/sources/#src-Hacke1995">378</a></sup>.`,hook:`NINDS: symptomatic ICH 6.4% against 0.6%, no mortality penalty at 3 months <sup class="c" data-ref="NINDS1995" title="Source 737"><a href="/stroke/sources/#src-NINDS1995">737</a></sup>.`},
 {y:2006,c:'Time is brain, quantified',sc:'time',who:'Jeffrey Saver',l:['What each minute costs, in a','typical large vessel stroke.'],
  t:'2006 · Time is brain',txt:`"Time is brain" quantified: a typical large vessel stroke loses 1.9 million neurons, 14 billion synapses and 12 km of myelinated fibres each minute <sup class="c" data-ref="Saver2006" title="Source 892"><a href="/stroke/sources/#src-Saver2006">892</a></sup>.`},
 {y:2008,c:'ECASS III: to 4.5 hours',sc:'lysis',who:'Hacke and colleagues',l:['821 patients, 3 to 4.5 hours.','The window widens.'],
  t:'2008 · ECASS III',txt:`ECASS III (821 patients, 0.9 mg/kg, 3 to 4.5 hours): favourable outcome 52.4% against 45.2% (OR 1.34, 1.02-1.76), symptomatic ICH 2.4% against 0.2% <sup class="c" data-ref="Hacke2008" title="Source 380"><a href="/stroke/sources/#src-Hacke2008">380</a></sup>. A meta-analysis of 6756 patients later found the odds ratio falling with delay: 1.75 within 3 hours, 1.26 at 3 to 4.5 hours, 1.15 (0.95-1.40) beyond <sup class="c" data-ref="Emberson2014" title="Source 278"><a href="/stroke/sources/#src-Emberson2014">278</a></sup>.`},
 {y:2013,c:'Three neutral trials; a new definition',sc:'neutral',who:'IMS III, SYNTHESIS, MR RESCUE',l:['Three NEJM trials, no benefit.','Thrombectomy looks finished.'],
  t:'2013 · Three neutral trials',txt:`In 2013 three NEJM trials were neutral: IMS III (656 patients; 40.8% against 38.7%, stopped for futility) <sup class="c" data-ref="Broderick2013" title="Source 132"><a href="/stroke/sources/#src-Broderick2013">132</a></sup>, SYNTHESIS (362 patients; 30.4% against 34.8%) <sup class="c" data-ref="Ciccone2013" title="Source 189"><a href="/stroke/sources/#src-Ciccone2013">189</a></sup> and MR RESCUE (118 patients; mRS 3.9 against 3.9) <sup class="c" data-ref="Kidwell2013" title="Source 499"><a href="/stroke/sources/#src-Kidwell2013">499</a></sup>. The same year the AHA/ASA combined clinical and tissue criteria in a new definition of stroke <sup class="c" data-ref="Sacco2013" title="Source 875"><a href="/stroke/sources/#src-Sacco2013">875</a></sup>.`},
 {y:2015,c:'MR CLEAN and the wave',sc:'stent',who:'Berkhemer, Goyal, Campbell, Saver, Jovin',l:['Five trials, one answer: pulling','the clot out works.'],
  t:'2015 · The thrombectomy wave',txt:`MR CLEAN (500 patients, proximal anterior occlusion, within 6 hours): adjusted common OR 1.67 (1.21-2.30); functional independence 32.6% against 19.1%; retrievable stents in 81.5% of the intervention group <sup class="c" data-ref="Berkhemer2015" title="Source 97"><a href="/stroke/sources/#src-Berkhemer2015">97</a></sup>. ESCAPE, EXTEND IA, SWIFT PRIME and REVASCAT followed <sup class="c" data-ref="Goyal2015,Campbell2015,Saver2015,Jovin2015" title="Source 153,362,475,894"><a href="/stroke/sources/#src-Goyal2015">153,362,475,894</a></sup>.`,hook:`MR CLEAN absolute difference in independence: 13.5 percentage points <sup class="c" data-ref="Berkhemer2015" title="Source 97"><a href="/stroke/sources/#src-Berkhemer2015">97</a></sup>.`},
 {y:2016,c:'HERMES pools the five',sc:'hermes',who:'Goyal and colleagues',l:['1287 patients pooled. Benefit','with no heterogeneity by subgroup.'],
  t:'2016 · HERMES',txt:`HERMES pooled the five (1287 patients): adjusted common OR 2.49 (1.76-3.53), number needed to treat 2.6 to reduce disability by at least one mRS level. No heterogeneity across subgroups, including age 80 or over <sup class="c" data-ref="Goyal2016" title="Source 363"><a href="/stroke/sources/#src-Goyal2016">363</a></sup>.`,hook:`HERMES number needed to treat: 2.6 <sup class="c" data-ref="Goyal2016" title="Source 363"><a href="/stroke/sources/#src-Goyal2016">363</a></sup>.`},
 {y:2018,c:'DAWN and DEFUSE 3',sc:'late',who:'Nogueira, Albers',l:['Up to 24 hours, if the tissue','can still be saved.'],
  t:'2018 · From clock to tissue',txt:`DAWN (206 patients, 6 to 24 hours, clinical-core mismatch): functional independence 49% against 13% <sup class="c" data-ref="Nogueira2018" title="Source 740"><a href="/stroke/sources/#src-Nogueira2018">740</a></sup>. DEFUSE 3 (182 patients, 6 to 16 hours, perfusion selection): 45% against 17%, mortality 14% against 26% (P=0.05) <sup class="c" data-ref="Albers2018" title="Source 16"><a href="/stroke/sources/#src-Albers2018">16</a></sup>. These moved selection from clock time toward tissue, the clinical use of the penumbra idea <sup class="c" data-ref="Yilmaz2025,Heiss2011" title="Source 418,1083"><a href="/stroke/sources/#src-Yilmaz2025">418,1083</a></sup>.`},
 {y:2025,c:'Tenecteplase approved in the US',sc:'lysis',who:'FDA, as reported by Genentech',l:['4 March 2025, for acute ischaemic','stroke in adults, resting on AcT.'],
  t:'2025 · Tenecteplase',txt:`FDA approval of TNKase for acute ischaemic stroke in adults was reported on 4 March 2025, resting on AcT <sup class="c" data-ref="Genentech2025,FDA-TNKase" title="Source 297,348"><a href="/stroke/sources/#src-Genentech2025">297,348</a></sup>. In 2025 the medium-vessel trials ESCAPE-MeVO and DISTAL showed no gain from thrombectomy <sup class="c" data-ref="Goyal2025,Psychogios2025" title="Source 364,815"><a href="/stroke/sources/#src-Goyal2025">364,815</a></sup>. Astrup marked 50 years of the penumbra <sup class="c" data-ref="Astrup2025" title="Source 60"><a href="/stroke/sources/#src-Astrup2025">60</a></sup>.`},
 {y:2026,c:'New AHA/ASA guidelines',sc:'guide',who:'Prabhakaran; Richards; and colleagues',l:['Two guidelines replace their','predecessors in one year.'],
  t:'2026 · New guidelines',txt:`The 2026 AHA/ASA early-management guideline replaces the 2018 guideline and 2019 update <sup class="c" data-ref="Prabhakaran2026,Powers2019" title="Source 809,811"><a href="/stroke/sources/#src-Prabhakaran2026">809,811</a></sup>; a correction has been issued <sup class="c" data-ref="Prabhakaran2026Correction" title="Source 812"><a href="/stroke/sources/#src-Prabhakaran2026Correction">812</a></sup>. The 2026 rehabilitation guideline replaces the 2016 one <sup class="c" data-ref="Richards2026,Winstein2016" title="Source 843,1053"><a href="/stroke/sources/#src-Richards2026">843,1053</a></sup>. LATE-MT tested thrombectomy at 24 to 72 hours <span class="ev early">Early evidence</span> <sup class="c" data-ref="Yang2026" title="Source 1081"><a href="/stroke/sources/#src-Yang2026">1081</a></sup>, and OCEANIC-STROKE a factor XIa inhibitor for prevention <sup class="c" data-ref="Sharma2026" title="Source 916"><a href="/stroke/sources/#src-Sharma2026">916</a></sup>.`,
  pt:`Doctors once saw stroke as something they could do little about. Clot-busting drugs, stroke units and clot-removal procedures changed that <sup class="c" data-ref="NINDS1995,Langhorne2020,Goyal2016" title="Source 363,544,737"><a href="/stroke/sources/#src-NINDS1995">363,544,737</a></sup>.`}];
/* the stretched axis: year to 0..1 */
const HS_AX=[ [-600,0],[1600,.05],[1700,.17],[1900,.36],[1950,.46],[2000,.68],[2010,.76],[2020,.93],[2027,1] ];
function hsX(y){for(let i=1;i<HS_AX.length;i++){if(y<=HS_AX[i][0]){const a=HS_AX[i-1],b=HS_AX[i];return lerp(a[1],b[1],(y-a[0])/(b[0]-a[0]))}}return 1}
/* where a jump lands: most of the way through a milestone, so its drawing has finished building */
function hsLand(i){const a=hsX(HS_EV[i].y),b=HS_EV[i+1]?hsX(HS_EV[i+1].y):1;return a+(b-a)*.7}
const HS_ERAS=[{a:-600,b:1600,s:'',l:'Apoplexy'},{a:1600,b:1700,s:'17th',l:'17th c.'},{a:1700,b:1900,s:'18-19th',l:'18th-19th c.'},{a:1900,b:1950,s:'1900s',l:'1900-50'},{a:1950,b:2000,s:'1950-99',l:'1950-99'},{a:2000,b:2027,s:'2000s',l:'Since 2000'}];
const HS_STEPS=[{y:-500,t:'Apoplexy'},{y:1658,t:'Wepfer, Willis'},{y:1761,t:'Softening, thrombosis'},{y:1927,t:'Seeing the brain'},{y:1975,t:'The penumbra'},{y:1993,t:'Units and lysis'},{y:2013,t:'Thrombectomy'},{y:2025,t:'2025 and 2026'}].map(s=>({...s,from:hsX(s.y),at:hsLand(HS_EV.findIndex(e=>e.y===s.y))}));
HS_STEPS[0].from=0;
/* thrombectomy trials: control, thrombectomy */
const HS_TR=[
 {g:'13',n:'IMS III',d:'656 patients',c:38.7,x:40.8},{g:'13',n:'SYNTHESIS',d:'362 patients',c:34.8,x:30.4},
 {g:'15',n:'MR CLEAN',d:'500 patients',c:19.1,x:32.6},{g:'15',n:'ESCAPE',d:'316 patients',c:29.3,x:53},{g:'15',n:'EXTEND IA',d:'70 patients',c:40,x:71},{g:'15',n:'SWIFT PRIME',d:'196 patients',c:35,x:60},{g:'15',n:'REVASCAT',d:'206 patients',c:28.2,x:43.7},
 {g:'18',n:'DAWN',d:'206 patients',c:13,x:49},{g:'18',n:'DEFUSE 3',d:'182 patients',c:17,x:45}];
const HS_TRG=[['all','All'],['13','2013: neutral'],['15','2015: the wave'],['18','2018: late window']];
const HS_TRC={all:`Each row shows the main outcome as reported. For the 2015 and 2018 trials that is functional independence <sup class="c" data-ref="Berkhemer2015,Goyal2015,Campbell2015,Saver2015,Jovin2015,Nogueira2018,Albers2018" title="Source 16,97,153,362,475,740,894"><a href="/stroke/sources/#src-Berkhemer2015">16,97,153,362,475,740,894</a></sup>. For the 2013 trials it is the percentage each paper reports <sup class="c" data-ref="Broderick2013,Ciccone2013" title="Source 132,189"><a href="/stroke/sources/#src-Broderick2013">132,189</a></sup>, so compare within a row. MR RESCUE (118 patients) reported a mean mRS of 3.9 in both arms and is not plotted <sup class="c" data-ref="Kidwell2013" title="Source 499"><a href="/stroke/sources/#src-Kidwell2013">499</a></sup>.`,
 13:`IMS III was stopped for futility <sup class="c" data-ref="Broderick2013" title="Source 132"><a href="/stroke/sources/#src-Broderick2013">132</a></sup>. In SYNTHESIS the endovascular figure was lower than the comparison <sup class="c" data-ref="Ciccone2013" title="Source 189"><a href="/stroke/sources/#src-Ciccone2013">189</a></sup>. MR RESCUE (118 patients) reported a mean mRS of 3.9 in both arms and is not plotted <sup class="c" data-ref="Kidwell2013" title="Source 499"><a href="/stroke/sources/#src-Kidwell2013">499</a></sup>.`,
 15:`Functional independence. MR CLEAN used retrievable stents in 81.5% of its intervention group <sup class="c" data-ref="Berkhemer2015" title="Source 97"><a href="/stroke/sources/#src-Berkhemer2015">97</a></sup>. ESCAPE also found mortality 10.4% against 19.0% <sup class="c" data-ref="Goyal2015" title="Source 362"><a href="/stroke/sources/#src-Goyal2015">362</a></sup>. EXTEND IA <sup class="c" data-ref="Campbell2015" title="Source 153"><a href="/stroke/sources/#src-Campbell2015">153</a></sup>, SWIFT PRIME <sup class="c" data-ref="Saver2015" title="Source 894"><a href="/stroke/sources/#src-Saver2015">894</a></sup>, REVASCAT <sup class="c" data-ref="Jovin2015" title="Source 475"><a href="/stroke/sources/#src-Jovin2015">475</a></sup>.`,
 18:`Functional independence, late window. DAWN: 6 to 24 hours, clinical-core mismatch <sup class="c" data-ref="Nogueira2018" title="Source 740"><a href="/stroke/sources/#src-Nogueira2018">740</a></sup>. DEFUSE 3: 6 to 16 hours, perfusion selection, mortality 14% against 26% (P=0.05) <sup class="c" data-ref="Albers2018" title="Source 16"><a href="/stroke/sources/#src-Albers2018">16</a></sup>.`};
function hsTx(x,y,s,cls='t-xs',st=''){return `<text x="${f1(x)}" y="${f1(y)}" class="${cls}"${st?` style="${st}"`:''}>${s}</text>`}
const HS_INK='fill:var(--ink);font-weight:600';
/* a scene for one milestone, drawn in box B; u = progress through the milestone, ph = moving phase */
function hsScene(E,B,u,ph,N){const cx=B.x+B.w/2,cy=B.y+B.h/2,fit=(w,h)=>Math.min(B.w/w,B.h/h),ue=ease(clamp(u*1.4));
  const brain=o=>{const s=fit(300,250);return brainSide(cx-150*s,cy-125*s,s,o)};
  const ax=(o,k=1)=>{const s=fit(240,300)*k;return brainAxial(cx-120*s,cy-150*s,s,o)};
  switch(E.sc){
   case'word':{let s=brain({dim:.75}).svg;
     s+=`<text x="${f1(cx)}" y="${f1(cy+4)}" class="t-mid" style="font:italic 700 ${N?36:42}px var(--display);fill:var(--ink);paint-order:stroke;stroke:var(--panel);stroke-width:5px;stroke-linejoin:round">${E.w}</text>`;
     s+=kitLabel(cx,cy+28,E.ws,{a:'m'});return s}
   case'wepfer':{const A=ax({side:'L',bleed:{r:lerp(8,30,ue),oedema:ue*.5},sah:ue*.7,orient:true},.95);let s=A.svg;if(A.at.bleed)s+=kitLabel(A.at.bleed[0],A.at.bleed[1]+4,'cerebral',{a:'m'});s+=kitLabel(cx,B.y+B.h-1,'blood in tissue and over the surface',{a:'m'});return s}
   case'willis':{const k=fit(300,262)*.98;return willis(cx-150*k,cy-131*k,k,{flow:1,ph,labels:!N}).svg}
   case'three':{const R=[['sanguineous','bloody'],['serous','watery'],['neither','no fluid found']];const h=(B.h-24)/3;let s='';R.forEach((r,i)=>{const a=clamp(u*4-i*.8),y=B.y+i*(h+12);
       s+=`<g style="opacity:${f1(a)}"><rect x="${f1(B.x+10)}" y="${f1(y)}" width="${f1(B.w-20)}" height="${f1(h)}" rx="10" style="fill:var(--panel-2)"/>${hsTx(cx,y+h/2+1,r[0],'t-mid','font:italic 700 24px var(--display);fill:var(--ink)')}${hsTx(cx,y+h/2+20,i<2?r[1]:'neither of the two','t-sm t-mid')}</g>`});return s}
   case'two':{const k=fit(500,300)*.96,sa=k;let s=brainAxial(B.x,cy-150*sa,sa,{side:'L',bleed:{r:lerp(8,32,ue),oedema:ue*.4}}).svg;
     s+=brainAxial(B.x+B.w-240*sa,cy-150*sa,sa,{side:'L',core:ue*.7}).svg;
     s+=kitLabel(B.x+120*sa,cy+150*sa+14,'haemorrhagic apoplexy',{a:'m'})+kitLabel(B.x+B.w-120*sa,cy+150*sa+14,'softening',{a:'m'});return s}
   case'lacune':{const A=ax({},.98);let s=A.svg;const pts=[A.at.lentiform,A.at.capsule,A.at.thalamus,A.at.caudate];pts.forEach((p,i)=>{if(!p)return;const a=clamp(u*5-i),o=(i%2?-1:1)*3;s+=`<circle cx="${f1(p[0]+o)}" cy="${f1(p[1]+o)}" r="4" style="fill:var(--core);stroke:var(--panel);stroke-width:1;opacity:${f1(a)}"/>`});
     s+=kitLabel(cx,B.y+B.h-1,'small deep infarcts (dark dots)',{a:'m'});return s}
   case'virchow':{const h=N?46:54,y=cy-50,cl=ue;let s=artery(B.x+4,y,B.w-8,{h,flow:1-cl,ph,clot:cl,at:.56}).svg;
     s+=kitLabel(B.x+B.w*.56,y-10,'thrombosis: a clot forms in place',{a:'m'});
     const y2=cy+50,u2=ease(ramp(u,.25,.9));s+=artery(B.x+4,y2,B.w-8,{h,flow:1,ph}).svg+clot(lerp(B.x+30,B.x+B.w-40,u2),y2+h/2,h*.7,{}) ;
     s+=kitLabel(cx,y2+h+18,'embolism: a clot travels',{a:'m'});return s}
   case'infarct':{return brain({vessels:{occl:'sup',flow:.8,ph},lesion:{core:lerp(6,30,ue),penumbra:lerp(10,34,ue)},lobes:false}).svg}
   case'moniz':{let s=brain({vessels:{flow:ue,ph},dim:.4}).svg;s+=kitLabel(cx,B.y+B.h-1,'contrast shows the arteries',{a:'m'});return s}
   case'strike':{let s=`<text x="${f1(cx)}" y="${f1(cy-16)}" class="t-mid" style="font:italic 700 40px var(--display);fill:var(--muted)">apoplexy</text>`;const w=ue*(N?150:172);
     s+=`<line x1="${f1(cx-86)}" x2="${f1(cx-86+w)}" y1="${f1(cy-28)}" y2="${f1(cy-28)}" style="stroke:var(--bad);stroke-width:4;stroke-linecap:round"/>`;
     s+=`<text x="${f1(cx)}" y="${f1(cy+46)}" class="t-mid" style="font:italic 700 40px var(--display);fill:var(--ink);opacity:${f1(ramp(u,.4,.8))}">stroke</text>`;return s}
   case'carotid':{const k=fit(170,250)*.98;return carotidBif(cx-85*k,cy-125*k,k,{stenosis:lerp(.1,.9,ue),flow:1-ue*.6,ph,labels:!N}).svg}
   case'ct':{return ax({mode:'ct',orient:true},1).svg}
   case'penumbra':{const bx=B.x+6,bw=B.w-12,by=cy-20,h=26,mx=40,X=v=>bx+bw*v/mx;let s=hsTx(bx,by-44,'Blood flow, ml/100 g per minute (baboon cortex)','t-xs','fill:var(--ink)');
     s+=`<rect x="${f1(X(0))}" y="${by}" width="${f1(X(6)-X(0))}" height="${h}" style="fill:var(--core)"/><rect x="${f1(X(6))}" y="${by}" width="${f1(X(15)-X(6))}" height="${h}" style="fill:var(--penumbra)"/><rect x="${f1(X(15))}" y="${by}" width="${f1(X(40)-X(15))}" height="${h}" style="fill:var(--salvage)"/>`;
     s+=hsTx(X(6),by+h+16,'6','t-sm t-mid','fill:var(--ink);font-weight:700')+hsTx(X(15),by+h+16,'about 15','t-sm t-mid','fill:var(--ink);font-weight:700');
     s+=hsTx(bx,by-9,'K⁺ released','t-xs')+hsTx(X(10.5),by+h+36,'penumbra','t-sm t-mid','fill:var(--ink);font-weight:700')+hsTx(X(30),by-9,'cortex working','t-xs t-mid');
     const m=X(lerp(38,3,ue));s+=`<path d="M${f1(m-6)} ${by-3}h12l-6 7z" style="fill:var(--ink)"/>`;return s}
   case'penumbra2':{const A=ax({side:'L',core:.35,penumbra:.8,saved:0,labels:false},1);let s=A.svg;if(A.at.core)s+=kitLabel(A.at.core[0],A.at.core[1]+4,'core',{a:'m'});s+=kitLabel(cx,B.y+B.h-1,'amber rim: the penumbra',{a:'m'});return s}
   case'unit':{let s=hsTx(cx,cy-40,'28%','t-mid',`font:700 ${N?60:72}px var(--display);fill:var(--rec)`);s+=hsTx(cx,cy-8,'lower odds of death within 4 months','t-sm t-mid','fill:var(--ink)')+hsTx(cx,cy+10,'10 trials, 1586 patients','t-xs t-mid');
     const n=10,sz=N?19:22;for(let i=0;i<n;i++){const x=cx-(n*sz)/2+i*sz+sz/2,on=clamp(u*n*1.3-i);s+=`<rect x="${f1(x-sz*.4)}" y="${f1(cy+34)}" width="${f1(sz*.8)}" height="${f1(sz*.55)}" rx="3" style="fill:var(--rec);opacity:${f1(.2+.8*on)}"/>`}
     s+=hsTx(cx,cy+64+sz*.2,'one bar per trial','t-xs t-mid');return s}
   case'lysis':{const h=N?50:60;const A=artery(B.x+4,cy-h/2,B.w-8,{h,flow:ease(ramp(u,.3,1))*.9+.05,ph,clot:1,at:.56,lysis:ue});let s=A.svg;s+=kitLabel(cx,cy+h/2+22,ue<.5?'a clot blocks the artery':'the drug breaks the clot down',{a:'m'});return s}
   case'time':{const sz=N?44:52;let s=clock(B.x+sz+6,cy,sz,lerp(0,60,clamp(u)),{full:60,col:'var(--accent)'});const x=B.x+2*sz+22;
     const R=[['1.9 million','neurons'],['14 billion','synapses'],['12 km','myelinated fibres']];R.forEach((r,i)=>{const y=cy-48+i*44;s+=hsTx(x,y+6,r[0],'t-big')+hsTx(x,y+22,r[1],'t-xs')});
     s+=hsTx(cx,cy+sz+36,'lost per minute (schematic clock)','t-xs t-mid');return s}
   case'neutral':{const R=[['IMS III','40.8% against 38.7%'],['SYNTHESIS','30.4% against 34.8%'],['MR RESCUE','mRS 3.9 against 3.9']];const h=(B.h-24)/3;let s='';R.forEach((r,i)=>{const y=B.y+i*(h+12),a=clamp(u*4-i*.8);
       s+=`<g style="opacity:${f1(a)}"><rect x="${f1(B.x+6)}" y="${f1(y)}" width="${f1(B.w-12)}" height="${f1(h)}" rx="10" style="fill:var(--panel-2)"/>${hsTx(B.x+20,y+h/2-2,r[0],'t-lbl')}${hsTx(B.x+20,y+h/2+16,r[1],'t-sm')}</g>`});return s}
   case'stent':{const h=N?56:66;return catheterStent(B.x+4,cy-h/2,B.w-8,{h,deploy:ramp(u,0,.5),retract:ramp(u,.5,1),ph,labels:!N}).svg+kitLabel(cx,cy+h/2+24,u<.5?'the stent opens through the clot':'the clot comes back with it',{a:'m'})}
   case'hermes':{let s=hsTx(cx,cy-20,'2.6','t-mid',`font:700 ${N?70:84}px var(--display);fill:var(--brand)`);s+=hsTx(cx,cy+6,'people treated to reduce disability','t-sm t-mid','fill:var(--ink)')+hsTx(cx,cy+22,'by at least one mRS level in one of them','t-sm t-mid','fill:var(--ink)');
     s+=hsTx(cx,cy+50,'adjusted common OR 2.49 (1.76-3.53)','t-xs t-mid');return s}
   case'late':{const sv=ease(ramp(u,.3,1));let s=brain({vessels:{flow:sv,ph},lesion:{core:18,penumbra:50,saved:sv}}).svg;s+=kitLabel(cx,B.y+B.h-1,'small core, large area still saved (schematic)',{a:'m'});return s}
   case'guide':{const R=[['Early management','replaces 2018 and 2019'],['Rehabilitation','replaces 2016']];let s='';R.forEach((r,i)=>{const a=clamp(u*3-i*.8),y=B.y+18+i*(N?106:130),h=N?92:112;
       s+=`<g style="opacity:${f1(a)}"><rect x="${f1(B.x+18)}" y="${f1(y)}" width="${f1(B.w-36)}" height="${h}" rx="8" style="fill:var(--panel-2);stroke:var(--line)"/>${hsTx(B.x+34,y+26,'2026 AHA/ASA','t-xs')}${hsTx(B.x+34,y+50,r[0],'t-big')}${hsTx(B.x+34,y+70,r[1],'t-sm')}</g>`});return s}
   default:return ''}}
inits.history=()=>{
  const svg=$('#hiSvg'),rg=$('#hiT'),note=$('#hiNote'),chips=$('#hiYears');let setSt=()=>{};
  chips.innerHTML=HS_EV.map((E,i)=>`<button class="tag" data-hy="${i}" aria-pressed="false"><small>${E.yt||E.y}</small>${E.c}</button>`).join('');
  const POS=HS_EV.map(E=>hsX(E.y));
  function evOf(t){let e=0;POS.forEach((p,i)=>{if(t>=p-.0005)e=i});return e}
  function draw(t){const N=vb(svg,'720 430','400 525'),e=evOf(t),E=HS_EV[e];
    const A=N?{x:16,w:368,y:44}:{x:18,w:684,y:44},B=N?{x:30,y:88,w:340,h:300}:{x:18,y:96,w:360,h:310},P=N?{x:16,y:440}:{x:408,y:150};
    const X=v=>A.x+A.w*v;
    let s='';
    /* era bands */
    HS_ERAS.forEach((r,i)=>{const a=X(hsX(r.a)),b=X(hsX(r.b)),on=E.y>=r.a&&E.y<r.b;
      s+=`<rect x="${f1(a+1)}" y="${A.y-22}" width="${f1(b-a-2)}" height="18" rx="4" style="fill:var(--${on?'brand-soft':'panel-2'})"/>`;
      const lab=N?r.s:r.l;if(lab&&b-a>lab.length*5.6)s+=hsTx((a+b)/2,A.y-9,lab,'t-xs t-mid',on?HS_INK:'')});
    s+=`<line x1="${A.x}" x2="${A.x+A.w}" y1="${A.y+8}" y2="${A.y+8}" class="axis"/>`;
    POS.forEach((p,i)=>{const x=X(p),on=i===e,past=i<e;s+=`<circle cx="${f1(x)}" cy="${A.y+8}" r="${on?6:3}" style="fill:${on?'var(--brand)':past?'var(--ink)':'var(--line)'}"/>`});
    s+=`<path d="M${f1(X(t)-5)} ${A.y+24}h10l-5 -8z" style="fill:var(--muted)"/>`;
    /* the milestone */
    const u=clamp((t-POS[e])/Math.max(.01,(POS[e+1]||1)-POS[e])),fd=clamp(u*14+.5);
    s+=`<g style="opacity:${f1(fd)}">${hsScene(E,B,u,t*90,N)}</g>`;
    s+=hsTx(P.x,P.y,E.yt||String(E.y),'',`font:700 ${N?40:52}px var(--display);fill:var(--brand);letter-spacing:-.02em`);
    s+=hsTx(P.x,P.y+(N?24:30),E.who,'t-lbl');
    E.l.forEach((q,i)=>{s+=hsTx(P.x,P.y+(N?46:58)+i*(N?18:20),q,N?'t-sm':'t-sm','fill:var(--ink)')});
    svg.innerHTML=s;note.innerHTML=noteHTML(E);setSt(phaseOf(HS_STEPS,t));
    $$('[data-hy]',chips).forEach(b=>b.setAttribute('aria-pressed',+b.dataset.hy===e))}
  const stop=playWire(rg,$('#hiPlay'),draw,48000,'Replay','history');
  setSt=stepWire($('#hiSteps'),HS_STEPS,rg,draw,stop);
  chips.addEventListener('click',e=>{const b=e.target.closest('[data-hy]');if(!b)return;stop();const v=hsLand(+b.dataset.hy);rg.value=v;draw(v);svg.scrollIntoView({block:'center',behavior:RM?'auto':'smooth'})});
  draw(+rg.value);

  /* ---------- the trials ---------- */
  const tS=$('#hiTr'),tC=$('#hiTrCap'),tB=$('#hiTrBtns');let tg='all',tP=1,tStop=null;
  tB.innerHTML=HS_TRG.map(g=>`<button class="btn" data-htr="${g[0]}" aria-pressed="${g[0]==='all'}">${g[1]}</button>`).join('');
  function drawTr(){const N=vb(tS,'720 430','400 640');
    const L=N?{lx:14,bx:22,bw:340,y0:48,rh:62}:{lx:16,bx:190,bw:470,y0:50,rh:38},X=v=>L.bx+L.bw*v/80;
    let s='';[0,20,40,60,80].forEach(v=>{const bot=L.y0+HS_TR.length*L.rh+(N?0:14);s+=`<line x1="${f1(X(v))}" x2="${f1(X(v))}" y1="${L.y0-14}" y2="${bot}" class="grid"/>`+hsTx(X(v),L.y0-20,v+'%','t-xs t-mid')});
    s+=hsTx(L.lx,16,'% with the main outcome, control to thrombectomy','t-sm','fill:var(--ink)');
    let gy=0;const gl={13:'2013',15:'2015',18:'2018'};
    HS_TR.forEach((T,i)=>{const on=tg==='all'||tg===T.g,y=L.y0+i*L.rh+(N?22:gy),op=on?1:.22,xc=X(T.c),xt=X(lerp(T.c,T.x,on?ease(tP):1)),better=T.x>T.c;
      s+=`<g style="opacity:${op}">`;
      if(N)s+=hsTx(L.lx,y-10,gl[T.g]+' · '+T.n+', '+T.d,'t-xs','fill:var(--ink);font-weight:600');
      else s+=hsTx(L.lx,y+1,gl[T.g]+' · '+T.n,'t-sm','fill:var(--ink);font-weight:600')+hsTx(L.lx,y+13,T.d,'t-xs');
      s+=`<line x1="${f1(xc)}" x2="${f1(xt)}" y1="${y}" y2="${y}" style="stroke:${better?'var(--brand)':'var(--muted)'};stroke-width:4"/>`;
      s+=`<circle cx="${f1(xc)}" cy="${y}" r="6" style="fill:var(--panel);stroke:var(--muted);stroke-width:2.4"/>`;
      s+=`<rect x="${f1(xt-6)}" y="${y-6}" width="12" height="12" rx="2" style="fill:var(--brand);stroke:var(--panel);stroke-width:1.5"/>`;
      const close=Math.abs(xt-xc)<52,lo=Math.min(T.c,T.x),hi=Math.max(T.c,T.x),lx=X(lo)-10,rx=X(hi)+10;
      s+=hsTx(T.x>T.c?lx:rx,y+4,T.c+'%',T.x>T.c?'t-sm t-end':'t-sm','fill:var(--muted)')+hsTx(T.x>T.c?rx:lx,y+4,T.x+'%',T.x>T.c?'t-sm':'t-sm t-end','fill:var(--ink);font-weight:700');
      s+='</g>'});
    const ky=N?622:L.y0+HS_TR.length*L.rh+26;
    s+=`<circle cx="${L.lx+6}" cy="${ky-3}" r="5" style="fill:var(--panel);stroke:var(--muted);stroke-width:2.2"/>`+hsTx(L.lx+18,ky,'control','t-xs','fill:var(--ink)');
    s+=`<rect x="${L.lx+78}" y="${ky-8}" width="10" height="10" rx="2" style="fill:var(--brand)"/>`+hsTx(L.lx+94,ky,'thrombectomy arm','t-xs','fill:var(--ink)');
    tS.innerHTML=s;tC.innerHTML=HS_TRC[tg]}
  tB.addEventListener('click',e=>{const b=e.target.closest('[data-htr]');if(!b)return;tg=b.dataset.htr;$$('[data-htr]').forEach(x=>x.setAttribute('aria-pressed',x===b));if(tStop)tStop();tP=.05;drawTr();tStop=animate(RM?1:800,q=>{tP=q;drawTr()},()=>{tStop=null;tP=1;drawTr()})});
  drawTr();
  const prevR=redraws.history;redraws.history=()=>{prevR&&prevR();drawTr()};
};
/* =============== 6.2 flashcards & mnemonics =============== */
/* part names come from GROUPS in 01-config.js */
const STRV_PARTN=Object.fromEntries(Object.entries(GROUPS).map(([k,v])=>[k,`Part ${k} · ${v[0]}`]));
const STRV_FC=[
 /* ---- Part 1: what, vessels, cascade, causes, bleeds, tia ---- */
 [1,`How does the classic WHO definition describe a stroke?`,`A focal (or global) deficit lasting more than 24 hours or leading to death, with no apparent cause other than a vascular one <sup class="c" data-ref="Engelhardt2017" title="Source 280"><a href="/stroke/sources/#src-Engelhardt2017">280</a></sup>.`],
 [1,`What did the AHA/ASA 2013 definition add?`,`Imaging or pathology evidence of infarction counts, even if symptoms are brief. Silent infarction has no known symptoms <sup class="c" data-ref="Sacco2013" title="Source 875"><a href="/stroke/sources/#src-Sacco2013">875</a></sup>.`],
 [1,`What are the global shares of the three stroke types?`,`GBD 2021: ischaemic 65.3%, intracerebral haemorrhage 28.8%, subarachnoid haemorrhage 5.8% <sup class="c" data-ref="Feigin2024" title="Source 305"><a href="/stroke/sources/#src-Feigin2024">305</a></sup>.`],
 [1,`What is the worldwide burden of stroke in GBD 2021?`,`11.9 million new strokes, 93.8 million people living after stroke, 7.3 million deaths and 160.5 million DALYs <sup class="c" data-ref="Feigin2024" title="Source 305"><a href="/stroke/sources/#src-Feigin2024">305</a></sup>.`],
 [1,`What is the lifetime risk of stroke from age 25?`,`About 25%, or 1 in 4 <sup class="c" data-ref="Feigin2018" title="Source 301"><a href="/stroke/sources/#src-Feigin2018">301</a></sup>. This is a population figure.`],
 [1,`What does "counts up, rates down" mean?`,`From 1990 to 2021, new strokes rose 70.2% while age-standardised incidence fell 21.8% <sup class="c" data-ref="Feigin2024" title="Source 305"><a href="/stroke/sources/#src-Feigin2024">305</a></sup>.`],
 [1,`Which single risk factor carries the largest share of stroke DALYs?`,`High systolic blood pressure, 56.8% <sup class="c" data-ref="Feigin2025" title="Source 306"><a href="/stroke/sources/#src-Feigin2025">306</a></sup>.`],
 [1,`How often does stroke recur over time?`,`Pooled: 11.1% at 1 year, 26.4% at 5 years, 39.2% at 10 years <sup class="c" data-ref="Mohan2011" title="Source 682"><a href="/stroke/sources/#src-Mohan2011">682</a></sup>.`],
 [1,`How complete is the circle of Willis in a general population?`,`Complete in only 11.9% of the Tromso population sample on 3T MR angiography <sup class="c" data-ref="Hindenes2020" title="Source 430"><a href="/stroke/sources/#src-Hindenes2020">430</a></sup>.`],
 [1,`Leg-predominant weakness with abulia points to which artery?`,`The anterior cerebral artery <sup class="c" data-ref="Stebner2025" title="Source 937"><a href="/stroke/sources/#src-Stebner2025">937</a></sup>.`],
 [1,`What does an entire MCA syndrome include?`,`Contralateral gaze palsy, hemiplegia, hemisensory loss, neglect and hemianopsia, with global aphasia if on the left <sup class="c" data-ref="Lo2025" title="Source 594"><a href="/stroke/sources/#src-Lo2025">594</a></sup>.`],
 [1,`What signs define Wallenberg syndrome?`,`Ipsilateral face and contralateral body loss of pain and temperature sense, with ipsilateral Horner syndrome <sup class="c" data-ref="Lo2025" title="Source 594"><a href="/stroke/sources/#src-Lo2025">594</a></sup>.`],
 [1,`Name the five classic lacunar syndromes.`,`Pure motor, pure sensory, sensorimotor, ataxic hemiparesis and dysarthria-clumsy hand <sup class="c" data-ref="Arboix2009" title="Source 47"><a href="/stroke/sources/#src-Arboix2009">47</a></sup>.`],
 [1,`What are the Oxfordshire shares?`,`Of infarcts in the original project: TACI 17%, PACI 34%, POCI 24%, LACI 25% <sup class="c" data-ref="Bamford1991" title="Source 78"><a href="/stroke/sources/#src-Bamford1991">78</a></sup>.`],
 [1,`What is spared in locked-in syndrome?`,`Vertical eye movement and blinking <sup class="c" data-ref="Das2023" title="Source 214"><a href="/stroke/sources/#src-Das2023">214</a></sup>.`],
 [1,`How much is lost each minute in a large-vessel stroke, by Saver's estimate?`,`1.9 million neurons, 14 billion synapses and 12 km of myelinated fibres <sup class="c" data-ref="Saver2006" title="Source 892"><a href="/stroke/sources/#src-Saver2006">892</a></sup>.`],
 [1,`What are the key blood-flow numbers?`,`Normal flow is about 50-60 mL/100 g/min. Below 10-20 mL/100 g/min is the injury zone <sup class="c" data-ref="Mangiardi2023" title="Source 629"><a href="/stroke/sources/#src-Mangiardi2023">629</a></sup>.`],
 [1,`What is the ischaemic penumbra?`,`Tissue in the perfusion range between two flow thresholds. Flow restored above the functional threshold can reverse deficits without permanent damage <sup class="c" data-ref="Heiss2011" title="Source 418"><a href="/stroke/sources/#src-Heiss2011">418</a></sup>.`],
 [1,`How fast do SELECT slow progressors grow?`,`Under 10 mL per hour <sup class="c" data-ref="Sarraj2021" title="Source 885"><a href="/stroke/sources/#src-Sarraj2021">885</a></sup>. Collaterals matter: growth was 52.3 cm3 with poor and 0.9 cm3 with good collaterals in one series <sup class="c" data-ref="Vagal2018" title="Source 993"><a href="/stroke/sources/#src-Vagal2018">993</a></sup>.`],
 [1,`When is the delayed opening of the blood-brain barrier?`,`At 24-72 hours, after a reversible early opening <sup class="c" data-ref="Yang2011" title="Source 1076"><a href="/stroke/sources/#src-Yang2011">1076</a></sup>.`],
 [1,`What are the five TOAST subtypes?`,`Large-artery atherosclerosis, cardioembolism, small-vessel occlusion, other determined and undetermined cause <sup class="c" data-ref="Adams1993" title="Source 4"><a href="/stroke/sources/#src-Adams1993">4</a></sup>. Large-artery needs over 50% stenosis <sup class="c" data-ref="Kim2014" title="Source 501"><a href="/stroke/sources/#src-Kim2014">501</a></sup>.`],
 [1,`What is ESUS?`,`A non-lacunar infarct with no proximal stenosis or cardioembolic source <sup class="c" data-ref="Hart2014" title="Source 405"><a href="/stroke/sources/#src-Hart2014">405</a></sup>. Three anticoagulant trials against aspirin were neutral <sup class="c" data-ref="Hart2018,Diener2019,Kamel2024" title="Source 242,407,484"><a href="/stroke/sources/#src-Hart2018">242,407,484</a></sup>.`],
 [1,`How much AF did long-term monitoring find in CRYSTAL AF?`,`12.4% at 12 months and 30.0% at 36 months <sup class="c" data-ref="Sanna2014,Brachmann2016" title="Source 122,884"><a href="/stroke/sources/#src-Sanna2014">122,884</a></sup>.`],
 [1,`What does SMASH-U classify, and what are the shares?`,`The cause of ICH: hypertensive angiopathy 35%, undetermined 21%, amyloid 20%, anticoagulation 14%, structural 5%, systemic disease 5% <sup class="c" data-ref="Meretoja2012" title="Source 664"><a href="/stroke/sources/#src-Meretoja2012">664</a></sup>.`],
 [1,`What does the location of an ICH suggest?`,`Deep bleeds point to hypertensive disease, and lobar bleeds to cerebral amyloid angiopathy <sup class="c" data-ref="Magid2022,An2017" title="Source 37,621"><a href="/stroke/sources/#src-Magid2022">37,621</a></sup>.`],
 [1,`How good is the CT angiography spot sign at predicting expansion?`,`Specificity 85%, sensitivity 51% <sup class="c" data-ref="Demchuk2012" title="Source 228"><a href="/stroke/sources/#src-Demchuk2012">228</a></sup>.`],
 [1,`What do the Ottawa SAH Rule's numbers show?`,`Six items, sensitivity 100% in derivation, specificity about 15% <sup class="c" data-ref="Perry2013" title="Source 786"><a href="/stroke/sources/#src-Perry2013">786</a></sup>.`],
 [1,`Why does the 6-hour mark matter for CT in suspected SAH?`,`Within 6 hours sensitivity was 100%, on a modern scanner read by a qualified radiologist <sup class="c" data-ref="Perry2011" title="Source 785"><a href="/stroke/sources/#src-Perry2011">785</a></sup>.`],
 [1,`What is the tissue definition of TIA?`,`A transient episode of focal neurological dysfunction from ischaemia, without acute infarction <sup class="c" data-ref="Easton2009" title="Source 265"><a href="/stroke/sources/#src-Easton2009">265</a></sup>.`],
 [1,`What 2-day stroke risk went with an ABCD2 score of 6-7?`,`8.1%, against 4.1% at 4-5 and 1.0% at 0-3 <sup class="c" data-ref="Johnston2007" title="Source 465"><a href="/stroke/sources/#src-Johnston2007">465</a></sup>.`],
 [1,`What did EXPRESS show about urgent TIA care?`,`90-day stroke fell from 10.3% to 2.1% <sup class="c" data-ref="Rothwell2007" title="Source 862"><a href="/stroke/sources/#src-Rothwell2007">862</a></sup>.`],
 [1,`What does NICE say about ABCD2?`,`Do not use it to decide urgency <sup class="c" data-ref="NICE-NG128" title="Source 733"><a href="/stroke/sources/#src-NICE-NG128">733</a></sup>.`],

 /* ---- Part 2: signs, imaging, nihss ---- */
 [2,`What did adding balance and eyes do in the BE-FAST study?`,`Missed ischaemic strokes fell from 14.1% to 4.4%. The study was retrospective and could not measure specificity <sup class="c" data-ref="Aroor2017" title="Source 50"><a href="/stroke/sources/#src-Aroor2017">50</a></sup>.`],
 [2,`What share of haemorrhages does FAST miss?`,`About 30.6% <sup class="c" data-ref="Kleindorfer2007" title="Source 508"><a href="/stroke/sources/#src-Kleindorfer2007">508</a></sup>.`],
 [2,`What are the items of the Cincinnati scale (CPSS)?`,`Arm, speech and face <sup class="c" data-ref="Kothari1999" title="Source 514"><a href="/stroke/sources/#src-Kothari1999">514</a></sup>.`],
 [2,`What are the published LVO thresholds for RACE and LAMS?`,`RACE 5 or more and LAMS 4 or more <sup class="c" data-ref="PerezDeLaOssa2014,Nazliel2008" title="Source 708,784"><a href="/stroke/sources/#src-PerezDeLaOssa2014">708,784</a></sup>. No clinical scale reliably gives both high sensitivity and high specificity <sup class="c" data-ref="Smith2018" title="Source 929"><a href="/stroke/sources/#src-Smith2018">929</a></sup>.`],
 [2,`How often are cerebrovascular events missed at the first emergency visit?`,`Roughly 9%, with a false-negative rate of 39.4% when the complaint is dizziness <sup class="c" data-ref="Tarnutzer2017" title="Source 963"><a href="/stroke/sources/#src-Tarnutzer2017">963</a></sup>.`],
 [2,`Is posterior stroke misdiagnosed more often than anterior?`,`About twice as often: 37% against 16% <sup class="c" data-ref="Arch2016" title="Source 48"><a href="/stroke/sources/#src-Arch2016">48</a></sup>.`],
 [2,`How common are stroke mimics?`,`About 30% of people seen by a stroke team <sup class="c" data-ref="Merino2013" title="Source 670"><a href="/stroke/sources/#src-Merino2013">670</a></sup>. The most frequent are seizure, syncope, sepsis, migraine and brain tumours <sup class="c" data-ref="Gibson2013" title="Source 352"><a href="/stroke/sources/#src-Gibson2013">352</a></sup>.`],
 [2,`What is the risk of symptomatic haemorrhage if a mimic is thrombolysed?`,`About 0.5 to 1% <sup class="c" data-ref="Tsivgoulis2015,Zinkstok2013" title="Source 985,1098"><a href="/stroke/sources/#src-Tsivgoulis2015">985,1098</a></sup>.`],
 [2,`How sensitive is CT against MRI for acute stroke?`,`26% against 83% for any acute stroke <sup class="c" data-ref="Chalela2007" title="Source 172"><a href="/stroke/sources/#src-Chalela2007">172</a></sup>. CT reached 41.8% in the posterior fossa <sup class="c" data-ref="Hwang2012" title="Source 452"><a href="/stroke/sources/#src-Hwang2012">452</a></sup>.`],
 [2,`How does ASPECTS score?`,`10 regions, 10 is normal, subtract 1 per region with early ischaemic change. Poor outcome rises sharply at 7 or less <sup class="c" data-ref="Pexman2001" title="Source 791"><a href="/stroke/sources/#src-Pexman2001">791</a></sup>.`],
 [2,`What were the DEFUSE 3 imaging criteria?`,`Core below 70 mL, mismatch ratio of 1.8 or more and penumbra of 15 mL or more, at 6 to 16 hours <sup class="c" data-ref="Albers2018" title="Source 16"><a href="/stroke/sources/#src-Albers2018">16</a></sup>.`],
 [2,`What does a DWI-positive, FLAIR-negative lesion suggest?`,`Onset within about 4.5 hours <sup class="c" data-ref="Thomalla2011,Thomalla2018" title="Source 974,975"><a href="/stroke/sources/#src-Thomalla2011">974,975</a></sup>.`],
 [2,`What was the Helsinki principle, and what did it reach?`,`Do as much as possible before arrival. Median door-to-needle fell from 105 minutes in 1998 to 20 in 2011 <sup class="c" data-ref="Meretoja2012D" title="Source 665"><a href="/stroke/sources/#src-Meretoja2012D">665</a></sup>.`],
 [2,`What is the structure of the NIHSS?`,`15 elements and a maximum of 42 <sup class="c" data-ref="Budincevic2022" title="Source 146"><a href="/stroke/sources/#src-Budincevic2022">146</a></sup>.`],
 [2,`What are the two named weaknesses of the NIHSS?`,`Left hemisphere bias and poor capture of posterior strokes <sup class="c" data-ref="Woo1999,Sato2008" title="Source 889,1062"><a href="/stroke/sources/#src-Woo1999">889,1062</a></sup>.`],
 [2,`What did NIHSS scores forecast in TOAST?`,`16 or more forecast death or severe disability, and 6 or less forecast good recovery <sup class="c" data-ref="Adams1999" title="Source 6"><a href="/stroke/sources/#src-Adams1999">6</a></sup>.`],
 [2,`What separates mRS 3 from mRS 4?`,`Grade 3 walks without assistance, with some help. Grade 4 cannot walk without assistance. Grade 6 is death <sup class="c" data-ref="Luo2026" title="Source 603"><a href="/stroke/sources/#src-Luo2026">603</a></sup>.`],

 /* ---- Part 3: lysis, evt, ich, sah, unit ---- */
 [3,`What is the published alteplase dose for stroke?`,`0.9 mg/kg, maximum 90 mg, 10% as a bolus over 1 minute and the rest over 60 minutes <sup class="c" data-ref="FDA-Activase" title="Source 293"><a href="/stroke/sources/#src-FDA-Activase">293</a></sup>.`],
 [3,`What is the published tenecteplase stroke dose?`,`0.25 mg/kg, maximum 25 mg, single bolus <sup class="c" data-ref="Menon2022,FDA-TNKase" title="Source 297,662"><a href="/stroke/sources/#src-Menon2022">297,662</a></sup>. 0.40 mg/kg gave no reperfusion gain <sup class="c" data-ref="Campbell2020JAMA" title="Source 159"><a href="/stroke/sources/#src-Campbell2020JAMA">159</a></sup>.`],
 [3,`What did NINDS show for symptomatic ICH and mortality?`,`Symptomatic ICH 6.4% against 0.6%, with 3-month mortality 17% against 21% <sup class="c" data-ref="NINDS1995" title="Source 737"><a href="/stroke/sources/#src-NINDS1995">737</a></sup>.`],
 [3,`How does time change alteplase benefit?`,`mRS 0-1 was 32.9% against 23.1% within 3 hours and 35.3% against 30.1% from 3 to 4.5 hours <sup class="c" data-ref="Emberson2014" title="Source 278"><a href="/stroke/sources/#src-Emberson2014">278</a></sup>.`],
 [3,`Do lytics help non-disabling minor stroke?`,`PRISMS, ARAMIS and TEMPO-2 did not show benefit <sup class="c" data-ref="Khatri2018,Chen2023,Coutts2024" title="Source 181,204,496"><a href="/stroke/sources/#src-Khatri2018">181,204,496</a></sup>.`],
 [3,`What drug history predicts angio-oedema with alteplase?`,`Prior ACE inhibitor use (OR 2.3) <sup class="c" data-ref="Hurford2015" title="Source 451"><a href="/stroke/sources/#src-Hurford2015">451</a></sup>.`],
 [3,`What did the ESO set as blood pressure thresholds around lysis?`,`Below 185/110 before, and below 180/105 during and for 24 hours after <sup class="c" data-ref="Sandset2026" title="Source 883"><a href="/stroke/sources/#src-Sandset2026">883</a></sup>.`],
 [3,`What is the HERMES headline?`,`Five trials, 1287 patients, common OR 2.49, and a number needed to treat of 2.6 for at least one mRS level better <sup class="c" data-ref="Goyal2016" title="Source 363"><a href="/stroke/sources/#src-Goyal2016">363</a></sup>.`],
 [3,`How do DAWN and DEFUSE 3 select people?`,`DAWN: clinical-core mismatch at 6 to 24 hours. DEFUSE 3: perfusion mismatch at 6 to 16 hours <sup class="c" data-ref="Nogueira2018,Albers2018" title="Source 16,740"><a href="/stroke/sources/#src-Nogueira2018">16,740</a></sup>.`],
 [3,`What does each hour of delay cost in thrombectomy?`,`Functional independence falls 5.2 percentage points <sup class="c" data-ref="Saver2016" title="Source 895"><a href="/stroke/sources/#src-Saver2016">895</a></sup>.`],
 [3,`What did basilar trials count as a good outcome, and what did ATTENTION find?`,`mRS 0-3: 46% against 23%, with mortality 37% against 55% <sup class="c" data-ref="Tao2022" title="Source 961"><a href="/stroke/sources/#src-Tao2022">961</a></sup>.`],
 [3,`Did thrombectomy help medium-vessel occlusion?`,`ESCAPE-MeVO and DISTAL were neutral on function <sup class="c" data-ref="Goyal2025,Psychogios2025" title="Source 364,815"><a href="/stroke/sources/#src-Goyal2025">364,815</a></sup>.`],
 [3,`Why not push systolic pressure below 140 after thrombectomy?`,`In OPTIMAL-BP it reduced functional independence (39.4% against 54.4%), and the ESO recommends against it <sup class="c" data-ref="Nam2023,Sandset2026" title="Source 703,883"><a href="/stroke/sources/#src-Nam2023">703,883</a></sup>.`],
 [3,`What goes into the ICH score?`,`GCS (0 to 2), age 80 or over, infratentorial origin, volume 30 cm3 or more, and intraventricular blood <sup class="c" data-ref="Hemphill2001" title="Source 422"><a href="/stroke/sources/#src-Hemphill2001">422</a></sup>.`],
 [3,`What does AHA/ASA 2022 say about systolic pressure below 130 in ICH?`,`It calls this potentially harmful in mild to moderate ICH <sup class="c" data-ref="Greenberg2022" title="Source 369"><a href="/stroke/sources/#src-Greenberg2022">369</a></sup>.`],
 [3,`What reverses warfarin best in ICH?`,`Four-factor PCC beat FFP for INR correction: INR 1.2 or lower within 3 hours in 67% against 9% (INCH) <sup class="c" data-ref="Steiner2016" title="Source 940"><a href="/stroke/sources/#src-Steiner2016">940</a></sup>.`],
 [3,`What is the story of factor VIIa in ICH?`,`It slowed haematoma growth without improving function, in FAST and FASTEST <sup class="c" data-ref="Mayer2008,Broderick2026" title="Source 133,642"><a href="/stroke/sources/#src-Mayer2008">133,642</a></sup>.`],
 [3,`When is cerebellar ICH a Class 1 indication for surgery?`,`At 15 mL or more, or with brainstem compression or hydrocephalus, in AHA/ASA 2022 <sup class="c" data-ref="Greenberg2022" title="Source 369"><a href="/stroke/sources/#src-Greenberg2022">369</a></sup>.`],
 [3,`What nimodipine regimen did BRANT use?`,`60 mg orally every 4 hours for 21 days. Capsules are never given intravenously <sup class="c" data-ref="Pickard1989,FDA-Nimodipine" title="Source 295,796"><a href="/stroke/sources/#src-Pickard1989">295,796</a></sup>.`],
 [3,`When does delayed cerebral ischaemia happen?`,`Mostly days 4 to 14, with a peak at days 6 to 10 <sup class="c" data-ref="Hoh2023" title="Source 432"><a href="/stroke/sources/#src-Hoh2023">432</a></sup>.`],
 [3,`What did ISAT show?`,`About 7% less death or dependence at 1 year with coiling, and more late rebleeding <sup class="c" data-ref="Molyneux2005" title="Source 685"><a href="/stroke/sources/#src-Molyneux2005">685</a></sup>.`],
 [3,`How much difference does a stroke unit make?`,`For every 100 people treated: 2 more survive, 6 more live at home, 6 more live independently <sup class="c" data-ref="Langhorne2020" title="Source 544"><a href="/stroke/sources/#src-Langhorne2020">544</a></sup>.`],
 [3,`What is FeSS, and what did QASC find?`,`Nurse-initiated protocols for Fever, Sugar and Swallow, with a number needed to treat of 6.4 for death or dependency at 90 days <sup class="c" data-ref="Middleton2011" title="Source 675"><a href="/stroke/sources/#src-Middleton2011">675</a></sup>.`],
 [3,`What is the benefit of aspirin started within 48 hours?`,`A net 9 fewer further strokes or deaths per 1000 in hospital <sup class="c" data-ref="Chen2000" title="Source 178"><a href="/stroke/sources/#src-Chen2000">178</a></sup>.`],
 [3,`What did CLOTS teach?`,`Stockings failed in CLOTS 1, thigh-length beat below-knee in CLOTS 2, and intermittent pneumatic compression worked in CLOTS 3 <sup class="c" data-ref="Dennis2009,Dennis2010,Dennis2013" title="Source 234,235,236"><a href="/stroke/sources/#src-Dennis2009">234,235,236</a></sup>.`],
 [3,`What is the number needed to treat for craniectomy in the pooled trials?`,`Two for survival, within 48 hours at age 60 or under <sup class="c" data-ref="Vahedi2007" title="Source 994"><a href="/stroke/sources/#src-Vahedi2007">994</a></sup>. Over 60: 38% against 18% survived without severe disability <sup class="c" data-ref="Juttler2014" title="Source 479"><a href="/stroke/sources/#src-Juttler2014">479</a></sup>.`],

 /* ---- Part 4: prevent, af, carotid ---- */
 [4,`What did INTERSTROKE find?`,`Ten factors made up about 90% of population attributable risk, with hypertension the largest at 47.9% <sup class="c" data-ref="ODonnell2016" title="Source 751"><a href="/stroke/sources/#src-ODonnell2016">751</a></sup>.`],
 [4,`How much does a 10 mm Hg fall in systolic pressure lower stroke?`,`By about 27% <sup class="c" data-ref="Ettehad2016" title="Source 289"><a href="/stroke/sources/#src-Ettehad2016">289</a></sup>.`],
 [4,`What is the trade-off in SPARCL?`,`Fewer strokes overall but more haemorrhagic strokes (55 against 33) <sup class="c" data-ref="Amarenco2006" title="Source 29"><a href="/stroke/sources/#src-Amarenco2006">29</a></sup>.`],
 [4,`When does dual antiplatelet benefit sit after minor stroke?`,`In the first 21 days <sup class="c" data-ref="Pan2019" title="Source 771"><a href="/stroke/sources/#src-Pan2019">771</a></sup>. Long-term dual therapy in lacunar stroke raised bleeding and death <sup class="c" data-ref="Benavente2012" title="Source 91"><a href="/stroke/sources/#src-Benavente2012">91</a></sup>.`],
 [4,`Which CHA2DS2-VASc items score 2?`,`Age 75 or over and previous thromboembolism <sup class="c" data-ref="Olesen2011" title="Source 756"><a href="/stroke/sources/#src-Olesen2011">756</a></sup>.`],
 [4,`How much does warfarin lower stroke in AF?`,`64%, against 22% for antiplatelets <sup class="c" data-ref="Hart2007" title="Source 404"><a href="/stroke/sources/#src-Hart2007">404</a></sup>. DOACs halve intracranial haemorrhage compared with warfarin <sup class="c" data-ref="Ruff2014" title="Source 867"><a href="/stroke/sources/#src-Ruff2014">867</a></sup>.`],
 [4,`What is the 5-year gain from carotid surgery by stenosis?`,`70% or more: 16% absolute gain. 50-69%: 4.6%. Below 30%: harm <sup class="c" data-ref="Rothwell2003" title="Source 859"><a href="/stroke/sources/#src-Rothwell2003">859</a></sup>.`],
 [4,`How much does timing of carotid surgery matter?`,`Number needed to treat 5 within 2 weeks, against 125 after 12 weeks <sup class="c" data-ref="Rothwell2004" title="Source 860"><a href="/stroke/sources/#src-Rothwell2004">860</a></sup>.`],
 [4,`What is the CREST trade-off?`,`More periprocedural stroke with stenting (4.1% against 2.3%), and more MI with surgery (2.3% against 1.1%) <sup class="c" data-ref="Brott2010" title="Source 136"><a href="/stroke/sources/#src-Brott2010">136</a></sup>.`],
 [4,`What did SAMMPRIS show?`,`Intracranial stenting was worse than aggressive medical therapy at 30 days: 14.7% against 5.8% <sup class="c" data-ref="Chimowitz2011" title="Source 184"><a href="/stroke/sources/#src-Chimowitz2011">184</a></sup>.`],
 [4,`When does PASCAL rate a PFO as probable?`,`RoPE of 7 or more plus a large shunt or atrial septal aneurysm <sup class="c" data-ref="Chambers2026" title="Source 173"><a href="/stroke/sources/#src-Chambers2026">173</a></sup>.`],

 /* ---- Part 5: rehab, after, nursing, frontier ---- */
 [5,`How fast does function recover in the Copenhagen data?`,`80% reached best ADL function by 6 weeks and 95% by 12.5 weeks <sup class="c" data-ref="Jorgensen1995" title="Source 471"><a href="/stroke/sources/#src-Jorgensen1995">471</a></sup>.`],
 [5,`What is proportional recovery, and why is it disputed?`,`About 0.7 of initial impairment, except a severe subgroup <sup class="c" data-ref="Prabhakaran2008,Winters2015" title="Source 810,1055"><a href="/stroke/sources/#src-Prabhakaran2008">810,1055</a></sup>. Statistical coupling may inflate it <sup class="c" data-ref="Hope2019" title="Source 437"><a href="/stroke/sources/#src-Hope2019">437</a></sup>.`],
 [5,`What did the 2026 AHA/ASA rehabilitation guideline say on early mobilisation?`,`Mobilise from 24 to 48 hours (COR 1), and no high-dose mobilisation in the first 24 hours (COR 3: Harm) <sup class="c" data-ref="Richards2026" title="Source 843"><a href="/stroke/sources/#src-Richards2026">843</a></sup>.`],
 [5,`When did extra arm therapy work best in CPASS?`,`At 2 to 3 months after stroke <sup class="c" data-ref="Dromerick2021" title="Source 256"><a href="/stroke/sources/#src-Dromerick2021">256</a></sup>.`],
 [5,`Which arm trials were positive and which neutral?`,`EXCITE was positive, ICARE and RATULS neutral <sup class="c" data-ref="Wolf2006,Winstein2016JAMA,Rodgers2019" title="Source 850,1054,1058"><a href="/stroke/sources/#src-Wolf2006">850,1054,1058</a></sup>.`],
 [5,`What did FCET2EC and VERSE show for aphasia therapy?`,`FCET2EC showed benefit in chronic aphasia, and VERSE no benefit from early intensive therapy <sup class="c" data-ref="Breitenstein2017,Godecke2021" title="Source 128,358"><a href="/stroke/sources/#src-Breitenstein2017">128,358</a></sup>.`],
 [5,`Does fluoxetine aid recovery?`,`No functional benefit in large trials, with less depression and more fractures <sup class="c" data-ref="Dennis2019,Hankey2020,Lundstrom2020,Legg2021" title="Source 238,392,565,602"><a href="/stroke/sources/#src-Dennis2019">238,392,565,602</a></sup>.`],
 [5,`What does botulinum toxin do for arm spasticity?`,`Less resistance to passive movement and better self-care, but no gain in arm capacity <sup class="c" data-ref="Andringa2019" title="Source 44"><a href="/stroke/sources/#src-Andringa2019">44</a></sup>.`],
 [5,`How common are mood and pain problems after stroke?`,`Depression about 31% <sup class="c" data-ref="Hackett2014" title="Source 381"><a href="/stroke/sources/#src-Hackett2014">381</a></sup>, anxiety 29% <sup class="c" data-ref="Rafsten2018" title="Source 824"><a href="/stroke/sources/#src-Rafsten2018">824</a></sup>, fatigue 48% <sup class="c" data-ref="Alghamdi2021" title="Source 20"><a href="/stroke/sources/#src-Alghamdi2021">20</a></sup>, central pain 11% <sup class="c" data-ref="Liampas2020" title="Source 572"><a href="/stroke/sources/#src-Liampas2020">572</a></sup>.`],
 [5,`What are the dementia figures?`,`10% develop dementia soon after a first stroke, and more than a third have it after recurrent stroke <sup class="c" data-ref="Pendlebury2009" title="Source 780"><a href="/stroke/sources/#src-Pendlebury2009">780</a></sup>.`],
 [5,`What are the UK driving rules after stroke, as published?`,`Group 1: 1 month off driving. Group 2: 1 year. Rules differ by country <sup class="c" data-ref="DVLA-Neuro" title="Source 263"><a href="/stroke/sources/#src-DVLA-Neuro">263</a></sup>.`],
 [5,`What is the standard observation schedule after thrombolysis?`,`Every 15 minutes for 2 hours, every 30 minutes for 6 hours, then hourly until 24 hours, as described in OPTIMISTmain <sup class="c" data-ref="Anderson2025F" title="Source 43"><a href="/stroke/sources/#src-Anderson2025F">43</a></sup>.`],
 [5,`When should a swallow screen happen, in the FeSS wording?`,`Within 4 hours of admission and before oral food, drink or medications <sup class="c" data-ref="Fasugba2023" title="Source 292"><a href="/stroke/sources/#src-Fasugba2023">292</a></sup>.`],
 [5,`Why does dysphagia matter so much?`,`Dysphagia raises pneumonia risk (RR 3.17), and confirmed aspiration raises it further (RR 11.56) <sup class="c" data-ref="Martino2005" title="Source 637"><a href="/stroke/sources/#src-Martino2005">637</a></sup>.`],
 [5,`Why did asundexian fail in AF but work after stroke?`,`It lost to apixaban in AF, and cut ischaemic stroke against placebo after non-cardioembolic stroke. Mechanism and comparator matter <sup class="c" data-ref="Piccini2025,Sharma2026" title="Source 795,916"><a href="/stroke/sources/#src-Piccini2025">795,916</a></sup>.`],
 [5,`What did paired vagus nerve stimulation add in VNS-REHAB?`,`A 2.6-point between-group difference on the Fugl-Meyer arm scale <sup class="c" data-ref="Dawson2021" title="Source 218"><a href="/stroke/sources/#src-Dawson2021">218</a></sup>.`],
 [5,`What is the lesson of LOOP?`,`Three times more AF found and twice as much anticoagulation did not significantly reduce stroke <sup class="c" data-ref="Svendsen2021" title="Source 950"><a href="/stroke/sources/#src-Svendsen2021">950</a></sup>.`],

 /* ---- Part 6: history ---- */
 [6,`Who first used the word "stroke" in English medical writing?`,`William Cole, in 1689 <sup class="c" data-ref="Engelhardt2017" title="Source 280"><a href="/stroke/sources/#src-Engelhardt2017">280</a></sup>.`],
 [6,`Who coined "lacune", "thrombosis" and "embolism"?`,`Dechambre "lacune" in 1838, and Virchow "thrombosis" and "embolism" in 1852 <sup class="c" data-ref="Engelhardt2017" title="Source 280"><a href="/stroke/sources/#src-Engelhardt2017">280</a></sup>.`],
 [6,`What was Egas Moniz's Nobel Prize for?`,`Prefrontal leucotomy, not angiography, although he showed the first cerebral angiogram in 1927 <sup class="c" data-ref="Artico2017" title="Source 53"><a href="/stroke/sources/#src-Artico2017">53</a></sup>.`],
 [6,`When was the first CT scan of a live patient?`,`1 October 1971, at Atkinson Morley Hospital <sup class="c" data-ref="Schulz2021" title="Source 905"><a href="/stroke/sources/#src-Schulz2021">905</a></sup>.`],
 [6,`Who said "penumbra" first?`,`Lindsay Symon, in his London laboratory in 1975 <sup class="c" data-ref="Astrup2025" title="Source 60"><a href="/stroke/sources/#src-Astrup2025">60</a></sup>.`],
 [6,`What was the thrombectomy turnaround?`,`Three neutral trials in 2013 <sup class="c" data-ref="Broderick2013,Ciccone2013,Kidwell2013" title="Source 132,189,499"><a href="/stroke/sources/#src-Broderick2013">132,189,499</a></sup>, then MR CLEAN in 2015 with a 13.5-point gain in independence <sup class="c" data-ref="Berkhemer2015" title="Source 97"><a href="/stroke/sources/#src-Berkhemer2015">97</a></sup>.`]
];
/* BE-FAST, ABCD2 and FeSS are published names; every other phrase here is written for this guide */
const STRV_MN=[
 ["BE-FAST",1,`Balance, Eyes, Face, Arm, Speech, Time. FAST with balance and eyes added. In one retrospective study it cut missed ischaemic strokes from 14.1% to 4.4%; the authors made changes to public education conditional on prospective validation <sup class="c" data-ref="Aroor2017" title="Source 50"><a href="/stroke/sources/#src-Aroor2017">50</a></sup>.`],
 ["ABCD2",1,`Age 60 or over, Blood pressure 140/90 mmHg or higher, Clinical features, Duration, Diabetes: 0 to 7 points <sup class="c" data-ref="Johnston2007" title="Source 465"><a href="/stroke/sources/#src-Johnston2007">465</a></sup>. Played below, with its limits.`],
 ["FeSS",1,`Fever, Sugar, Swallow: the three protocols nurses started in QASC <sup class="c" data-ref="Middleton2011" title="Source 675"><a href="/stroke/sources/#src-Middleton2011">675</a></sup>. As later listed: temperature of 37.5°C or more, glucose above 10 mmol/L, and a swallow screen within 4 hours <sup class="c" data-ref="Fasugba2023" title="Source 292"><a href="/stroke/sources/#src-Fasugba2023">292</a></sup>.`],
 ["The two twos",0,`CHA2DS2-VASc shows you its 2-point items in its own name: A<sub>2</sub> (age 75 or over) and S<sub>2</sub> (previous thromboembolism). Every other item scores 1 <sup class="c" data-ref="Olesen2011" title="Source 756"><a href="/stroke/sources/#src-Olesen2011">756</a></sup>.`],
 ["Nine, ninety, ten",0,`Alteplase as labelled: <b>0.9</b> mg/kg, maximum <b>90</b> mg, <b>10</b>% as the bolus <sup class="c" data-ref="FDA-Activase" title="Source 293"><a href="/stroke/sources/#src-FDA-Activase">293</a></sup>.`],
 ["A quarter, up to twenty-five",0,`Tenecteplase for stroke as published: <b>0.25</b> mg/kg, maximum <b>25</b> mg, one bolus <sup class="c" data-ref="Menon2022,FDA-TNKase" title="Source 297,662"><a href="/stroke/sources/#src-Menon2022">297,662</a></sup>.`],
 ["Fifteen, thirty, hourly",0,`Standard observations after lysis: every <b>15</b> minutes for 2 hours, every <b>30</b> minutes for 6 hours, then hourly until 24 hours <sup class="c" data-ref="Anderson2025F" title="Source 43"><a href="/stroke/sources/#src-Anderson2025F">43</a></sup>.`],
 ["Sixty, four, twenty-one",0,`Nimodipine in BRANT: <b>60</b> mg by mouth every <b>4</b> hours for <b>21</b> days <sup class="c" data-ref="Pickard1989" title="Source 796"><a href="/stroke/sources/#src-Pickard1989">796</a></sup>.`],
 ["Four to fourteen, peak at six to ten",0,`Delayed cerebral ischaemia after aneurysmal SAH: mostly days <b>4</b> to <b>14</b>, peak risk days <b>6</b> to <b>10</b> <sup class="c" data-ref="Hoh2023" title="Source 432"><a href="/stroke/sources/#src-Hoh2023">432</a></sup>.`],
 ["Seventy big, fifty small, thirty harmed",0,`Symptomatic carotid surgery by stenosis: 70% or more gains 16% over 5 years, 50-69% gains 4.6%, and below 30% is harmed <sup class="c" data-ref="Rothwell2003" title="Source 859"><a href="/stroke/sources/#src-Rothwell2003">859</a></sup>.`]
];
/* ABCD2 for the animation: letter, word, the rule as published, the most points the item can add */
const STRV_AB=[
 ['A','Age','60 or over: 1 point',1],
 ['B','Blood pressure','140/90 mmHg or higher: 1 point',1],
 ['C','Clinical features','weakness 2, speech only 1',2],
 ['D','Duration','60 min or more 2, 10-59 min 1',2],
 ['D','Diabetes','present: 1 point',1]
];
/* the published 2-day bands, shown as population figures */
const STRV_BANDS=[
 {n:'0-3',w:'low',r:1.0,p:'34% of people'},
 {n:'4-5',w:'moderate',r:4.1,p:'45% of people'},
 {n:'6-7',w:'high',r:8.1,p:'21% of people'}
];
const STRV_STEPS=[
 {from:0,at:.06,k:'A',t:'Age: 60 or over',txt:`Age 60 or over scores 1 <sup class="c" data-ref="Johnston2007" title="Source 465"><a href="/stroke/sources/#src-Johnston2007">465</a></sup>. In an earlier emergency department cohort of 1,707 people, age carried an odds ratio of 1.8 <sup class="c" data-ref="Johnston2000" title="Source 464"><a href="/stroke/sources/#src-Johnston2000">464</a></sup>.`,pt:'The first letter is age. Being 60 or over adds one point.',hook:'ABCD2 items: Age, Blood pressure, Clinical features, Duration, Diabetes. Total 0 to 7. <sup class="c" data-ref="Johnston2007" title="Source 465"><a href="/stroke/sources/#src-Johnston2007">465</a></sup>'},
 {from:1/6,at:1/6+.06,k:'B',t:'Blood pressure: 140/90 or higher',txt:`A blood pressure of 140/90 mmHg or higher scores 1 <sup class="c" data-ref="Johnston2007" title="Source 465"><a href="/stroke/sources/#src-Johnston2007">465</a></sup>.`,pt:'B is blood pressure. A reading of 140/90 or higher adds one point.'},
 {from:2/6,at:2/6+.06,k:'C',t:'Clinical features: weakness or speech',txt:`Unilateral weakness scores 2. Speech disturbance without weakness scores 1 <sup class="c" data-ref="Johnston2007" title="Source 465"><a href="/stroke/sources/#src-Johnston2007">465</a></sup>.`,pt:'C is what happened. Weakness on one side adds two points. Trouble speaking without weakness adds one.',hook:'Clinical features score by the worse symptom: weakness 2, speech without weakness 1. <sup class="c" data-ref="Johnston2007" title="Source 465"><a href="/stroke/sources/#src-Johnston2007">465</a></sup>'},
 {from:3/6,at:3/6+.06,k:'D',t:'Duration: how long it lasted',txt:`60 minutes or more scores 2, and 10 to 59 minutes scores 1 <sup class="c" data-ref="Johnston2007" title="Source 465"><a href="/stroke/sources/#src-Johnston2007">465</a></sup>. Watch the clock: under 10 minutes adds nothing.`,pt:'The first D is how long it lasted. The longer, the more points, up to two.'},
 {from:4/6,at:4/6+.06,k:'D',t:'Diabetes',txt:`Diabetes scores 1 <sup class="c" data-ref="Johnston2007" title="Source 465"><a href="/stroke/sources/#src-Johnston2007">465</a></sup>. Added up, the highest possible score is 7.`,pt:'The second D is diabetes. It adds one point. That makes seven in all.'},
 {from:5/6,at:5/6+.06,k:'Total',t:'The bands, and the limits',txt:`Stroke at 2 days: 1.0% at 0-3, 4.1% at 4-5, 8.1% at 6-7 <sup class="c" data-ref="Johnston2007" title="Source 465"><a href="/stroke/sources/#src-Johnston2007">465</a></sup>. The limits matter: at a cut-off of 4, sensitivity was 86.7% and specificity 35.4%, and 20% of people scoring under 4 had carotid stenosis over 50% or AF <sup class="c" data-ref="Wardlaw2015" title="Source 1033"><a href="/stroke/sources/#src-Wardlaw2015">1033</a></sup>. NICE says do not use ABCD2 to decide urgency <sup class="c" data-ref="NICE-NG128" title="Source 733"><a href="/stroke/sources/#src-NICE-NG128">733</a></sup>.`,pt:'A low score does not mean safe. The bands describe large groups of people, not one person. If stroke signs appear, even briefly, call emergency services <sup class="c" data-ref="Harbison2003,Ekundayo2013" title="Source 274,398"><a href="/stroke/sources/#src-Harbison2003">274,398</a></sup>.',hook:'A low ABCD2 does not exclude a dangerous cause: 20% under 4 had carotid stenosis or AF. <sup class="c" data-ref="Wardlaw2015" title="Source 1033"><a href="/stroke/sources/#src-Wardlaw2015">1033</a></sup>'}
];
inits.review=()=>{
  let filt='all',deck=[],i=0;
  const F=[['all','All cards'],...Object.keys(STRV_PARTN).map(k=>[k,'Part '+k])];
  $('#fcFilter').innerHTML=F.map(([k,l])=>`<button class="btn" data-ff="${k}" aria-pressed="${k==='all'}">${l}</button>`).join('');
  const fc=$('#fc');
  function build(shuf){deck=STRV_FC.filter(c=>filt==='all'||String(c[0])===filt);if(shuf){const r=rng(Date.now()%1e6);for(let k=deck.length-1;k>0;k--){const j=Math.floor(r()*(k+1));[deck[k],deck[j]]=[deck[j],deck[k]]}}i=0;render()}
  function render(){const c=deck[i];fc.classList.remove('flip');
    $('#fcTagF').textContent=STRV_PARTN[c[0]]+' · question';$('#fcTagB').textContent=STRV_PARTN[c[0]]+' · answer';
    $('#fcFront').textContent=c[1];$('#fcBack').innerHTML=c[2];$('#fcCount').textContent=`${i+1} / ${deck.length}`;$('#fcBar').style.width=((i+1)/deck.length*100)+'%'}
  const flip=()=>fc.classList.toggle('flip');
  fc.addEventListener('click',e=>{if(e.target.closest('sup.c'))return;flip()});$('#fcFlip').onclick=flip;
  const next=()=>{i=(i+1)%deck.length;render()},prev=()=>{i=(i-1+deck.length)%deck.length;render()};
  $('#fcNext').onclick=next;$('#fcPrev').onclick=prev;$('#fcShuf').onclick=()=>build(true);
  $('#fcFilter').addEventListener('click',e=>{const b=e.target.closest('[data-ff]');if(!b)return;filt=b.dataset.ff;$$('[data-ff]').forEach(x=>x.setAttribute('aria-pressed',x===b));build(false)});
  document.addEventListener('keydown',e=>{if(cur!=='review')return;if(e.target.closest('input')||(e.target.closest('button')&&e.target!==fc))return;
    if(e.key===' '||e.key==='Enter'){e.preventDefault();flip()}else if(e.key==='ArrowRight')next();else if(e.key==='ArrowLeft')prev()});
  build(false);
  $('#mnList').innerHTML=STRV_MN.map(m=>`<div class="card"><span class="tag ${m[1]?'good':'accent'}">${m[1]?'published name':'memory aid written for this guide'}</span><b class="big">${m[0]}</b><p>${m[2]}</p></div>`).join('');

  /* ---- mnemonic in motion: ABCD2 ---- */
  const svg=$('#strvSvg'),rg=$('#strvT');
  const tx=(x,y,c,txt,st='',a='')=>`<text class="${c}" x="${f1(x)}" y="${f1(y)}"${a?` text-anchor="${a}"`:''}${st?` style="${st}"`:''}>${txt}</text>`;
  /* a blood drop with sugar specks, for the diabetes item */
  const drop=(cx,cy,r,k)=>{let g=`<path d="M${f1(cx)} ${f1(cy-r*1.5)}C${f1(cx+r*.5)} ${f1(cy-r*.7)} ${f1(cx+r)} ${f1(cy-r*.2)} ${f1(cx+r)} ${f1(cy+r*.3)}A${f1(r)} ${f1(r)} 0 1 1 ${f1(cx-r)} ${f1(cy+r*.3)}C${f1(cx-r)} ${f1(cy-r*.2)} ${f1(cx-r*.5)} ${f1(cy-r*.7)} ${f1(cx)} ${f1(cy-r*1.5)}Z" style="fill:var(--bad-soft);stroke:var(--bad);stroke-width:2"/>`;
    for(let n=0;n<9;n++){const a=n*2.4,d=r*.72*Math.sqrt((n+.5)/9),o=clamp(k*9-n);g+=`<rect x="${f1(cx+Math.cos(a)*d-4)}" y="${f1(cy+r*.25+Math.sin(a)*d-4)}" width="8" height="8" rx="1.5" transform="rotate(${Math.round(a*40)} ${f1(cx+Math.cos(a)*d)} ${f1(cy+r*.25+Math.sin(a)*d)})" style="fill:var(--panel);stroke:var(--ink);stroke-width:1;opacity:${f1(o)}"/>`}
    return g};
  function draw(t){
    const N=vb(svg,'720 410','400 730');
    const p=phaseOf(STRV_STEPS,t),u=clamp((t-STRV_STEPS[p].from)*6),ph=t*40;
    const L=N?{x:12,y:34,w:376,rh:43,th:37,ty:264}:{x:16,y:44,w:300,rh:56,th:48,ty:338};
    const R=N?{x:12,y:322,w:376,h:398}:{x:332,y:14,w:372,h:382};
    let s=tx(L.x,L.y-13,'rv-a','ABCD2: five letters, seven points');
    /* running total: the most each item can add */
    let lit=0;STRV_AB.forEach((a,k)=>{if(k<p)lit+=a[3]});
    const curPts=p<5?STRV_AB[p][3]:0;const add=p<5?Math.round(ease(ramp(u,.3,.7))*curPts):0;lit+=add;
    STRV_AB.forEach(([l,word,rule,pts],k)=>{
      const y=L.y+k*L.rh,hot=k===p,done=k<p||p===5;
      s+=`<g style="opacity:${hot?1:done?.85:.55}">`;
      s+=`<rect x="${L.x}" y="${y}" width="${L.w}" height="${L.th}" rx="9" style="fill:var(${hot?'--brand-soft':'--panel'});stroke:var(${hot?'--brand':'--line'});stroke-width:${hot?1.8:1.1}"/>`;
      const cr=N?13:15,cy=y+L.th/2;
      s+=`<circle cx="${L.x+cr+7}" cy="${cy}" r="${cr}" style="fill:var(${hot?'--brand':'--muted'})"/>`+tx(L.x+cr+7,cy+5,'rv-n',l,'','middle');
      const x2=L.x+cr*2+16;
      s+=tx(x2,y+(N?15:20),'rv-c',word,'font-weight:700')+tx(x2,y+(N?31:38),'rv-b',rule);
      s+=tx(L.x+L.w-10,cy+5,'rv-c','+'+pts,'font-weight:700','end');
      s+='</g>'});
    const bw=(L.w-6*5)/7;
    s+=tx(L.x,L.ty,'rv-b',`Highest possible score so far: ${p===5?7:lit} of 7`);
    for(let k=0;k<7;k++){const on=p===5||k<lit;s+=`<rect x="${f1(L.x+k*(bw+5))}" y="${L.ty+8}" width="${f1(bw)}" height="24" rx="5" style="fill:var(${on?'--brand':'--panel-2'});stroke:var(--line)"/>`+tx(L.x+k*(bw+5)+bw/2,L.ty+25,on?'rv-m':'rv-b',String(k+1),'','middle')}
    /* explainer panel */
    const W=R.w,cx=W/2;
    s+=`<g transform="translate(${R.x} ${R.y})"><rect x="0" y="0" width="${W}" height="${R.h}" rx="12" style="fill:var(--panel-2);opacity:.55"/>`;
    const H=['Age','Blood pressure','Clinical features','Duration','Diabetes','Adding it up: stroke within 2 days'][p];
    s+=tx(16,30,'rv-a',p<5?`${STRV_AB[p][0]}: ${H}`:H);
    const cap=(a,b)=>tx(cx,R.h-(b?44:24),'rv-c',a,'','middle')+(b?tx(cx,R.h-22,'rv-c',b,'','middle'):'');
    const sc=N?150:140;
    if(p===0){
      const x0=34,x1=W-34,ay=sc+70,X=a=>x0+(x1-x0)*(a-20)/70,age=lerp(32,78,ease(ramp(u,.05,.8))),on=age>=60;
      s+=`<rect x="${f1(X(60))}" y="${ay-8}" width="${f1(x1-X(60))}" height="16" rx="4" style="fill:var(--accent-soft);stroke:var(--accent)"/><line class="axis" x1="${x0}" y1="${ay}" x2="${x1}" y2="${ay}"/>`;
      [20,40,60,80].forEach(a=>{s+=`<line class="axis" x1="${f1(X(a))}" y1="${ay-5}" x2="${f1(X(a))}" y2="${ay+5}"/>`+tx(X(a),ay+26,'rv-b',String(a),a===60?'font-weight:700;fill:var(--ink)':'','middle')});
      s+=person(X(age),ay-98,84,on?'var(--accent)':'var(--muted)');
      s+=tx(X(age),ay-108,'rv-a',on?'+1':'0','','middle');
      s+=tx(cx,ay+50,'rv-b','age in years','','middle');
      s+=cap('Age 60 or over adds 1 point');
    }else if(p===1){
      const v=lerp(110,165,ease(ramp(u,.05,.8))),on=v>=140;
      s+=gauge(cx,sc+64,104,v,200,{bands:[{to:140,col:'var(--panel-2)'},{to:200,col:'var(--accent)'}],big:true});
      s+=tx(cx,sc+90,'rv-b','mmHg, systolic side shown','','middle');
      s+=tx(cx,sc+114,'rv-a',on?'+1':'0','','middle');
      s+=cap('140/90 mmHg or higher adds 1 point');
    }else if(p===2){
      const x1=W*.27,x2=W*.73,dr=ease(ramp(u,.05,.5)),sp=ramp(u,.5,.9);
      s+=armsGlyph(x1,sc+10,136,{drift:dr,side:'L'});
      s+=tx(x1,sc+98,'rv-a','+2','','middle')+tx(x1,sc+118,'rv-c','weakness','','middle')+tx(x1,sc+136,'rv-c','on one side','','middle');
      const bx=x2-62,by=sc-52;
      s+=`<g style="opacity:${f1(.35+.65*sp)}"><path d="M${f1(bx+10)} ${by}H${f1(bx+114)}Q${f1(bx+124)} ${by} ${f1(bx+124)} ${by+10}V${by+60}Q${f1(bx+124)} ${by+70} ${f1(bx+114)} ${by+70}H${f1(bx+40)}L${f1(bx+22)} ${by+88}V${by+70}H${f1(bx+10)}Q${f1(bx)} ${by+70} ${f1(bx)} ${by+60}V${by+10}Q${f1(bx)} ${by} ${f1(bx+10)} ${by}Z" style="fill:var(--panel);stroke:var(--ink);stroke-width:1.6"/>`;
      let w='';for(let n=0;n<=40;n++){const a=n/40;w+=`${n?'L':'M'}${f1(bx+16+a*92)} ${f1(by+35+Math.sin(a*14+ph)*(5+6*Math.sin(a*5)))}`}
      s+=`<path d="${w}" style="fill:none;stroke:var(--accent);stroke-width:2.2;stroke-linecap:round"/></g>`;
      s+=tx(x2,sc+98,'rv-a','+1','','middle')+tx(x2,sc+118,'rv-c','speech trouble,','','middle')+tx(x2,sc+136,'rv-c','no weakness','','middle');
      s+=cap('Only the higher of the two counts');
    }else if(p===3){
      const min=60*ease(ramp(u,.03,.9)),pts=min>=59.5?2:min>=10?1:0,x1=W*.3,cy=sc+20;
      s+=clock(x1,cy,78,min,{full:60,col:'var(--accent)'});
      s+=tx(x1,cy+108,'rv-c',`${Math.round(min)} minutes`,'font-weight:700','middle');
      const rows=[['under 10 min','0'],['10-59 min','+1'],['60 min or more','+2']];
      rows.forEach((r,k)=>{const y=cy-52+k*42,hot=k===pts,x=W*.56,w=W*.44-14;
        s+=`<rect x="${f1(x)}" y="${y}" width="${f1(w)}" height="34" rx="7" style="fill:var(${hot?'--accent-soft':'--panel'});stroke:var(${hot?'--accent':'--line'});stroke-width:${hot?1.8:1}"/>`+tx(x+8,y+22,'rv-c',r[0],hot?'font-weight:700':'')+tx(x+w-8,y+22,'rv-c',r[1],'font-weight:700','end')});
      s+=cap('Longer symptoms add more points');
    }else if(p===4){
      const k=ease(ramp(u,.05,.7));
      s+=drop(cx,sc+6,70,k);
      s+=tx(cx,sc+118,'rv-a',k>.6?'+1':'0','','middle');
      s+=cap('Diabetes adds 1 point: 7 is the most possible');
    }else{
      const k=ease(ramp(u,.05,.7)),x0=N?94:92,bw2=W-x0-66,y0=58;
      STRV_BANDS.forEach((b,j)=>{const y=y0+j*76,w=Math.max(2,bw2*k*b.r/8.1);
        s+=tx(16,y+20,'rv-a',b.n)+tx(16,y+40,'rv-b',b.w);
        s+=`<rect x="${x0}" y="${y+4}" width="${f1(w)}" height="28" rx="5" style="fill:var(--accent);opacity:${.45+j*.25}"/>`;
        s+=tx(x0+w+7,y+24,'rv-c',b.r.toFixed(1)+'%','font-weight:700',);
        s+=tx(x0,y+50,'rv-b',b.p)});
      s+=tx(cx,y0+240,'rv-b','Population figures from the published cohorts,','','middle')+tx(cx,y0+258,'rv-b','not a forecast for any one person.','','middle');
      s+=cap('NICE: do not use ABCD2 to','decide how urgent care is');
    }
    s+='</g>';svg.innerHTML=s;
    setSt(p);$('#strvNote').innerHTML=noteHTML(STRV_STEPS[p]);
    rg.setAttribute('aria-valuetext',`${STRV_STEPS[p].k}: ${STRV_STEPS[p].t}`)}
  const stop=playWire(rg,$('#strvPlay'),draw,26000,'Replay','review');
  const setSt=stepWire($('#strvSteps'),STRV_STEPS,rg,draw,stop);
  draw(+rg.value);
};

/* =============== 6.3 quiz =============== */
